"use strict";
const LESSONS_K01 = {"1": "# पाठ 1 — मशरूम पौधा नहीं, कवक (Fungus) है\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 1\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि मशरूम \"पौधा\" क्यों नहीं बल्कि एक \"कवक\" (फ़ंगस) क्यों है। आप यह भी अच्छी तरह जानेंगे कि इस एक बात का आपके पूरे धंधे पर क्या असर पड़ता है। यह पूरे इस कोर्स का पहला पाठ है — इसलिए यहाँ अपनी नींव बहुत मज़बूत बनानी है। और अंत में आप अपनी पहली, \"मशरूम-पहचान सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> मशरूम में \"हरा रंग\" (क्लोरोफ़िल) नहीं होता। इसलिए वह धूप से अपना खाना नहीं बनाता। इसीलिए उसे खेत मिट्टी और धूप की ज़रूरत ही नहीं पड़ती — यह एक बात ही पूरे मशरूम-धंधे की असली बुनियाद है।\n\n### 3. बरसात में जो अपने-आप उग आता है\n\nगाँव में बरसात के दिनों में गोबर के ढेर पर या सड़ी लकड़ी पर सफ़ेद छाते जैसी चीज़ उग आती है। लोग इसे \"कुकुरमुत्ता\" कहते हैं। बाज़ार वाला अपने-आप कभी नहीं उगा — वही \"मशरूम\" जो बाज़ार में बिकता है इसे किसी ने सोच-समझकर तैयार किया है — धान और गेहूँ खेत में उगते हैं; मशरूम अलग तरह से क्यों उगता है यह समझना ज़रूरी है।\n\n### 4. \"पौधा\" और \"कवक\" में फ़र्क़\n\nपौधे अपना खाना ख़ुद बनाते हैं — पौधों में \"हरा रंग\" होता है जो धूप की ऊर्जा को पकड़कर अपना खाना ख़ुद बनाता है — इसीलिए पौधों को हमेशा धूप और मिट्टी चाहिए। कवक \"तैयार खाना\" खाते हैं — मशरूम जैसे कवक ख़ुद अपना खाना नहीं बना सकते — वे किसी और चीज़ (जैसे पुआल या लकड़ी) में पहले से मौजूद खाने को \"पचाकर\" जीते हैं — इसीलिए इसे धूप या मिट्टी की ज़रूरत नहीं पड़ती।\n\n### 5. यह एक बात आपके धंधे को कैसे बदलती है\n\nपाठ 2-12 में आगे गहराई से सीखेंगे — क्योंकि मशरूम को धूप और बड़े खेत की ज़रूरत नहीं पड़ती इसीलिए इसे छोटे कमरे में भी उगाया जा सकता है — यह उन लोगों के लिए भी एक बहुत बड़ा अवसर है जिनके पास बड़ी ज़मीन बिलकुल नहीं है। इसीलिए \"जगह-रहित\" खेती संभव है — पारंपरिक फ़सलों की तरह \"एकड़-दर-एकड़\" ज़मीन की बजाय मशरूम को \"कमरे के अंदर\" भी बड़ी मात्रा में उगाया जा सकता है — यह गाँव के छोटे किसान के लिए एक बहुत बड़ा अवसर है।\n\n### 6. अपनी पहली, \"मशरूम-पहचान सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — क्या आपने कभी अपने गाँव में \"कुकुरमुत्ता\" उगते हुए देखा है और अब यह जानकर कि \"यह एक कवक है पौधा नहीं\" आपकी समझ कैसे बदली।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">मशरूम पौधा नहीं, कवक है</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">पौधा</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">हरा रंग, धूप से खाना</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">मिट्टी, धूप ज़रूरी</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">कवक (मशरूम)</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">तैयार खाना पचाता है</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">धूप-मिट्टी की ज़रूरत नहीं</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">यही फ़र्क़, पूरे धंधे की बुनियाद</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"मशरूम-पहचान हिस्सा\" (नया, अध्याय-1 का पहला पन्ना) जोड़िए — पौधा-कवक फ़र्क़, धंधे पर असर अपनी भाषा में। फिर अपनी पहली, \"मशरूम-पहचान सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मैंने अपने गाँव में यह-यह तरह की चीज़ उगते देखी है (लिखिए)। बताओ — क्या यह \"मशरूम का ही\" एक जंगली रूप हो सकता है और इसे खाना सुरक्षित है या नहीं?*\n\n**⚠️ ज़रूरी सावधानी:** AI कभी भी \"यह खाने योग्य है\" जैसी अंतिम गारंटी न दे — जंगली मशरूम बहुत ख़तरनाक हो सकते हैं — कभी भी अनजान मशरूम न चखें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मशरूम भी आख़िर एक पौधा ही है बस यह हरा नहीं दिखता\" — जबकि मशरूम और पौधे की पूरी \"जीवन-प्रक्रिया\" ही अलग है — इस पूरी ग़लतफ़हमी से आगे कई और ग़लत फ़ैसले जैसे \"इसे भी धूप चाहिए\" सोचना हो सकते हैं।**\n\n\"मशरूम भी एक पौधा है\" सोचना एक बुनियादी भूल है। हमेशा अच्छी तरह याद रखें मशरूम एक अलग और अनोखे प्रकार का जीव यानी \"कवक\" है।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| मशरूम को \"पौधा\" समझना | इसे हमेशा \"कवक\" के रूप में समझें |\n| जंगली अनजान मशरूम चखना | कभी भी अनजान मशरूम न चखें |\n| बिना जानकारी के उगाना शुरू करना | पहले पूरा जीवन-चक्र समझें |\n| मशरूम-पहचान हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"मशरूम-पहचान सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nकवक-विज्ञान (माइकोलॉजी) के सामान्य शैक्षिक सिद्धांत — कवक व पौधों के बीच पोषण-भेद: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ मशरूम \"पौधा\" क्यों नहीं बल्कि \"कवक\" क्यों है — मैं समझा सकता हूँ।\n☐ इस एक बात का धंधे पर क्या असर पड़ता है — मुझे साफ़ है।\n☐ यह आगे इस पूरे कोर्स की नींव कैसे बनता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"मशरूम भी पौधा है\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"मशरूम-पहचान सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — अगर आपके आस-पास बरसात में \"कुकुरमुत्ता\" उगता हो तो उसे ध्यान से देखें (छूकर या चखकर नहीं) — इसका आकार रंग और बनावट नोट करें — यह पूरा अनुभव आपको आगे आने वाले पाठों में \"असली\" मशरूम की सही पहचान समझने में अच्छी मदद करेगा।\n\nएक आख़िरी सोच — यह जानना कि \"मशरूम एक अलग तरह का जीव है\" सिर्फ़ एक \"विज्ञान की बात\" नहीं — यह पूरी समझ आपको यह समझने में मदद करती है कि \"क्यों मशरूम की खेती बाक़ी फ़सलों से इतनी अलग है\" और \"क्यों इसमें इतनी सारी संभावनाएँ हैं।\"\n\nएक और ज़रूरी बात — अगर आपके परिवार में कोई यह सोचता है कि \"मशरूम तो बस एक तरह की सब्ज़ी है\" तो उन्हें भी यह बुनियादी फ़र्क़ स्पष्ट रूप से समझाएँ — यह आगे की सारी सीख को आसान बनाता है।\n\nएक अंतिम सुझाव — इस पाठ को दोबारा पढ़ने से पहले यह सोचें — \"अगर मुझे किसी को एक ही वाक्य में यह समझाना हो कि मशरूम पौधा क्यों नहीं है तो मैं क्या कहूँगा/कहूँगी\" — यह अभ्यास आपकी समझ को और मज़बूत करेगा।\n\nअंत में याद रखें कि यह पूरी \"पौधा-नहीं-कवक\" की सोच अगले पाठ में सीखी जाने वाली \"जीवन-चक्र का पहिया\" की सीधी तैयारी है — जब आप यह समझ लें कि \"मशरूम क्या है\" तो यह समझना कि \"यह कैसे जन्म लेता है और कैसे बढ़ता है\" अगला स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में आपके साथ शामिल हों तो सभी को \"मशरूम कवक है पौधा नहीं\" वाली यह बुनियादी सीख स्पष्ट रूप से समझाएँ ताकि पूरा परिवार एक ही सही समझ के साथ आगे बढ़े।\n\nएक आख़िरी बात — यह पूरी \"मशरूम-पहचान\" की सोच दिखने में एक \"छोटी वैज्ञानिक\" बात लगती है पर यह असल में आपके पूरे आगे के धंधे की सबसे ज़रूरी बुनियादी नींव है।\n\nएक और गहरी सोच — अगर आप कभी किसी ग्राहक को अपने धंधे के बारे में बताएँ तो यह \"मशरूम कवक है\" वाली बात भी शामिल कर सकते हैं — यह आपके ज्ञान और आपकी तैयारी को दिखाता है।\n\nएक अंतिम विचार — जो व्यक्ति इस बुनियादी फ़र्क़ को अच्छी तरह समझ लेता है वह आगे चलकर हर तकनीकी फ़ैसला (जैसे \"कमरा कैसा हो\" \"कितनी धूप चाहिए\") बहुत आसानी से और सही तरीक़े से ले पाता है।\n\n---\n---\n", "2": "# पाठ 2 — जीवन-चक्र का पहिया — बीजाणु से बीजाणु तक\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 2\n**सुरक्षा:** 🟢 सामान्य · **काम:** «देखो» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि मशरूम का पूरा जीवन एक \"पहिये\" की तरह कैसे घूमता है। आप यह भी अच्छी तरह जानेंगे कि इस पहिये के हर पड़ाव पर आपका क्या काम है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात पाठ 1 की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"जीवन-चक्र सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> मशरूम का जीवन एक पहिये की तरह घूमता है — \"बीजाणु\" (छोटे-छोटे बीज जैसे कण) से शुरू होकर \"जाल\" (धागे) फिर \"कली\" फिर \"फल-शरीर\" (जो हम खाते हैं) और फिर वापस \"बीजाणु\" तक — पूरी खेती इसी पहिये को समझने और सही समय पर सही काम करने की कला है।\n\n### 3. पहिये के चार मुख्य पड़ाव\n\nपहला — बीजाणु से जाल — पाठ 3 में आगे गहराई से सीखेंगे — बहुत महीन \"बीजाणु\" कण सही जगह मिलने पर एक बहुत पतला सफ़ेद धागा बनाता है — हज़ारों धागे मिलकर \"जाल\" (माइसीलियम) बनाते हैं। दूसरा — जाल का फैलना — पाठ 4 में आगे गहराई से सीखेंगे — यह जाल अपने आस-पास के \"खाने\" (पुआल या भूसे) में चारों तरफ़ फैलता जाता है और पूरा बैग धीरे-धीरे सफ़ेद हो जाता है।\n\n### 4. बाक़ी दो पड़ाव\n\nतीसरा — कली बनना — पाठ 5 में आगे गहराई से सीखेंगे — जब जाल पूरा फैल जाता है तो छोटी-छोटी सफ़ेद \"कलियाँ\" (गाँठें) उभरने लगती हैं। चौथा — फल-शरीर बनना और फिर बीजाणु — पाठ 6 में आगे गहराई से सीखेंगे — कली बड़ी होकर पूरा मशरूम (फल-शरीर) बनती है जिसे हम तोड़कर बेचते हैं — अगर इसे न तोड़ा जाए तो इसकी टोपी के नीचे फिर \"बीजाणु\" बनने लगते हैं और पहिया दोबारा वहीं पहुँच जाता है जहाँ से शुरू हुआ था।\n\n### 5. यह पाठ 1 की सीख से कैसे आगे बढ़ता है\n\nपाठ 1 ने सिखाया कि मशरूम \"कवक\" क्यों है \"पौधा\" क्यों नहीं। यह पूरा पाठ उस \"क्या है\" वाली समझ से आगे बढ़कर अब \"यह कैसे जन्म लेता और बढ़ता है\" — इस ज़रूरी अगले सवाल का जवाब देता है — बिना इस पूरे चक्र को समझे आप कभी यह नहीं समझ पाएँगे कि \"आज मेरे बैग को क्या चाहिए।\"\n\n### 6. «देखो» — अपनी पहली, \"जीवन-चक्र सोच\" लिखना\n\nयह «देखो» पाठ है — इसका मक़सद आपको इस पूरे चक्र से परिचित कराना है न कि अभी इसे \"याद\" कराना। अपनी नोटबुक में इन चार पड़ावों को अपनी भाषा में क्रम से लिखें — बीजाणु जाल कली और फल-शरीर।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">जीवन-चक्र का पहिया — चार पड़ाव</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">पहले दो पड़ाव</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">बीजाणु → जाल बनना</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जाल का फैलना</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">आख़िरी दो पड़ाव</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">कली बनना</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">फल-शरीर → फिर बीजाणु</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">एक घूमता पहिया, हर पड़ाव पर अलग काम</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"जीवन-चक्र हिस्सा\" जोड़िए — चार पड़ाव अपनी भाषा में। फिर अपनी पहली \"जीवन-चक्र सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे मशरूम के जीवन-चक्र के बारे में बताओ — बीजाणु से लेकर फल-शरीर बनने तक चार आसान पड़ावों में।*\n\nAI इसे सामान्य रूप में समझाने में मददगार है — इस कोर्स में आगे आने वाले पाठों में आप हर पड़ाव को ख़ुद अपने अनुभव से गहराई से समझेंगे।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मशरूम अचानक एक दिन में उग आता है\" बिना यह समझे कि इसके पीछे यह पूरा चार-पड़ाव वाला चक्र चल रहा होता है — जबकि हर पड़ाव के अपने ठीक ज़रूरत हैं और बिना इन्हें समझे आप सही समय पर सही काम नहीं कर पाएँगे।**\n\n\"मशरूम अचानक उग आता है\" सोचना एक अधूरी समझ है। हमेशा इस पूरे चार-पड़ाव चक्र को ध्यान में रखें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| पूरे चक्र को समझे बिना उगाना शुरू करना | पहले चारों पड़ाव अच्छी तरह समझें |\n| हर पड़ाव को \"एक-जैसा\" मानना | हर पड़ाव की अलग ज़रूरत समझें |\n| फल-शरीर बनने के बाद भी न तोड़ना | सही समय पर तोड़ना सीखें (आगे के पाठ) |\n| जीवन-चक्र हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"जीवन-चक्र सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी चक्र को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nकवक-जीवन-चक्र (बीजाणु-माइसीलियम-फल-शरीर) के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ मशरूम का पूरा जीवन एक \"पहिये\" की तरह कैसे घूमता है — मैं समझा सकता हूँ।\n☐ इस पहिये के हर पड़ाव पर मेरा क्या काम है — मुझे साफ़ है।\n☐ यह पाठ 1 की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"मशरूम अचानक उग आता है\" सोचना क्यों अधूरा है।\n☐ मैंने अपनी पहली, \"जीवन-चक्र सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — इस पूरे चार-पड़ाव वाले चक्र को एक \"साधारण कहानी\" की तरह याद करें — \"पहले बीज फिर धागा फिर कली फिर फल\" — यह सरल याद आगे के तकनीकी पाठों को समझने में बहुत मदद करेगी।\n\nएक आख़िरी सोच — यह समझना कि \"पहिया घूमता रहता है\" (एक ही बैग से कई बार फ़सल मिल सकती है) आपको यह समझने में मदद करता है कि \"जाल को बचाना\" ही सबसे ज़रूरी काम है — मशरूम टूट जाए तो कोई बात नहीं जाल फिर दे देगा।\n\nएक और ज़रूरी बात — अगर आप कभी उलझन में पड़ें तो यह सोचें — \"अभी मेरा बैग इन चार पड़ावों में से किस पड़ाव पर है\" — यह पूरी सोच आपको हमेशा सही दिशा में आगे ले जाएगी।\n\nएक अंतिम सुझाव — इस पूरे चक्र को, अपनी नोटबुक में, एक सरल चित्र की तरह भी बना सकते हैं — यह, आगे के, हर पाठ में, आपकी अच्छी मदद करेगा।\n\nअंत में याद रखें कि यह पूरी जीवन-चक्र की सोच अगले पाठ में सीखी जाने वाली \"बीजाणु और जाल क्या हैं\" की सीधी तैयारी है — जब आप पूरा पहिया समझ लें तो इसके पहले दो पड़ावों को और गहराई से समझना अगला स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको यह पूरा \"चार-पड़ाव वाला पहिया\" बहुत स्पष्ट रूप से समझाएँ ताकि पूरा परिवार एक ही स्पष्ट समझ के साथ आगे बढ़े।\n\nएक आख़िरी बात — यह पूरी और गहरी, जीवन-चक्र की सोच, दिखने में एक \"वैज्ञानिक और जटिल\" विषय ही लगती है, पर यह असल में, आपकी पूरी खेती को समझने की, सबसे सरल और सबसे ज़रूरी कुंजी है।\n\nएक और गहरी सोच — इस पूरे पहिये को \"साल-भर चलने वाली कहानी\" की तरह देखें — हर एक बार जब आप एक नया बैग तैयार करते हैं तो यह पहिया फिर से \"बीजाणु\" से शुरू होकर \"फल-शरीर\" तक घूमता है — यह पूरा पहिया आपके धंधे का \"दिल\" जैसा ही है।\n\nएक अंतिम विचार — जो कोई भी व्यक्ति इस पूरे पहिये को बहुत गहराई से समझ लेता है वह आगे चलकर कभी भी \"मशरूम क्यों नहीं उग रहा\" जैसे सवालों में नहीं उलझता — क्योंकि उसे हमेशा पता होता है कि यह पूरी समस्या इसी चार-पड़ाव वाले पहिये के किसी एक हिस्से में ही छिपी है।\n\n---\n---\n", "3": "# पाठ 3 — बीजाणु (Spore) और जाल (Mycelium) क्या हैं\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 3\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि \"बीजाणु\" (स्पोर) और \"जाल\" (माइसीलियम) असल में क्या हैं। आप यह भी अच्छी तरह जानेंगे कि इन दोनों में क्या फ़र्क़ है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात जीवन-चक्र की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"बीजाणु-जाल सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> \"बीजाणु\" मशरूम का \"बीज\" है — बहुत महीन धूल जैसे कण जो आँख से नहीं दिखते। \"जाल\" (माइसीलियम) असली मशरूम का \"शरीर\" है — यह सफ़ेद धागों का एक जाल है जो हफ़्तों तक चुपचाप बढ़ता रहता है — यही समझना इस पूरे धंधे की सबसे गहरी नींव है।\n\n### 3. \"बीजाणु\" (स्पोर) असल में क्या है\n\nमशरूम की टोपी के नीचे बनते हैं — मशरूम की टोपी के नीचे की तरफ़ बहुत महीन धूल जैसे कण बनते हैं — इन्हें \"बीजाणु\" कहते हैं। बीज की तरह काम करते हैं — जैसे धान या गेहूँ का बीज ज़मीन में पड़कर अंकुरित होता है वैसे ही \"बीजाणु\" भी सही जगह मिलने पर अंकुरित होकर एक बिलकुल नया जाल बनाना तुरंत शुरू कर देता है।\n\n### 4. \"जाल\" (माइसीलियम) असल में क्या है\n\nअसली \"मशरूम\" का शरीर — पाठ 1 की \"कवक\" सीख की तरह ही \"बीजाणु\" से निकला बहुत पतला सफ़ेद धागा हज़ारों-हज़ारों की संख्या में मिलकर एक \"रुई\" जैसा \"जाल\" बनाता है — यही असली मशरूम का \"शरीर\" है जो हम तोड़ते हैं वह सिर्फ़ इसका \"फल\" है। हफ़्तों तक चुपचाप बढ़ता है — यह पूरा \"जाल\" पुआल या भूसे के अंदर फैलता हुआ हफ़्तों तक बिना दिखे चुपचाप अपना काम करता रहता है — इसीलिए जब तक यह पूरी तरह \"फैल\" नहीं जाता तब तक कोई भी मशरूम नहीं दिखता।\n\n### 5. यह जीवन-चक्र की सीख से कैसे आगे बढ़ता है\n\nपाठ 2 ने सिखाया कि पूरा चक्र चार पड़ावों में कैसे घूमता है। यह पूरा पाठ उस \"पूरे चक्र\" की समझ से आगे बढ़कर अब इसके पहले दो ज़रूरी \"हिस्सों\" — \"बीजाणु\" और \"जाल\" — को गहराई से समझाता है — बिना इन्हें ठीक से समझे आगे के \"जाल-फैलाव\" और \"कली-बनने\" वाले पाठ समझना मुश्किल होगा।\n\n### 6. अपनी पहली, \"बीजाणु-जाल सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — \"बीजाणु\" और \"जाल\" में क्या फ़र्क़ है अपनी ही भाषा में स्पष्ट रूप से लिखिए जैसे आप किसी बच्चे को समझा रहे हों।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">बीजाणु और जाल — क्या हैं</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">बीजाणु (Spore)</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">मशरूम का \"बीज\"</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">आँख से नहीं दिखता</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">जाल (Mycelium)</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">असली मशरूम का शरीर</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">सफ़ेद धागों का जाल</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">बीज से शरीर तक — पहला बदलाव</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"बीजाणु-जाल हिस्सा\" जोड़िए — बीजाणु क्या है, जाल क्या है अपनी भाषा में। फिर अपनी पहली \"बीजाणु-जाल सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे \"बीजाणु\" और \"जाल\" के बीच का फ़र्क़ एक सरल उदाहरण से समझाओ जो मेरे गाँव की किसी आम चीज़ से जुड़ा हो।*\n\nAI सरल और आसान उदाहरणों से समझाने में काफ़ी मददगार है — असली और गहरी समझ हमेशा अपनी ख़ुद की नोटबुक में अच्छी तरह लिखकर ही बनती है।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"जो मशरूम हम तोड़ते हैं वही पूरा जीव है\" — जबकि असली मशरूम वह \"जाल\" (माइसीलियम) है जो ज़मीन या बैग के अंदर छिपा रहता है — जो हम तोड़ते हैं वह सिर्फ़ इसका \"फल\" है \"पूरा पेड़\" नहीं।**\n\n\"जो भी तोड़ते हैं, वही पूरा जीव है\" सोचना, एक बड़ी और बुनियादी भूल है। हमेशा यह अच्छी तरह याद रखें कि \"जाल\" ही असली शरीर है \"फल-शरीर\" तो सिर्फ़ इसका एक छोटा हिस्सा है।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| \"फल-शरीर\" को ही \"पूरा मशरूम\" मानना | हमेशा \"जाल\" को असली शरीर मानें |\n| \"बीजाणु\" और \"जाल\" को मिलाना | दोनों को अलग स्पष्ट रूप से समझें |\n| जाल को नुक़सान पहुँचाना (आगे के पाठ) | जाल को सबसे ज़्यादा महत्व दें |\n| बीजाणु-जाल हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"बीजाणु-जाल सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nकवक-जीव-विज्ञान में बीजाणु व माइसीलियम की परिभाषा के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ \"बीजाणु\" और \"जाल\" असल में क्या हैं — मैं समझा सकता हूँ।\n☐ इन दोनों में क्या फ़र्क़ है — मुझे साफ़ है।\n☐ यह जीवन-चक्र की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"फल-शरीर ही पूरा मशरूम है\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"बीजाणु-जाल सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — जब भी आप आगे के हर पाठ में \"जाल फैलना\" या \"जाल सफ़ेद हो रहा है\" जैसे शब्द पढ़ें तो हमेशा याद रखें कि यह वही \"जाल\" यानी माइसीलियम है जिसे आज आपने यहाँ समझा — यह पूरा दोहराव आपकी समझ को और भी ज़्यादा मज़बूत करेगा।\n\nएक आख़िरी सोच — अपने ज़हन में \"जाल\" को \"पौधे की जड़\" की तरह सोचें — जैसे जड़ पौधे को हमेशा ज़िंदा रखती है वैसे ही \"जाल\" मशरूम को हमेशा ज़िंदा रखता है — यह तुलना इसे याद रखने में मदद कर सकती है।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह पूरी \"बीजाणु-जाल\" वाली बुनियादी समझ पूरे हब के साथ अच्छी तरह साझा करें — ताकि सभी एक ही स्पष्ट और सही समझ से अपनी शुरुआत करें।\n\nएक अंतिम सुझाव — अगर कभी संभव हो तो अपने आस-पास के किसी सड़े हुए पेड़ या गोबर के ढेर में सफ़ेद धागे जैसा \"जाल\" ढूँढ़ने की अच्छी कोशिश करें — यह पूरा अनुभव आपको असली \"जाल\" को अपनी ही आँखों से देखने का एक अच्छा मौक़ा देगा।\n\nअंत में याद रखें कि यह पूरी बीजाणु-जाल की सोच अगले पाठ में सीखी जाने वाली \"जाल का फैलना — भीतर क्या हो रहा है\" की सीधी तैयारी है — जब आप यह समझ लें कि \"जाल\" क्या है तो यह पूरी तरह समझना कि \"यह अंदर ही अंदर आख़िर कैसे फैलता है\" अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"बीजाणु बीज है जाल शरीर है\" वाली यह पूरी और सरल याद बहुत स्पष्ट रूप से समझाएँ ताकि सभी एक-जैसी समझ के साथ आगे बढ़ें।\n\nएक आख़िरी बात — यह पूरी और गहरी, बीजाणु-जाल की सोच, दिखने में एक \"छोटी और तकनीकी\" बात ही लगती है, पर यह असल में, आपके पूरे धंधे की, \"जड़\" को समझने वाली, सबसे गहरी और ज़रूरी नींव है।\n\nएक और गहरी सोच — \"बीजाणु\" को \"बीज-भंडार\" (सीड-बैंक) की तरह सोचें — जैसे किसान अगली फ़सल के लिए अपने बीज सँभालकर रखता है वैसे ही \"बीजाणु\" प्रकृति का अपना \"बीज-भंडार\" है जो अगली पीढ़ी के \"जाल\" को जन्म देता है।\n\nएक अंतिम विचार — जो व्यक्ति \"बीजाणु\" और \"जाल\" के फ़र्क़ को अच्छी तरह समझ लेता है वह आगे चलकर \"बीज-गुणवत्ता\" (आगे के पाठों में) और \"जाल-स्वास्थ्य\" — इन दोनों अलग विषयों को कभी नहीं उलझाता और हर समस्या को सही जगह ढूँढ़ पाता है।\n\n---\n---\n", "4": "# पाठ 4 — जाल का फैलना (Colonization) — भीतर क्या हो रहा है\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 4\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि \"जाल का फैलना\" (कॉलोनाइज़ेशन) के दौरान बैग के भीतर असल में क्या होता है। आप यह भी अच्छी तरह जानेंगे कि इस पूरे दौर में आपको आख़िर क्या करना चाहिए और क्या बिलकुल नहीं करना चाहिए। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, बीजाणु-जाल की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"जाल-फैलाव सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> जब भी \"जाल\" बनना शुरू हो जाता है तो यह अपने चारों तरफ़ के \"खाने\" यानी पुआल या भूसे में धीरे-धीरे फैलता चला जाता है — यह पूरी प्रक्रिया \"जाल का फैलना\" ही कहलाती है — और इस पूरे दौर में \"सबसे ज़्यादा धैर्य और सबसे कम हस्तक्षेप\" ही सबसे अच्छी नीति है।\n\n### 3. भीतर असल में क्या हो रहा है\n\nजाल \"खाना\" पचा रहा है — पाठ 3 की \"जाल-कवक तैयार खाना खाते हैं\" सीख की तरह ही यह पूरा जाल अपने आस-पास के पुआल या भूसे में मौजूद पोषक-तत्वों को धीरे-धीरे \"पचाकर\" अपनी ऊर्जा बना रहा है — यह पूरी प्रक्रिया धीमी है पर यह लगातार चलती रहती है। पूरा बैग सफ़ेद होता जाता है — जैसे-जैसे यह जाल फैलता जाता है बैग का रंग धीरे-धीरे गहरे से हल्के सफ़ेद में बदलता चला जाता है — यह पूरा सफ़ेद रंग ही आपको स्पष्ट रूप से बताता है कि \"जाल अब तक कितना फैल चुका है।\"\n\n### 4. इस दौर में आपका क्या काम है\n\nछेड़ना नहीं — सबसे ज़रूरी नियम — इस पूरे दौर में बैग को बार-बार खोलना हिलाना या छूना बिलकुल भी नहीं चाहिए — हर बार छेड़ने से जाल को एक \"तनाव\" यानी झटका मिलता है जो इसके पूरे फैलाव को धीमा कर सकता है। अँधेरा और गर्मी बनाए रखें — पाठ 442 की \"तापमान-नमी\" सीख की तरह ही इस पूरे दौर में जाल को \"अँधेरे\" और \"स्थिर गर्मी\" की बहुत ज़रूरत होती है ना कि कभी भी रोशनी की — रोशनी इस समय कोई फ़ायदा नहीं देती बल्कि कभी-कभी थोड़ा नुक़सान भी कर सकती है।\n\n### 5. यह बीजाणु-जाल की सीख से कैसे आगे बढ़ता है\n\nपाठ 3 ने सिखाया कि \"बीजाणु\" और \"जाल\" असल में क्या हैं। यह पूरा पाठ उस \"क्या है\" वाली समझ से आगे बढ़कर अब \"यह कैसे बढ़ता है\" — इस अगले ज़रूरी सवाल का जवाब देता है — बिना यह समझे आप कभी भी यह नहीं समझ पाएँगे कि \"मुझे इस पूरे दौर में धैर्य आख़िर क्यों रखना चाहिए।\"\n\n### 6. अपनी पहली, \"जाल-फैलाव सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — इस \"जाल फैलाव\" के दौर में आप \"छेड़ना नहीं\" और \"अँधेरा-गर्मी\" रखने की इन दो बातों को अपने शब्दों में कैसे याद रखेंगे।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">जाल का फैलना — भीतर क्या हो रहा है</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">भीतर क्या होता है</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जाल, खाना पचाता है</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">बैग सफ़ेद होता जाता है</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">आपका काम</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">छेड़ना नहीं</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">अँधेरा-गर्मी बनाए रखें</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">सबसे ज़्यादा धैर्य, सबसे कम हस्तक्षेप</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"जाल-फैलाव हिस्सा\" जोड़िए — भीतर क्या होता है, आपका क्या काम अपनी भाषा में। फिर अपनी पहली \"जाल-फैलाव सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मेरा बैग अभी \"जाल-फैलाव\" के दौर में है (लिखिए)। बताओ — इस दौर में मुझे किन बातों का सबसे ज़्यादा ध्यान रखना चाहिए?*\n\nAI इसमें सामान्य और शुरुआती दिशा देने में काफ़ी मददगार है — असली और सटीक समय-सीमा और तापमान हमेशा अपने ख़ुद के अनुभव या उस्ताद से ही पुष्टि करें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मुझे बार-बार बैग खोलकर देखना चाहिए कि जाल कितना फैला\" — जबकि हर बार बैग खोलने से न सिर्फ़ जाल को \"तनाव\" मिलता है बल्कि बाहरी हवा से \"संदूषण\" (कॉन्टेमिनेशन) का ख़तरा भी बढ़ता है — इस दौर में \"कम से कम छेड़ना\" ही सबसे सुरक्षित तरीक़ा है।**\n\n\"बार-बार खोलकर देखना\" एक, बहुत नुक़सानदायक भूल है। हमेशा इस पूरे दौर में बैग को कम से कम छेड़ें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| बार-बार बैग खोलकर देखना | कम से कम छेड़ें |\n| रोशनी में बैग रखना | अँधेरा बनाए रखें |\n| तापमान में बार-बार बदलाव | स्थिर गर्मी बनाए रखें |\n| जाल-फैलाव हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"जाल-फैलाव सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस दौर में जल्दबाज़ी करना | धैर्य रखें समय दें |\n\n### 13. स्रोत\n\nकवक-कॉलोनाइज़ेशन (जाल-फैलाव) प्रक्रिया के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ \"जाल का फैलना\" के दौरान बैग के भीतर असल में क्या होता है — मैं समझा सकता हूँ।\n☐ इस दौर में मुझे क्या करना चाहिए और क्या नहीं — मुझे साफ़ है।\n☐ यह बीजाणु-जाल की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"बार-बार खोलकर देखना\" क्यों नुक़सानदायक है।\n☐ मैंने अपनी पहली, \"जाल-फैलाव सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — अगर आपको यह जाँचना ही है कि \"जाल कितना फैला है\" तो बैग के बाहर से ही रंग देखकर अच्छा अंदाज़ा लगाएँ — बार-बार खोलने की बजाय हमेशा सिर्फ़ \"देखने\" की एक अच्छी आदत डालें।\n\nएक आख़िरी सोच — यह \"धैर्य\" वाला सबक़ सिर्फ़ इस एक पड़ाव तक सीमित नहीं — इस पूरी मशरूम-खेती में बार-बार \"कम हस्तक्षेप ज़्यादा धैर्य\" वाला यही सिद्धांत हर जगह दोहराया जाता है।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह \"छेड़ना नहीं\" वाला नियम पूरे हब के साथ साझा करें — क्योंकि सिर्फ़ एक ही सदस्य की जल्दबाज़ी पूरे बैच को बहुत बड़ा नुक़सान पहुँचा सकती है।\n\nएक अंतिम सुझाव — इस पूरे दौर में अपनी नोटबुक में सिर्फ़ \"तारीख़\" और \"रंग-अनुमान\" नियमित रूप से लिखते रहें — यह पूरी आदत आगे आपको अपने अनुभव से \"औसत समय\" समझने में बहुत मदद करेगी।\n\nअंत में, याद रखें कि यह पूरी, जाल-फैलाव की सोच, अगले पाठ में सीखी जाने वाली \"नन्ही कली (Primordia) कैसे बनती है\" की सीधी तैयारी है — जब जाल पूरा फैल जाता है, तो, इसके ठीक अगले पड़ाव को अच्छी तरह समझना, अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस प्रक्रिया में शामिल हों तो सबको \"छेड़ना नहीं\" वाली यह पूरी और ज़रूरी आदत बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी जल्दबाज़ी में बैग को नुक़सान न पहुँचाए।\n\nएक आख़िरी बात — यह पूरी जाल-फैलाव की सोच दिखने में एक \"कुछ न करने\" जैसी बात लगती है पर यह असल में सबसे बड़ा अनुशासन और सबसे ज़रूरी कौशल है।\n\nएक और गहरी सोच — यह धैर्य वाला समय आपको अपने \"रिकॉर्ड\" (नोटबुक) पर काम करने का भी मौक़ा देता है — इस दौर में आप अपने ख़र्च अपनी तैयारी और आगे की योजना पर ध्यान दे सकते हैं जबकि बैग ख़ुद अपना काम कर रहा होता है।\n\nएक अंतिम विचार — जो व्यक्ति इस \"धैर्य के दौर\" को अच्छी तरह समझ लेता है वह आगे चलकर कभी भी जल्दबाज़ी में आकर अपने बैग को नुक़सान नहीं पहुँचाता — यही संयम आगे के हर चक्र में भी उसके काम आता है।\n\n---\n---\n", "5": "# पाठ 5 — नन्ही कली (Primordia) कैसे बनती है\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 5\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप बहुत अच्छी तरह जानेंगे कि \"नन्ही कली\" यानी प्राइमोर्डिया आख़िर कैसे बनती है। आप यह भी अच्छी तरह जानेंगे कि इस पड़ाव पर पिछले पड़ाव से बिलकुल उलटा क्या काम करना पड़ता है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, जाल-फैलाव की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"कली-बनना सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> जब भी जाल पूरा फैल जाता है और उसे एक \"झटका\" यानी बदलाव मिलता है तो जगह-जगह छोटी-छोटी सफ़ेद \"गाँठें\" स्पष्ट रूप से उभरने लगती हैं — इन्हें \"कली\" (प्राइमोर्डिया) कहते हैं — यह पूरी कली पिन के सिर जैसी दिखती है और आगे चलकर धीरे-धीरे बढ़कर पूरा मशरूम बनती है।\n\n### 3. कली कैसे बनती है\n\nयहाँ एक \"झटका\" चाहिए — पाठ 4 की \"छेड़ना नहीं\" सीख के ठीक बिलकुल उलट — जब जाल पूरा फैल जाता है तब उसे \"ताज़ी हवा\" और \"हल्की रोशनी\" का एक \"झटका\" मिलना चाहिए — यही \"झटका\" जाल को यह पूरा \"संकेत\" देता है कि \"अब फल बनाने का सही समय आ चुका है।\" गाँठें जगह-जगह उभरती हैं — यह झटका मिलने के कुछ दिनों बाद पूरे जाल पर जगह-जगह छोटी-छोटी सफ़ेद गाँठें स्पष्ट रूप से दिखने लगती हैं — यही \"कली\" कहलाती है।\n\n### 4. पिछले पड़ाव से उलटा काम\n\nअँधेरे से हल्की रोशनी की तरफ़ — पाठ 4 की \"अँधेरा बनाए रखें\" सीख के ठीक उलट अब इस पड़ाव पर जाल को थोड़ी \"हल्की रोशनी\" देना ज़रूरी होता है। बंद और रुकी हुई हवा से ताज़ी और खुली हवा की तरफ़ — पाठ 4 की \"छेड़ना नहीं\" सीख के उलट अब बैग या कमरे में \"ताज़ी हवा\" यानी ऑक्सीजन आने देना बहुत ज़रूरी हो जाता है — यह पूरा और ज़रूरी बदलाव ही \"कली\" बनने को ट्रिगर करता है।\n\n### 5. यह जाल-फैलाव की सीख से कैसे आगे बढ़ता है\n\nपाठ 4 ने सिखाया कि जाल-फैलाव के पूरे दौरान \"अँधेरा गर्मी और न छेड़ना\" आख़िर कितना ज़रूरी है। यह पूरा पाठ उस समझ से आगे बढ़कर अब \"इसके ठीक उलट\" काम कब और क्यों करना है यह पूरी बात सिखाता है — यही इस पूरे जीवन-चक्र की सबसे दिलचस्प और ज़रूरी बात है — हर एक पड़ाव का अपना अलग नियम होता है।\n\n### 6. अपनी पहली, \"कली-बनना सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — पाठ 4 की \"अँधेरा-न-छेड़ना\" वाली सीख और आज की \"रोशनी-हवा\" वाली सीख में आख़िर क्या पूरा उलट-फेर है यह अपनी भाषा में स्पष्ट रूप से लिखिए।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">नन्ही कली कैसे बनती है</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">कैसे बनती है</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">एक \"झटका\" चाहिए</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">गाँठें जगह-जगह उभरती हैं</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">उलटा काम</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">अँधेरे से रोशनी की तरफ़</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">बंद से ताज़ी हवा की तरफ़</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">हर पड़ाव का अपना अलग नियम</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"कली-बनना हिस्सा\" जोड़िए — कैसे बनती है, उलटा काम अपनी भाषा में। फिर अपनी पहली \"कली-बनना सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मेरा बैग पूरा सफ़ेद हो गया है (लिखिए)। बताओ — अब \"कली\" बनाने के लिए मुझे क्या बदलाव करना चाहिए?*\n\nAI इसमें सामान्य और शुरुआती दिशा देने में मददगार है — असली और सटीक समय और हवा-रोशनी की मात्रा हमेशा अपने ख़ुद के अनुभव या उस्ताद से ही पुष्टि करें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"पिछले पड़ाव में तो अँधेरा और न-छेड़ना अच्छा था तो अब भी वही जारी रखना चाहिए\" — जबकि हर पड़ाव का अपना अलग नियम है — पिछले पड़ाव का नियम इस नए पड़ाव पर लागू करना कली बनने से रोक सकता है।**\n\n\"पिछला नियम ही, आगे भी हमेशा चलेगा\" सोचना, एक बड़ी भूल है। हमेशा हर एक पड़ाव के ठीक अलग नियम को अच्छी तरह समझें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| अँधेरा ही जारी रखना | सही समय पर हल्की रोशनी दें |\n| बंद हवा ही बनाए रखना | ताज़ी हवा आने दें |\n| झटका न देना | सही समय पर बदलाव करें |\n| कली-बनना हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"कली-बनना सोच\" न लिखना | पहले सोच लिखकर देखें |\n| जल्दी में झटका देना | पहले पूरा फैलाव सुनिश्चित करें |\n\n### 13. स्रोत\n\nकवक-प्राइमोर्डिया-निर्माण (कली-बनना) प्रक्रिया के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ \"नन्ही कली\" कैसे बनती है — मैं समझा सकता हूँ।\n☐ पिछले पड़ाव से उलटा क्या काम करना पड़ता है — मुझे साफ़ है।\n☐ यह जाल-फैलाव की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"पिछला नियम ही आगे भी चलेगा\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"कली-बनना सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — जब भी आप अपने बैग को पूरा सफ़ेद देखें तो इसे थोड़ी-सी ताज़ी हवा और हल्की रोशनी वाली जगह में धीरे-धीरे ले जाना शुरू करें — यही \"झटका\" आगे की कली बनाने में बहुत अच्छी मदद करेगा।\n\nएक आख़िरी सोच — यह \"उलट-फेर\" वाला सबक़ आगे भी कई बार दोहराया जाएगा — इस पूरी मशरूम-खेती में हर एक पड़ाव अपनी अलग \"भाषा\" बोलता है और एक अच्छे उगाने वाले को यह \"भाषा\" अच्छी तरह पहचाननी आनी चाहिए।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह \"कली-बनना\" वाला ज़रूरी बदलाव पूरे हब के साथ अच्छी तरह साझा करें — यह पूरी जानकारी सभी को सही समय पर सही काम करने में अच्छी मदद करेगी।\n\nएक अंतिम सुझाव — जब भी पहली बार आपको अपना \"कली\" दिखे तो उसकी सही तारीख़ अपनी नोटबुक में ज़रूर नोट करें — यह पूरी जानकारी आगे आपके \"औसत समय\" के हिसाब में बहुत काम आएगी।\n\nअंत में याद रखें कि यह पूरी कली-बनना की सोच अगले पाठ में सीखी जाने वाली \"फल-शरीर यानी जो हम खाते हैं\" की सीधी तैयारी है — जब कली बन जाती है तो यह बड़ी होकर पूरा मशरूम आख़िर कैसे बनती है यह अच्छी तरह समझना अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस प्रक्रिया में शामिल हों तो सबको \"हर पड़ाव का अलग नियम है\" वाली यह पूरी और ज़रूरी सोच बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी ग़लत समय पर ग़लत काम न करे।\n\nएक आख़िरी बात — यह पूरी, कली-बनना की सोच, दिखने में एक \"छोटी और तकनीकी\" बात ही लगती है, पर यह असल में, आपकी पूरी फ़सल की, सबसे बड़ी और महत्वपूर्ण शुरुआत है।\n\nएक और गहरी सोच — \"कली\" बनने का यह पूरा समय बहुत ज़्यादा \"संवेदनशील\" यानी नाज़ुक भी होता है — इस पूरे दौर में बहुत ज़्यादा तेज़ हवा या बहुत ज़्यादा नमी कली को आसानी से नुक़सान पहुँचा सकती है — इसलिए \"बदलाव\" तो ज़रूर करें पर इसे हमेशा \"संतुलित\" तरीक़े से ही करें।\n\nएक अंतिम विचार — जो कोई भी व्यक्ति यह पूरी तरह समझ लेता है कि \"हर पड़ाव के संकेत अलग-अलग हैं\" वह अपने बैग के साथ कभी भी \"एक-जैसा\" व्यवहार नहीं करता है — वह हर बार अपने बैग को ध्यान से देखकर यह पहचानता है कि \"आज इसे आख़िर क्या चाहिए\" और हमेशा उसी सही हिसाब से अपना ज़रूरी काम करता है।\n\n---\n---\n", "6": "# पाठ 6 — फल-शरीर यानी जो हम खाते हैं\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 6\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि \"फल-शरीर\" (जो हम तोड़कर खाते और बेचते हैं) कैसे बनता है। आप यह भी अच्छी तरह जानेंगे कि इसे \"फल\" क्यों कहा जाता है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, कली-बनना की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"फल-शरीर सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> \"कली\" तीन-चार दिन में बड़ी होकर पूरा मशरूम बन जाती है — डंठल निकलता है ऊपर टोपी खुलती है — यही हम तोड़ते हैं और बेचते हैं — यही \"फल-शरीर\" है ठीक वैसे ही जैसे आम के पेड़ पर \"आम\" लगता है — जाल \"पेड़\" है मशरूम इसका \"फल\" है।\n\n### 3. \"फल-शरीर\" क्यों कहा जाता है\n\nजाल असली \"जीव\" है — पाठ 3 की \"जाल असली शरीर है\" सीख की तरह ही जो सफ़ेद जाल बैग के भीतर फैला है वही असली जीव है — वह हफ़्तों तक चुपचाप बढ़ता रहता है। मशरूम इसका \"फल\" है — जो मशरूम हम तोड़ते हैं वह उस जाल का \"फल\" है — ठीक जैसे आम के पेड़ पर आम लगता है वैसे ही जाल पर मशरूम लगता है — इसीलिए एक ही बैग से कई-कई बार आपको फ़सल मिल सकती है।\n\n### 4. एक ही बैग से बार-बार फ़सल क्यों मिलती है\n\nजाल वहीं बना रहता है — क्योंकि यह पूरा \"जाल\" यानी असली जीव मरता बिलकुल नहीं है वह बार-बार फल दे सकता है बशर्ते उसे सही देखभाल मिलती रहे। मशरूम टूट जाए तो कोई बात नहीं — पाठ 4 की \"जाल को बचाना सबसे ज़रूरी\" सीख की तरह ही अगर मशरूम (फल-शरीर) तोड़ दिया जाए तो यह कोई बड़ी बात नहीं — असली \"जाल\" फिर से नई कली दे देगा — इसीलिए \"जाल को बचाना\" \"फल\" को बचाने से कहीं ज़्यादा ज़रूरी है।\n\n### 5. यह कली-बनना की सीख से कैसे आगे बढ़ता है\n\nपाठ 5 ने सिखाया कि \"कली\" कैसे बनती है। यह पूरा पाठ उस \"कली\" वाली समझ से आगे बढ़कर अब \"कली बड़ी होकर कैसे पूरा मशरूम बनती है\" — इस अगले ज़रूरी सवाल का जवाब देता है — यह पूरा हिस्सा इस चार-पड़ाव वाले पूरे चक्र का \"फल\" वाला हिस्सा है जो आपको असल में सीधी कमाई दिलाता है।\n\n### 6. अपनी पहली, \"फल-शरीर सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — \"जाल आम के पेड़ जैसा है और मशरूम आम जैसा है\" — इस तुलना को अपनी भाषा में समझाकर लिखिए जैसे आप किसी बच्चे को समझा रहे हों।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">फल-शरीर यानी जो हम खाते हैं</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">क्यों \"फल\" कहा जाता है</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जाल असली जीव है</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">मशरूम, इसका \"फल\" है</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">बार-बार फ़सल क्यों</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जाल वहीं बना रहता है</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">मशरूम टूटे, तो कोई बात नहीं</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">आम के पेड़ जैसी सोच — जाल पेड़, मशरूम फल</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"फल-शरीर हिस्सा\" जोड़िए — क्यों \"फल\" कहा जाता है, बार-बार फ़सल क्यों अपनी भाषा में। फिर अपनी पहली \"फल-शरीर सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे \"जाल\" और \"फल-शरीर\" के रिश्ते को आम के पेड़ और आम की तुलना से आसान तरीक़े से समझाओ।*\n\nAI सरल और आसान तुलनाओं से समझाने में काफ़ी मददगार है — असली और गहरी समझ हमेशा अपनी ख़ुद की नोटबुक में अच्छी तरह लिखकर ही बनती है।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"एक बार मशरूम तोड़ लिया तो बैग का काम ख़त्म हो गया\" — जबकि असली \"जाल\" अभी भी बैग के अंदर ज़िंदा है और सही देखभाल मिलने पर फिर से नई कली दे सकता है — यह ग़लतफ़हमी आपको कई संभावित फ़सलों से वंचित कर सकती है।**\n\n\"मशरूम तोड़ते ही बैग का पूरा काम ख़त्म\" सोचना एक बहुत महंगी भूल है। हमेशा याद रखें अगर \"जाल\" ज़िंदा है तो अगली फ़सल भी पूरी तरह संभव है।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| तोड़ने के बाद बैग फेंक देना | जाल ज़िंदा हो तो देखभाल जारी रखें |\n| \"फल\" को ही \"पूरा जीव\" मानना | \"जाल\" को असली जीव मानें |\n| सही समय पर न तोड़ना (आगे पाठ) | सही समय पहचानना सीखें |\n| फल-शरीर हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"फल-शरीर सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nकवक-फल-शरीर (फ़्रूटिंग-बॉडी) निर्माण के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ \"फल-शरीर\" कैसे, बनता है — मैं समझा सकता हूँ।\n☐ इसे \"फल\" क्यों कहा जाता है — मुझे साफ़ है।\n☐ यह कली-बनना की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"मशरूम तोड़ते ही बैग का काम ख़त्म\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"फल-शरीर सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — जब आप पहली बार मशरूम तोड़ें तो बैग को फेंकने की बजाय फिर से सही देखभाल (हल्की नमी हवा) देते रहें — ध्यान से देखें कि क्या वह पूरा बैग फिर से नई कली देता है।\n\nएक आख़िरी सोच — यह \"आम के पेड़ जैसी\" तुलना सिर्फ़ समझने के लिए नहीं — यह आपको यह भी सिखाती है कि \"पेड़\" (जाल) की देखभाल \"फल\" (मशरूम) से ज़्यादा ज़रूरी है — यही सोच आगे हर फ़ैसले में काम आएगी।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो \"एक ही बैग से बार-बार फ़सल\" वाली यह पूरी सीख हब के सभी सदस्यों के साथ अच्छी तरह साझा करें — यह पूरी सीख सभी को अपनी कुल लागत बहुत हद तक कम करने में मदद कर सकती है।\n\nएक अंतिम सुझाव — अपनी पहली फ़सल के बाद अपनी नोटबुक में नोट करें — \"कितने दिन में दूसरी फ़सल आई\" — यह पूरी जानकारी आगे आपके पूरे धंधे की योजना बनाने में बहुत बड़ा काम आएगी।\n\nअंत में याद रखें कि यह पूरी फल-शरीर की सोच अगले पाठ में सीखी जाने वाली \"यह चक्र समझने से हर फ़ैसला आसान क्यों हो जाता है\" की सीधी तैयारी है — जब आप पूरा चक्र समझ लें तो इसका \"सार\" समझना अगला स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस प्रक्रिया में शामिल हों तो सबको \"जाल पेड़ है मशरूम फल है\" वाली यह पूरी और सरल तुलना बहुत स्पष्ट रूप से समझाएँ ताकि सभी एक-जैसी समझ के साथ आगे बढ़ें।\n\nएक आख़िरी बात — यह पूरी फल-शरीर की सोच दिखने में एक \"साधारण\" बात लगती है पर यह असल में आपकी पूरी कमाई का सीधा स्रोत समझने वाली सबसे ज़रूरी और बुनियादी सीख है।\n\nएक और गहरी सोच — जब आप आगे \"फ़सल-चक्र\" (कितनी बार फ़सल मिलती है) के बारे में सीखेंगे तो यह \"जाल-वहीं-बना-रहता-है\" वाली समझ आपको यह अंदाज़ा लगाने में मदद करेगी कि \"एक बैग से मुझे कुल कितनी कमाई हो सकती है।\"\n\nएक अंतिम विचार — जो व्यक्ति \"जाल\" की देखभाल को \"फल\" से ज़्यादा महत्व देना सीख लेता है वह आगे चलकर हमेशा ज़्यादा कमाई करता है — क्योंकि वह एक ही बैग से कई बार फ़सल ले पाता है जबकि \"जाल\" को नज़रअंदाज़ करने वाला व्यक्ति सिर्फ़ एक ही बार में संतोष कर लेता है।\n\n---\n---\n", "7": "# पाठ 7 — यह चक्र समझने से हर फ़ैसला आसान क्यों हो जाता है\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि पूरा जीवन-चक्र (पाठ 2-6) समझ लेने से आपके आगे के हर फ़ैसले कैसे आसान हो जाते हैं। आप यह भी अच्छी तरह जानेंगे कि \"समस्या-निदान\" (कहाँ गड़बड़ी हुई) कैसे आसान बनता है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, फल-शरीर की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"पूरा-चक्र सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> अब तक आपने चार-पड़ाव वाला पूरा चक्र — बीजाणु जाल कली और फल-शरीर — सीख लिया है। यह पूरा अध्याय का आख़िरी और \"जोड़ने वाला\" पाठ है — यहाँ हम यह पूरी तरह देखते हैं कि यह \"पूरी और गहरी समझ\" आपको \"समस्या कहाँ है\" और \"आगे क्या करना है\" यह तय करने में कैसे मदद करती है।\n\n### 3. समस्या-निदान आसान क्यों हो जाता है\n\nहर एक पड़ाव की अपनी अलग \"पहचान\" है — पाठ 2 की \"पहिया कहाँ टूटता है\" सीख की तरह ही अगर आपका बैग सफ़ेद नहीं हो रहा तो समस्या \"जाल-फैलाव\" पड़ाव में है — अगर कली नहीं निकल रही तो समस्या \"कली-बनना\" पड़ाव में है। \"कहाँ हूँ\" पूछना आसान हो जाता है — पूरे चक्र को अच्छी तरह समझने के बाद आप ख़ुद से सिर्फ़ एक सवाल पूछकर अपनी समस्या पकड़ सकते हैं — \"अभी मेरा बैग इन चार पड़ावों में से किस पड़ाव पर है और उसे अभी क्या चाहिए।\"\n\n### 4. फ़ैसले आसान क्यों हो जाते हैं\n\nहर पड़ाव का \"नियम\" पहले से पता है — पाठ 4-5 की \"उलटे नियम\" सीख की तरह ही बिना इस चक्र को समझे आप हर बार \"अंदाज़े\" से काम करेंगे — इस चक्र को समझने के बाद आप हर पड़ाव पर \"सही समय पर सही काम\" पहले से जानते हैं। घबराहट की जगह \"स्पष्टता\" — नए उगाने वालों को अकसर हर छोटी समस्या पर घबराहट होती है — पूरा चक्र समझने के बाद यह घबराहट \"स्पष्ट समझ\" में आसानी से बदल जाती है — \"यह तो बस इस पड़ाव की बात है\" — यह पूरी सोच आपको हमेशा शांत रखती है।\n\n### 5. यह फल-शरीर की सीख से कैसे आगे बढ़ता है\n\nपाठ 6 ने सिखाया कि \"फल-शरीर\" कैसे बनता है और यह आख़िरी पड़ाव है। यह पूरा पाठ अब इन सभी चार पड़ावों को एक साथ \"जोड़कर\" देखने का काम करता है — यह कोई \"नई\" जानकारी नहीं बल्कि पिछले पाँच पाठों की \"संगठित समझ\" है जो आगे के हर तकनीकी पाठ की नींव बनेगी।\n\n### 6. अपनी पहली, \"पूरा-चक्र सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में चारों पड़ावों को एक साथ एक \"क्रम\" में फिर से लिखें और हर पड़ाव के आगे यह लिखें कि \"अगर यहाँ समस्या हो तो इसका मतलब क्या हो सकता है।\"\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"38\" text-anchor=\"middle\" font-size=\"18\" fill=\"#0B1F3A\" font-weight=\"bold\">पूरा चक्र समझने से हर फ़ैसला आसान क्यों</text>\n<rect x=\"40\" y=\"65\" width=\"345\" height=\"235\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"100\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">समस्या-निदान आसान</text>\n<text x=\"212\" y=\"135\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">हर पड़ाव की अपनी पहचान</text>\n<text x=\"212\" y=\"161\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">\"कहाँ हूँ\" पूछना आसान</text>\n<rect x=\"415\" y=\"65\" width=\"345\" height=\"235\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"100\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">फ़ैसले आसान</text>\n<text x=\"587\" y=\"135\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">हर पड़ाव का नियम पहले पता</text>\n<text x=\"587\" y=\"161\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">घबराहट की जगह स्पष्टता</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">पूरी समझ, हर फ़ैसले की कुंजी</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"पूरा-चक्र हिस्सा\" जोड़िए — समस्या-निदान आसान, फ़ैसले आसान अपनी भाषा में। फिर अपनी पहली \"पूरा-चक्र सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे पूरा चार-पड़ाव वाला जीवन-चक्र याद कराओ और हर पड़ाव के साथ यह बताओ कि \"अगर यहाँ समस्या हो तो इसका क्या मतलब हो सकता है।\"*\n\nAI इस पूरी और गहरी समझ को दोहराने में काफ़ी मददगार है — असली अपनी ख़ुद की समस्या को हल करने के लिए हमेशा अपने अनुभव और उस्ताद की मदद भी लें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मुझे हर चीज़ याद नहीं रखनी बस जब समस्या आएगी तब देख लूँगा/लूँगी\" — जबकि अगर पूरा चक्र पहले से स्पष्ट न हो तो समस्या आने पर आप घबराकर ग़लत फ़ैसला ले सकते हैं — पहले से तैयार रहना हमेशा बेहतर होता है।**\n\n\"बाद में देख लूँगा/लूँगी\" सोचना एक जोखिम भरी भूल है। हमेशा पहले से पूरा चक्र स्पष्ट रखें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| \"बाद में देख लूँगा\" सोचना | पहले से पूरा चक्र स्पष्ट रखें |\n| समस्या आने पर घबरा जाना | शांत रहकर पड़ाव पहचानें |\n| हर पड़ाव को अलग-अलग याद रखना | इन्हें एक \"जुड़ी कहानी\" की तरह याद रखें |\n| पूरा-चक्र हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"पूरा-चक्र सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nकवक-जीवन-चक्र आधारित समस्या-निदान (डायग्नोसिस) के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ पूरा जीवन-चक्र समझ लेने से आगे के फ़ैसले कैसे आसान हो जाते हैं — मैं समझा सकता हूँ।\n☐ \"समस्या-निदान\" कैसे आसान बनता है — मुझे साफ़ है।\n☐ यह फल-शरीर की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"बाद में देख लूँगा\" सोचना क्यों जोखिम भरा है।\n☐ मैंने अपनी पहली, \"पूरा-चक्र सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — इस पूरे चक्र को हर कुछ दिनों में दोहराते रहें जब तक यह आपकी \"आदत\" न बन जाए — जैसे आप कोई कहानी याद करते हैं वैसे ही इसे याद करें।\n\nएक आख़िरी सोच — यह \"जोड़ने\" वाली समझ सिर्फ़ \"समस्या हल\" करने के लिए नहीं — यह पूरी समझ आपको आगे अध्याय-2 में \"कौन-सा मशरूम चुनें\" जैसे बड़े फ़ैसले लेने में भी एक बहुत मज़बूत आधार देती है।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह पूरा चक्र पूरे हब के साथ मिलकर दोहराएँ — जब सब लोग एक ही \"भाषा\" समझते हैं तो आपसी बातचीत भी बहुत आसान हो जाती है।\n\nएक अंतिम सुझाव — इस चक्र को अपने घर में कहीं ऐसी जगह लिखकर चिपकाएँ जहाँ आप रोज़ देखते हों — यह पूरी सूची आपको बार-बार याद दिलाती रहेगी।\n\nअंत में, याद रखें कि यह पूरी, चक्र-समझ की सोच, अगले पाठ में सीखी जाने वाली \"दुनिया में हर साल कितना मशरूम पैदा होता है\" की सीधी तैयारी है — जब, आप, \"यह पूरी तरह कैसे उगता है\" समझ लें, तो, \"दुनिया में, आख़िर कितना उगता है\", यह अच्छी तरह समझना, अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"पूरा चक्र एक साथ\" वाली यह पूरी और ज़रूरी सोच बहुत स्पष्ट रूप से समझाएँ ताकि सभी एक-जैसी स्पष्ट समझ के साथ आगे बढ़ें।\n\nएक आख़िरी बात — यह पूरी चक्र-समझ की सोच दिखने में एक \"दोहराव\" जैसी बात लगती है पर यह असल में आपके आगे के पूरे धंधे की सबसे मज़बूत और ज़रूरी नींव है।\n\nएक और गहरी सोच — जब भी आगे कोई नई तकनीकी जानकारी सीखें तो उसे इसी चार-पड़ाव वाले चक्र के \"किसी एक पड़ाव\" से जोड़कर देखें — इससे नई जानकारी को याद रखना बहुत आसान हो जाएगा।\n\nएक अंतिम विचार — जो व्यक्ति इस पूरे चक्र को अपनी \"दूसरी प्रकृति\" (आदत जैसी) बना लेता है वह आगे चलकर कभी भी किसी समस्या से डरता नहीं — क्योंकि उसे हमेशा पता होता है कि \"समाधान कहाँ ढूँढ़ना है।\"\n\n---\n---\n", "8": "# पाठ 8 — दुनिया में हर साल कितना मशरूम पैदा होता है — स्रोत-वर्ष सहित\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 8\n**सुरक्षा:** 🟢 सामान्य · **काम:** «देखो» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि दुनिया में हर साल कितना मशरूम पैदा होता है। आप यह भी अच्छी तरह जानेंगे कि इन आँकड़ों को \"स्रोत-वर्ष\" के साथ क्यों देखना ज़रूरी है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, पूरा-चक्र की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"वैश्विक-बाज़ार सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> मशरूम की खेती अब दुनिया भर में एक बहुत बड़ा उद्योग बन चुकी है — करोड़ों टन मशरूम हर साल दुनिया भर में उगाई जाती है। **यह संख्या समय के साथ बढ़ती रहती है इसलिए इस कोर्स में कोई भी दिया गया आँकड़ा हमेशा \"उस समय का\" (स्रोत-वर्ष सहित) है — ताज़ा संख्या के लिए हमेशा आधिकारिक स्रोत ही देखें।**\n\n### 3. दुनिया में मशरूम उत्पादन की स्थिति\n\nएक बड़ा और बढ़ता उद्योग — पाठ 590 की \"आँकड़े कभी स्थिर नहीं\" सीख की तरह ही (आगे इस कोर्स में यह नियम बार-बार दोहराया जाएगा) मशरूम का वैश्विक उत्पादन हर साल बढ़ रहा है — यह पूरा बढ़ता उद्योग दिखाता है कि इस धंधे में बढ़ने की बहुत बड़ी संभावना है। \"स्रोत-वर्ष\" क्यों ज़रूरी है — जब भी आप कहीं यह पढ़ें कि \"दुनिया में इतना मशरूम उगता है\" तो यह ज़रूर देखें कि यह आँकड़ा \"किस साल\" का है — पुराना आँकड़ा आज की असली स्थिति नहीं बता सकता।\n\n### 4. यह संख्या आपके लिए क्या मायने रखती है\n\nएक बड़ा अवसर — यह पूरा और बड़ा बढ़ता उद्योग दिखाता है कि अगर आप अच्छी गुणवत्ता का मशरूम उगाएँ तो बाज़ार में अपनी जगह बनाने की बहुत बड़ी संभावना है। \"स्थानीय\" आँकड़े भी ज़रूरी हैं — पाठ 12 में आगे आप ख़ुद अपने ज़िले का बाज़ार-भाव इकट्ठा करेंगे — \"वैश्विक\" आँकड़े सिर्फ़ \"बड़ी तस्वीर\" दिखाते हैं असली फ़ैसला हमेशा \"स्थानीय\" जानकारी से ही लें।\n\n### 5. यह पूरा-चक्र की सीख से कैसे आगे बढ़ता है\n\nपाठ 7 ने सिखाया कि \"कैसे उगता है\" यह समझने से फ़ैसले कैसे आसान होते हैं। यह पूरा पाठ उस \"कैसे\" वाली तकनीकी समझ से आगे बढ़कर अब \"कितना बड़ा बाज़ार है\" — इस व्यावसायिक सवाल का जवाब देता है — दोनों बातें मिलकर आपको यह समझने में मदद करती हैं कि \"क्या यह धंधा मेरे लिए सही है।\"\n\n### 6. «देखो» — अपनी पहली, \"वैश्विक-बाज़ार सोच\" लिखना\n\nयह «देखो» पाठ है — इसका मक़सद आपको इस बड़े बाज़ार से परिचित कराना है न कि अभी इसे \"याद\" कराना। अपनी नोटबुक में लिखें — यह जानकर कि मशरूम का वैश्विक उद्योग इतना बड़ा है आपकी इस धंधे के बारे में सोच कैसे बदली।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">दुनिया में मशरूम — स्रोत-वर्ष सहित</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">क्यों स्रोत-वर्ष ज़रूरी</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">आँकड़े हर साल बढ़ते हैं</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">पुराना आँकड़ा, आज सही नहीं</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">आपके लिए मायने</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">बड़ा, बढ़ता अवसर</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">स्थानीय आँकड़े भी ज़रूरी</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">बड़ी तस्वीर, हमेशा ताज़ा स्रोत से</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"वैश्विक-बाज़ार हिस्सा\" जोड़िए — क्यों स्रोत-वर्ष ज़रूरी, आपके लिए मायने अपनी भाषा में। फिर अपनी पहली \"वैश्विक-बाज़ार सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे दुनिया में मशरूम उत्पादन के बारे में ताज़ा आँकड़े बताओ और यह भी बताओ कि यह \"किस साल\" का आँकड़ा है।*\n\n**⚠️ ज़रूरी सावधानी:** AI कभी भी \"यह आँकड़ा अंतिम सच\" जैसा दावा न करे — यह सिर्फ़ सामान्य दिशा दे सकता है — असली और ताज़ा आँकड़े हमेशा आधिकारिक स्रोत से ही अच्छी तरह पुष्टि करें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मुझे कहीं से एक आँकड़ा मिल गया वह हमेशा सच रहेगा\" — जबकि यह आँकड़े हर साल बदलते हैं — पुराने आँकड़े पर भरोसा करके फ़ैसला लेना आपको ग़लत दिशा में ले जा सकता है।**\n\n\"एक बार मिला आँकड़ा हमेशा सच रहेगा\" सोचना एक भूल है। हमेशा ताज़ा आँकड़े ढूँढ़ें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| पुराने आँकड़े पर भरोसा करना | हमेशा ताज़ा आँकड़े ढूँढ़ें |\n| \"स्रोत-वर्ष\" न देखना | हमेशा स्रोत-वर्ष ज़रूर देखें |\n| सिर्फ़ \"वैश्विक\" आँकड़े पर फ़ैसला लेना | \"स्थानीय\" जानकारी भी ज़रूर लें |\n| वैश्विक-बाज़ार हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"वैश्विक-बाज़ार सोच\" न लिखना | पहले सोच लिखकर देखें |\n| AI के आँकड़े को बिना जाँचे मानना | हमेशा आधिकारिक स्रोत से पुष्टि करें |\n\n### 13. स्रोत\n\nवैश्विक मशरूम-उत्पादन-रुझान (ट्रेंड) के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026। **सटीक ताज़ा वैश्विक उत्पादन-संख्या के लिए हमेशा आधिकारिक अंतरराष्ट्रीय कृषि-संगठन की वेबसाइट से ही पुष्टि करें।**\n\n### 14. योग्यता-जाँच\n\n☐ दुनिया में हर साल कितना मशरूम पैदा होता है — मैं समझा सकता हूँ।\n☐ इन आँकड़ों को \"स्रोत-वर्ष\" के साथ क्यों देखना ज़रूरी है — मुझे साफ़ है।\n☐ यह पूरा-चक्र की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"एक बार मिला आँकड़ा हमेशा सच\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"वैश्विक-बाज़ार सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — जब भी आप कहीं \"मशरूम बाज़ार\" के बारे में कोई आँकड़ा पढ़ें चाहे वह अख़बार में हो या इंटरनेट पर हमेशा यह देखने की आदत डालें कि \"यह किस साल की बात है।\"\n\nएक आख़िरी सोच — यह \"बड़ा वैश्विक बाज़ार\" सिर्फ़ बड़ी कंपनियों के लिए नहीं — छोटे गाँव के उगाने वाले भी इस बढ़ते बाज़ार का हिस्सा बन सकते हैं ख़ासकर \"स्थानीय ताज़ा\" मशरूम के ज़रिए।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह \"बड़ी तस्वीर\" पूरे हब के साथ साझा करें — यह पूरी बात सभी को यह अच्छी तरह समझने में मदद करती है कि \"हम सब एक बड़े और बढ़ते उद्योग का हिस्सा हैं।\"\n\nएक अंतिम सुझाव — अपनी अलग नोटबुक में एक \"आँकड़ा-पन्ना\" बनाएँ जहाँ आप समय-समय पर नए आँकड़े (स्रोत-वर्ष सहित) नोट करते रहें — यह पूरी सूची आगे आपके धंधे की योजना बनाने में बहुत काम आएगी।\n\nअंत में याद रखें कि यह पूरी वैश्विक-बाज़ार की सोच अगले पाठ में सीखी जाने वाली \"बटन ऑयस्टर और शिटाके का वैश्विक बाज़ार\" की सीधी तैयारी है — जब आप \"कुल कितना\" समझ लें तो \"कौन-सी प्रजाति आख़िर सबसे ज़्यादा बिकती है\" यह अच्छी तरह समझना अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"हमेशा स्रोत-वर्ष देखें\" वाली यह पूरी और ज़रूरी आदत बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी बासी आँकड़े पर भरोसा न करे।\n\nएक आख़िरी बात — यह पूरी वैश्विक-बाज़ार की सोच दिखने में एक \"बड़ी दूर की\" बात लगती है पर यह असल में आपके छोटे धंधे को एक बड़े और बढ़ते अवसर से जोड़ने वाली सबसे प्रेरक सीख है।\n\nएक और गहरी सोच — यह \"बड़ा बाज़ार\" सिर्फ़ \"प्रेरणा\" के लिए नहीं — यह आपको यह भी समझने में मदद करता है कि अगर आप कभी अपना धंधा बढ़ाना चाहें (जैसे अध्याय-9 हब बनाना) तो इस बड़े बाज़ार में बढ़ने की पूरी गुंजाइश है।\n\nएक अंतिम विचार — जो व्यक्ति \"वैश्विक\" और \"स्थानीय\" दोनों आँकड़ों को साथ में देखता है वह ज़्यादा संतुलित और समझदार फ़ैसले ले पाता है — सिर्फ़ \"बड़ी तस्वीर\" या सिर्फ़ \"अपने गाँव की बात\" — दोनों ही अकेले काफ़ी नहीं हैं।\n\n---\n---\n", "9": "# पाठ 9 — बटन, ऑयस्टर और शिटाके का वैश्विक बाज़ार\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि \"बटन\" \"ऑयस्टर\" और \"शिटाके\" — यह तीन मशरूम प्रजातियाँ दुनिया भर में इतनी लोकप्रिय क्यों हैं। आप यह भी अच्छी तरह जानेंगे कि इनमें से हर एक की क्या अलग ख़ासियत है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, वैश्विक-बाज़ार की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"तीन-प्रजाति सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> दुनिया भर में उगाई जाने वाली सैकड़ों-सैकड़ों मशरूम प्रजातियों में से \"बटन\" \"ऑयस्टर\" (धिंगरी) और \"शिटाके\" — यह तीन सबसे ज़्यादा उगाई और बेची जाने वाली प्रजातियाँ हैं — हर एक की अपनी बिलकुल अलग-अलग \"ख़ासियत\" यानी विशेषता शक्ल और अपना बाज़ार है।\n\n### 3. \"बटन\" और \"ऑयस्टर\" — दो आम प्रजातियाँ\n\n\"बटन\" मशरूम — सबसे जाना-पहचाना — यह पूरा वही सफ़ेद और गोल मशरूम है जो आमतौर पर बड़े शहरों के बाज़ारों में सबसे ज़्यादा दिखता है — इसे ठंडे तापमान की बहुत ज़्यादा ज़रूरत होती है और इसकी खेती में अकसर \"कम्पोस्ट\" यानी खाद-मिश्रण इस्तेमाल किया जाता है। \"ऑयस्टर\" (धिंगरी) — आसान और तेज़ — यह प्रजाति अकसर नए उगाने वालों के लिए सबसे आसान मानी जाती है — इसे बहुत कम तापमान-नियंत्रण चाहिए और यह पुआल या भूसे पर बहुत आसानी से उग जाती है।\n\n### 4. \"शिटाके\" — एक ख़ास महँगी प्रजाति\n\nलकड़ी पर उगने वाली — पाठ 1-6 की \"जाल लकड़ी या पुआल में पचता है\" सीख की तरह ही \"शिटाके\" मशरूम ख़ासकर \"लकड़ी\" यानी लॉग या \"चूरा\" पर ध्यान से उगाई जाती है — इसे तैयार होने में ज़्यादा समय लगता है पर इसका दाम भी अकसर बहुत ज़्यादा मिलता है। स्वाद और औषधीय गुणों के लिए जाना-जाता है — शिटाके को पूरी दुनिया में इसके ख़ास स्वाद और स्वास्थ्य-लाभ के लिए भी बहुत पसंद किया जाता है — यह पूरी बात इसे हमेशा \"प्रीमियम\" यानी ऊँचे-दाम वाली श्रेणी में रखती है।\n\n### 5. यह वैश्विक-बाज़ार की सीख से कैसे आगे बढ़ता है\n\nपाठ 8 ने सिखाया कि दुनिया में \"कुल कितना\" मशरूम उगता है। यह पूरा पाठ उस \"कुल\" संख्या से आगे बढ़कर अब \"किन-किन प्रजातियों\" से यह संख्या बनती है — इस अगले ज़रूरी सवाल का जवाब देता है — यह पूरी समझ आपको आगे अध्याय-2 में \"मेरे लिए कौन-सा मशरूम\" चुनने में सीधे बहुत मदद करेगी।\n\n### 6. अपनी पहली, \"तीन-प्रजाति सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में \"बटन\" \"ऑयस्टर\" और \"शिटाके\" — तीनों को एक-एक वाक्य में उनकी सबसे बड़ी ख़ासियत के साथ लिखिए।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"38\" text-anchor=\"middle\" font-size=\"18\" fill=\"#0B1F3A\" font-weight=\"bold\">बटन, ऑयस्टर, शिटाके — वैश्विक बाज़ार</text>\n<rect x=\"30\" y=\"65\" width=\"228\" height=\"200\" fill=\"#0B1F3A\" rx=\"8\"/>\n<text x=\"144\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">बटन</text>\n<text x=\"144\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">सबसे जाना-पहचाना</text>\n<text x=\"144\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">ठंडा तापमान, कम्पोस्ट</text>\n<rect x=\"286\" y=\"65\" width=\"228\" height=\"200\" fill=\"#1565C0\" rx=\"8\"/>\n<text x=\"400\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">ऑयस्टर</text>\n<text x=\"400\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">आसान, नए उगाने वालों के लिए</text>\n<text x=\"400\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">पुआल-भूसे पर उगती है</text>\n<rect x=\"542\" y=\"65\" width=\"228\" height=\"200\" fill=\"#2E7D32\" rx=\"8\"/>\n<text x=\"656\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">शिटाके</text>\n<text x=\"656\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">लकड़ी पर, प्रीमियम दाम</text>\n<text x=\"656\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">स्वाद-औषधीय गुण</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">हर प्रजाति की अपनी अलग ख़ासियत</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"तीन-प्रजाति हिस्सा\" जोड़िए — बटन-ऑयस्टर, शिटाके अपनी भाषा में। फिर अपनी पहली \"तीन-प्रजाति सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे \"बटन\" \"ऑयस्टर\" और \"शिटाके\" मशरूम के बीच का फ़र्क़ एक सरल तालिका में समझाओ।*\n\nAI इसमें तुलनात्मक और स्पष्ट तालिका बनाने में काफ़ी मददगार है — असली और अंतिम फ़ैसला अपने ख़ुद के इलाक़े के हिसाब से अध्याय-2 में गहराई से सीखकर ही लें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"जो प्रजाति सबसे महँगी बिकती है (जैसे शिटाके) वही सबसे अच्छी चुनाव है\" — बिना यह सोचे कि \"क्या मेरे पास इसे उगाने के लिए सही मौसम कच्चा-माल और समय है\" — जबकि हर प्रजाति की अपनी अलग ज़रूरतें हैं और \"महँगी\" होना ही \"आसान या सही\" होने की गारंटी नहीं है।**\n\n\"सबसे महँगी प्रजाति ही सबसे अच्छी है\" सोचना एक अधूरी भूल है। हमेशा अपनी ख़ुद की परिस्थिति के हिसाब से प्रजाति चुनें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| \"सबसे महँगी प्रजाति\" को ही \"सबसे अच्छी\" मानना | अपनी परिस्थिति के हिसाब से चुनें |\n| तीनों प्रजातियों को \"एक-जैसा\" मानना | हर प्रजाति की अलग ज़रूरत समझें |\n| बिना जानकारी के \"शिटाके\" जैसी कठिन प्रजाति चुनना | पहले अध्याय-2 में गहराई से समझें |\n| तीन-प्रजाति हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"तीन-प्रजाति सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nबटन, ऑयस्टर व शिटाके मशरूम-प्रजातियों की सामान्य विशेषताओं के शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ \"बटन\" \"ऑयस्टर\" और \"शिटाके\" — यह तीन प्रजातियाँ इतनी लोकप्रिय क्यों हैं — मैं समझा सकता हूँ।\n☐ इनमें से हर एक की क्या अलग ख़ासियत है — मुझे साफ़ है।\n☐ यह वैश्विक-बाज़ार की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"सबसे महँगी प्रजाति ही सबसे अच्छी\" सोचना क्यों ग़लत है।\n☐ मैंने अपनी पहली, \"तीन-प्रजाति सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — अपने नज़दीकी बाज़ार में ख़ुद जाकर देखें कि इनमें से कौन-सी प्रजातियाँ बिकती हैं और किस दाम पर बिकती हैं — यह पूरा अनुभव आपको अध्याय-2 की \"कौन-सा मशरूम\" वाली सीख में बहुत बड़ी मदद करेगा।\n\nएक आख़िरी सोच — यह पूरी तरह ज़रूरी नहीं है कि, आपको, सिर्फ़ इन तीन प्रजातियों में से ही, चुनना हो — दुनिया में, कई और भी प्रजातियाँ मौजूद हैं — यह तीन, सिर्फ़, \"सबसे आम और शुरुआती-दोस्ताना\" उदाहरण ही हैं।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह पूरी तरह संभव है कि हब के अलग-अलग सदस्य अलग-अलग प्रजातियाँ उगाएँ और फिर सब मिलकर एक बड़ी \"विविध\" उत्पाद-सूची पूरे बाज़ार में पेश करें।\n\nएक अंतिम सुझाव — इन तीनों प्रजातियों की अलग-अलग फ़ोटो अगर संभव हो तो इंटरनेट या किसी किताब में ध्यान से देखें — इससे आपको इन्हें आसानी से पहचानने में बहुत मदद मिलेगी जब आप बाज़ार में जाएँगे।\n\nअंत में याद रखें कि यह पूरी तीन-प्रजाति की सोच अगले पाठ में सीखी जाने वाली \"ताज़ा सूखा पाउडर और विशेष — चार अलग बाज़ार\" की सीधी तैयारी है — जब आप \"कौन-सी प्रजाति\" है यह समझ लें तो \"किस रूप में\" आख़िर बेची जाती है यह अच्छी तरह समझना अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"हर प्रजाति की अलग-अलग ज़रूरत है\" वाली यह पूरी और ज़रूरी सोच बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी ग़लत प्रजाति न चुने।\n\nएक आख़िरी बात — यह पूरी तीन-प्रजाति की सोच दिखने में एक \"साधारण जानकारी\" जैसी बात लगती है पर यह असल में आपके आगे के \"कौन-सा मशरूम चुनें\" वाले सबसे बड़े फ़ैसले की पहली और ज़रूरी नींव है।\n\nएक और गहरी सोच — याद रखें यह सिर्फ़ \"तीन\" प्रजातियाँ हैं — दुनिया में सैकड़ों अलग-अलग मशरूम प्रजातियाँ हैं जिनमें से कुछ \"औषधीय\" (जैसे रेइशी) भी हैं — यह कोर्स आगे मुख्य रूप से इन्हीं तीन आम प्रजातियों पर केंद्रित रहेगा।\n\nएक अंतिम विचार — जो व्यक्ति \"प्रजाति-चुनाव\" को सिर्फ़ \"दाम\" से नहीं बल्कि \"अपनी ख़ुद की तैयारी बाज़ार और मौसम\" से जोड़कर सोचता है वह आगे चलकर एक ज़्यादा टिकाऊ और सफल धंधा खड़ा कर पाता है।\n\n---\n---\n", "10": "# पाठ 10 — ताज़ा, सूखा, पाउडर और विशेष — चार अलग बाज़ार\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 10\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप बहुत अच्छी तरह जानेंगे कि मशरूम को \"ताज़ा सूखा पाउडर और विशेष\" — इन चार अलग रूपों में बेचा जा सकता है। आप यह भी अच्छी तरह जानेंगे कि हर रूप का अपना अलग बाज़ार क्यों है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, तीन-प्रजाति की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"चार-बाज़ार सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> एक ही मशरूम को चार पूरी तरह अलग-अलग \"रूपों\" में बेचा जा सकता है — \"ताज़ा\" (जैसा तोड़ा वैसा ही) \"सूखा\" (पानी निकालकर) \"पाउडर\" (पीसकर) और \"विशेष\" (जैसे अचार या दवा-जैसे उत्पाद) — हर एक रूप का अपना अलग ग्राहक अपना अलग दाम और अपनी अलग-अलग \"उम्र\" यानी कितने दिन टिकता है भी है।\n\n### 3. \"ताज़ा\" और \"सूखा\" — दो मुख्य रूप\n\n\"ताज़ा\" — सबसे आम पर जल्दी ख़राब — पाठ 11 में आगे गहराई से सीखेंगे — यह पूरा सबसे ज़्यादा बिकने वाला रूप है पर इसकी \"उम्र\" हमेशा सबसे कम होती है — इसलिए इसे बहुत जल्दी बेचना ज़रूरी होता है। \"सूखा\" — लंबी उम्र नया बाज़ार — मशरूम से अच्छी तरह पानी निकालकर इसे \"सूखा\" बनाया जा सकता है — यह पूरा उत्पाद कई महीनों तक टिक सकता है और दूर के कई बाज़ारों में भी आसानी से भेजा जा सकता है।\n\n### 4. \"पाउडर\" और \"विशेष\" — दो नए अवसर\n\n\"पाउडर\" — रसोई और स्वास्थ्य बाज़ार — सूखे मशरूम को अच्छी तरह पीसकर पाउडर बनाया जा सकता है — इसे खाने में मिलाना बहुत आसान होता है और इसकी \"उम्र\" भी और भी ज़्यादा लंबी होती है। \"विशेष\" उत्पाद — नई संभावनाएँ — पाठ 608-618 में आगे गहराई से सीखेंगे — मशरूम से अचार सूप-मसाला या अन्य \"मूल्य-वर्धित\" यानी वैल्यू-ऐडेड उत्पाद भी आसानी से बनाए जा सकते हैं जिनसे ज़्यादा कमाई हो सकती है।\n\n### 5. यह तीन-प्रजाति की सीख से कैसे आगे बढ़ता है\n\nपाठ 9 ने सिखाया कि \"कौन-सी प्रजाति\" यानी बटन ऑयस्टर शिटाके पूरी दुनिया में आख़िर लोकप्रिय है। यह पूरा पाठ उस \"प्रजाति\" वाली समझ से आगे बढ़कर अब \"उसी प्रजाति को किस रूप में बेचें\" — इस ज़रूरी अगले सवाल का जवाब देता है — एक ही मशरूम कई-कई अलग-अलग तरीक़ों से आपको कमाई दिला सकता है।\n\n### 6. अपनी पहली, \"चार-बाज़ार सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में \"ताज़ा\" \"सूखा\" \"पाउडर\" और \"विशेष\" — चारों रूपों को एक-एक वाक्य में उनकी सबसे बड़ी ख़ासियत के साथ लिखिए।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"38\" text-anchor=\"middle\" font-size=\"18\" fill=\"#0B1F3A\" font-weight=\"bold\">ताज़ा, सूखा, पाउडर, विशेष — चार बाज़ार</text>\n<rect x=\"30\" y=\"65\" width=\"228\" height=\"200\" fill=\"#0B1F3A\" rx=\"8\"/>\n<text x=\"144\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">ताज़ा</text>\n<text x=\"144\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">सबसे आम</text>\n<text x=\"144\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जल्दी ख़राब</text>\n<rect x=\"286\" y=\"65\" width=\"228\" height=\"200\" fill=\"#1565C0\" rx=\"8\"/>\n<text x=\"400\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">सूखा-पाउडर</text>\n<text x=\"400\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">लंबी उम्र</text>\n<text x=\"400\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">दूर बाज़ार तक जा सकता</text>\n<rect x=\"542\" y=\"65\" width=\"228\" height=\"200\" fill=\"#2E7D32\" rx=\"8\"/>\n<text x=\"656\" y=\"98\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">विशेष उत्पाद</text>\n<text x=\"656\" y=\"130\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">अचार, मसाला</text>\n<text x=\"656\" y=\"156\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">ज़्यादा कमाई</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">एक मशरूम, चार तरह की कमाई</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"चार-बाज़ार हिस्सा\" जोड़िए — ताज़ा-सूखा, पाउडर-विशेष अपनी भाषा में। फिर अपनी पहली \"चार-बाज़ार सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मुझे \"ताज़ा\" \"सूखा\" \"पाउडर\" और \"विशेष\" मशरूम-उत्पादों के बीच का फ़र्क़ एक सरल तालिका में समझाओ।*\n\nAI इसमें तुलनात्मक और स्पष्ट तालिका बनाने में काफ़ी मददगार है — असली और अंतिम फ़ैसला अपने ख़ुद के इलाक़े और ग्राहकों के हिसाब से ही हमेशा लें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मुझे तो सिर्फ़ ताज़ा मशरूम ही बेचना है बाक़ी रूपों की ज़रूरत नहीं\" — जबकि \"सूखा\" या \"पाउडर\" जैसे रूप आपको \"ख़राब हो जाने वाले\" या \"बिना बिके बचे\" मशरूम को भी बेचने का मौक़ा देते हैं — सिर्फ़ एक ही रूप पर हमेशा निर्भर रहना आपकी पूरी कमाई को काफ़ी हद तक सीमित कर सकता है।**\n\n\"सिर्फ़ ताज़ा ही बेचूँगा/बेचूँगी\" सोचना, एक बहुत सीमित सोच है। हमेशा इन सभी चारों रूपों को एक संभावित और बड़े अवसर की तरह देखें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| सिर्फ़ \"ताज़ा\" रूप पर निर्भर रहना | चारों रूपों को अवसर की तरह देखें |\n| \"उम्र\" (दिन) का ध्यान न रखना | हर रूप की उम्र स्पष्ट रूप से जानें |\n| बिना तैयारी \"विशेष\" उत्पाद बनाना | पहले सही जानकारी और अनुभव लें |\n| चार-बाज़ार हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"चार-बाज़ार सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी समझ को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nताज़ा, सूखा, पाउडर व मूल्य-वर्धित मशरूम-उत्पाद-श्रेणियों के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ मशरूम को \"ताज़ा सूखा पाउडर और विशेष\" — इन चार रूपों में कैसे बेचा जा सकता है — मैं समझा सकता हूँ।\n☐ हर रूप का अपना अलग बाज़ार क्यों है — मुझे साफ़ है।\n☐ यह तीन-प्रजाति की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"सिर्फ़ ताज़ा ही बेचूँगा/बेचूँगी\" सोचना क्यों सीमित है।\n☐ मैंने अपनी पहली, \"चार-बाज़ार सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — शुरुआत में \"ताज़ा\" बेचने पर ही अपना पूरा ध्यान दें पर साथ ही यह भी सोचें कि \"अगर कुछ मशरूम बिना बिके बच जाएँ तो मैं उन्हें कैसे सूखा सकता/सकती हूँ\" — यह पूरी सोच आपकी संभावित बर्बादी को बहुत कम करती है।\n\nएक आख़िरी सोच — \"पाउडर\" और \"विशेष\" उत्पाद अकसर सबसे ज़्यादा \"मुनाफ़ा\" यानी हर किलो पर बचत देते हैं क्योंकि इनमें आपकी \"मेहनत\" यानी प्रसंस्करण भी जुड़ी होती है जिसका पूरा दाम ग्राहक ख़ुशी से चुकाता है।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो यह पूरी तरह संभव है कि कुछ सदस्य \"ताज़ा\" बेचें और कुछ सदस्य \"सूखा या प्रसंस्करण\" पर ध्यान दें — इससे पूरे हब की कुल कमाई काफ़ी हद तक बढ़ सकती है।\n\nएक अंतिम सुझाव — अपने आस-पास के बाज़ार में देखें कि \"सूखा\" या \"पाउडर\" मशरूम कहीं बिकता है या नहीं — अगर कहीं भी नहीं बिकता तो यह आपके लिए एक बहुत बड़ा \"नया और अनछुआ अवसर\" हो सकता है।\n\nअंत में याद रखें कि यह पूरी चार-बाज़ार की सोच अगले पाठ में सीखी जाने वाली \"मशरूम की सबसे बड़ी अड़चन — जल्दी ख़राब होना\" की सीधी तैयारी है — जब आप इन चारों रूपों को अच्छी तरह समझ लें तो \"ताज़ा\" रूप की सबसे बड़ी चुनौती समझना अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"एक मशरूम चार तरह की कमाई\" वाली यह पूरी और प्रेरक सोच बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी मशरूम कभी बर्बाद न जाए।\n\nएक आख़िरी बात — यह पूरी चार-बाज़ार की सोच दिखने में एक \"साधारण वर्गीकरण\" जैसी बात लगती है पर यह असल में आपकी कमाई के कई नए रास्ते खोलने वाली सबसे व्यावहारिक और उपयोगी सीख है।\n\nएक और गहरी सोच — इन चारों रूपों को \"एक ही ज़ंजीर\" की तरह सोचें — \"ताज़ा\" पहले फिर जो न बिके वह \"सूखा\" फिर जो टूटा-फूटा हो वह \"पाउडर\" में — इस तरह आपका कोई भी मशरूम बर्बाद नहीं होता।\n\nएक अंतिम विचार — जो व्यक्ति इन सभी चार रूपों को अपनी संभावित \"योजना\" में पहले से ही शामिल कर लेता है वह आगे चलकर अपने धंधे को सबसे कम बर्बादी और सबसे ज़्यादा स्थिरता के साथ चला पाता है।\n\n---\n---\n", "11": "# पाठ 11 — मशरूम की सबसे बड़ी अड़चन — जल्दी ख़राब होना\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 11\n**सुरक्षा:** 🟡 ध्यान दें · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पूरे पाठ के बाद आप अच्छी तरह जानेंगे कि मशरूम इतनी जल्दी ख़राब क्यों होता है। आप यह भी अच्छी तरह जानेंगे कि यह जानकारी आपके पूरे धंधे की योजना को कैसे बदलती है। आप यह भी अच्छी तरह समझेंगे कि यह पूरी बात, चार-बाज़ार की सीख से कैसे आगे बढ़ती है। और अंत में आप अपनी पहली, \"जल्दी-ख़राब सोच\" भी लिखेंगे।\n\n### 2. मुख्य बात\n\n> मशरूम में \"पानी\" की मात्रा बहुत ज़्यादा होती है (लगभग 90 प्रतिशत तक) — यही वजह है कि यह तोड़ने के कुछ ही घंटों या एक-दो दिन में ख़राब होने लगता है — यह पूरी और गंभीर \"जल्दी ख़राब होना\" वाली बात ही मशरूम-धंधे की सबसे बड़ी अड़चन है और इसे समझना बहुत ज़रूरी है।\n\n### 3. मशरूम इतनी जल्दी ख़राब क्यों होता है\n\nबहुत ज़्यादा \"पानी\" की मात्रा — मशरूम का ज़्यादातर पूरा हिस्सा सिर्फ़ पानी ही है — यही पानी इसे बहुत \"ताज़ा\" और \"स्वादिष्ट\" भी बनाता है पर यही पानी ही इसे जल्दी \"सड़ने\" का सबसे बड़ा कारण भी बनता है। कोई \"छिलका\" या \"सुरक्षा-परत\" नहीं — पाठ 1 की \"कवक\" सीख की तरह ही फलों या सब्ज़ियों की तरह ही मशरूम में भी कोई मोटी \"सुरक्षा-परत\" बिलकुल नहीं होती है — इसीलिए यह पूरा मशरूम हवा और नमी से बहुत जल्दी प्रभावित हो जाता है।\n\n### 4. यह जानकारी आपकी योजना को कैसे बदलती है\n\nतोड़ने के तुरंत बाद बेचने की योजना — पाठ 610 की \"ख़रीदार-माँग\" सीख की तरह ही (आगे इस कोर्स में) आपको अपनी \"बिक्री\" की योजना \"तोड़ने से पहले\" ही बनानी होगी — \"पहले तोड़ो फिर ग्राहक ढूँढ़ो\" वाला तरीक़ा यहाँ काम नहीं करता। \"ठंडक\" और \"सूखा-प्रसंस्करण\" की तैयारी — पाठ 10 की \"चार-बाज़ार\" सीख की तरह ही अगर आपके पास \"ठंडा रखने\" की व्यवस्था या \"जल्दी सुखाने\" की योजना न हो तो बिना बिका माल बर्बाद हो सकता है।\n\n### 5. यह चार-बाज़ार की सीख से कैसे आगे बढ़ता है\n\nपाठ 10 ने सिखाया कि मशरूम को चार अलग रूपों में बेचा जा सकता है। यह पूरा पाठ उस \"विकल्प\" वाली समझ से आगे बढ़कर अब \"क्यों यह विकल्प इतने ज़रूरी हैं\" — इस गहरी वजह को समझाता है — यह पूरी \"जल्दी ख़राब होना\" वाली बात ही वह मुख्य कारण है जो आपको \"सूखा\" या \"पाउडर\" जैसे विकल्पों पर भी सोचने को मजबूर करता है।\n\n### 6. अपनी पहली, \"जल्दी-ख़राब सोच\" लिखना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में लिखें — यह जानकर कि मशरूम इतनी जल्दी ख़राब होता है आप अपनी \"बिक्री\" की योजना को कैसे बदलेंगे।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"42\" text-anchor=\"middle\" font-size=\"21\" fill=\"#0B1F3A\" font-weight=\"bold\">मशरूम की सबसे बड़ी अड़चन</text>\n<rect x=\"40\" y=\"80\" width=\"345\" height=\"220\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"212\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">क्यों जल्दी ख़राब</text>\n<text x=\"212\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">बहुत ज़्यादा पानी</text>\n<text x=\"212\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">कोई सुरक्षा-परत नहीं</text>\n<rect x=\"415\" y=\"80\" width=\"345\" height=\"220\" fill=\"#2E7D32\" rx=\"10\"/>\n<text x=\"587\" y=\"115\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">योजना कैसे बदलें</text>\n<text x=\"587\" y=\"150\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">पहले बिक्री-योजना बनाएँ</text>\n<text x=\"587\" y=\"176\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">ठंडक-सुखाने की तैयारी</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">तोड़ने से पहले, बिक्री सोचें</text>\n</svg>\n\n### 7. आज का काम\n\nबीज-निर्माण पन्ने में \"जल्दी-ख़राब हिस्सा\" जोड़िए — क्यों जल्दी ख़राब, योजना कैसे बदलें अपनी भाषा में। फिर अपनी पहली \"जल्दी-ख़राब सोच\" लिखिए।\n\n### 8. नाप\n\nकाम पूरा तब, जब हिस्सा भरा हो और सोच लिखी हो।\n\n### 9. सबूत\n\nहिस्से और सोच की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मैं अपने मशरूम को जल्दी ख़राब होने से बचाना चाहता/चाहती हूँ (लिखिए)। बताओ — मुझे अपनी बिक्री योजना में क्या-क्या ध्यान रखना चाहिए?*\n\nAI इसमें सामान्य और शुरुआती दिशा देने में मददगार है — असली और सटीक \"कितने घंटे या दिन\" यह पूरा उत्पाद टिकेगा यह हमेशा अपने ख़ुद के अनुभव या उस्ताद से ही पुष्टि करें।\n\n### 11. आम ग़लती\n\n**यह सोचना कि \"मैं तो बाद में ग्राहक ढूँढ़ लूँगा/लूँगी पहले मशरूम तोड़ लेता/लेती हूँ\" — जबकि मशरूम तोड़ने के बाद हर घंटा इसकी \"उम्र\" कम करता है — बिना पहले से तैयार ग्राहक या योजना के मशरूम तोड़ना हमेशा बर्बादी का एक बड़ा ख़तरा है।**\n\n\"पहले तोड़ो फिर ग्राहक ढूँढ़ो\" सोचना एक महंगी भूल है। हमेशा पहले से अपनी बिक्री की योजना तैयार रखें।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| बिना योजना के मशरूम तोड़ना | पहले से बिक्री योजना बनाएँ |\n| ठंडक या सुखाने की तैयारी न रखना | पहले से यह व्यवस्था कर रखें |\n| \"ताज़ा\" पर ही पूरी तरह निर्भर रहना | \"सूखा-पाउडर\" का विकल्प भी रखें |\n| जल्दी-ख़राब हिस्सा न लिखना | पहले हिस्सा भरकर देखें |\n| \"जल्दी-ख़राब सोच\" न लिखना | पहले सोच लिखकर देखें |\n| इस बुनियादी चुनौती को हल्के में लेना | ध्यान से पूरा पाठ फिर पढ़ें |\n\n### 13. स्रोत\n\nताज़ा मशरूम की उच्च नमी-मात्रा व शीघ्र-क्षय (पेरिशेबिलिटी) के सामान्य शैक्षिक सिद्धांत: [हिंदी विकिपीडिया — कुकुरमुत्ता (कवक)](https://hi.wikipedia.org) — देखा गया 10-08-2026। आईसीएआर मशरूम अनुसंधान निदेशालय, सोलन: [dmrsolan.res.in](https://dmrsolan.res.in) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ मशरूम इतनी जल्दी ख़राब क्यों होता है — मैं समझा सकता हूँ।\n☐ यह जानकारी मेरी योजना को कैसे बदलती है — मुझे साफ़ है।\n☐ यह चार-बाज़ार की सीख से कैसे आगे बढ़ता है — मैं बता सकता हूँ।\n☐ मैं जानता हूँ कि \"पहले तोड़ो फिर ग्राहक ढूँढ़ो\" सोचना क्यों महंगी भूल है।\n☐ मैंने अपनी पहली, \"जल्दी-ख़राब सोच\" लिख ली है।\n\nएक व्यावहारिक सलाह — अपने संभावित ग्राहकों यानी दुकानदार या परिवार से पहले ही स्पष्ट रूप से बात कर लें कि \"मैं इस दिन इतनी मात्रा में मशरूम तोड़ूँगा/तोड़ूँगी क्या आप इसे ख़रीदेंगे\" — यह पूरी तैयारी आपको हमेशा \"पहले से तैयार\" ग्राहक ही देती है।\n\nएक आख़िरी सोच — \"जल्दी ख़राब होना\" कोई \"समस्या\" ही नहीं — यह आपको \"ताज़गी\" का एक बड़ा \"फ़ायदा\" भी देता है — कई ग्राहक \"एकदम ताज़ा\" मशरूम के लिए ख़ुशी से ज़्यादा दाम देने को भी तैयार हो सकते हैं।\n\nएक और ज़रूरी बात — अगर आप हब का हिस्सा हों तो \"ठंडक\" या \"सुखाने\" की व्यवस्था को साझा तौर पर बनाना अकसर ज़्यादा किफ़ायती हो सकता है — अकेले-अकेले हर घर में अलग व्यवस्था बनाने से कहीं बेहतर।\n\nएक अंतिम सुझाव — अपनी अलग नोटबुक में यह अच्छी तरह नोट करें कि \"मेरे इलाक़े में ताज़ा मशरूम आख़िर कितने घंटे या दिन में ख़राब होने लगता है\" — यह पूरी जानकारी आगे आपकी योजना बनाने में बहुत काम आएगी।\n\nअंत में याद रखें कि यह पूरी जल्दी-ख़राब की सोच अगले पाठ में सीखी जाने वाली \"आज का काम — अपने ज़िले के बाज़ार-भाव की तालिका बनाओ\" की सीधी तैयारी है — जब आप यह पूरी तरह समझ लें कि \"जल्दी बेचना आख़िर क्यों ज़रूरी है\" तो अपने ज़िले के असली बाज़ार-भाव जानना अगला और स्वाभाविक क़दम है।\n\nएक और उपयोगी सुझाव — अगर आपके परिवार के सदस्य भी इस कोर्स में शामिल हों तो सबको \"पहले बिक्री योजना फिर तोड़ना\" वाली यह पूरी और ज़रूरी आदत बहुत स्पष्ट रूप से समझाएँ ताकि कोई भी बिना योजना के कभी न तोड़े।\n\nएक आख़िरी बात — यह पूरी जल्दी-ख़राब की सोच दिखने में एक \"चिंताजनक\" विषय लगती है पर यह असल में आपको अपने धंधे की सबसे बड़ी चुनौती के लिए पहले से तैयार करने वाली सबसे बुद्धिमान और व्यावहारिक सोच है।\n\nएक और गहरी सोच — दुनिया भर के सफल मशरूम-उगाने वाले इस \"जल्दी ख़राब होने\" वाली चुनौती को \"समस्या\" नहीं बल्कि अपनी \"योजना\" का एक स्वाभाविक हिस्सा मानते हैं — वे हमेशा पहले से तैयार रहते हैं।\n\nएक अंतिम विचार — जो व्यक्ति यह समझ लेता है कि \"मशरूम इंतज़ार नहीं करता\" वह कभी भी बिना योजना के फ़सल नहीं तोड़ता — यही अनुशासन आगे चलकर उसे कम नुक़सान और ज़्यादा मुनाफ़े की तरफ़ ले जाता है।\n\n---\n---\n", "12": "# पाठ 12 — आज का काम — अपने ज़िले के बाज़ार-भाव की तालिका बनाओ\n\n**अध्याय:** अ-1 · **पाठ:** 12 में से 12\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह पूरे अध्याय-1 का आख़िरी समापन-काम है — मशरूम का जीवन-चक्र और वैश्विक बाज़ार, इस पूरी बारह-पाठ लंबी यात्रा की अंतिम मुहर। इस पूरे काम के बाद आप अपने ज़िले के असली और सटीक बाज़ार-भाव की पूरी स्पष्ट \"तालिका\" बनाएँगे। आप उस्ताद-घर की दो अनुभवी आँखों से इसे जँचवाएँगे। और अंत में आप आगे के अध्याय-2 की राह भी खोलेंगे।\n\n### 2. मुख्य बात\n\n> आज का अभ्यास — मशरूम-पहचान जीवन-चक्र बीजाणु-जाल जाल-फैलाव कली-बनना फल-शरीर पूरा-चक्र वैश्विक-बाज़ार तीन-प्रजाति चार-बाज़ार और जल्दी-ख़राब इन सभी ग्यारह हिस्सों को एक साथ लाकर अपने ज़िले के असली बाज़ार-भाव की पूरी \"तालिका\" बनाना — यह अध्याय-1 की हर सीख को एक ही जगह असली व्यावहारिक निर्णय-औज़ार में उतारने का पल है।\n\n### 3. ग्यारह हिस्से (याद-सूत्र)\n\nएक — मशरूम-पहचान यानी पाठ 1: कवक पौधा नहीं। दो — जीवन-चक्र यानी पाठ 2: चार-पड़ाव वाला पहिया। तीन — बीजाणु-जाल यानी पाठ 3: बीज और शरीर। चार — जाल-फैलाव यानी पाठ 4: छेड़ना नहीं। पाँच — कली-बनना यानी पाठ 5: उलटा काम।\n\n### 4. बाक़ी छह हिस्से\n\nछह — फल-शरीर यानी पाठ 6: जाल पेड़ है। सात — पूरा-चक्र यानी पाठ 7: फ़ैसले आसान। आठ — वैश्विक-बाज़ार यानी पाठ 8: स्रोत-वर्ष ज़रूरी। नौ — तीन-प्रजाति, यानी पाठ 9: बटन-ऑयस्टर-शिटाके। दस — चार-बाज़ार, यानी पाठ 10: ताज़ा-सूखा-पाउडर-विशेष। ग्यारह — जल्दी-ख़राब यानी पाठ 11: पहले बिक्री योजना।\n\n### 5. अपने ज़िले के बाज़ार-भाव की पूरी \"तालिका\" बनाना\n\nअब इसे व्यावहारिक बनाइए। अपनी नोटबुक में एक स्पष्ट तालिका बनाइए — इसमें अपने ज़िले या इलाक़े में मिलने वाले \"बटन ऑयस्टर शिटाके\" (जो भी मिले) का \"ताज़ा\" और अगर संभव हो तो \"सूखा\" दाम अलग-अलग दुकानों से पूछकर स्पष्ट रूप से लिखें।\n\n### 6. दो आँखों की जाँच और अध्याय-1 की कड़ी\n\nअब यह पूरी \"बाज़ार-भाव तालिका\" दोनों दो अनुभवी आँखों से बहुत अच्छी तरह गुज़रे। घर की आँख — क्या यह, व्यावहारिक और अपनी असली जगह से मेल खाता दिखता है। उस्ताद की आँख — तीन सवाल: क्या मैंने यह तालिका अंदाज़े से नहीं बल्कि असली दुकानों से पूछकर बनाई है? क्या मैं यह पूरी तरह समझता/समझती हूँ कि \"जल्दी ख़राब होने\" की वजह से यह दाम हर दिन बदल सकता है? क्या मैं यह स्पष्ट रूप से समझा सकता/सकती हूँ कि \"मशरूम कवक है पौधा नहीं\" और इसके चार-पड़ाव वाले जीवन-चक्र को? दोनों पूरे जवाब दर्ज कीजिए। फिर अपनी बही में, यह पूरी बारह-पाठ कड़ी लिखिए — मशरूम-पहचान समझी → जीवन-चक्र जाना → बीजाणु-जाल समझे → जाल-फैलाव सीखा → कली-बनना जाना → फल-शरीर समझा → पूरा-चक्र जोड़ा → वैश्विक-बाज़ार देखा → तीन-प्रजाति समझी → चार-बाज़ार जाना → जल्दी-ख़राब समझा → आज बाज़ार-भाव तालिका बनाई।\n\nएक अंतिम गहरी सोच जोड़ लीजिए — यह पूरा अध्याय-1 सिर्फ़ \"मशरूम कैसे उगता है\" नहीं सिखाता यह एक बड़ी सोच सिखाता है — असली समझदार व्यवसायी अपने धंधे की \"तकनीकी\" (कैसे उगे) और \"व्यावसायिक\" (कैसे बिके) दोनों बातें एक साथ समझता है — यही दोनों तरफ़ की पूरी समझ ही उसे एक सफल और टिकाऊ धंधा खड़ा करने में बहुत मदद करती है।\n\nएक और उपयोगी सुझाव — यह पूरी और स्पष्ट \"बाज़ार-भाव तालिका\" एक बार बनाकर हमेशा के लिए \"स्थिर\" कभी नहीं रहती। जैसे-जैसे समय बीतता जाएगा इन दामों को हर कुछ हफ़्तों में बहुत नियमित रूप से अद्यतन करते रहें।\n\nएक आख़िरी बात — यह पूरा अभ्यास आज सिर्फ़ काग़ज़ पर नहीं रहेगा। जैसे-जैसे आप आगे अध्याय-2 में \"मेरे लिए कौन-सा मशरूम\" चुनेंगे यह आज की बाज़ार-भाव तालिका आपकी सबसे बड़ी ठोस नींव बनेगी। यही असली सीख है — मशरूम का धंधा कोई एक बार सीखने वाली चीज़ नहीं बल्कि एक जीवित बढ़ती हुई यात्रा है जो आपके पूरे व्यवसाय को हर नए दिन के साथ और स्पष्ट और मज़बूत बनाती चली जाएगी जैसे-जैसे आप आगे अध्याय-2 — \"मेरे लिए कौन-सा मशरूम\" — में नई बड़ी सीखें पाएँगे।\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n<text x=\"400\" y=\"34\" text-anchor=\"middle\" font-size=\"17\" fill=\"#0B1F3A\" font-weight=\"bold\">अपने ज़िले के बाज़ार-भाव की तालिका बनाओ</text>\n<rect x=\"20\" y=\"58\" width=\"180\" height=\"72\" fill=\"#0B1F3A\" rx=\"6\"/>\n<text x=\"110\" y=\"88\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">मशरूम-पहचान</text>\n<text x=\"110\" y=\"112\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जीवन-चक्र</text>\n<rect x=\"210\" y=\"58\" width=\"180\" height=\"72\" fill=\"#1565C0\" rx=\"6\"/>\n<text x=\"300\" y=\"88\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">बीजाणु-जाल</text>\n<text x=\"300\" y=\"112\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">कली-फल</text>\n<rect x=\"400\" y=\"58\" width=\"180\" height=\"72\" fill=\"#2E7D32\" rx=\"6\"/>\n<text x=\"490\" y=\"88\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\" font-weight=\"bold\">वैश्विक-बाज़ार</text>\n<text x=\"490\" y=\"112\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">तीन-प्रजाति</text>\n<rect x=\"590\" y=\"58\" width=\"190\" height=\"72\" fill=\"#0B1F3A\" rx=\"6\"/>\n<text x=\"685\" y=\"88\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\" font-weight=\"bold\">चार-बाज़ार</text>\n<text x=\"685\" y=\"112\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F5F7FA\">जल्दी-ख़राब</text>\n<rect x=\"90\" y=\"180\" width=\"620\" height=\"90\" fill=\"#0B1F3A\" rx=\"10\"/>\n<text x=\"400\" y=\"218\" text-anchor=\"middle\" font-size=\"17\" fill=\"#F5F7FA\" font-weight=\"bold\">दो आँखें — घर + उस्ताद</text>\n<text x=\"400\" y=\"253\" text-anchor=\"middle\" font-size=\"16\" fill=\"#F9A825\">अध्याय-1 पूरा — 🎉</text>\n<rect x=\"200\" y=\"740\" width=\"400\" height=\"36\" rx=\"27\" fill=\"#F9A825\"/>\n<text x=\"400\" y=\"765\" text-anchor=\"middle\" font-size=\"20\" fill=\"#0B1F3A\">तकनीकी + व्यावसायिक समझ, दोनों साथ</text>\n</svg>\n\n### 7. आज का काम\n\nयह «अभ्यास» पाठ है — आज यहाँ अपने ज़िले के बाज़ार-भाव की पूरी \"तालिका\" बनाई जाएगी। कम-से-कम तीन-चार अलग-अलग दुकानों या स्रोतों से दाम पूछकर इसे एक साफ़ और स्पष्ट तालिका में ध्यान से लिखिए। घर-बैठक में पढ़कर टिप्पणी दर्ज कीजिए, उस्ताद-बैठक के तीन सवाल पूछकर जवाब दर्ज कीजिए। आख़िर में बारह-पाठ कड़ी लिखकर किसी घरवाले को अध्याय-1 की पूरी यात्रा सुनाइए।\n\n### 8. नाप\n\nकाम पूरा तब, जब पूरी, \"बाज़ार-भाव तालिका\" बनी हो, घर-टिप्पणी और उस्ताद-जवाब दर्ज हों, और बारह-पाठ कड़ी लिखी हो। अध्याय-1 की मुहर उस्ताद-जवाबों के बाद पक्की मानी जाए।\n\n### 9. सबूत\n\nपूरी बाज़ार-भाव तालिका, घर-टिप्पणी, और उस्ताद-जवाब की फ़ोटो सबूत-खाते में।\n\n### 10. AI-सहायक\n\n*मेरी आज की पूरी \"बाज़ार-भाव तालिका\" यह रही — सभी दाम (पढ़कर लिखिए)। कसकर जाँचो — कोई दाम \"बहुत अजीब\" या \"बहुत अलग\" तो नहीं? मुहर घर और उस्ताद की — तुम्हारी जाँच सिर्फ़ धार तेज़ करने को।*\n\n**⚠️ ज़रूरी सावधानी:** AI सिर्फ़ इस तालिका में कोई \"अजीब\" दाम ढूँढ़ने में मदद कर सकता है — असली अंतिम सही दाम हमेशा अपने ख़ुद के असली बाज़ार-अनुभव से ही आते हैं।\n\n### 11. आम ग़लती\n\n**तालिका को \"अध्याय पूरा दिखाने\" के लिए जल्दी में भर देना — असली दुकानों से पूछे बिना, अंदाज़े से, दाम भर देना, जो, आपकी अपनी असली परिस्थिति और अनुभव से मेल न खाती हो।**\n\nयह पूरे कोर्स की सबसे पुरानी और मज़बूत सीख यहाँ भी लागू होती है — किताबी और अंदाज़े के जवाब किसी काम के नहीं अगर वे आपकी अपनी असली परिस्थिति और अनुभव से न आएँ। हर एक ऐसी बाज़ार-भाव तालिका, हमेशा, असली दुकानों से, पूछी गई जानकारी से ही आनी चाहिए।\n\n### 12. सुरक्षा-पत्रक\n\n| ख़तरा | बचाव |\n|---|---|\n| अंदाज़े से दाम भर देना | असली दुकानों से पूछकर ही लिखें |\n| सिर्फ़ एक ही दुकान से पूछना | कम-से-कम तीन-चार स्रोत देखें |\n| तालिका को जल्दी में अधूरा छोड़ना | पूरा समय लेकर, ध्यान से करें |\n| उस्ताद-मुहर को बार-बार टालते रहना | बैठक की तारीख़ आज ही पक्की तय करें |\n| पुराने दाम को हमेशा सही मानना | दाम नियमित रूप से फिर जाँचें |\n| तालिका को कभी अद्यतन न करना | नियमित समीक्षा करते रहें |\n\n### 13. स्रोत\n\nछोटे कृषि व्यवसायों में स्थानीय बाज़ार-भाव-सर्वेक्षण-समापन-अभ्यास की प्रकाशित शैक्षिक रूपरेखा: [ICAR-DMR सोलन](https://dmrsolan.res.in) — देखा गया 10-08-2026। समापन-बाज़ार-भाव-तालिका के नमूने: [ACS उद्यम-पेज](https://acslearn.com) — देखा गया 10-08-2026।\n\n### 14. योग्यता-जाँच\n\n☐ ग्यारह हिस्से मैं एक ही साँस में सुना सकता हूँ।\n☐ मैं यह भी जानता हूँ कि किताबी जवाब आख़िर क्यों काफ़ी नहीं होते हैं।\n☐ पूरे अध्याय-1 की बारह-पाठ कड़ी मैं अच्छी तरह सुना सकता हूँ।\n☐ मैं अच्छी तरह समझता हूँ कि यह तालिका आख़िर क्यों असली दुकानों से आनी चाहिए, अंदाज़े से नहीं।\n☐ मैंने अपने ज़िले की, पूरी, \"बाज़ार-भाव तालिका\" बनाकर, घर-टिप्पणी लेकर उस्ताद-बैठक की तारीख़ भी पक्की तय कर ली है।\n\n---\n---\n", "13": "# पाठ 13 — एक ही मशरूम सबके लिए ठीक नहीं होता — फिर बटन ही क्यों\n\n**अध्याय:** अ-2 · **पाठ:** 1 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप एक बड़ा फ़ैसला समझ जाएँगे। मशरूम की दुनिया में कई प्रजातियाँ हैं। यह कोर्स उनमें से एक को चुनकर आगे बढ़ता है। वह है बटन मशरूम। आप जानेंगे कि यह चुनाव किस हिसाब से हुआ। और यह भी कि यही हिसाब आपके हर बड़े फ़ैसले में काम आएगा।\n\n### 2. मुख्य बात\n\n> प्रजाति का चुनाव दिल से नहीं, हिसाब से होता है। चार कसौटियाँ हैं — बाज़ार, मौसम, कच्चा माल और आपकी तैयारी। इस इलाक़े में चारों का काँटा बटन की तरफ़ झुकता है।\n\n---\n\n### दो पड़ोसियों की कहानी\n\nमान लो एक गाँव में दो पड़ोसी हैं — रमेश और सुरेश। दोनों ने सुना कि मशरूम में कमाई है। रमेश ने बिना सोचे वह प्रजाति उगा ली, जिसका वीडियो पहले दिखा। फ़सल अच्छी हुई। पर हाट में कोई पहचानता ही नहीं था। ग्राहक पूछते रहे — यह क्या चीज़ है? माल सस्ते में निकालना पड़ा।\n\nसुरेश ने पहले हफ़्ता-भर बाज़ार घूमा। देखा कि दुकानों पर सफ़ेद गोल टोपी वाला मशरूम बिकता है। ग्राहक उसे नाम से माँगते हैं। सुरेश ने वही उगाया। माल हाथों-हाथ गया।\n\nफ़र्क़ मेहनत का नहीं था। फ़र्क़ फ़ैसले का था। रमेश ने पसंद से चुना। सुरेश ने हिसाब से चुना। यह पूरा पाठ आपको सुरेश बनाने के लिए है।\n\n### चार कसौटियाँ — फ़ैसले की तराज़ू\n\nकिसी भी प्रजाति को चुनने से पहले चार सवाल पूछे जाते हैं।\n\nपहला सवाल — बाज़ार। मेरे इलाक़े में कौन-सा मशरूम बिकता है? जो बिकता ही नहीं, उसे उगाना घाटे का सौदा है।\n\nदूसरा सवाल — मौसम। मेरे इलाक़े की गर्मी-सर्दी किस प्रजाति को रास आती है? हर मशरूम का अपना मिज़ाज होता है।\n\nतीसरा सवाल — कच्चा माल। इस प्रजाति का खाना मेरे पास या पास के बाज़ार में मिलेगा या नहीं?\n\nचौथा सवाल — मेरी तैयारी। जेब, जगह और समय कितना है? कुछ प्रजातियाँ सस्ती शुरुआत देती हैं। कुछ शुरू में ही बड़ी माँग रखती हैं।\n\nअगले तीन पाठ इन्हीं कसौटियों को एक-एक करके खोलेंगे। अभी चारों को तराज़ू पर रखकर बटन का जवाब देखते हैं।\n\n### बटन का दावा — सबूत के साथ\n\nअब वह हिसाब देखिए, जिस पर इस कोर्स की नींव रखी गई।\n\nबाज़ार का सबूत सबसे भारी है। बटन मशरूम दुनिया के मशरूम-बाज़ार का सबसे बड़ा हिस्सा है। यह बात बाज़ार-शोध संस्था की रिपोर्ट कहती है। और अपने घर का सबूत उससे भी क़रीब है। बिहार आज भारत का नंबर-एक मशरूम-राज्य है। यहाँ साल में इकतालीस हज़ार टन से ज़्यादा मशरूम होता है। यह देश के कुल उत्पादन का लगभग ग्यारह प्रतिशत है। साठ से सत्तर हज़ार किसान यह काम कर रहे हैं। और इस कारोबार की रीढ़ यही सफ़ेद बटन है।\n\nसरकार का हाथ भी इसी तरफ़ है। किट और मशरूम-ढाँचे पर पचास से नब्बे प्रतिशत तक अनुदान की योजनाएँ चलती हैं। महिलाओं को प्राथमिकता मिलती है। यानी रास्ता अकेले नहीं चलना है।\n\nएक बात ईमानदारी से भी। बटन उगाना सबसे आसान नहीं है। इसका खाना यानी कम्पोस्ट बनाना मेहनत माँगता है। इसे ठंडा मौसम चाहिए। फिर भी कोर्स ने इसे चुना। क्योंकि चुनाव की कसौटी आसानी नहीं, बिक्री है। जो चीज़ बिकती है, उसकी मेहनत वसूल होती है।\n\n### बाक़ी प्रजातियों का क्या होगा\n\nइसका मतलब यह नहीं कि बाक़ी मशरूम बेकार हैं। ढींगरी, मिल्की, पैडी स्ट्रॉ, शिटाके — सबकी अपनी जगह है। इस कोर्स में उन सबका एक पूरा जानकारी-अध्याय है। नाम है — अन्य प्रजातियाँ, एक नज़र में। वहाँ आप हर किस्म की पहचान और उसका मौसम जानेंगे।\n\nपर सीखने की गहराई एक ही प्रजाति में उतरेगी। कारण सीधा है। एक धंधे को जड़ से सीखने वाला दूसरा धंधा जल्दी पकड़ लेता है। चार को ऊपर-ऊपर छूने वाला किसी में नहीं टिकता। पहले बटन में पक्के बनिए। बाक़ी दरवाज़े अपने-आप खुलते जाएँगे।\n\n### चित्र — चार कसौटियों की तराज़ू\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">प्रजाति का फ़ैसला — चार कसौटियाँ</text>\n  <rect x=\"60\" y=\"110\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"220\" y=\"148\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कसौटी-1</text>\n  <text x=\"220\" y=\"180\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">बाज़ार में कौन बिकता है</text>\n  <rect x=\"420\" y=\"110\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"580\" y=\"148\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कसौटी-2</text>\n  <text x=\"580\" y=\"180\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">मौसम किसे रास आता है</text>\n  <rect x=\"60\" y=\"230\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"220\" y=\"268\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कसौटी-3</text>\n  <text x=\"220\" y=\"300\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कच्चा माल कहाँ से</text>\n  <rect x=\"420\" y=\"230\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"580\" y=\"268\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कसौटी-4</text>\n  <text x=\"580\" y=\"300\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">जेब, जगह और समय</text>\n  <line x1=\"220\" y1=\"325\" x2=\"390\" y2=\"430\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"580\" y1=\"325\" x2=\"410\" y2=\"430\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"220\" y1=\"205\" x2=\"120\" y2=\"250\" stroke=\"#F5F7FA\" stroke-width=\"0\"/>\n  <circle cx=\"400\" cy=\"520\" r=\"90\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <text x=\"400\" y=\"510\" font-size=\"26\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">बटन</text>\n  <text x=\"400\" y=\"545\" font-size=\"26\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">मशरूम</text>\n  <rect x=\"120\" y=\"650\" width=\"560\" height=\"60\" rx=\"30\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"688\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">चारों काँटे इसी तरफ़ झुकते हैं — इसलिए यही रीढ़</text>\n  <text x=\"400\" y=\"760\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">बाक़ी प्रजातियाँ — जानकारी-अध्याय (अ-31) में</text>\n</svg>\n\n### कसौटी ज़िंदा चीज़ है\n\nएक बात और पल्ले बाँध लीजिए। यह फ़ैसला पत्थर की लकीर नहीं है। कसौटियाँ ज़िंदा हैं। हालात बदलें, तो तराज़ू दोबारा उठानी पड़ती है।\n\nकब-कब दोबारा तौलना है? तीन मौक़ों पर। पहला — जब आप नई जगह जाएँ। दूसरे ज़िले या दूसरे राज्य का बाज़ार-मौसम अलग हो सकता है। मान लो कोई सीखने वाला ठंडे पहाड़ी इलाक़े का है। वहाँ यही चार सवाल किसी और किस्म की तरफ़ भी झुक सकते हैं। दूसरा मौक़ा — जब आपका बाज़ार बदले। कोई होटल-कड़ी किसी ख़ास किस्म की बड़ी माँग ले आए, तो हिसाब नया होगा। तीसरा — जब आपकी अपनी तैयारी बदले। आज की छोटी जेब कल बड़ी होगी।\n\nदोबारा तौलने का ख़र्च देखिए — एक शाम और एक नोटबुक। और ग़लत किस्म पर अड़े रहने का ख़र्च? पूरा मौसम, पूरी लागत और हिम्मत की चोट। सस्ती जाँच से महँगी हार टलती है। इसलिए साल में एक बार, फ़सल-मौसम से पहले, अपना फ़ैसला-पत्र निकालकर चारों पंक्तियाँ ताज़ा कर लीजिए। पुरानी लिखावट के आगे नई तारीख़ से नई हालत लिखिए। दो साल की लिखावट मिलाकर पढ़ेंगे, तो अपने ही इलाक़े की चाल दिखने लगेगी।\n\nयही इस कोर्स की ईमानदारी है। हम बटन इसलिए नहीं पढ़ा रहे कि वही एकमात्र सच है। इसलिए पढ़ा रहे हैं कि आपके इलाक़े की तराज़ू आज यही कहती है। तौलने का हुनर आपके हाथ में रहेगा। किस्म बदले या ज़माना — तराज़ू वही चार पलड़ों वाली रहेगी।\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरा फ़ैसला-पत्र\" नाम का पन्ना बनाइए। चार पंक्तियाँ खींचिए — हर कसौटी की एक। हर पंक्ति के आगे अपने घर की आज की सच्चाई लिखिए। जैसे — जगह के आगे लिखिए कि कौन-सी कोठरी या कोना ख़ाली है। जो नहीं मालूम, वहाँ साफ़ लिखिए — पता करना है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- चारों कसौटियों की पंक्तियाँ भरी हों\n- कम से कम दो पंक्तियों में \"पता करना है\" जैसा ईमानदार सवाल बचा हो\n\n### 5. सबूत\n\nफ़ैसला-पत्र की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैं बिहार के गाँव में रहता हूँ और बटन मशरूम का धंधा सोच रहा हूँ। मेरा फ़ैसला-पत्र यह कहता है। इन चार कसौटियों में मेरी सबसे कमज़ोर कड़ी कौन-सी दिखती है?\"* — फिर अपनी चारों पंक्तियाँ बताइए।\n\n### 7. आम ग़लती\n\nलोग वह प्रजाति चुन लेते हैं, जिसका वीडियो सबसे पहले दिख गया। **वीडियो आपका बाज़ार नहीं जानता।** वीडियो बनाने वाले का इलाक़ा अलग है, उसका ग्राहक अलग है। फ़ैसला अपने बाज़ार से निकालिए, परदे से नहीं।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | अध्याय अ-1 पूरा |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | सोचना, लिखना, घर की जगह देखना |\n| क्या कभी नहीं | बिना बाज़ार देखे बीज या सामान ख़रीदना |\n\n### 9. स्रोत\n\n- बटन — दुनिया के मशरूम-बाज़ार का सबसे बड़ा हिस्सा ([imarcgroup.com](https://www.imarcgroup.com/mushroom-market)) · देखा गया 09-08-2026\n- बिहार — भारत का नंबर-एक मशरूम-राज्य ([freshplaza.com](https://www.freshplaza.com/asia/article/9793769/bihar-emerges-as-india-s-top-mushroom-producer/)) · देखा गया 09-08-2026\n\n*अनुदान की योजनाएँ समय-समय पर बदलती हैं। आवेदन से पहले अपने ज़िले के उद्यान-कार्यालय से ताज़ा नियम पूछिए।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं चारों कसौटियाँ बिना देखे गिना सकता हूँ\n- [ ] मैं बता सकता हूँ कि रमेश की फ़सल क्यों नहीं बिकी\n- [ ] मैं बिहार के मशरूम-कारोबार का एक पक्का आँकड़ा बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि कोर्स ने आसान नहीं, बिकाऊ प्रजाति क्यों चुनी\n- [ ] मैंने अपना चार-पंक्ति फ़ैसला-पत्र भर लिया है\n\n**आगे का पाठ:** पहली कसौटी की असली परीक्षा — अपने पाँव से हाट जाकर बाज़ार को गिनना।\n\n---\n---\n", "14": "# पाठ 14 — बाज़ार की कसौटी — मेरे इलाक़े में कौन बिकता है\n\n**अध्याय:** अ-2 · **पाठ:** 2 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप बाज़ार को अंदाज़े से नहीं, गिनती से पढ़ेंगे। आप तीन ठिकानों का एक छोटा सर्वे करना सीखेंगे। और एक पत्रक भरेंगे, जो आगे के कई फ़ैसलों की नींव बनेगा।\n\n### 2. मुख्य बात\n\n> फ़सल पहले नहीं, ग्राहक पहले। जो आदमी उगाने से पहले बेचने की जगह देख लेता है, वह आधी जंग वहीं जीत लेता है।\n\n---\n\n### आँख का धोखा, गिनती का सच\n\nबाज़ार के बारे में हर आदमी की एक राय होती है। कोई कहता है — यहाँ तो ख़ूब बिकेगा। कोई कहता है — यहाँ कोई नहीं ख़रीदेगा। दोनों के पास सबूत नहीं होता। सिर्फ़ सुनी-सुनाई बात होती है।\n\nधंधे में राय नहीं चलती। गिनती चलती है। और अच्छी बात यह है कि गिनती का यह काम मुफ़्त है। न पैसा लगता है, न मशीन। सिर्फ़ एक शाम, एक नोटबुक और थोड़ी हिम्मत लगती है — दुकानदार से बात करने की।\n\n### तीन ठिकाने — कहाँ-कहाँ जाना है\n\nआपका सर्वे तीन जगह होगा। तीनों का ग्राहक अलग है, इसलिए तीनों का सच अलग है।\n\nपहला ठिकाना — हफ़्ते की हाट या सब्ज़ी-मंडी। यहाँ आम घरों का ग्राहक आता है। यहीं सबसे बड़ी बिक्री छिपी होती है।\n\nदूसरा ठिकाना — क़स्बे की दो-तीन सब्ज़ी-दुकानें। दुकानदार रोज़ का खिलाड़ी है। वह जानता है कि कौन-सी चीज़ लौटती है और कौन-सी दोपहर तक उड़ जाती है।\n\nतीसरा ठिकाना — कोई होटल, ढाबा या शादी-भोज का रसोइया। यह थोक का ग्राहक है। एक होटल दस घरों के बराबर ख़रीद सकता है।\n\n### क्या पूछना, क्या गिनना\n\nहर ठिकाने पर पाँच बातें दर्ज करनी हैं। सीधे और नम्र सवालों से।\n\nएक — मशरूम मिलता है या नहीं। दो — कौन-सी किस्म रखी है। सफ़ेद गोल टोपी वाला बटन है, या पंखुड़ी जैसा ढींगरी, या कोई और। तीन — दाम क्या चल रहा है। पैकेट का वज़न ज़रूर देखिए, क्योंकि दाम वज़न से जुड़ा होता है। चार — माल आता कहाँ से है। अपने ज़िले से, पटना से, या बाहर से। पाँच — दुकानदार की एक राय। क्या और माल मिले तो बिकेगा?\n\nमान लो हाट में चार सब्ज़ी-ठेले हैं। दो पर बटन रखा है। एक ठेले वाला कहता है — शादी के महीने में माँग दुगनी हो जाती है। यह एक पंक्ति सोने जैसी है। इसे शब्दों-समेत लिखिए। ऐसे ही टुकड़ों से आपका बाज़ार-नक़्शा बनता है।\n\n### एक दिन का सच पूरा सच नहीं\n\nसर्वे की एक चालाकी समझ लीजिए। सोमवार की सूनी हाट और इतवार की भरी हाट — दोनों अलग कहानी कहती हैं। त्योहार के पहले की माँग और सावन की माँग अलग होती है।\n\nइसलिए अपने पत्रक पर तारीख़ और दिन ज़रूर लिखिए। और मन में यह नोट रखिए — यह एक दिन की झलक है, पूरी तस्वीर नहीं। पूरी तस्वीर कई झलकों से बनेगी। आगे माँग-योजना वाले अध्याय में यही पत्रक बड़ा होकर सालाना नक़्शा बनेगा।\n\nएक सावधानी और। दुकानदार से बात करते समय ख़रीदार बनकर मत जाइए। सीधा कहिए — मैं मशरूम उगाना सीख रहा हूँ, थोड़ी जानकारी चाहिए। सच बोलने वाले को दुकानदार अक्सर ज़्यादा बताता है।\n\n### चित्र — बाज़ार-पत्रक का नमूना\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">मेरा बाज़ार-पत्रक — एक ठिकाने का खाका</text>\n  <rect x=\"80\" y=\"100\" width=\"640\" height=\"620\" rx=\"14\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"80\" y=\"100\" width=\"640\" height=\"70\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"145\" font-size=\"24\" fill=\"#F9A825\" text-anchor=\"middle\">ठिकाना: हाट / दुकान / होटल · दिन-तारीख़</text>\n  <text x=\"120\" y=\"230\" font-size=\"22\" fill=\"#0B1F3A\">1. मशरूम मिलता है?  हाँ / नहीं</text>\n  <line x1=\"120\" y1=\"250\" x2=\"680\" y2=\"250\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"310\" font-size=\"22\" fill=\"#0B1F3A\">2. किस्म कौन-सी? (बटन / ढींगरी / और)</text>\n  <line x1=\"120\" y1=\"330\" x2=\"680\" y2=\"330\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"390\" font-size=\"22\" fill=\"#0B1F3A\">3. दाम और पैकेट का वज़न</text>\n  <line x1=\"120\" y1=\"410\" x2=\"680\" y2=\"410\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"470\" font-size=\"22\" fill=\"#0B1F3A\">4. माल कहाँ से आता है</text>\n  <line x1=\"120\" y1=\"490\" x2=\"680\" y2=\"490\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"550\" font-size=\"22\" fill=\"#0B1F3A\">5. दुकानदार की एक राय (उसी के शब्द)</text>\n  <line x1=\"120\" y1=\"570\" x2=\"680\" y2=\"570\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <rect x=\"120\" y=\"610\" width=\"560\" height=\"80\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"645\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">यही पत्रक तीन ठिकानों पर भरना है</text>\n  <text x=\"400\" y=\"675\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">तारीख़-दिन के बिना पत्रक अधूरा है</text>\n  <text x=\"400\" y=\"755\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">एक दिन की झलक = शुरुआत · पूरी तस्वीर कई झलकों से</text>\n</svg>\n\n### गिनती किस काम आएगी — आगे की कड़ी\n\nयह पत्रक सिर्फ़ आज का अभ्यास नहीं है। यही आपके धंधे की पहली बही है। आगे जब बिक्री के दरवाज़े चुनने का अध्याय आएगा, तब यही तीन पत्रक बताएँगे कि पहला माल किस दरवाज़े ले जाना है। जब दाम तय करने की घड़ी आएगी, तब आज की दाम-पंक्ति ही आपकी ज़मीन बनेगी। और जब माँग-योजना का पाठ आएगा, तब महीनों के जमा पत्रक मिलकर सालाना चाल दिखाएँगे।\n\nएक छोटा नियम गिनती की सफ़ाई का भी। हर आँकड़े के आगे यह ज़रूर दिखे कि वह किस ठिकाने से आया। बिना ठिकाने का आँकड़ा अफ़वाह बन जाता है। ठिकाने वाला आँकड़ा सबूत रहता है। यही आदत आगे हर रजिस्टर में काम आएगी।\n\nइसलिए इस पन्ने को सँभालकर रखिए। फटे-पुराने काग़ज़ पर नहीं, अपनी पक्की नोटबुक में। धंधे वाले की ताक़त उसकी बही में होती है। बही आज से शुरू हो गई।\n\n### बात करने का सलीक़ा\n\nसर्वे का आधा फल पूछने के ढंग से मिलता है। कुछ सलीक़े गाँठ बाँध लीजिए।\n\nवक़्त देखकर जाइए। भीड़ के समय दुकानदार का ध्यान गिनती पर होता है, बात पर नहीं। सुबह की सुस्त घड़ी या दोपहर का ठहराव बेहतर है। पहुँचकर पहले राम-सलाम, फिर अपनी बात एक वाक्य में — सीखने वाला हूँ, दो मिनट चाहिए। समय ख़त्म होते ही धन्यवाद कहकर हटिए। यही दुकानदार आगे आपका पहला ख़रीदार बन सकता है। रिश्ता आज से बनता है।\n\nएक काम बिल्कुल मत कीजिए — मोल-भाव। आप आज ख़रीदने नहीं, समझने आए हैं। भाव-तोल करते ही बातचीत का रंग बदल जाता है।\n\nहोटल-ढाबे पर एक सवाल और जोड़ लीजिए — हफ़्ते में कितना मशरूम लगता है और किस दिन। रसोइया यह गिनती ज़बानी जानता है। थोक ग्राहक की यह एक पंक्ति दस घरों की गिनती के बराबर होती है।\n\nलौटकर तीनों पत्रकों को जोड़िए। नीचे तीन पंक्तियों का सार लिखिए — कहाँ माल है, कहाँ नहीं है, और सबसे चौंकाने वाली बात कौन-सी मिली। मान लो सार यह निकला — हाट में बटन है, होटल वाला ताज़ा माल ढूँढ रहा है। यह एक पंक्ति आपके धंधे का पहला दरवाज़ा दिखा रही है। ऐसे ही सार से नक़्शा बनता है।\n\n### 3. आज का काम «असली»\n\nऊपर वाले खाके से नोटबुक में तीन पत्रक बनाइए। फिर सचमुच निकलिए — एक हाट या मंडी, एक सब्ज़ी-दुकान, एक होटल या ढाबा। तीनों जगह पाँचों सवाल पूछकर पत्रक भरिए। दुकानदार की राय उसी के शब्दों में उतारिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- तीनों पत्रकों पर ठिकाने का नाम, दिन और तारीख़ लिखी हो\n- कम से कम एक पत्रक में दाम वज़न-समेत दर्ज हो\n\n### 5. सबूत\n\nतीनों भरे पत्रकों की फ़ोटो। हो सके तो एक ठिकाने की दूर से ली गई फ़ोटो भी।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैंने अपने इलाक़े के तीन ठिकानों का मशरूम-सर्वे किया है। आँकड़े यह हैं। इनसे मेरे बाज़ार के बारे में क्या समझ बनती है और कौन-सी जानकारी अभी अधूरी है?\"* — फिर तीनों पत्रक पढ़कर सुनाइए।\n\n### 7. आम ग़लती\n\nलोग सर्वे के नाम पर सिर्फ़ दाम पूछकर लौट आते हैं। **अकेला दाम आधी ख़बर है।** किस्म, वज़न, माल का रास्ता और दुकानदार की राय — इनके बिना दाम का कोई मतलब नहीं बनता। पाँचों खाने भरिए, तभी पत्रक बोलेगा।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13 पूरा |\n| ज़रूरी सामान | नोटबुक, क़लम, आने-जाने का इंतज़ाम |\n| देखरेख | नाबालिग हों तो घर के बड़े को बताकर निकलें |\n| क्या कर सकते हैं | देखना, पूछना, गिनना, लिखना |\n| क्या कभी नहीं | सर्वे के जोश में कोई ख़रीद या सौदा कर बैठना |\n\n### 9. स्रोत\n\n- अपने ही तीन ठिकानों की गिनती — यही इस पाठ का असली स्रोत है\n- मंडी-भाव की सरकारी झलक ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n\n*सरकारी portal पर हर मंडी का भाव रोज़ नहीं चढ़ता। अपनी आँख की गिनती को ही पहला दर्जा दीजिए।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीनों ठिकानों के नाम और उनका फ़र्क़ बता सकता हूँ\n- [ ] मैं पाँचों सवाल बिना देखे बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि पत्रक पर दिन-तारीख़ क्यों ज़रूरी है\n- [ ] मैंने तीनों पत्रक सचमुच भर लिए हैं\n- [ ] मैं जानता हूँ कि एक दिन की झलक पूरा सच क्यों नहीं है\n\n**आगे का पाठ:** दूसरी कसौटी — मौसम। बटन को ठंडक क्यों चाहिए, और आपके इलाक़े में उसकी खिड़की कब खुलती है।\n\n---\n---\n", "15": "# पाठ 15 — मौसम की कसौटी — बटन को ठंडक चाहिए\n\n**अध्याय:** अ-2 · **पाठ:** 3 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप बटन का मिज़ाज समझ जाएँगे। आप जानेंगे कि उसे किस चरण में कितनी ठंडक चाहिए। और अपने इलाक़े के बारह महीनों में वह खिड़की ढूँढ लेंगे, जब यह धंधा बिना मशीन के चल सकता है।\n\n### 2. मुख्य बात\n\n> बटन गर्मी का नहीं, ठंडक का जीव है। मौसम से लड़ने वाला हारता है। मौसम के साथ चलने वाला कम ख़र्च में जीतता है।\n\n---\n\n### हर जीव का अपना मौसम\n\nआम गर्मी में आता है। गोभी सर्दी में फलती है। कोई किसान जुलाई में गोभी की ज़िद नहीं करता। मशरूम भी जीव है। उसका भी मौसम है।\n\nबटन का मिज़ाज ठंडा है। यह पहाड़ी यूरोप की ठंडी जलवायु से चला मशरूम है। गर्म हवा में इसका जाल सुस्त पड़ता है। कलियाँ रुक जाती हैं। और गर्मी में गंदगी वाले जीव तेज़ हो जाते हैं। यानी दुश्मन ताक़तवर, दोस्त कमज़ोर।\n\nइसीलिए बटन की खेती में मौसम पहली गिनती है। जगह, बीज, कम्पोस्ट — सब बाद में। पहले यह तय होता है कि कब उगाना है।\n\n### दो चरण, दो ज़रूरतें\n\nबटन की ज़िंदगी में ठंडक की माँग एक जैसी नहीं रहती। दो चरण अलग-अलग माँग रखते हैं।\n\nपहला चरण — जाल फैलना। बीज मिलाने के बाद सफ़ेद जाल पूरे कम्पोस्ट में दौड़ता है। इस चरण में बटन थोड़ी नरम गर्माहट चाहता है। मशरूम अनुसंधान निदेशालय की प्रकाशित सामग्री के अनुसार यह श्रेणी लगभग बाईस से पच्चीस डिग्री की है।\n\nदूसरा चरण — कली और फ़सल। केसिंग के बाद जब मशरूम बनना शुरू होता है, तब उसे असली ठंडक चाहिए। यह श्रेणी लगभग चौदह से अठारह डिग्री की है।\n\nदोनों नंबर श्रेणी हैं, ताला नहीं। नस्ल बदलने पर थोड़ा ऊपर-नीचे होता है। इसीलिए पक्का नियम यह है — अपने बीज की पर्ची पर लिखी श्रेणी को ही अंतिम मानिए। पर्ची और पाठ में फ़र्क़ दिखे, तो पर्ची जीतेगी।\n\n### बिहार की खिड़की\n\nअब अपने इलाक़े को देखिए। मैदानी बिहार की गर्मी तेज़ है। पर सर्दी भी असली है। नवंबर से फ़रवरी की रातें ठंडी होती हैं। यही बटन की क़ुदरती खिड़की है।\n\nइस खिड़की का मतलब समझिए। इन महीनों में फ़सल वाला चरण बिना ठंडक-मशीन के चल सकता है। मोटा ख़र्च बच जाता है। इसीलिए बिहार का बटन-कारोबार सर्दी की फ़सल पर खड़ा है।\n\nअब उल्टा हिसाब कीजिए। फ़सल सर्दी में चाहिए, तो उसकी तैयारी पहले शुरू होती है। कम्पोस्ट बनने में हफ़्ते लगते हैं। जाल फैलने में और हफ़्ते। यानी असली काम पतझड़ से ही छिड़ जाता है। यह उल्टा-हिसाब आगे एक पूरे पाठ में बारीकी से बैठेगा। अभी सिर्फ़ सिद्धांत पकड़िए — फ़सल की तारीख़ से पीछे चलकर काम की तारीख़ निकलती है।\n\nऔर गर्मी में बटन? हो सकता है, पर ठंडक-मशीन वाले ढाँचे में। वह ऊपर की सीढ़ी का ख़र्च है। पहली सीढ़ी वाले के लिए सीधा नियम — मौसम की खिड़की में चलिए, मशीन से मत लड़िए।\n\n### मौसम-पत्रक — आपका अपना नक़्शा\n\nकिताब का मौसम और आपके गाँव का मौसम जुड़वाँ नहीं होते। नदी-किनारे का गाँव अलग है। शहर से सटा मोहल्ला अलग है। इसलिए हर सीखने वाला अपना मौसम-पत्रक बनाता है।\n\nतरीक़ा सरल है। बारह महीनों की सूची बनाइए। हर महीने के आगे अपनी याद से लिखिए — रात कैसी रहती है? ठंडी, नरम या गर्म? घर के बुज़ुर्गों से पूछिए, उनकी याद लंबी होती है। फिर उन महीनों पर घेरा लगाइए, जिनकी रातें सचमुच ठंडी हैं। वही घेरा आपकी खिड़की है।\n\n### चित्र — साल का पहिया और सर्दी की खिड़की\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">बटन की मौसम-खिड़की — मैदानी इलाक़ा</text>\n  <circle cx=\"400\" cy=\"420\" r=\"240\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <path d=\"M 400 180 A 240 240 0 0 1 631 357 L 400 420 Z\" fill=\"#1565C0\"/>\n  <path d=\"M 400 180 A 240 240 0 0 0 169 357 L 400 420 Z\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"150\" font-size=\"22\" fill=\"#0B1F3A\" text-anchor=\"middle\">नवंबर — फ़रवरी</text>\n  <text x=\"400\" y=\"250\" font-size=\"24\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">ठंडी रातें</text>\n  <text x=\"400\" y=\"285\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">फ़सल की खिड़की</text>\n  <text x=\"400\" y=\"560\" font-size=\"22\" fill=\"#0B1F3A\" text-anchor=\"middle\">गर्म महीने — बिना मशीन फ़सल नहीं</text>\n  <text x=\"235\" y=\"470\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">पतझड़ से</text>\n  <text x=\"235\" y=\"498\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">तैयारी शुरू</text>\n  <line x1=\"285\" y1=\"480\" x2=\"350\" y2=\"420\" stroke=\"#2E7D32\" stroke-width=\"5\"/>\n  <rect x=\"110\" y=\"690\" width=\"580\" height=\"60\" rx=\"30\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"728\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">जाल: लगभग 22-25° · फ़सल: लगभग 14-18° (श्रेणी)</text>\n  <text x=\"400\" y=\"775\" font-size=\"17\" fill=\"#0B1F3A\" text-anchor=\"middle\">अंतिम सच = आपके बीज की पर्ची · अपना मौसम-पत्रक ख़ुद बनाइए</text>\n</svg>\n\n### खिड़की छोटी नहीं, मौक़ा है\n\nकोई मन में कह सकता है — बस चार-पाँच महीने की खिड़की? बाक़ी साल क्या करें? इसे कमी मत समझिए, ढाँचा समझिए। खिड़की के महीने फ़सल के हैं। उसके पहले के महीने तैयारी के हैं — सामान, कम्पोस्ट, सफ़ाई, सीख। और फ़सल के बाद के महीने बिक्री की समीक्षा और अगले साल की योजना के हैं। यानी साल का हर हिस्सा काम का है, बस काम का नाम बदलता है। बड़े किसान भी इसी घड़ी से चलते हैं। आगे माँग-योजना वाला अध्याय इसी घड़ी को तालिका में बदलेगा।\n\n### ठंडक के दो साथी — नमी और हवा\n\nमौसम सिर्फ़ तापमान नहीं होता। बटन की कोठरी में दो साथी और गिने जाते हैं — नमी और हवा। इनकी बारीक़ नाप आगे के अध्यायों में आएगी। अभी सिर्फ़ पहचान पकड़िए।\n\nनमी यानी हवा में बसा पानी। मशरूम का शरीर ही ज़्यादातर पानी है, इसलिए सूखी हवा उसे झुलसा देती है। सर्दी की सुबह की गीली ठंडक बटन को भाती है। और हवा यानी ताज़ा साँस। बंद दम-घुटे कमरे में मशरूम भी घुटता है। ठंडा पर हवादार कोना — यही जोड़ी चाहिए।\n\nएक बात रात-दिन की भी। दिन का तापमान अख़बार बताता है। पर आपकी फ़सल रात में जीती है। इसलिए मौसम-पत्रक में रात की हालत लिखवाई गई है, दिन की नहीं।\n\nपहचान का एक घरेलू तरीक़ा भी है। शाम को कोठरी में पाँच मिनट खड़े होइए। साँस घुटे, तो हवा कम है। दीवारें सीली चमकें, तो नमी की गवाही है। यंत्र से पहले आँख-नाक भी नापते हैं।\n\nऔर एक सस्ती सलाह अभी से। आगे जब सामान की सूची बनेगी, उसमें एक साधारण थर्मामीटर ज़रूर रहेगा। अंदाज़े की ठंडक और नापी हुई ठंडक में वही फ़र्क़ है, जो सुनी हुई और गिनी हुई हाट में था। नाप की आदत इसी कोर्स की पहचान है।\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में बारह महीनों का मौसम-पत्रक बनाइए। हर महीने के आगे रात की हालत लिखिए — ठंडी, नरम या गर्म। कम से कम एक बुज़ुर्ग से पूछकर उनकी बात भी जोड़िए। फिर ठंडे महीनों पर घेरा लगाकर नीचे लिखिए — मेरी खिड़की इतने महीने की है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- बारहों महीनों की पंक्तियाँ भरी हों\n- घेरे वाले महीनों की गिनती नीचे साफ़ लिखी हो\n\n### 5. सबूत\n\nभरे मौसम-पत्रक की फ़ोटो, घेरा दिखता हुआ।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरे इलाक़े का मौसम-पत्रक यह कहता है। बटन के दो चरणों की ठंडक-श्रेणियाँ ये हैं। मेरी फ़सल-खिड़की कौन-से महीनों में सबसे पक्की दिखती है?\"* — फिर अपना पत्रक पढ़कर सुनाइए। जवाब को बुज़ुर्गों की याद से मिलाइए।\n\n### 7. आम ग़लती\n\nजोश में लोग अप्रैल-मई में शुरुआत कर बैठते हैं। **मौसम माफ़ नहीं करता।** गर्म कमरे में कलियाँ रुकती हैं और गंदगी दौड़ती है। पहली फ़सल हारकर आदमी धंधे को दोष देता है। दोष धंधे का नहीं, तारीख़ का था।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13-14 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | पूछना, याद जोड़ना, पत्रक भरना |\n| क्या कभी नहीं | गर्म महीनों में बिना ठंडक-इंतज़ाम फ़सल की योजना बनाना |\n\n### 9. स्रोत\n\n- भारतीय कृषि अनुसंधान परिषद — मशरूम अनुसंधान निदेशालय, सोलन ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n\n*तापमान की दोनों श्रेणियाँ प्रकाशित वैज्ञानिक सामग्री का सार हैं। नस्ल बदलने पर श्रेणी थोड़ी खिसकती है — अपने बीज की पर्ची अंतिम है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बटन के दो चरणों की ठंडक-माँग का फ़र्क़ बता सकता हूँ\n- [ ] मैं दोनों श्रेणियाँ स्रोत-समेत बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि पर्ची किताब से क्यों जीतती है\n- [ ] मैंने अपना बारह-महीने का मौसम-पत्रक भर लिया है\n- [ ] मैं उल्टे-हिसाब का सिद्धांत एक वाक्य में कह सकता हूँ\n\n**आगे का पाठ:** तीसरी कसौटी — बटन का खाना। कम्पोस्ट क्या है और आपके इलाक़े में कहाँ से मिलेगा।\n\n---\n---\n", "16": "# पाठ 16 — कच्चा माल और कम्पोस्ट — क्या, कहाँ से मिलेगा\n\n**अध्याय:** अ-2 · **पाठ:** 4 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप बटन के खाने को नाम से जानेंगे — कम्पोस्ट। आप समझेंगे कि शुरुआत में इसे ख़रीदना ही समझदारी क्यों है। और अपने इलाक़े में इसके ठिकाने खोजने का तरीक़ा सीखेंगे।\n\n### 2. मुख्य बात\n\n> बटन घास-फूस सीधे नहीं खाता। उसका खाना पकाकर बनता है — इसी पके खाने का नाम कम्पोस्ट है। पहली सीढ़ी वाला इसे बनाता नहीं, ख़रीदता है।\n\n---\n\n### पका हुआ खाना — कम्पोस्ट की पहचान\n\nहर मशरूम का भोजन अलग है। ढींगरी भीगे पुआल पर चल जाती है। शिटाके लकड़ी का चूरा माँगता है। बटन इन दोनों से आगे की माँग रखता है।\n\nबटन को चाहिए — सड़ाकर पकाया हुआ ख़ास मिश्रण। गेहूँ का भूसा, मुर्ग़ी-खाद जैसी चीज़ें और कुछ मसाले मिलाकर ढेर बनाया जाता है। ढेर भीतर से गर्म होता है। हफ़्तों की पलटाई और भाप-सफ़ाई के बाद वह गहरा भूरा, नरम माल बनता है। महक मीठी-मिट्टी जैसी होती है, अमोनिया की चुभन नहीं। यही तैयार कम्पोस्ट है।\n\nयह बनाना पूरा हुनर है। इसीलिए इस कोर्स में इसके अपने अध्याय हैं — वहाँ आप ढेर से भाप तक सब सीखेंगे। पर वह आगे की बात है।\n\n### पहली सीढ़ी का नियम — बनाओ मत, ख़रीदो\n\nनए आदमी के लिए सबसे बड़ा जाल यही है — पहले ही दिन कम्पोस्ट बनाने बैठ जाना। हफ़्तों की मेहनत, और अनुभव बिना ढेर बिगड़ने का पूरा ख़तरा। ढेर बिगड़ा तो फ़सल शुरू होने से पहले ही हार हो गई।\n\nसमझदार रास्ता उल्टा है। बाज़ार से तैयार कम्पोस्ट ख़रीदिए। कई जगह तो बीज मिला हुआ चरण-तीन कम्पोस्ट भी मिलता है — यानी जाल दौड़ा हुआ माल, जिसे बस बिछाकर सँभालना है। शुरुआत इसी से सबसे सस्ती और सबसे पक्की बैठती है।\n\nइस रास्ते का एक और फ़ायदा गिनिए। ख़रीदे माल पर आपकी पूरी ताक़त देखभाल सीखने में लगती है। यही असली हुनर है। कम्पोस्ट बनाना बाद में सीखेंगे, जब हाथ जम जाएगा।\n\n### ठिकाने कहाँ-कहाँ हैं\n\nअब सवाल यह कि ख़रीदें कहाँ से। नाम हर ज़िले में अलग होंगे, पर ठिकानों की क़िस्में तीन ही हैं।\n\nपहली क़िस्म — सरकारी और अर्ध-सरकारी ठिकाने। ज़िले का उद्यान-कार्यालय, कृषि विज्ञान केंद्र, या राज्य का बाग़वानी विभाग। ये ख़ुद बेचते नहीं तो बेचने वालों का पता ज़रूर देते हैं। बिहार बाग़वानी विभाग की योजनाएँ ([horticulture.bihar.gov.in](https://horticulture.bihar.gov.in/)) यहीं से खुलती हैं।\n\nदूसरी क़िस्म — बड़ी कम्पोस्ट-इकाइयाँ। जहाँ मशरूम का कारोबार जमा है, वहाँ कुछ लोग सिर्फ़ कम्पोस्ट बनाकर बेचने का धंधा करते हैं। इस कोर्स में आगे एक पूरा अध्याय इसी धंधे पर है — यानी कल आप ख़रीदार हैं, परसों विक्रेता भी बन सकते हैं।\n\nतीसरी क़िस्म — पुराने मशरूम-किसान और उनके समूह। साठ-सत्तर हज़ार किसानों वाले राज्य में हर बड़े प्रखंड में कोई न कोई अनुभवी मिलेगा। ऐसा आदमी माल भी देता है और मुफ़्त की सीख भी।\n\n### ढुलाई और मात्रा का हिसाब\n\nख़रीद में दो बातें पहले सोचिए। पहली — मात्रा। पहला चक्र पाँच बैग का है। मान लो हर बैग में दस-बारह किलो कम्पोस्ट बैठता है। यानी कुल पचास-साठ किलो का इंतज़ाम चाहिए। यह एक जुगाड़-गाड़ी का काम है, ट्रक का नहीं।\n\nदूसरी — दूरी। कम्पोस्ट भारी और नमी वाला माल है। सौ किलोमीटर की ढुलाई छोटी ख़रीद को महँगा कर देती है। इसलिए पास का ठिकाना दूर के सस्ते ठिकाने से अक्सर जीत जाता है। यह हिसाब आगे इकाई-अर्थशास्त्र में गिनती से बैठेगा।\n\nऔर परख? महक, रंग और जाल की पहचान वाली पूरी कसौटी पहले-चक्र वाले अध्याय में हाथ पकड़कर सिखाई जाएगी। आज का काम सिर्फ़ ठिकाने खोजना है।\n\n### चित्र — कम्पोस्ट के तीन रास्ते\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">तैयार कम्पोस्ट कहाँ से — तीन क़िस्म के ठिकाने</text>\n  <rect x=\"60\" y=\"120\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"160\" y=\"165\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">सरकारी</text>\n  <text x=\"160\" y=\"195\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">उद्यान-कार्यालय</text>\n  <text x=\"160\" y=\"225\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">कृषि विज्ञान केंद्र</text>\n  <text x=\"160\" y=\"255\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">पता यहीं मिलता है</text>\n  <rect x=\"300\" y=\"120\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"165\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">कम्पोस्ट-इकाई</text>\n  <text x=\"400\" y=\"195\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">बनाकर बेचने वाले</text>\n  <text x=\"400\" y=\"225\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">चरण-3 माल भी</text>\n  <text x=\"400\" y=\"255\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">बीज-मिला विकल्प</text>\n  <rect x=\"540\" y=\"120\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"640\" y=\"165\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">पुराने किसान</text>\n  <text x=\"640\" y=\"195\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">और उनके समूह</text>\n  <text x=\"640\" y=\"225\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">माल के साथ</text>\n  <text x=\"640\" y=\"255\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">मुफ़्त सीख भी</text>\n  <line x1=\"160\" y1=\"275\" x2=\"380\" y2=\"430\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"400\" y1=\"275\" x2=\"400\" y2=\"430\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"640\" y1=\"275\" x2=\"420\" y2=\"430\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"270\" y=\"440\" width=\"260\" height=\"110\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"485\" font-size=\"24\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">आपका आँगन</text>\n  <text x=\"400\" y=\"520\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">पाँच बैग ≈ 50-60 किलो</text>\n  <rect x=\"110\" y=\"610\" width=\"580\" height=\"60\" rx=\"30\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"648\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">पास का ठिकाना दूर के सस्ते से अक्सर जीतता है</text>\n  <text x=\"400\" y=\"730\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">पहली सीढ़ी: बनाओ मत, ख़रीदो — बनाना आगे के अध्यायों में</text>\n</svg>\n\n### भूसे वाला इलाक़ा — छिपा हुआ फ़ायदा\n\nएक हौसला बढ़ाने वाली बात भी गिन लीजिए। कम्पोस्ट की सबसे बड़ी सामग्री गेहूँ का भूसा है। और गेहूँ वाले मैदानी इलाक़े में भूसा घर-घर की चीज़ है। यही वजह है कि यह धंधा यहाँ की मिट्टी में इतना जमा। जब आप आगे चलकर ख़ुद कम्पोस्ट बनाएँगे, तब कच्चा माल आपके अपने खेत-खलिहान से या पड़ोस से मिलेगा। दूर से मँगाने वाले इलाक़ों के मुक़ाबले यह सीधी बचत है। आज ख़रीदार बनकर शुरू कीजिए। कल यही भूसा आपको बनाने वाला बना देगा।\n\n### ख़रीद से पहले के पाँच सवाल\n\nठिकाना मिल जाए, तो बातचीत के पाँच सवाल तैयार रखिए। ये सवाल आपको जानकार ख़रीदार बनाते हैं।\n\nपहला — माल कौन-से चरण का है? सादा तैयार कम्पोस्ट है, या बीज-मिला चरण-तीन? दूसरा — अगली खेप कब उतरेगी? कम्पोस्ट रोज़ नहीं बनता, बैच में बनता है। तीसरा — दाम किस हिसाब से है? किलो के भाव या बैग के भाव? वज़न पूछे बिना दाम अधूरा है। चौथा — भराई किसमें होगी? बोरा उनका या आपका? पाँचवाँ — ढुलाई का इंतज़ाम किसके ज़िम्मे?\n\nमान लो एक ठिकाना किलो के भाव बोलता है और दूसरा बैग के भाव। तुलना से पहले दोनों को एक ही पैमाने पर लाइए — प्रति किलो। पैमाना मिलाए बिना तुलना धोखा देती है।\n\nपाँचों जवाब नोटबुक में उतारिए। दो ठिकानों के जवाब आमने-सामने रखते ही सस्ता-महँगा ख़ुद बोल पड़ेगा।\n\nऔर एक पक्का पहरा। फ़ोन की मीठी बात पर अग्रिम पैसा कभी मत भेजिए। पहले माल आँख से देखिए, तब जेब खोलिए। भला ठिकाना देखने से कभी नहीं रोकता। जो रोकता है, वही ठिकाना छोड़ने लायक़ है।\n\n### 3. आज का काम «असली»\n\nनोटबुक में \"कम्पोस्ट-ठिकाना खोज\" पन्ना बनाइए। फिर सचमुच खोज कीजिए — फ़ोन से, पूछताछ से या जाकर। अपने इलाक़े के कम से कम दो संभावित ठिकाने दर्ज कीजिए। हर ठिकाने के आगे लिखिए — नाम, जगह, दूरी और बात किससे हुई। एक ठिकाना सरकारी क़िस्म का ज़रूर आज़माइए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दो ठिकाने नाम और दूरी के साथ दर्ज हों\n- हर ठिकाने पर बातचीत का एक-पंक्ति नतीजा लिखा हो\n\n### 5. सबूत\n\nखोज-पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मुझे अपने ज़िले में बटन मशरूम का तैयार कम्पोस्ट चाहिए। सरकारी दफ़्तर में जाकर ठीक-ठीक क्या और कैसे पूछूँ, ताकि सही ठिकाने का पता मिले?\"* — मिले जवाब से अपने सवालों की सूची बनाइए। पते की पक्की पुष्टि फ़ोन या मुलाक़ात से ही मानिए।\n\n### 7. आम ग़लती\n\nनए लोग पहले ही महीने ढेर बनाने की ठान लेते हैं। **कच्चा हाथ, बिगड़ा ढेर।** हफ़्तों की मेहनत और पैसा एक साथ डूबता है। पहला चक्र ख़रीदे माल पर सीखिए। बनाने का मैदान आगे पूरा खुला है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13-15 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, फ़ोन |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | पूछताछ, फ़ोन, दफ़्तर जाना, दर्ज करना |\n| क्या कभी नहीं | बिना देखे-परखे अग्रिम पैसा भेजना |\n\n### 9. स्रोत\n\n- बिहार सरकार — बाग़वानी विभाग ([horticulture.bihar.gov.in](https://horticulture.bihar.gov.in/)) · देखा गया 09-08-2026\n- मशरूम अनुसंधान निदेशालय, सोलन ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n\n*ठिकानों के नाम-पते ज़िले-दर-ज़िले बदलते हैं। इस पाठ ने क़िस्में सिखाईं — असली पते आपकी खोज से निकलेंगे।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बता सकता हूँ कि कम्पोस्ट क्या है और बटन को यही क्यों चाहिए\n- [ ] मैं समझा सकता हूँ कि पहली सीढ़ी पर ख़रीदना बनाने से बेहतर क्यों है\n- [ ] मैं तीनों क़िस्म के ठिकाने गिना सकता हूँ\n- [ ] मैंने अपने इलाक़े के दो ठिकाने दर्ज कर लिए हैं\n- [ ] मैं ढुलाई-दूरी का असर एक वाक्य में कह सकता हूँ\n\n**आगे का पाठ:** खाने के बाद बीज की बारी — Spawn (मशरूम बीज) क्या है और भरोसे का बीज कहाँ मिलता है।\n\n---\n---\n", "17": "# पाठ 17 — Spawn (मशरूम बीज) कहाँ से मिलेगा\n\n**अध्याय:** अ-2 · **पाठ:** 5 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप Spawn को ठीक-ठीक पहचानेंगे। आप जानेंगे कि भरोसे का Spawn किन ठिकानों से मिलता है। ताज़गी परखने की तीन निशानियाँ सीखेंगे। और अपने इलाक़े में इसके स्रोत खोजना शुरू कर देंगे।\n\n### 2. मुख्य बात\n\n> Spawn आपकी फ़सल की छत है। घटिया Spawn के ऊपर कोई मेहनत काम नहीं आती। इसलिए Spawn सबसे सस्ती जगह से नहीं, सबसे भरोसे की जगह से लिया जाता है।\n\n---\n\n### ज़िंदा माल की पहचान\n\nपहले पहचान पक्की कीजिए। Spawn कोई सूखा दाना नहीं है। यह उबालकर बाँझ किए गए अनाज पर चढ़ा हुआ मशरूम का ज़िंदा जाल है। थैली में सफ़ेद रुई जैसा फैलाव दिखता है। वही जाल आगे चलकर आपके कम्पोस्ट में दौड़ेगा।\n\nज़िंदा माल की अपनी शर्तें होती हैं। यह गर्मी से मरता है। पुराना होकर कमज़ोर पड़ता है। गंदगी लगे तो बीमार होता है। यानी Spawn की ख़रीद आलू-प्याज़ की ख़रीद जैसी नहीं है। यह मुर्ग़ी के चूज़े ख़रीदने जैसी है। ज़िंदा चीज़ को परखकर, सँभालकर लाना पड़ता है।\n\nएक राहत भी याद कर लीजिए। पिछले पाठ में चरण-तीन कम्पोस्ट का रास्ता बताया गया था। उस माल में जाल पहले से दौड़ा होता है। वह रास्ता चुनने वाले को पहले चक्र में अलग Spawn नहीं ख़रीदना पड़ता। फिर भी यह पाठ ध्यान से पढ़िए। दूसरे चक्र से यह ख़रीद आपकी अपनी होगी।\n\n### फ़सल की छत यहीं तय होती है\n\nअब वह बात, जो इस पाठ की जान है। मान लो दो सीखने वालों ने एक जैसा कम्पोस्ट लिया। एक जैसी कोठरी सजाई। एक जैसी देखभाल की। फिर भी एक की फ़सल भरपूर आई और दूसरे की आधी रह गई। फ़र्क़ कहाँ था? थैली में था।\n\nकमज़ोर या बूढ़ा Spawn धीमा चलता है। जाल सुस्त फैलता है। और सुस्त जाल का मैदान गंदगी के जीव पहले घेर लेते हैं। यानी घटिया Spawn सिर्फ़ कम फ़सल नहीं देता। वह पूरे बैग के बिगड़ने का दरवाज़ा भी खोलता है।\n\nइसीलिए पक्का नियम बना लीजिए। बाक़ी चीज़ों में दस रुपये बचाइए, हर्ज नहीं। Spawn में बचत मत ढूँढिए। यहाँ सस्ता अक्सर सबसे महँगा साबित होता है।\n\n### भरोसे के ठिकाने\n\nSpawn बनाना लैब का काम है। भाप से बाँझ करना, साफ़ कमरे में टीका लगाना — यह हुनर आगे के अध्यायों में सिखाया जाएगा। अभी ख़रीदार की नज़र से ठिकाने गिनिए।\n\nपहला ठिकाना — सरकारी लैब। मशरूम अनुसंधान निदेशालय जैसी संस्थाएँ, कृषि विश्वविद्यालय और कई कृषि विज्ञान केंद्र Spawn बनाते या बनवाते हैं। यहाँ का माल नाप-तौल के नियम से बनता है।\n\nदूसरा ठिकाना — निजी Spawn-लैब। मशरूम वाले इलाक़ों में कुछ कारोबारी सिर्फ़ यही काम करते हैं। अच्छी निजी लैब की पहचान उसकी साख से होती है। पुराने ख़रीदारों से राय लीजिए।\n\nतीसरा ठिकाना — बड़े मशरूम-किसान। कई अनुभवी किसान अपनी ज़रूरत का Spawn ख़ुद बनाते हैं और बचा हुआ बेचते हैं। पास का भरोसेमंद किसान नए आदमी के लिए अक्सर सबसे सुविधाजनक स्रोत बनता है।\n\nतीनों में साझी शर्त एक ही है — नाम-पता और ज़िम्मेदारी। बिना पहचान की थैली किसी मेले-ठेले से कभी मत उठाइए। जिस माल पर बनाने वाले का नाम नहीं, उस पर जवाबदेही भी नहीं।\n\n### ताज़गी की तीन निशानियाँ\n\nठिकाना मिल जाए, तो थैली को तीन निशानियों पर परखिए।\n\nपहली निशानी — रंग। भला Spawn ऊपर से नीचे तक सफ़ेद जाल से भरा दिखता है। कहीं हरा, काला या सलेटी धब्बा दिखे, तो वह थैली वहीं छोड़ दीजिए। धब्बा गंदगी की फफूँद है।\n\nदूसरी निशानी — तारीख़। Spawn बैच में बनता है और हर बैच की बनने की तारीख़ होती है। तारीख़ पूछिए और लिखवाइए। जितना ताज़ा, उतना जानदार। बहुत पुरानी थैली का जाल थका हुआ निकलता है।\n\nतीसरी निशानी — महक और नमी। थैली खुलने पर भीनी, मशरूम जैसी महक आनी चाहिए। खट्टी या सड़ी गंध ख़राबी की गवाही है। दाने आपस में जाल से बँधे हों, पर थैली में पानी न छूटा हो।\n\nलाने के बाद की सँभाल भी ताज़गी का हिस्सा है। थैली को धूप और चूल्हे की गर्मी से दूर, ठंडी छायादार जगह रखिए। और टालमटोल मत कीजिए — ज़िंदा माल इंतज़ार में कमज़ोर होता है। ख़रीद की तारीख़ काम की तारीख़ से मिलाकर तय कीजिए।\n\n### कितना लेना है — मोटा अंदाज़\n\nमात्रा का सवाल भी पहले सुलझा लीजिए। Spawn कम्पोस्ट के वज़न के हिसाब से लगता है — थोड़े में बहुत काम चलता है। पाँच बैग के पहले चक्र की ज़रूरत सचमुच छोटी होती है। ठीक-ठीक तौल का सूत्र बिछाई वाले अध्याय में गिनकर सिखाया जाएगा। आज ठिकाने से बस यह पूछ लीजिए — पाँच घरेलू बैग के लिए आप कितना देने की सलाह देते हैं। उसका जवाब नोटबुक में उतार लीजिए। बेचने वाले की सलाह और कोर्स का सूत्र मिलाकर ही अंतिम तौल बनेगी।\n\n### बुकिंग की संस्कृति\n\nएक व्यावहारिक बात और। लैब हलवाई की दुकान नहीं है कि जब पहुँचे, माल हाज़िर मिले। बैच बनने में हफ़्ते लगते हैं। मौसम की खिड़की में माँग एक साथ फटती है। इसलिए मशरूम की दुनिया में पहले से कहकर माल लिखवाने का रिवाज़ है।\n\nआपके लिए इसका मतलब सीधा है। खिड़की खुलने का इंतज़ार मत कीजिए। ठिकाने से पहले ही बात पक्की कर लीजिए — कौन-से हफ़्ते कितना माल चाहिए। पिछले पाठ का उल्टा-हिसाब यहीं काम आता है। जो आदमी तारीख़ से पीछे चलकर बुकिंग करता है, वह भीड़ के मौसम में भी ख़ाली हाथ नहीं लौटता।\n\n### चित्र — थैली की परख\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">Spawn की थैली — क्या देखना है</text>\n  <rect x=\"90\" y=\"120\" width=\"260\" height=\"340\" rx=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"6\"/>\n  <circle cx=\"150\" cy=\"200\" r=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n  <circle cx=\"220\" cy=\"260\" r=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n  <circle cx=\"290\" cy=\"200\" r=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n  <circle cx=\"180\" cy=\"330\" r=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n  <circle cx=\"260\" cy=\"380\" r=\"16\" fill=\"#F5F7FA\" stroke=\"#2E7D32\" stroke-width=\"3\"/>\n  <text x=\"220\" y=\"500\" font-size=\"24\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">✓ सही थैली</text>\n  <text x=\"220\" y=\"535\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">ऊपर-नीचे तक सफ़ेद जाल</text>\n  <rect x=\"450\" y=\"120\" width=\"260\" height=\"340\" rx=\"16\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\" stroke-width=\"6\"/>\n  <circle cx=\"530\" cy=\"220\" r=\"30\" fill=\"#2E7D32\"/>\n  <circle cx=\"620\" cy=\"330\" r=\"24\" fill=\"#0B1F3A\"/>\n  <text x=\"580\" y=\"500\" font-size=\"24\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">✗ छोड़ दो</text>\n  <text x=\"580\" y=\"535\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">हरा या काला धब्बा = गंदगी</text>\n  <rect x=\"90\" y=\"590\" width=\"620\" height=\"70\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"622\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">तीन निशानियाँ: रंग · बनने की तारीख़ · महक</text>\n  <text x=\"400\" y=\"650\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">नाम-पते के बिना थैली कभी नहीं</text>\n  <text x=\"400\" y=\"720\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">ठंडी छाया में रखो · देर मत करो — यह ज़िंदा माल है</text>\n</svg>\n\n### 3. आज का काम «असली»\n\nनोटबुक में \"Spawn-स्रोत खोज\" पन्ना बनाइए। फ़ोन या पूछताछ से अपने इलाक़े के कम से कम दो संभावित स्रोत दर्ज कीजिए — नाम, क़िस्म (सरकारी लैब, निजी लैब या किसान), दूरी और बात का नतीजा। हर स्रोत से एक सवाल ज़रूर पूछिए — अगला बैच कब बनेगा और बुकिंग कैसे होती है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दो स्रोत क़िस्म और दूरी के साथ दर्ज हों\n- दोनों के आगे बैच-बुकिंग का जवाब लिखा हो\n\n### 5. सबूत\n\nखोज-पन्ने की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैं बटन मशरूम का Spawn पहली बार ख़रीदने जा रहा हूँ। बेचने वाले से कौन-कौन से सवाल पूछूँ, ताकि माल की उम्र और गुणवत्ता का सही अंदाज़ा लगे?\"* — मिले सवालों को अपनी नोटबुक में उतारिए। थैली की अंतिम परख अपनी आँख और नाक से ही कीजिए।\n\n### 7. आम ग़लती\n\nलोग बीस रुपये बचाने के लिए बिना नाम-पते वाली सस्ती थैली उठा लेते हैं। **छत ही कच्ची, तो घर क्या बनेगा।** पूरा कम्पोस्ट, पूरी मेहनत और पूरा मौसम उसी एक थैली पर टिका है। भरोसा पहले, भाव बाद में।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13-16 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, फ़ोन |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | पूछताछ, बुकिंग की जानकारी, दर्ज करना |\n| क्या कभी नहीं | बिना पहचान की थैली ख़रीदना या धब्बेदार माल लेना |\n\n### 9. स्रोत\n\n- मशरूम अनुसंधान निदेशालय, सोलन ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n- बिहार सरकार — बाग़वानी विभाग ([horticulture.bihar.gov.in](https://horticulture.bihar.gov.in/)) · देखा गया 09-08-2026\n\n*स्रोतों के नाम-पते इलाक़े-दर-इलाक़े बदलते हैं। यह पाठ परखने की कसौटी देता है — पते आपकी खोज से निकलेंगे।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं समझा सकता हूँ कि Spawn ज़िंदा माल क्यों कहलाता है\n- [ ] मैं तीनों ठिकानों की क़िस्में गिना सकता हूँ\n- [ ] मैं ताज़गी की तीनों निशानियाँ बिना देखे बोल सकता हूँ\n- [ ] मैं बुकिंग-रिवाज़ की वजह बता सकता हूँ\n- [ ] मैंने अपने इलाक़े के दो स्रोत दर्ज कर लिए हैं\n\n**आगे का पाठ:** चौथी कसौटी — अपनी ओर मुड़ने की बारी। जेब, जगह और समय की ईमानदार गिनती।\n\n---\n---\n", "18": "# पाठ 18 — मेरी जेब, जगह और समय\n\n**अध्याय:** अ-2 · **पाठ:** 6 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nअब तक की कसौटियाँ बाहर की थीं — बाज़ार, मौसम, माल। यह पाठ आईना घुमाता है। इसके बाद आप अपनी तीन पूँजियों की ईमानदार गिनती कर पाएँगे — पैसा, जगह और समय। और जान जाएँगे कि छोटी पूँजी शर्म की नहीं, सही सीढ़ी चुनने की बात है।\n\n### 2. मुख्य बात\n\n> धंधा तीन टाँगों की तिपाई पर खड़ा होता है — जेब, जगह और समय। कोई एक टाँग छोटी हो, तो तिपाई गिरती नहीं — बस उतनी ही ऊँची बनाई जाती है, जितनी टाँगें उठा सकें।\n\n---\n\n### झूठ अपने-आप से नहीं\n\nइस पाठ का पहला नियम अजीब लगेगा — आज आपको किसी और से नहीं, अपने-आप से सच बुलवाना है।\n\nनए धंधे के जोश में आदमी अपने-आप से दो झूठ बोलता है। पहला झूठ — इंतज़ाम हो जाएगा। पैसे का, जगह का, हर चीज़ का। दूसरा झूठ — समय निकल आएगा। दोनों झूठ शुरू में मीठे लगते हैं। और बीच मँझधार में डुबोते हैं। आधा चक्र चलाकर पैसा चुक जाए, या फ़सल के नाज़ुक हफ़्ते में देखभाल करने वाला ही न हो — दोनों हालात में नुक़सान पक्का है।\n\nइसलिए यह गिनती काग़ज़ पर होगी। काग़ज़ जोश में नहीं आता। जो लिखा है, वही है। जो नहीं है, वह साफ़ दिखेगा। और साफ़ दिखी कमी कभी हार नहीं होती। वह सिर्फ़ अगला क़दम बताती है।\n\n### पहली टाँग — जेब\n\nपैसे की गिनती से घबराइए मत। यहाँ रुपये की रक़म नहीं लिखनी। रक़में तो आपके अपने पत्रकों से निकलेंगी — बाज़ार-पत्रक का दाम, कम्पोस्ट-ठिकाने के पाँच सवालों का जवाब, Spawn-स्रोत की बात। पक्की गिनती का पूरा तरीक़ा आगे इकाई-हिसाब वाले अध्याय में स्रोत-सहित सिखाया जाएगा।\n\nआज सिर्फ़ तीन ईमानदार पंक्तियाँ लिखनी हैं। पहली — मैं पहले चक्र के लिए बिना उधार कितना लगा सकता हूँ। दूसरी — यह पैसा किस झोले से आएगा — बचत, घर की सहमति, समूह की बचत या कुछ और। तीसरी — यह पैसा डूब जाए तो घर की थाली पर असर पड़ेगा या नहीं।\n\nतीसरी पंक्ति सबसे ज़रूरी है। पहला चक्र सीखने का है। सीखने का पैसा वही होना चाहिए, जिसके डूबने से रसोई न रुके। जो रक़म रसोई से जुड़ी है, वह धंधे की मेज़ पर कभी नहीं रखी जाती।\n\n### दूसरी टाँग — जगह\n\nअब घर का चक्कर लगाइए — नोटबुक हाथ में लेकर। तलाश एक ऐसे कोने की है, जो चार शर्तें पूरी करे।\n\nपहली शर्त — ठंडा और छायादार हो। धूप की दीवार से सटा टीन का कमरा बटन का दुश्मन है। दूसरी — हवा आती-जाती हो। तीसरी — धोया-बुहारा जा सके। मिट्टी झड़ती छत और सफ़ाई न होने वाला कोना काम ख़राब करेगा। चौथी — जानवर, मुर्ग़ी और रोज़ की भीड़ से अलग हो। खाना बनता आँगन और बच्चों का खेल-रास्ता ठीक जगह नहीं है।\n\nजो कोना चुना, उसकी नाप लिखिए। मान लो कोठरी आठ हाथ लंबी और छह हाथ चौड़ी निकली। यही पंक्ति आगे बताएगी कि पाँच बैग कहाँ रखे जाएँगे और आगे कितनी गुंजाइश है। जगह छोटी निकले तो भी दर्ज कीजिए। पाँच बैग का पहला चक्र सचमुच छोटे कोने में समा जाता है।\n\n### तीसरी टाँग — समय\n\nतीसरी गिनती सबसे अनदेखी रहती है। मशरूम रोज़ थोड़ा-थोड़ा समय माँगता है। सुबह एक नज़र, शाम एक नज़र। नमी देखना, हवा देखना, रजिस्टर भरना। फ़सल के हफ़्तों में यह माँग बढ़ जाती है।\n\nतो पंक्तियाँ बनाइए — घर में यह समय किसके पास है। सिर्फ़ अपना नाम मत लिखिए। घर की टीम गिनिए। कई घरों में यह काम सबसे अच्छा घर की महिलाएँ सँभालती हैं — आँगन के पास रहने वाला ही रोज़ की नज़र रख पाता है। सरकारी योजनाओं में महिलाओं की प्राथमिकता की एक वजह यही है। जो नाम लिखें, उससे बात करके सहमति भी लिखवाइए। बिन पूछे बाँटा काम आधा ही होता है।\n\nआख़िर में तीनों टाँगों को एक साथ देखिए। तीनों भरी हों, तो तिपाई तैयार है। कोई पंक्ति काँपती हो, तो वहीं अगला क़दम लिखिए — किससे बात करनी है, क्या जुटाना है। यही ईमानदार नक़्शा अगले पाठ के तैयारी-पत्र की रीढ़ बनेगा।\n\n### छोटी तिपाई की ताक़त\n\nआख़िर में एक हिम्मत की बात। गिनती के बाद कई लोगों की तिपाई छोटी निकलेगी। जेब हल्की, कोना तंग, समय थोड़ा। ऐसे में मन कहता है — यह धंधा हमारे बस का नहीं। यह सोच ग़लत है।\n\nइस कोर्स का पूरा ढाँचा ही छोटी तिपाई से शुरू होता है। पाँच बैग का चक्र बना ही इसलिए है। छोटा चक्र छोटी ग़लती करता है। छोटी ग़लती सस्ती पड़ती है। और सस्ती ग़लती से सीखा सबक़ जीवन-भर चलता है। बड़ी तिपाई वाले जब बड़ी ग़लती से डूबते हैं, तब छोटी तिपाई वाला सीखकर खड़ा हो चुका होता है।\n\nतिपाई का नियम दुकानों पर भी वही चलता है। पान की गुमटी से शुरू करने वाले सेठ बने हैं। शुरुआत का नाप इज़्ज़त नहीं घटाता। झूठा नाप घटाता है।\n\nएक रास्ता जुड़ने का भी है। अकेले की जेब छोटी हो, तो समूह की जेब बड़ी होती है। गाँव के स्वयं-सहायता समूह और साथ की सहेलियाँ-साथी मिलकर पहला चक्र साझा कर सकते हैं। पूँजी बँटती है, सीख सबकी होती है। कई कामयाब मशरूम-कहानियाँ ऐसे ही साझे आँगन से निकली हैं।\n\n### चित्र — तीन टाँगों की तिपाई\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">धंधे की तिपाई — तीन पूँजियाँ</text>\n  <ellipse cx=\"400\" cy=\"250\" rx=\"230\" ry=\"55\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <text x=\"400\" y=\"245\" font-size=\"26\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">पहला चक्र — पाँच बैग</text>\n  <text x=\"400\" y=\"278\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">सीखना, कमाना नहीं</text>\n  <line x1=\"250\" y1=\"295\" x2=\"180\" y2=\"620\" stroke=\"#0B1F3A\" stroke-width=\"14\"/>\n  <line x1=\"400\" y1=\"305\" x2=\"400\" y2=\"640\" stroke=\"#0B1F3A\" stroke-width=\"14\"/>\n  <line x1=\"550\" y1=\"295\" x2=\"620\" y2=\"620\" stroke=\"#0B1F3A\" stroke-width=\"14\"/>\n  <rect x=\"90\" y=\"630\" width=\"180\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"180\" y=\"668\" font-size=\"24\" fill=\"#F5F7FA\" text-anchor=\"middle\">जेब</text>\n  <text x=\"180\" y=\"700\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">रसोई से अलग पैसा</text>\n  <rect x=\"310\" y=\"650\" width=\"180\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"688\" font-size=\"24\" fill=\"#F5F7FA\" text-anchor=\"middle\">जगह</text>\n  <text x=\"400\" y=\"720\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">ठंडी, हवादार, साफ़</text>\n  <rect x=\"530\" y=\"630\" width=\"180\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"620\" y=\"668\" font-size=\"24\" fill=\"#F5F7FA\" text-anchor=\"middle\">समय</text>\n  <text x=\"620\" y=\"700\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">रोज़ सुबह-शाम नज़र</text>\n  <text x=\"400\" y=\"440\" font-size=\"22\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">टाँग छोटी = तिपाई छोटी बनाओ</text>\n  <text x=\"400\" y=\"472\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">गिरती तब है, जब कोई टाँग झूठी हो</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरी तीन पूँजियाँ\" पन्ना बनाइए। तीन हिस्से कीजिए — जेब, जगह, समय। जेब में तीनों ईमानदार पंक्तियाँ लिखिए। जगह में चुने कोने की नाप और चारों शर्तों की हालत दर्ज कीजिए। समय में नाम, बेला और उस आदमी की सहमति लिखिए। जो टाँग काँपे, उसके आगे अगला क़दम लिखिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- तीनों हिस्सों में कुल कम से कम आठ भरी पंक्तियाँ हों\n- रसोई वाली पंक्ति का जवाब साफ़ हाँ या नहीं में हो\n\n### 5. सबूत\n\nभरे पन्ने की फ़ोटो और चुने कोने की एक फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मशरूम के पहले छोटे चक्र के लिए मैंने घर का एक कोना चुना है। उसकी हालत यह है। इन चार शर्तों में से किसमें सुधार सबसे पहले और सबसे सस्ता होगा?\"* — फिर कोने का पूरा हाल बताइए। सुझाव को अपनी जेब-पंक्ति से मिलाकर ही मानिए।\n\n### 7. आम ग़लती\n\nलोग तीसरी टाँग यानी समय को गिनते ही नहीं। **मशरूम छुट्टी नहीं देता।** ब्याह-त्योहार, खेत की कटाई, बाहर की नौकरी — सब पहले से पत्रक पर आना चाहिए। जिस हफ़्ते कोई देखने वाला नहीं, उस हफ़्ते की फ़सल भगवान भरोसे है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13-17 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, नापने का फ़ीता या हाथ-नाप |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | घर की नाप-जोख, घरवालों से बात, पंक्तियाँ भरना |\n| क्या कभी नहीं | रसोई या क़र्ज़ का पैसा पहले चक्र में लगाने की योजना बनाना |\n\n### 9. स्रोत\n\n- आपके अपने घर की नाप और घरवालों की बात — इस पाठ का असली स्रोत यही है\n- महिला-प्राथमिकता वाली योजनाओं की झलक ([horticulture.bihar.gov.in](https://horticulture.bihar.gov.in/)) · देखा गया 09-08-2026\n\n*योजनाओं की शर्तें बदलती रहती हैं। लाभ की सोच से पहले ज़िले के दफ़्तर से ताज़ा नियम पूछिए।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीनों पूँजियाँ और तिपाई का नियम समझा सकता हूँ\n- [ ] मैं बता सकता हूँ कि रसोई का पैसा धंधे में क्यों नहीं लगता\n- [ ] मैं जगह की चारों शर्तें बिना देखे गिना सकता हूँ\n- [ ] मैंने समय की पंक्ति में नाम और सहमति दोनों लिखवा ली है\n- [ ] मैं काँपती टाँग को अगले क़दम में बदलना जानता हूँ\n\n**आगे का पाठ:** अध्याय की आख़िरी कड़ी — चारों कसौटियों को एक तैयारी-पत्र में पिरोना, AI को साथ लेकर।\n\n---\n---\n", "19": "# पाठ 19 — आज का काम — AI से मौसम-आँकड़ा लेकर अपना तैयारी-पत्र भरो\n\n**अध्याय:** अ-2 · **पाठ:** 7 में से 7\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह अध्याय का समेटने वाला पाठ है। इसके बाद आपके पास एक पन्ने का तैयारी-पत्र होगा — छह पंक्तियों में आपके पूरे फ़ैसले की तस्वीर। और आप AI से मौसम की जानकारी निकालकर उसे परखने का तरीक़ा सीख चुके होंगे।\n\n### 2. मुख्य बात\n\n> बिखरे पत्रक जानकारी हैं। एक पन्ने पर सिमटे पत्रक फ़ैसला हैं। आज बिखरा हुआ सब कुछ एक पन्ने पर आएगा — और उस पन्ने पर तारीख़ के साथ आपका नाम होगा।\n\n---\n\n### पाँच पन्नों की फ़सल\n\nज़रा पीछे मुड़कर देखिए। इस अध्याय में आपने सिर्फ़ पढ़ा नहीं, कमाया है। फ़ैसला-पत्र बना। बाज़ार के तीन पत्रक भरे। मौसम-पत्रक पर खिड़की घिरी। कम्पोस्ट-ठिकाने दर्ज हुए। Spawn-स्रोत खुले। तीन पूँजियों की गिनती हुई।\n\nयही इस कोर्स का ढंग है। हर पाठ के अंत का काम अगले पाठ की ज़मीन बनता है। जिसने काम छोड़कर सिर्फ़ पढ़ा, उसके पास आज जोड़ने को कुछ नहीं होगा। ऐसा हो, तो शर्माइए मत — पीछे के काम पूरे करके लौटिए। पन्ने इंतज़ार करेंगे।\n\n### AI से मौसम-आँकड़ा — सही सवाल का हुनर\n\nतैयारी-पत्र की मौसम-पंक्ति को आज एक और गवाह मिलेगा। आपके पास पहले से दो गवाह हैं — अपनी याद और बुज़ुर्गों की याद। तीसरा गवाह AI होगा।\n\nAI से पूछने का ढंग सीखिए। गोल-मोल सवाल गोल-मोल जवाब लाता है। नपा-तुला सवाल काम की चीज़ देता है। ऐसे पूछिए — मेरे ज़िले में साल के किन महीनों की रातें सबसे ठंडी रहती हैं, महीना-वार मोटा हाल बताओ। ज़िले का नाम ज़रूर जोड़िए। फिर एक सवाल और — इनमें से कौन-से महीने चौदह से अठारह डिग्री वाली फ़सल-श्रेणी के सबसे क़रीब बैठते हैं।\n\nअब सबसे ज़रूरी क़दम — मिलान। AI का जवाब अपने मौसम-पत्रक के घेरे से मिलाइए। तीनों गवाह एक सुर बोलें, तो पंक्ति पक्की। AI कुछ अलग कहे, तो आँख मूँदकर मत मानिए। AI दूर बैठा अंदाज़ लगाता है। आपके गाँव की रात आपने और आपके बुज़ुर्गों ने जी है। लोहे का नियम वही है — AI सलाह देता है, फ़ैसला आपका है।\n\n### AI के जवाब की तीन छन्नियाँ\n\nमिलान को और पक्का करने के लिए तीन छन्नियाँ सीख लीजिए। हर जवाब इनसे छानकर ही पत्रक तक पहुँचे।\n\nपहली छन्नी — जगह। जवाब में अपने ज़िले का नाम ढूँढिए। AI कभी-कभी पूरे राज्य या देश का औसत थमा देता है। पटना की रात और आपके गाँव की रात एक नहीं होती। जवाब गोल लगे, तो सवाल में जगह और कसकर दोहराइए।\n\nदूसरी छन्नी — मौसम की क़िस्म। पूछा रात का हाल था, जवाब दिन के तापमान का न आ जाए। फ़सल रात में जीती है, यह पिछले पाठ की सीख यहाँ पहरा देगी।\n\nतीसरी छन्नी — ताज़गी। मौसम का ढर्रा धीरे-धीरे बदलता भी है। बुज़ुर्ग की चालीस साल पुरानी याद और AI का ताज़ा आँकड़ा थोड़ा अलग बोल सकते हैं। दोनों में खिंचाव दिखे, तो बीच का सावधान रास्ता लीजिए — खिड़की को उदार नहीं, कंजूस मानिए। कंजूस खिड़की वाला कभी धोखा नहीं खाता।\n\nएक अभ्यास-चाल और आज़माइए। एक ही सवाल दो बार थोड़े अलग शब्दों में पूछिए। दोनों जवाब मिलते हों, तो भरोसा बढ़ा। दोनों अलग बोलें, तो समझिए कि ज़मीन कच्ची है — वहाँ अपनी नाप ही चलेगी।\n\nतीनों छन्नियों से निकला जवाब ही पत्रक की स्याही बनने लायक़ है।\n\n### तैयारी-पत्र — छह पंक्तियों का दस्तावेज़\n\nअब नोटबुक का सबसे साफ़ पन्ना खोलिए। ऊपर मोटा शीर्षक लिखिए — मेरा तैयारी-पत्र। नीचे छह पंक्तियाँ बनेंगी।\n\nपंक्ति एक — बाज़ार। तीनों पत्रकों का एक-वाक्य सार। किस्म, चलता दाम और सबसे बड़ा ख़रीदार-सुराग़।\n\nपंक्ति दो — मौसम। तीन गवाहों से पक्की हुई खिड़की — किस महीने से किस महीने तक।\n\nपंक्ति तीन — कम्पोस्ट। चुना हुआ पहला ठिकाना, दूरी समेत। दूसरा नाम बदल के तौर पर।\n\nपंक्ति चार — Spawn या चरण-तीन। कौन-सा रास्ता चुना और किस स्रोत से।\n\nपंक्ति पाँच — तीन पूँजियाँ। जेब-जगह-समय की एक-एक शब्द वाली हालत।\n\nपंक्ति छह — मेरा फ़ैसला। एक वाक्य, अपनी क़लम से। साथ में आज की तारीख़ और दस्तख़त।\n\nहर पंक्ति के आगे हालत का एक शब्द भी लिखिए — पक्का, अधूरा या पता-नहीं। अधूरे और पता-नहीं वाली पंक्तियाँ आपकी अगली दौड़ की सूची हैं। छहों पक्की होने की कोई जल्दी नहीं। सच्चा अधूरा पन्ना झूठे भरे पन्ने से हज़ार गुना क़ीमती है।\n\n### यह पन्ना आगे कहाँ-कहाँ बोलेगा\n\nइस एक पन्ने की उम्र लंबी है। पहला चक्र शुरू करते समय यही बताएगा कि माल कहाँ से मँगाना है। सामान की सूची यही से निकलेगी। आगे जब हिसाब-किताब और Project Report के अध्याय आएँगे, तब यह पन्ना उनकी पहली ईंट बनेगा। और महीनों बाद जब आप इसे दोबारा पढ़ेंगे, तब यह आईना बनेगा — कहाँ से चले थे, कहाँ पहुँचे।\n\nएक सुझाव और। इस पन्ने की फ़ोटो खींचकर फ़ोन में अलग रख लीजिए। काग़ज़ खोते हैं, तस्वीरें टिकती हैं। धंधे वाले का पहला दस्तावेज़ यही है — सँभालिए।\n\n### चित्र — तैयारी-पत्र का खाका\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">मेरा तैयारी-पत्र — छह पंक्तियाँ</text>\n  <rect x=\"90\" y=\"80\" width=\"620\" height=\"640\" rx=\"14\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"90\" y=\"80\" width=\"620\" height=\"58\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"118\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\">हालत का शब्द: पक्का / अधूरा / पता-नहीं</text>\n  <text x=\"120\" y=\"185\" font-size=\"21\" fill=\"#0B1F3A\">1. बाज़ार — तीन पत्रकों का सार</text>\n  <line x1=\"120\" y1=\"205\" x2=\"680\" y2=\"205\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"260\" font-size=\"21\" fill=\"#0B1F3A\">2. मौसम — तीन गवाहों वाली खिड़की</text>\n  <line x1=\"120\" y1=\"280\" x2=\"680\" y2=\"280\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"335\" font-size=\"21\" fill=\"#0B1F3A\">3. कम्पोस्ट — ठिकाना और दूरी</text>\n  <line x1=\"120\" y1=\"355\" x2=\"680\" y2=\"355\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"410\" font-size=\"21\" fill=\"#0B1F3A\">4. Spawn या चरण-3 — चुना रास्ता</text>\n  <line x1=\"120\" y1=\"430\" x2=\"680\" y2=\"430\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"485\" font-size=\"21\" fill=\"#0B1F3A\">5. तीन पूँजियाँ — जेब · जगह · समय</text>\n  <line x1=\"120\" y1=\"505\" x2=\"680\" y2=\"505\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"120\" y=\"560\" font-size=\"21\" fill=\"#0B1F3A\">6. मेरा फ़ैसला — तारीख़ और दस्तख़त</text>\n  <line x1=\"120\" y1=\"580\" x2=\"680\" y2=\"580\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <rect x=\"120\" y=\"615\" width=\"560\" height=\"80\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"650\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">AI = तीसरा गवाह · अंतिम फ़ैसला = आपकी क़लम</text>\n  <text x=\"400\" y=\"680\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">सच्चा अधूरा पन्ना झूठे भरे पन्ने से क़ीमती है</text>\n  <text x=\"400\" y=\"750\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">फ़ोटो खींचकर फ़ोन में रखो — यह पहला दस्तावेज़ है</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nपहले AI से अपने ज़िले का महीना-वार रात-मौसम पूछिए और जवाब को अपने मौसम-पत्रक से मिलाइए। फिर नोटबुक के साफ़ पन्ने पर छह पंक्तियों वाला तैयारी-पत्र बनाइए। हर पंक्ति पिछले पाठों के अपने पन्नों से भरिए। हर पंक्ति के आगे हालत का शब्द लगाइए। आख़िर में फ़ैसले का वाक्य, तारीख़ और दस्तख़त कीजिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- छहों पंक्तियाँ भरी हों और हर एक पर हालत का शब्द लगा हो\n- मौसम-पंक्ति के पास तीनों गवाहों के मेल-बेमेल की एक टिप्पणी हो\n\n### 5. सबूत\n\nपूरे तैयारी-पत्र की साफ़ फ़ोटो, तारीख़ और दस्तख़त दिखते हुए।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"यह मेरा छह-पंक्ति का तैयारी-पत्र है। इसे पढ़कर बताओ — कौन-सी पंक्ति सबसे कमज़ोर है और उसे पक्का करने का सबसे सस्ता रास्ता क्या है?\"* — जवाब को अपनी अधूरी-सूची में जोड़िए। पर पंक्ति बदलने की क़लम सिर्फ़ अपने हाथ में रखिए।\n\n### 7. आम ग़लती\n\nलोग अच्छा दिखाने के लिए हर पंक्ति पर पक्का लिख देते हैं। **यह पन्ना किसी को दिखाने के लिए नहीं है।** यह आपका अपना आईना है। आईने से झूठ बोलने वाला बाज़ार में जाकर सच से टकराता है। अधूरा लिखिए, आगे बढ़िए।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 13-18 के सब काम पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, AI वाला फ़ोन |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | AI से पूछना, मिलान, पन्ना भरना, दस्तख़त |\n| क्या कभी नहीं | AI के जवाब को बिना अपने पत्रक से मिलाए पक्का मान लेना |\n\n### 9. स्रोत\n\n- आपके पिछले छह पाठों के अपने पन्ने — इस पाठ का पहला स्रोत यही है\n- मौसम की सरकारी जानकारी ([mausam.imd.gov.in](https://mausam.imd.gov.in/)) · देखा गया 09-08-2026\n\n*AI और सरकारी site दोनों मोटा चित्र देते हैं। आपके गाँव की रात का ठीक हाल आपकी अपनी नाप से ही निकलेगा।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं AI से मौसम पूछने का नपा-तुला सवाल बना सकता हूँ\n- [ ] मैं तीन-गवाह मिलान का तरीक़ा समझा सकता हूँ\n- [ ] मैं छहों पंक्तियों के नाम बिना देखे गिना सकता हूँ\n- [ ] मेरे तैयारी-पत्र पर तारीख़ और दस्तख़त दोनों हैं\n- [ ] मैं बता सकता हूँ कि अधूरा सच भरे झूठ से बेहतर क्यों है\n\n**आगे का पाठ:** अध्याय अ-2 पूरा हुआ — बधाई। अगला अध्याय ग्राहक की दुनिया खोलेगा — ग्राहक कौन है और कहाँ है।\n\n---\n---\n", "20": "# पाठ 20 — फ़सल पहले नहीं, ग्राहक पहले — क्यों\n\n**अध्याय:** अ-3 · **पाठ:** 1 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आपकी सोच का क्रम बदल जाएगा। नए किसान की सोच फ़सल से शुरू होकर ग्राहक पर ख़त्म होती है। धंधे वाले की सोच ग्राहक से शुरू होकर फ़सल पर ख़त्म होती है। यह पाठ आपको दूसरी क़तार में खड़ा करेगा — और इसकी ठोस वजह समझाएगा।\n\n### 2. मुख्य बात\n\n> मशरूम गोदाम की चीज़ नहीं है। यह घड़ी की सुई पर बिकने वाली फ़सल है। जिसकी बिक्री का रास्ता तुड़ाई से पहले तय है, वही इस धंधे में टिकता है।\n\n---\n\n### दो दिन की मोहलत\n\nबटन मशरूम की एक क़ुदरती सच्चाई पहले समझिए। तोड़ने के बाद यह तेज़ी से ढलता है। सफ़ेद रंग मटमैला पड़ने लगता है। टोपी खुलने लगती है। आम घरेलू हालात में एक-दो दिन के भीतर इसकी रौनक़ और दाम — दोनों गिर जाते हैं। ठंडी सँभाल से उम्र बढ़ती ज़रूर है, पर वह आगे की सीढ़ी है।\n\nअब इस सच्चाई का मतलब निकालिए। गेहूँ वाला किसान फ़सल काटकर महीनों दाम का इंतज़ार कर सकता है। मशरूम वाले के पास यह सुविधा नहीं है। उसकी फ़सल हर सुबह पूछती है — आज मैं किसकी टोकरी में जाऊँगी? जिस दिन जवाब नहीं, उस दिन माल घाटे में है।\n\nइसीलिए इस धंधे का पक्का क्रम उल्टा है। पहले ख़रीदार, फिर फ़सल। बिक्री का रास्ता पक्का हुए बिना बड़ी बुआई जुआ है।\n\n### सड़क किनारे की टोकरी\n\nएक जानी-पहचानी तस्वीर से बात पक्की कीजिए। मान लो किसी गाँव में एक उत्साही आदमी ने बढ़िया फ़सल उगा ली। तुड़ाई के दिन उसे सूझा कि अब बेचना भी है। वह टोकरी लेकर सड़क किनारे बैठ गया।\n\nदोपहर तक चार-पाँच राहगीर रुके। किसी ने भाव पूछकर मुँह बनाया। शाम ढलते माल कुम्हलाने लगा। अगले दिन बचा माल आधे भाव में गया। तीसरे दिन घर में सब्ज़ी मशरूम की बनी — बिकने से बची हुई।\n\nग़लती फ़सल में नहीं थी। फ़सल तो बढ़िया थी। ग़लती क्रम में थी। बेचने की सोच तुड़ाई के दिन शुरू हुई, जबकि उसे बुआई से पहले शुरू होना था। इस अध्याय का हर पाठ इसी क्रम को सीधा करता है।\n\n### ग्राहक-पहले सोच के तीन फल\n\nक्रम सीधा करने से सिर्फ़ माल ही नहीं बचता। तीन बड़े फल और मिलते हैं।\n\nपहला फल — सही मात्रा। ग्राहक पहले तय हो, तो उगाने की मात्रा उसकी माँग से निकलती है। न माल कम पड़ता है, न सड़ता है। अंधेरे में बोने वाला हमेशा या ज़्यादा बोता है या कम।\n\nदूसरा फल — सही समय। ग्राहक बता देता है कि उसे किस दिन, किस मौसम में माल चाहिए। शादी के महीने की माँग और सावन की माँग अलग है। तुड़ाई का दिन ग्राहक की घड़ी से मिलाया जा सकता है।\n\nतीसरा फल — ठीक दाम। पहले से बात पक्की करने वाला दाम आराम से तय करता है। कुम्हलाते माल वाला नहीं कर पाता। जिसकी टोकरी शाम तक बिकनी ही है, वह हर भाव पर हाँ कहता है। मोल-भाव की ताक़त उसी के पास होती है, जिसके पास इंतज़ार की ताक़त है।\n\n### आपके पास शुरुआत पहले से है\n\nअच्छी ख़बर यह है कि आप ख़ाली हाथ नहीं हैं। पिछले अध्याय के बाज़ार-पत्रक याद कीजिए। हाट, दुकान और होटल की गिनती आपकी नोटबुक में पड़ी है। दुकानदार की वह सुनहरी राय भी — और माल मिले तो बिकेगा।\n\nवह सर्वे इलाक़े की तस्वीर था। यह अध्याय उससे अगला क़दम है — तस्वीर से नाम-पते तक। अब हम बाज़ार को वर्गों में बाँटेंगे। हर वर्ग की आदत पढ़ेंगे। और अध्याय के अंत तक आपके पास अपने दस संभावित ग्राहकों की सूची होगी — नाम, जगह और बात के नतीजे समेत।\n\nध्यान रखिए — यह सब तब हो रहा है, जब आपका पहला बैग अभी बिछा भी नहीं। यही तो क्रम की ख़ूबसूरती है। जिस दिन पहली फ़सल आएगी, ख़रीदार पहले से रास्ता देख रहे होंगे।\n\n### ग्राहक-पहले का मतलब सौदा-पहले नहीं\n\nएक बारीक़ फ़र्क़ यहीं साफ़ कर लीजिए। ग्राहक-पहले का मतलब यह नहीं कि आज ही जाकर पक्के सौदे ठोक आइए। जिसके पास अभी फ़सल ही नहीं, उसका पक्का वादा झूठ की नींव पर खड़ा होगा। और टूटा वादा इस छोटे बाज़ार में लंबी उम्र जीता है।\n\nग्राहक-पहले का असली मतलब है — रास्ता पहले। कौन ख़रीद सकता है, यह जानना। उससे पहचान बनाना। उसकी ज़रूरत और आदत समझना। दरवाज़े पर दस्तक देकर यह कहना कि फ़सल आने पर सबसे पहले आपको दिखाऊँगा। दिखाने का वादा और बेचने का वादा — दोनों में ज़मीन-आसमान का फ़र्क़ है। पहला वादा आप आज निभा सकते हैं। दूसरा वादा फ़सल हाथ में आने पर ही होगा।\n\nरास्ता बनाने का एक फ़ायदा अनदेखा रह जाता है — हिम्मत। जिस आदमी को मालूम है कि चार दरवाज़े उसकी टोकरी का इंतज़ार कर रहे हैं, वह फ़सल की मेहनत दुगने मन से करता है। अकेले अँधेरे में बोने वाले की हिम्मत हर अफ़वाह से डोलती है।\n\nइसी अध्याय के अगले पाठ यही सिखाएँगे — बिना बेचे रिश्ता कैसे बनता है। और आगे \"पहला संदेश और पहला वादा\" वाला पाठ बताएगा कि पक्की बात किस घड़ी और किस नाप से होती है। तब तक क़लम रिश्तों पर चलेगी, सौदों पर नहीं।\n\n### चित्र — उल्टा क्रम बनाम सीधा क्रम\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">दो क्रम — एक हारता है, एक जीतता है</text>\n  <rect x=\"70\" y=\"110\" width=\"300\" height=\"70\" rx=\"12\" fill=\"#0B1F3A\"/>\n  <text x=\"220\" y=\"153\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\">✗ नए किसान का क्रम</text>\n  <rect x=\"90\" y=\"210\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"220\" y=\"248\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">पहले फ़सल उगाई</text>\n  <line x1=\"220\" y1=\"270\" x2=\"220\" y2=\"310\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"90\" y=\"310\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"220\" y=\"348\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">फिर ख़रीदार ढूँढा</text>\n  <line x1=\"220\" y1=\"370\" x2=\"220\" y2=\"410\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"90\" y=\"410\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#0B1F3A\"/>\n  <text x=\"220\" y=\"448\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\">माल कुम्हलाया, दाम गिरा</text>\n  <rect x=\"430\" y=\"110\" width=\"300\" height=\"70\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"580\" y=\"153\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\">✓ धंधे वाले का क्रम</text>\n  <rect x=\"450\" y=\"210\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#2E7D32\"/>\n  <text x=\"580\" y=\"248\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">पहले ग्राहक पक्का</text>\n  <line x1=\"580\" y1=\"270\" x2=\"580\" y2=\"310\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"450\" y=\"310\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#2E7D32\"/>\n  <text x=\"580\" y=\"348\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">माँग के नाप की फ़सल</text>\n  <line x1=\"580\" y1=\"370\" x2=\"580\" y2=\"410\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"450\" y=\"410\" width=\"260\" height=\"60\" rx=\"10\" fill=\"#F9A825\"/>\n  <text x=\"580\" y=\"448\" font-size=\"21\" fill=\"#0B1F3A\" text-anchor=\"middle\">ताज़ा माल, ठीक दाम</text>\n  <rect x=\"110\" y=\"560\" width=\"580\" height=\"70\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"592\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">वजह: तुड़ाई के बाद रौनक़ की मोहलत छोटी है</text>\n  <text x=\"400\" y=\"620\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">इंतज़ार की ताक़त = मोल-भाव की ताक़त</text>\n  <text x=\"400\" y=\"700\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">इस अध्याय का लक्ष्य: दस ग्राहकों की अपनी सूची</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरा क्रम\" पन्ना बनाइए। बाईं ओर सड़क-किनारे वाली कहानी अपने शब्दों में चार-पाँच वाक्यों में लिखिए। दाईं ओर लिखिए कि उसी आदमी को बुआई से पहले कौन-से तीन काम कर लेने चाहिए थे। आख़िर में एक वाक्य अपने लिए — मैं पहला बैग बिछाने से पहले कौन-से तीन काम पूरे करूँगा।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दोनों ओर की लिखावट पूरी हो\n- अपने तीन कामों में कम से कम एक में किसी असली आदमी से बात करना शामिल हो\n\n### 5. सबूत\n\nभरे पन्ने की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैं मशरूम बेचने की तैयारी फ़सल से पहले करना चाहता हूँ। मेरे इलाक़े जैसे क़स्बे में बुआई से पहले के तीन सबसे ज़रूरी बिक्री-काम कौन-से होने चाहिए?\"* — जवाब को अपने पन्ने के तीन कामों से मिलाइए और सूची पक्की कीजिए।\n\n### 7. आम ग़लती\n\nलोग कहते हैं — पहले माल तो हो, बेचना क्या मुश्किल है। **मुश्किल बेचना नहीं, घड़ी है।** माल हाथ में आते ही उलटी गिनती चालू हो जाती है। जो बात आज आराम से हो सकती है, वही बात कुम्हलाती टोकरी के सामने मजबूरी बन जाती है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | अध्याय अ-1 पूरा |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | सोचना, लिखना, योजना बनाना |\n| क्या कभी नहीं | बिक्री-रास्ता तय किए बिना बड़ी मात्रा की बुआई ठानना |\n\n### 9. स्रोत\n\n- मशरूम अनुसंधान निदेशालय, सोलन — तुड़ाई-उपरांत सँभाल की सामग्री ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n\n*रौनक़ ढलने की रफ़्तार किस्म, मौसम और सँभाल से घटती-बढ़ती है। ठंडी सँभाल के तरीक़े तुड़ाई वाले खंड में सिखाए जाएँगे।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं मशरूम और गेहूँ की बिक्री-घड़ी का फ़र्क़ समझा सकता हूँ\n- [ ] मैं सड़क-किनारे वाली कहानी की असली ग़लती बता सकता हूँ\n- [ ] मैं ग्राहक-पहले सोच के तीनों फल गिना सकता हूँ\n- [ ] मैं बता सकता हूँ कि मोल-भाव की ताक़त किसके पास होती है\n- [ ] मैंने बुआई-पूर्व अपने तीन काम लिख लिए हैं\n\n**आगे का पाठ:** ग्राहक एक भीड़ नहीं, चार अलग वर्ग हैं — घर, दुकान, संस्था और प्रसंस्करण। चारों की पहचान।\n\n---\n---\n", "21": "# पाठ 21 — ग्राहक के चार वर्ग — घर, दुकान, संस्था, प्रसंस्करण\n\n**अध्याय:** अ-3 · **पाठ:** 2 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद \"ग्राहक\" शब्द आपके लिए धुँधली भीड़ नहीं रहेगा। आप ख़रीदारों को चार साफ़ वर्गों में पहचानेंगे। और अपने इलाक़े के जाने-पहचाने चेहरों को इन्हीं वर्गों के खानों में बिठाना शुरू कर देंगे।\n\n### 2. मुख्य बात\n\n> ग्राहक-ग्राहक एक नहीं होता। घर, दुकान, संस्था और प्रसंस्करण — चार अलग दुनियाएँ हैं। जो बेचने वाला चारों को एक लाठी से हाँकता है, वह चारों से हारता है।\n\n---\n\n### भीड़ को खानों में बाँटिए\n\nबाज़ार को समझने की पहली तरकीब यही है — भीड़ को खानों में बाँटो। दर्ज़ी यही करता है। वह \"कपड़ा पहनने वाले लोग\" नहीं सोचता। वह सोचता है — स्कूल की पोशाक वाले, शादी के जोड़े वाले, रोज़ के कुर्ते वाले। हर खाने का कपड़ा, नाप और दाम अलग।\n\nमशरूम का बाज़ार भी ठीक ऐसे बँटता है। चार खाने बनते हैं। हर खाने का अपना स्वभाव है। आज चारों की पहचान कीजिए। अगले पाठ में इनकी माँग, दाम और भुगतान की आदतें खुलेंगी।\n\n### वर्ग-1: घर की रसोई\n\nपहला वर्ग सबसे नज़दीक का है — घरेलू ख़रीदार। मोहल्ले की चाची, स्कूल के मास्टर साहब, आपकी अपनी रिश्तेदारी। ये लोग अपनी रसोई के लिए थोड़ा-थोड़ा माल लेते हैं — पाव भर, आधा किलो।\n\nइस वर्ग की जान रिश्ते में है। यह चेहरा देखकर ख़रीदता है। जिस पर भरोसा जमा, उसी से बार-बार लेता है। ताज़गी की क़दर यह वर्ग सबसे ज़्यादा करता है — सुबह की तोड़ी टोकरी इसकी आँख में चमक ले आती है। नए उत्पादक की पहली बिक्री अक्सर इसी वर्ग से खुलती है, क्योंकि यहाँ पहुँचने के लिए किसी दुकान-काउंटर की ज़रूरत नहीं।\n\n### वर्ग-2: दुकान और ठेला\n\nदूसरा वर्ग बीच की कड़ी है — सब्ज़ी की दुकान, हाट का ठेला, किराना जो सब्ज़ी भी रखता है। यह ख़ुद नहीं खाता। यह आगे बेचने के लिए ख़रीदता है।\n\nइसीलिए इसकी नज़र अलग चीज़ें तौलती है। माल टिकेगा कितना? ग्राहक लौटाएगा तो नहीं? रोज़ मिलेगा या कभी-कभार? दुकानदार को स्वाद से ज़्यादा भरोसे की सप्लाई चाहिए। बदले में वह एक बड़ी सुविधा देता है — आपका माल उसकी भीड़ के सामने रोज़ सजता है। एक दुकान से रिश्ता यानी सैकड़ों घरों तक बिना दौड़े पहुँच।\n\n### वर्ग-3: संस्था की रसोई\n\nतीसरा वर्ग बड़ी हाँडी वाला है — होटल, ढाबा, शादी-भोज का रसोइया, हॉस्टल या दफ़्तर की मेस। यहाँ ख़रीद किलो में नहीं, थैलों में होती है। पिछले अध्याय के सर्वे की याद कीजिए — एक होटल दस घरों के बराबर ख़रीद सकता है।\n\nइस वर्ग की धड़कन भरोसे की तारीख़ है। रसोइए ने रविवार की दावत के लिए दस किलो कहा, तो रविवार सुबह दस किलो चाहिए ही चाहिए। माल घटा या देर हुई, तो उसकी दावत बिगड़ती है — और आपका नाम कटता है। जो उत्पादक तारीख़ का पक्का है, उसके लिए यह वर्ग सोने की खान है।\n\n### वर्ग-4: प्रसंस्करण वाले\n\nचौथा वर्ग सबसे दूर का है, पर जानना ज़रूरी है — प्रसंस्करण करने वाले। जो मशरूम को सुखाकर, पीसकर या पैक करके नया रूप देते हैं। अचार-पापड़ बनाने वाले समूह से लेकर बड़ी इकाइयों तक।\n\nयह वर्ग मात्रा का बादशाह है। इसे एक जैसा माल, बड़ी तौल में, तय भाव पर चाहिए। रौनक़ से ज़्यादा इसे छँटाई और नियम की परवाह है। नए उत्पादक के लिए यह पहला दरवाज़ा नहीं है — इसकी शर्तें बड़ी होती हैं। पर आगे चलकर यही वर्ग बची-खुची और दूसरे दर्जे की फ़सल का ठिकाना बन सकता है। कोर्स के प्रसंस्करण वाले रास्ते में आप ख़ुद इस वर्ग के भीतर जाकर देखेंगे — शायद कभी इस पार से उस पार भी।\n\n### चेहरे खानों से बड़े होते हैं\n\nखाने बनाते समय एक सच याद रखिए — असली आदमी खानों से बड़ा होता है। किराना वाला भोज का ठेका भी ले सकता है — वह दुकान और संस्था दोनों में बैठा। स्कूल के मास्टर साहब घर के ग्राहक भी हैं और हॉस्टल-मेस की सिफ़ारिश की चाबी भी। ऐसे दोहरे चेहरे आपके नक़्शे के हीरे हैं — एक रिश्ते से दो दरवाज़े खुलते हैं। इसलिए नाम लिखते समय उसका हर रूप सोचिए और जहाँ-जहाँ बैठे, वहाँ-वहाँ दर्ज कीजिए। और वक़्त के साथ चेहरे खाने भी बदलते हैं — आज का घरेलू ख़रीदार कल ठेला लगा सकता है। नक़्शा ज़िंदा रखिए।\n\n### चारों एक साथ क्यों नहीं\n\nअब बड़ा सवाल — बेचें किसे? जवाब आगे के पाठ देंगे, पर सिद्धांत आज पकड़िए। चारों वर्ग एक साथ साधना नए आदमी के बस का नहीं। हर वर्ग अलग समय, अलग तैयारी और अलग स्वभाव माँगता है।\n\nसमझदार शुरुआत दो वर्गों से होती है — जो आपकी मात्रा और आपके स्वभाव से मेल खाएँ। पाँच बैग वाले पहले चक्र का माल घरेलू वर्ग और एक-दो दुकानों के लिए ही ठीक बैठता है। संस्था-वर्ग दूसरे-तीसरे चक्र की मंज़िल है, जब मात्रा और भरोसा दोनों जम जाएँ। यही सीढ़ी-दर-सीढ़ी चढ़ाई आगे \"दो रास्ते चुनो\" वाले पाठ में गिनती से तय होगी।\n\n### चित्र — चार वर्गों का नक़्शा\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">ग्राहक के चार वर्ग — चार स्वभाव</text>\n  <circle cx=\"400\" cy=\"430\" r=\"80\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <text x=\"400\" y=\"420\" font-size=\"24\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">आपकी</text>\n  <text x=\"400\" y=\"455\" font-size=\"24\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">टोकरी</text>\n  <rect x=\"60\" y=\"120\" width=\"310\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"215\" y=\"160\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">1. घर की रसोई</text>\n  <text x=\"215\" y=\"195\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">थोड़ा माल · रिश्ते से ख़रीद</text>\n  <text x=\"215\" y=\"225\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">पहली बिक्री का दरवाज़ा</text>\n  <rect x=\"430\" y=\"120\" width=\"310\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"585\" y=\"160\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">2. दुकान-ठेला</text>\n  <text x=\"585\" y=\"195\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">आगे बेचने को ख़रीदे</text>\n  <text x=\"585\" y=\"225\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">भरोसे की सप्लाई चाहिए</text>\n  <rect x=\"60\" y=\"580\" width=\"310\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"215\" y=\"620\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">3. संस्था की रसोई</text>\n  <text x=\"215\" y=\"655\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">थैलों में ख़रीद · होटल-भोज</text>\n  <text x=\"215\" y=\"685\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">तारीख़ का पक्का वादा</text>\n  <rect x=\"430\" y=\"580\" width=\"310\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"585\" y=\"620\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">4. प्रसंस्करण</text>\n  <text x=\"585\" y=\"655\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बड़ी तौल · एक जैसा माल</text>\n  <text x=\"585\" y=\"685\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">आगे की मंज़िल</text>\n  <line x1=\"260\" y1=\"250\" x2=\"355\" y2=\"380\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"540\" y1=\"250\" x2=\"445\" y2=\"380\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"260\" y1=\"580\" x2=\"355\" y2=\"480\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"540\" y1=\"580\" x2=\"445\" y2=\"480\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"770\" font-size=\"19\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">शुरुआत दो वर्गों से — चारों एक साथ नहीं</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में चार खानों वाला \"वर्ग-नक़्शा\" बनाइए। हर खाने में अपने इलाक़े के असली नाम भरिए — घरेलू खाने में तीन जान-पहचान के घर, दुकान खाने में दो दुकानें, संस्था खाने में एक होटल या भोज-रसोइया, प्रसंस्करण खाने में जो पता हो वह, न पता हो तो साफ़ लिखिए — खोजना है। पिछले अध्याय के बाज़ार-पत्रक से नाम उठाने की पूरी छूट है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- पहले तीन खानों में मिलाकर कम से कम छह असली नाम हों\n- हर नाम के आगे जगह या पहचान की एक पंक्ति हो\n\n### 5. सबूत\n\nभरे वर्ग-नक़्शे की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"छोटे क़स्बे के नए मशरूम-उत्पादक के लिए चार ग्राहक-वर्गों में से शुरुआती दो वर्ग चुनने के क्या पैमाने होने चाहिए?\"* — मिले पैमानों को नोटबुक में लिखिए। अंतिम चुनाव अगले पाठों की गिनती के बाद ही कीजिए।\n\n### 7. आम ग़लती\n\nनए लोग सबसे पहले सबसे बड़े ग्राहक के पीछे भागते हैं — बड़ा होटल या कोई इकाई। **बड़ा दरवाज़ा बड़ी शर्तें माँगता है।** रोज़ की तय मात्रा, पक्की तारीख़, कभी-कभी उधारी भी। पाँच बैग वाले की कमर यह बोझ नहीं उठा पाती। सीढ़ी नीचे से चढ़िए।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20 पूरा |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | नाम जुटाना, खाने भरना, पुराने पत्रक पलटना |\n| क्या कभी नहीं | बिना तैयारी बड़े ग्राहक से वादा कर बैठना |\n\n### 9. स्रोत\n\n- आपके अपने बाज़ार-पत्रक (अध्याय अ-2) — नामों का पहला स्रोत यही हैं\n- राष्ट्रीय बाग़वानी बोर्ड — मशरूम की बाज़ार-झलक ([nhb.gov.in](https://www.nhb.gov.in/)) · देखा गया 09-08-2026\n\n*वर्गों का बँटवारा समझने का औज़ार है। असली इलाक़े में कुछ चेहरे दो वर्गों में भी बैठ सकते हैं — जैसे किराना जो भोज का ठेका भी लेता है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं चारों वर्गों के नाम और एक-एक पहचान बिना देखे बोल सकता हूँ\n- [ ] मैं बता सकता हूँ कि दुकानदार स्वाद से ज़्यादा क्या तौलता है\n- [ ] मैं समझा सकता हूँ कि संस्था-वर्ग की धड़कन तारीख़ क्यों है\n- [ ] मैं जानता हूँ कि पहला चक्र किन दो वर्गों के नाप का है\n- [ ] मेरे वर्ग-नक़्शे में छह असली नाम दर्ज हैं\n\n**आगे का पाठ:** चारों वर्गों की जेब खुलेगी — किसकी माँग कितनी, दाम कैसा और पैसा कब मिलता है।\n\n---\n---\n", "22": "# पाठ 22 — हर वर्ग की माँग, दाम और भुगतान अलग होता है\n\n**अध्याय:** अ-3 · **पाठ:** 3 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nपिछले पाठ में वर्गों के चेहरे पहचाने। इस पाठ में उनकी जेब पढ़ेंगे। इसके बाद आप हर वर्ग की तीन आदतें बोल सकेंगे — कितना माँगता है, दाम कैसे देखता है और पैसा कब देता है। यही तीन आदतें आगे आपके दो-वर्ग चुनाव की कसौटी बनेंगी।\n\n### 2. मुख्य बात\n\n> बिक्री की क़ीमत सिर्फ़ भाव नहीं होती। मात्रा, भाव और पैसे की तारीख़ — तीनों मिलकर सौदे का असली चेहरा बनाते हैं। सस्ता दिखता सौदा देर के भुगतान से महँगा हो जाता है।\n\n---\n\n### तीन तराज़ू — एक साथ तौलिए\n\nनए बेचने वाले की आँख सिर्फ़ भाव पर टिकती है। जहाँ भाव ऊँचा, वहीं दौड़ पड़ता है। पुराना खिलाड़ी तीन तराज़ू एक साथ उठाता है।\n\nपहली तराज़ू — मात्रा। कितना माल, कितनी बार? रोज़ पाव भर लेने वाले सौ घर और हफ़्ते में एक बार बीस किलो लेने वाला एक रसोइया — दोनों की गिनती अलग ढंग से बैठती है।\n\nदूसरी तराज़ू — भाव का ढंग। कौन भाव पर अड़ता है, कौन ताज़गी पर रीझता है, कौन लिखित रेट माँगता है?\n\nतीसरी तराज़ू — पैसे की तारीख़। माल आज गया, पैसा कब आएगा? आज? हफ़्ते बाद? महीने के हिसाब से? छोटे उत्पादक के लिए यह तराज़ू सबसे भारी है, क्योंकि उसकी अगली ख़रीद इसी पैसे से होनी है।\n\nअब चारों वर्गों को इन्हीं तीन तराज़ुओं पर बारी-बारी तौलिए।\n\n### घर की रसोई — छोटी तौल, हाथों-हाथ पैसा\n\nघरेलू वर्ग की मात्रा छोटी और बिखरी है। पाव-आधा किलो, हफ़्ते में एक-दो बार। पर गिनती जोड़िए — मान लो बीस घर बँध गए, तो हफ़्ते की अच्छी-ख़ासी तौल बन जाती है।\n\nभाव के मामले में यह वर्ग अक्सर सबसे नरम है। ताज़ा, साफ़ और जान-पहचान का माल हो, तो कई मामलों में यह प्रति किलो सबसे बेहतर दाम भी दे देता है — क्योंकि बीच में कोई कड़ी नहीं खाती।\n\nऔर भुगतान? यही इसकी सबसे मीठी आदत है — हाथ में माल, हाथ में पैसा। नए उत्पादक की साँस इसी नक़दी से चलती है।\n\n### दुकान — बँधी तौल, दबा भाव, मिला-जुला पैसा\n\nदुकान की मात्रा बँधी और दोहराई जाने वाली है — रोज़ या एक दिन छोड़कर, तय तौल। यही इसका सबसे बड़ा सुख है। बिक्री का पहिया अपने-आप घूमता है।\n\nपर भाव यहाँ दबता है। दुकानदार आगे बेचकर कमाएगा, इसलिए वह आपसे थोक के भाव माँगेगा। यह बेईमानी नहीं, उसका धंधा है। घरेलू भाव की उम्मीद यहाँ मत रखिए।\n\nभुगतान की आदत दुकान-दुकान बदलती है। कोई रोज़ हिसाब साफ़ करता है। कोई हफ़्ते का खाता चलाता है। पहली बात में ही यह तय कर लेना — पैसा कब — आगे के झगड़े से बचाता है। यह हुनर अगले पाठों में बात-दर-बात सिखाया जाएगा।\n\n### संस्था — बड़ी तौल, तय भाव, खाते का पैसा\n\nसंस्था-वर्ग की मात्रा बड़ी और तारीख़ से बँधी है। दावत के दिन दस-बीस किलो एकमुश्त। यही इसका जादू है — एक सौदे में हफ़्ते की फ़सल निकल जाती है।\n\nभाव यहाँ अक्सर पहले से तय होता है — महीने या मौसम का बँधा रेट। बार-बार मोल-भाव नहीं।\n\nपर पैसे की तारीख़ पर आँख खोलकर चलिए। कई होटल-मेस महीने के खाते पर चलते हैं। माल आज, पैसा अगले महीने की पहली-दूसरी को। जिसकी जेब यह इंतज़ार झेल सकती है, उसके लिए सोना। जिसकी अगली ख़रीद आज के पैसे पर टिकी है, उसके लिए फंदा। इसीलिए यह वर्ग पहले चक्र की मंज़िल नहीं है।\n\n### प्रसंस्करण — तौल का पहाड़, भाव की चक्की\n\nप्रसंस्करण वर्ग की तीनों आदतें बड़े पैमाने की हैं। मात्रा सबसे बड़ी। भाव सबसे कसा हुआ — क्योंकि वह आपके माल को कच्चा माल गिनता है। भुगतान लिखे काग़ज़ और बिल के रास्ते, अपनी तय रफ़्तार से।\n\nनए आदमी के लिए इस वर्ग की असली क़ीमत एक और बात में है — यह दूसरे दर्जे के माल का ठिकाना बन सकता है। खुली टोपी वाले, टेढ़े-मेढ़े दाने, जो घरेलू टोकरी में नहीं सजते — सुखाने-पीसने वाले के लिए वे भी माल हैं। पूरी फ़सल का दाना-दाना बिकाने की यह चाबी आगे प्रसंस्करण वाले रास्ते में मिलेगी।\n\n### नक़दी की साँस — एक मान-लो हिसाब\n\nतीसरी तराज़ू का वज़न एक मान-लो कहानी से तौलिए। मान लो आपके पहले चक्र की एक हफ़्ते की फ़सल दस किलो निकली। सामने दो रास्ते हैं।\n\nरास्ता-अ — पूरा माल दुकान को। भाव थोक का, यानी दबा हुआ। पर पैसा उसी शाम हाथ में। उस पैसे से अगले हफ़्ते की ज़रूरत का सामान उसी हफ़्ते आ गया। चक्र का पहिया घूमता रहा।\n\nरास्ता-ब — पूरा माल होटल को। भाव मान लो चौथाई ऊँचा। सुनकर जी ललचाता है। पर पैसा महीने के खाते में गया। बीच के हफ़्तों में अगली ख़रीद किस जेब से होगी? जिसके पास अलग बचत नहीं, उसका पहिया वहीं रुक जाता है। ऊँचे भाव वाला सौदा चक्र तोड़कर घाटे का निकला।\n\nऔर यह भी गिनिए — दुकान वाले रास्ते में दुकानदार से रोज़ की मुलाक़ात मुफ़्त मिली। रोज़ की मुलाक़ात यानी रोज़ की ख़बर — किस दिन क्या चला, क्या लौटा। यह ख़बर भी एक कमाई है, जो खाते में नहीं दिखती।\n\nसबक़ साफ़ है। शुरुआती दौर में भाव से पहले साँस देखिए। साँस यानी नक़दी की आवाजाही। पूरा गिनती-गणित आगे इकाई-हिसाब वाले अध्याय में सीखेंगे — आज सिर्फ़ यह पहचान पक्की कीजिए।\n\n### चित्र — तीन तराज़ुओं की तालिका\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">चार वर्ग × तीन तराज़ू</text>\n  <rect x=\"60\" y=\"100\" width=\"680\" height=\"80\" rx=\"10\" fill=\"#0B1F3A\"/>\n  <text x=\"150\" y=\"148\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\">वर्ग</text>\n  <text x=\"330\" y=\"148\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">मात्रा</text>\n  <text x=\"510\" y=\"148\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">भाव</text>\n  <text x=\"670\" y=\"148\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">पैसा कब</text>\n  <rect x=\"60\" y=\"190\" width=\"680\" height=\"110\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"150\" y=\"235\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">घर</text>\n  <text x=\"330\" y=\"235\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">छोटी, बिखरी</text>\n  <text x=\"510\" y=\"235\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">अक्सर बेहतर</text>\n  <text x=\"670\" y=\"235\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">हाथों-हाथ</text>\n  <text x=\"400\" y=\"275\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">नए उत्पादक की नक़दी-साँस यहीं से</text>\n  <rect x=\"60\" y=\"310\" width=\"680\" height=\"110\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"150\" y=\"355\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">दुकान</text>\n  <text x=\"330\" y=\"355\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बँधी, रोज़ की</text>\n  <text x=\"510\" y=\"355\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">थोक का, दबा</text>\n  <text x=\"670\" y=\"355\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">रोज़ या हफ़्ता</text>\n  <text x=\"400\" y=\"395\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">बिक्री का पहिया अपने-आप घूमता है</text>\n  <rect x=\"60\" y=\"430\" width=\"680\" height=\"110\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"150\" y=\"475\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">संस्था</text>\n  <text x=\"330\" y=\"475\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बड़ी, तारीख़-बँधी</text>\n  <text x=\"510\" y=\"475\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">पहले से तय</text>\n  <text x=\"670\" y=\"475\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">अक्सर महीने का खाता</text>\n  <text x=\"400\" y=\"515\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">जेब इंतज़ार झेले, तभी छूना</text>\n  <rect x=\"60\" y=\"550\" width=\"680\" height=\"110\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"150\" y=\"595\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">प्रसंस्करण</text>\n  <text x=\"330\" y=\"595\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">सबसे बड़ी</text>\n  <text x=\"510\" y=\"595\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">सबसे कसा</text>\n  <text x=\"670\" y=\"595\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">बिल के रास्ते</text>\n  <text x=\"400\" y=\"635\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">दूसरे दर्जे के माल का ठिकाना भी</text>\n  <rect x=\"120\" y=\"700\" width=\"560\" height=\"60\" rx=\"30\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"738\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">सौदे का असली चेहरा = तीनों तराज़ू एक साथ</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nपिछले पाठ का वर्ग-नक़्शा खोलिए। हर भरे नाम के आगे तीन छोटे खाने जोड़िए — मात्रा, भाव-ढंग, पैसा-कब। जो जानते हैं, भरिए। जो नहीं जानते, वहाँ सवालिया निशान लगाइए। यही सवालिया निशान अगले पाठों की बातचीत के सवाल बनेंगे।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- कम से कम चार नामों के तीनों खाने छुए गए हों\n- हर सवालिया निशान के पीछे साफ़ हो कि किससे पूछकर भरेगा\n\n### 5. सबूत\n\nबढ़े हुए वर्ग-नक़्शे की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मशरूम बेचने में महीने के खाते वाले भुगतान का जोखिम छोटे उत्पादक के लिए कैसे घटता है? तीन व्यावहारिक तरीक़े बताओ।\"* — तरीक़ों को नोटबुक में लिखिए। इन्हें आज़माने की बारी संस्था-वर्ग तक पहुँचने पर आएगी।\n\n### 7. आम ग़लती\n\nलोग सबसे ऊँचे भाव वाले सौदे को सबसे अच्छा मान बैठते हैं। **भाव अकेला नहीं चलता।** ऊँचे भाव के साथ महीने की उधारी हो, तो अगला चक्र ठप। थोड़ा नीचा भाव और हाथों-हाथ पैसा — शुरुआत में यही जोड़ी जिताती है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-21 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | खाने जोड़ना, अंदाज़ लिखना, सवाल छाँटना |\n| क्या कभी नहीं | उधारी वाले बड़े सौदे को पहली फ़सल से बाँध देना |\n\n### 9. स्रोत\n\n- मंडी-भावों की सरकारी झलक ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n- आपके अपने इलाक़े की पूछताछ — भुगतान-आदतों का सच्चा स्रोत वही है\n\n*भाव और भुगतान-रिवाज़ इलाक़े-दर-इलाक़े बदलते हैं। यह पाठ ढाँचा देता है — असली अंक आपकी बातचीत से भरेंगे।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीनों तराज़ुओं के नाम और मतलब बोल सकता हूँ\n- [ ] मैं बता सकता हूँ कि घरेलू वर्ग का भाव अक्सर बेहतर क्यों बैठता है\n- [ ] मैं समझा सकता हूँ कि दुकानदार थोक-भाव क्यों माँगता है\n- [ ] मैं महीने-खाते का जोखिम एक वाक्य में कह सकता हूँ\n- [ ] मेरे नक़्शे में हर नाम पर तीन खाने जुड़ गए हैं\n\n**आगे का पाठ:** सबसे पहले वर्ग की गहराई — घरेलू ग्राहक की आदतें, पसंद और उसे बाँधे रखने का हुनर।\n\n---\n---\n", "23": "# पाठ 23 — घरेलू ग्राहक की आदत समझना\n\n**अध्याय:** अ-3 · **पाठ:** 4 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद घरेलू ग्राहक आपके लिए किताब की तरह खुल जाएगा। आप जानेंगे कि वह मशरूम कब, क्यों और कैसे ख़रीदता है। किस बात से बँधता है और किस बात से टूटता है। और अपनी पहली घरेलू-सूची पर उसकी आदतें उतारना शुरू कर देंगे।\n\n### 2. मुख्य बात\n\n> घरेलू ग्राहक भाव से पहले भरोसा ख़रीदता है। उसकी टोकरी छोटी है, पर उसकी ज़बान लंबी है — ख़ुश हुआ तो दस घरों में तारीफ़, रूठा तो बीस घरों में शिकायत।\n\n---\n\n### रसोई की नज़र से देखिए\n\nघरेलू ग्राहक को समझने की तरकीब एक ही है — उसकी रसोई में खड़े होकर सोचिए। मशरूम उसकी रोज़ की सब्ज़ी नहीं है। यह ख़ास दिन की चीज़ है। मेहमान आए, कोई त्योहार हो, बच्चों की फ़रमाइश हो, या हफ़्ते में एक दिन कुछ अलग बनाने का मन — तब मशरूम की याद आती है।\n\nइस आदत का मतलब गहरा है। ख़ास मौक़े की चीज़ से उम्मीदें भी ख़ास होती हैं। दाल में एक दिन कंकड़ निकल जाए, तो घरवाली अगले दिन फिर वही दाल ले लेती है। मेहमानों की सब्ज़ी बिगड़ जाए, तो वह दुकान महीनों याद रहती है। मशरूम ख़ास मौक़े की थाली में जाता है — इसलिए यहाँ माफ़ी की गुंजाइश सबसे कम है।\n\n### आँख, नाक और उँगली की परख\n\nघरेलू ख़रीदार माल कैसे परखता है? तीन औज़ारों से — आँख, नाक और उँगली।\n\nआँख सफ़ेदी देखती है। बटन की बंद, चमकदार, बेदाग़ टोपी उसकी नज़र में ताज़गी की मुहर है। मटमैला रंग और खुली टोपी उसे बासीपन बोलती है — चाहे माल कल ही का क्यों न हो।\n\nनाक महक टटोलती है। भीनी, मिट्टी जैसी ताज़ा गंध भाती है। ज़रा-सी खट्टी या तीखी बू आई, तो थैली वहीं वापस।\n\nउँगली कसाव नापती है। कड़क, भरा हुआ दाना पसंद है। पिलपिला या चिपचिपा छूते ही मन उतर जाता है।\n\nइन तीनों औज़ारों की तसल्ली जिस बेचने वाले के माल में रोज़ मिलती है, उसका नाम रसोई में जम जाता है। फिर भाव दूसरे नंबर की बात रह जाती है।\n\n### बँधने की तीन डोरियाँ\n\nघरेलू ग्राहक एक बार ख़रीद ले, यह आसान है। बार-बार ख़रीदे, यह हुनर है। तीन डोरियाँ उसे बाँधती हैं।\n\nपहली डोरी — एक-सा माल। आज बढ़िया, कल दोयम — यह झूला भरोसा तोड़ता है। छोटी मात्रा में ही सही, पर हर बार एक जैसा साफ़ माल जाए।\n\nदूसरी डोरी — बँधा दिन। मान लो आपने कह दिया — हर बुधवार और रविवार सुबह ताज़ी तुड़ाई मिलेगी। बस, अब उसकी रसोई का कैलेंडर आपसे जुड़ गया। बँधे दिन का इंतज़ार अपने-आप माँग बन जाता है।\n\nतीसरी डोरी — छोटी-छोटी इज़्ज़त। नाम लेकर बात, बच्चे का हाल-चाल, कभी तौल में दो दाने ऊपर। गाँव-क़स्बे का धंधा रिश्ते की ज़मीन पर उगता है। यह डोरी सबसे सस्ती है और सबसे मज़बूत भी।\n\n### ज़बान का पहिया — दोनों दिशा में\n\nअब वह बात, जो घरेलू वर्ग को बाक़ी तीनों से अलग करती है — उसकी ज़बान। संस्था चुपचाप ख़रीदती है। घरेलू ग्राहक बोलता है।\n\nचाची को माल पसंद आया, तो कुएँ-चौपाल-मोबाइल हर जगह आपका नाम चलेगा। यही मुफ़्त का प्रचार आपकी सूची को दस से बीस और बीस से चालीस घरों तक ले जाएगा। बिना एक पैसा ख़र्चे।\n\nपर पहिया उलटा भी घूमता है। एक ख़राब थैली की शिकायत उतनी ही तेज़ दौड़ती है। इसीलिए घरेलू वर्ग में एक पक्का नियम रखिए — शक वाला माल इस टोकरी में कभी नहीं। जो दाना ख़ुद अपने मेहमान को न परोसें, वह चाची की थैली में भी न जाए। दूसरे दर्जे के माल के अपने ठिकाने हैं — यह पिछले पाठ में देख चुके हैं।\n\n### मौक़ों का कैलेंडर — कब बढ़ती है रसोई की माँग\n\nख़ास मौक़े की चीज़ है, तो मौक़ों का कैलेंडर भी बनता है। साल के कुछ पड़ाव घरेलू माँग को उठाते हैं। शादी-लगन के महीने सबसे आगे — मेहमानों की थाली सजती है। त्योहारों की भीड़ उसके साथ। जाड़े के मेहमान-मौसम में गरम सूप और पकौड़े की फ़रमाइश अलग से।\n\nपर कैलेंडर में उतार भी दर्ज कीजिए। कई घरों में व्रत-उपवास और ख़ास धार्मिक दिनों में कुछ चीज़ों से परहेज़ चलता है — कहीं-कहीं मशरूम भी उस सूची में गिना जाता है। यह बात घर-घर और समाज-समाज अलग है। इसका इलाज बहस नहीं, नम्र जानकारी है। अपनी बैठकी में सहज पूछ लीजिए — आपके यहाँ किन दिनों नहीं बनता? जवाब बिना तर्क के आदर से दर्ज कीजिए। ग्राहक की थाली का नियम ग्राहक तय करता है।\n\nएक टक्कर सर्दी की भी गिनिए। जाड़ा आपकी फ़सल का मौसम है, पर वही मौसम सस्ती हरी सब्ज़ियों की बहार भी लाता है। भरी हुई सब्ज़ी-टोकरी के बीच मशरूम को अपनी ख़ास जगह — स्वाद, नयापन और मेहमान-शान — के दम पर लड़ना होता है। यही समझ आगे दाम और संदेश वाले पाठों में काम आएगी।\n\nकैलेंडर बनाने का सबसे सस्ता तरीक़ा भी बैठकी ही है। जिस घर में बैठे हैं, वहीं पूछ लीजिए — साल में सबसे ज़्यादा किस महीने बनता है? तीन-चार घरों के जवाब जोड़ते ही आपके इलाक़े का मौक़ा-नक़्शा उभर आएगा।\n\nइस पूरे कैलेंडर को बँधे-दिन वाली डोरी से जोड़िए — मौक़े के हफ़्तों में आपका बँधा दिन सोने का हो जाता है।\n\n### चित्र — घरेलू ग्राहक की किताब\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">घरेलू ग्राहक — परख और डोरियाँ</text>\n  <rect x=\"70\" y=\"110\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"170\" y=\"155\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">आँख</text>\n  <text x=\"170\" y=\"190\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बंद, चमकदार</text>\n  <text x=\"170\" y=\"220\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बेदाग़ टोपी</text>\n  <rect x=\"300\" y=\"110\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"155\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">नाक</text>\n  <text x=\"400\" y=\"190\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">भीनी ताज़ा महक</text>\n  <text x=\"400\" y=\"220\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">खट्टी बू = वापसी</text>\n  <rect x=\"530\" y=\"110\" width=\"200\" height=\"150\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"630\" y=\"155\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\">उँगली</text>\n  <text x=\"630\" y=\"190\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">कड़क, भरा दाना</text>\n  <text x=\"630\" y=\"220\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">पिलपिला = ना</text>\n  <text x=\"400\" y=\"310\" font-size=\"22\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">तीन परख पार — तब भरोसे की तिजोरी खुलती है</text>\n  <rect x=\"70\" y=\"350\" width=\"660\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"388\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">डोरी-1: हर बार एक-सा माल</text>\n  <text x=\"400\" y=\"420\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">झूलता दर्जा = टूटता भरोसा</text>\n  <rect x=\"70\" y=\"460\" width=\"660\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"498\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">डोरी-2: बँधा दिन — जैसे बुधवार-रविवार</text>\n  <text x=\"400\" y=\"530\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">इंतज़ार ख़ुद माँग बन जाता है</text>\n  <rect x=\"70\" y=\"570\" width=\"660\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"608\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">डोरी-3: नाम, हाल-चाल, छोटी इज़्ज़त</text>\n  <text x=\"400\" y=\"640\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">रिश्ता — सबसे सस्ती, सबसे मज़बूत डोरी</text>\n  <text x=\"400\" y=\"720\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">ज़बान का पहिया: ख़ुश = दस घरों में नाम · रूठा = बीस में शिकायत</text>\n  <text x=\"400\" y=\"760\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">नियम: शक वाला दाना इस टोकरी में कभी नहीं</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nअपने वर्ग-नक़्शे के घरेलू खाने के तीन नामों में से एक जान-पहचान का घर चुनिए। वहाँ चाय-बात के बहाने पाँच मिनट बैठिए और तीन बातें सहज पूछिए — मशरूम कब-कब बनता है, कहाँ से लेते हैं, और लेते समय क्या देखते हैं। जवाब घर लौटकर नोटबुक में \"घरेलू आदत-पन्ना\" पर उतारिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- तीनों सवालों के जवाब दर्ज हों\n- जवाबों में से निकली एक सीख अपने शब्दों में लिखी हो\n\n### 5. सबूत\n\nआदत-पन्ने की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"गाँव-क़स्बे का घरेलू ग्राहक सब्ज़ी बेचने वाले से किन छोटी बातों पर टूटकर दूसरे के पास चला जाता है? पाँच आम कारण बताओ।\"* — पाँचों कारण लिखिए और हरेक के आगे अपना बचाव-उपाय सोचकर जोड़िए।\n\n### 7. आम ग़लती\n\nलोग घरेलू ग्राहक की छोटी तौल देखकर उसे हल्का गिनते हैं। **तौल छोटी है, ज़बान बड़ी है।** यही वर्ग आपका मुफ़्त प्रचारक है और यही सबसे तेज़ बदनामी-वाहक भी। पहले चक्र की साख इसी आँगन में बनती या बिगड़ती है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-22 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | जान-पहचान में बैठकी, सहज सवाल, दर्ज करना |\n| क्या कभी नहीं | बात को सौदे में बदलकर अभी से वादा ठोक देना |\n\n### 9. स्रोत\n\n- आपकी अपनी बैठकी और आदत-पन्ना — घरेलू आदतों का पहला स्रोत यही है\n- भारतीय खाद्य सुरक्षा एवं मानक प्राधिकरण — ताज़ा सब्ज़ी की सँभाल ([fssai.gov.in](https://fssai.gov.in/)) · देखा गया 09-08-2026\n\n*आदतें घर-घर थोड़ी बदलती हैं। तीन-चार घरों की बात मिलाकर ही इलाक़े का ढर्रा पकड़ में आता है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बता सकता हूँ कि मशरूम ख़ास मौक़े की चीज़ होने का क्या मतलब है\n- [ ] मैं आँख-नाक-उँगली की तीनों परखें गिना सकता हूँ\n- [ ] मैं तीनों डोरियाँ और उनका काम समझा सकता हूँ\n- [ ] मैं ज़बान के पहिये की दोनों दिशाएँ जानता हूँ\n- [ ] मैंने एक घर की बैठकी करके आदत-पन्ना भर लिया है\n\n**आगे का पाठ:** अगला वर्ग — दुकानदार। उससे पहली बात कैसे खोलें कि दरवाज़ा खुले, बंद न हो।\n\n---\n---\n", "24": "# पाठ 24 — सब्ज़ी दुकानदार से पहली बात\n\n**अध्याय:** अ-3 · **पाठ:** 5 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद दुकानदार के पास जाने से पहले आपके हाथ में पूरी तैयारी होगी। सही घड़ी, सही पहला वाक्य, पूछने के चार सवाल और लौटने का सलीक़ा। और आप एक असली दुकान पर यह पहली बात करके भी आएँगे।\n\n### 2. मुख्य बात\n\n> दुकानदार से पहली बात माल बेचने के लिए नहीं होती। वह दरवाज़ा खोलने के लिए होती है। पहले दिन जो सिर्फ़ सीखने आता है, दुकानदार उसे बेचने वाले दिन तक याद रखता है।\n\n---\n\n### दुकानदार की कुर्सी पर बैठिए\n\nबात शुरू करने से पहले उस पार की कुर्सी पर बैठकर सोचिए। दुकानदार का दिन कैसा है? भोर में मंडी, दिन-भर काँटा-तराज़ू, उधारी का हिसाब, सड़ते माल की चिंता। उसके पास हर हफ़्ते कोई न कोई कुछ बेचने आता है। ज़्यादातर को वह दो वाक्यों में टाल देता है।\n\nतो वह किसकी सुनता है? जो उसका समय बचाए। जो उसकी चिंता समझे। और जो पहले ही दिन गले न पड़े। आपकी पहली बात का पूरा ढाँचा इसी समझ पर खड़ा होगा। अ-2 में सीखा सलीक़ा — सुस्त घड़ी चुनना, एक वाक्य में परिचय, समय ख़त्म होते ही उठ जाना — यहाँ ज्यों का त्यों लागू है। अब उसके ऊपर की मंज़िल चढ़िए।\n\n### पहला वाक्य — बेचना नहीं, सीखना\n\nदुकान पर पहुँचकर सबसे बड़ा फंदा पहला वाक्य है। ग़लत शुरुआत — भैया, मशरूम रखिएगा? इस सवाल का बना-बनाया जवाब दुकानदार की जेब में रखा है — अभी नहीं। दरवाज़ा खुलने से पहले बंद।\n\nसही शुरुआत बिल्कुल अलग है — भैया, मैं मशरूम उगाना सीख रहा हूँ। आप बरसों से सब्ज़ी बेच रहे हैं। दो मिनट मिलें तो कुछ पूछना था। अब देखिए क्या हुआ। आपने माँगा नहीं, इज़्ज़त दी। बेचने वाले से हर कोई बचता है। सिखाने का मौक़ा हर अनुभवी को भाता है। यही वाक्य दरवाज़े की चाबी है।\n\n### चार सवाल — दुकानदार की क़लम से\n\nभीतर पहुँचकर चार सवाल पूछिए। चारों ऐसे हैं, जो उसके अनुभव को बुलाते हैं और आपकी नोटबुक भरते हैं।\n\nपहला — आपके यहाँ मशरूम की माँग कैसी रहती है, कौन लोग माँगते हैं? दूसरा — जो माल अभी आता है, उसमें क्या अच्छा है और क्या खलता है? यह सवाल सोने की खान है। दुकानदार की शिकायत ही आपके लिए मौक़े का नक़्शा है। तीसरा — आप नया माल किस कसौटी पर परखते हैं? चौथा — कोई नया उत्पादक आपसे जुड़ना चाहे, तो उसे पहले क्या साबित करना चाहिए?\n\nग़ौर कीजिए — चारों में एक भी जगह आपने अपना माल नहीं बेचा। आपने उसकी क़लम से अपनी तैयारी की सूची लिखवा ली। शर्तें अब अंदाज़ा नहीं, उसी की ज़बानी दर्ज हैं।\n\n### लौटती बात — बीज बोकर उठिए\n\nबात समेटते समय दो काम कीजिए। पहला — धन्यवाद, नाम लेकर। दूसरा — एक हल्का, बिना बोझ वाला वाक्य — जब मेरी पहली फ़सल आएगी, तो सबसे पहले आपको दिखाने लाऊँगा। आपकी राय मेरे लिए क़ीमती है।\n\nइस वाक्य में वादा माल दिखाने भर का है, बेचने-ख़रीदने का नहीं। दुकानदार पर कोई बोझ नहीं पड़ा। पर उसके मन में एक खूँटी गड़ गई — वह लड़का आएगा। जिस दिन आप ताज़ी टोकरी लेकर पहुँचेंगे, वह अजनबी नहीं होंगे। वह उस बातचीत की अगली कड़ी होंगे। पहली बात का असली फल यही खूँटी है।\n\nलौटकर नोटबुक में दर्ज कीजिए — दुकान का नाम, तारीख़, चारों जवाब और उसकी परख-कसौटी। यह पन्ना आगे \"दस ग्राहकों की सूची\" वाले पाठ में सीधा काम आएगा।\n\n### किस दुकान से शुरुआत\n\nआख़िरी सवाल — पहली बात किस दुकान से? अपने बाज़ार-पत्रक में झाँकिए। जिस दुकान पर मशरूम पहले से बिकता दिखा था, वह सबसे सहज शुरुआत है — वहाँ माँग साबित है, बस अपनी जगह बनानी है। जहाँ मशरूम नहीं दिखा था, वह दूसरी बारी का दरवाज़ा है — वहाँ माँग जगानी होगी, यह अगली सीढ़ी का हुनर है।\n\nऔर एक हौसले की बात। पहली बात में घबराहट सबको होती है। इसका इलाज अभ्यास है — घर में किसी से दुकानदार बनने को कहिए और पूरी बात दो बार दोहराइए। ज़बान पर चढ़ी बात दुकान पर लड़खड़ाती नहीं।\n\n### ना का भी सलीक़ा\n\nएक तैयारी ना सुनने की भी रखिए। कोई दुकानदार रूखा मिलेगा। कोई कहेगा — समय नहीं है। यह आपकी हार नहीं, उसके दिन की थकान है।\n\nना मिलने पर तीन काम कीजिए। पहला — मुस्कुराकर धन्यवाद, बहस शून्य। दूसरा — दरवाज़ा खुला छोड़ने वाली एक पंक्ति: कोई बात नहीं, कभी फ़ुर्सत हो तो आ जाऊँगा। तीसरा — एक सोने का सवाल: आपकी नज़र में इलाक़े की किस दुकान को अच्छे ताज़े माल की तलाश रहती है? रूखा दुकानदार भी इस सवाल पर अक्सर रास्ता दिखा देता है — और उसकी बताई दुकान पर आपकी पहली पंक्ति बन जाती है: फ़लाँ भैया ने आपका नाम लिया था। जान-पहचान के हवाले से खुला दरवाज़ा आधा खुला ही मिलता है।\n\nऔर हर भेंट के बाद अपनी भी जाँच कीजिए — कौन-सा क़दम अटका? पहला वाक्य भूले, या कोई सवाल छूटा? अगली दुकान पर वही कड़ी कसिए। हर भेंट पिछली से बेहतर होती जाएगी।\n\nनोटबुक में ना भी दर्ज कीजिए — नाम, तारीख़ और लहजा। कई ना समय बदलने पर हाँ बनी हैं। दर्ज ना भूलती नहीं।\n\n### चित्र — पहली बात की सीढ़ी\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">दुकानदार से पहली बात — पाँच क़दम</text>\n  <rect x=\"80\" y=\"110\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"148\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">क़दम-1: सुस्त घड़ी चुनो — भीड़ का वक़्त नहीं</text>\n  <text x=\"400\" y=\"180\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">उसका समय बचाना पहली इज़्ज़त है</text>\n  <rect x=\"80\" y=\"220\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"258\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">क़दम-2: पहला वाक्य — सीखने आया हूँ, बेचने नहीं</text>\n  <text x=\"400\" y=\"290\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">\"मशरूम रखिएगा?\" = बंद दरवाज़ा</text>\n  <rect x=\"80\" y=\"330\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"368\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">क़दम-3: चार सवाल — माँग · शिकायत · परख · शर्त</text>\n  <text x=\"400\" y=\"400\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">उसकी शिकायत = आपके मौक़े का नक़्शा</text>\n  <rect x=\"80\" y=\"440\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"478\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">क़दम-4: बीज बोकर उठो — पहली फ़सल दिखाने आऊँगा</text>\n  <text x=\"400\" y=\"510\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">वादा दिखाने का, बेचने का नहीं</text>\n  <rect x=\"80\" y=\"550\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"588\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">क़दम-5: लौटकर सब दर्ज — नाम, तारीख़, चारों जवाब</text>\n  <text x=\"400\" y=\"620\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">यही पन्ना दस-ग्राहक सूची की ईंट है</text>\n  <text x=\"400\" y=\"700\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">घर पर दो बार अभ्यास — ज़बान पर चढ़ी बात लड़खड़ाती नहीं</text>\n  <text x=\"400\" y=\"745\" font-size=\"19\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">पहली बात का फल सौदा नहीं — याद रह जाना है</text>\n</svg>\n\n### 3. आज का काम «असली»\n\nपहले घर में किसी को दुकानदार बनाकर पूरी बात का दो बार अभ्यास कीजिए। फिर बाज़ार-पत्रक से चुनी एक असली दुकान पर जाकर पाँचों क़दम आज़माइए — सुस्त घड़ी, सीखने वाला पहला वाक्य, चार सवाल, दिखाने का वादा, विदा। लौटकर \"दुकान-पन्ना\" भरिए — नाम, तारीख़, चारों जवाब, परख-कसौटी।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दुकान-पन्ने पर चारों सवालों के जवाब दर्ज हों\n- दुकानदार की कम से कम एक शिकायत उसी के शब्दों में लिखी हो\n\n### 5. सबूत\n\nभरे दुकान-पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैंने दुकानदार से पहली जानकारी-बात कर ली है। उसकी शिकायतें और शर्तें यह हैं। अगली मुलाक़ात में भरोसा बढ़ाने के लिए मुझे क्या तैयारी करके जाना चाहिए?\"* — फिर पन्ना पढ़कर सुनाइए। सुझावों में से दो चुनकर अपनी अगली-दौड़ सूची में डालिए।\n\n### 7. आम ग़लती\n\nलोग पहली ही बात में भाव पूछ बैठते हैं या भाव बता बैठते हैं। **भाव रिश्ते के बाद की बात है।** जिस मेज़ पर अभी परिचय भी नहीं जमा, वहाँ भाव की बात जल्दबाज़ लगती है। पहली मुलाक़ात का एक ही सौदा है — याद रह जाना।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-23 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, आने-जाने का इंतज़ाम |\n| देखरेख | नाबालिग हों तो घर के बड़े को बताकर निकलें |\n| क्या कर सकते हैं | अभ्यास, दुकान-भेंट, सवाल, दर्ज करना |\n| क्या कभी नहीं | पहली बात में दाम-मात्रा का पक्का वादा करना |\n\n### 9. स्रोत\n\n- आपकी अपनी दुकान-भेंट और दुकान-पन्ना — इस पाठ का असली स्रोत यही है\n- मंडी-भाव की सरकारी झलक — भेंट से पहले भाव का मोटा अंदाज़ा ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n\n*हर दुकानदार का मिज़ाज अलग है। एक बेरुख़ी से हिम्मत मत तोड़िए — पत्रक में अगली दुकान का नाम भी दर्ज है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं दुकानदार की कुर्सी वाली सोच दो वाक्यों में समझा सकता हूँ\n- [ ] मैं सही और ग़लत पहले वाक्य का फ़र्क़ बता सकता हूँ\n- [ ] मैं चारों सवाल बिना देखे बोल सकता हूँ\n- [ ] मैं जानता हूँ कि दिखाने का वादा बेचने के वादे से क्यों अलग है\n- [ ] मैंने एक असली दुकान का दुकान-पन्ना भर लिया है\n\n**आगे का पाठ:** बड़ी हाँडी की दुनिया — होटल, ढाबा और शादी की रसोई से बात करने का ढंग।\n\n---\n---\n", "25": "# पाठ 25 — होटल, ढाबा और शादी की रसोई से बात\n\n**अध्याय:** अ-3 · **पाठ:** 6 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद बड़ी हाँडी की दुनिया आपके लिए अजनबी नहीं रहेगी। आप जानेंगे कि होटल-ढाबे में असली फ़ैसला किसका चलता है। किस घड़ी बात खुलती है। कौन-से पाँच सवाल संस्था-वर्ग की जेब खोलते हैं। और एक असली रसोई से बात करके संस्था-पन्ना भरेंगे।\n\n### 2. मुख्य बात\n\n> संस्था की रसोई भाव से पहले भरोसा तौलती है और भरोसे से पहले तारीख़। जो आदमी छोटी बात का पक्का निकला, बड़ी हाँडी उसी की टोकरी से भरती है।\n\n---\n\n### असली फ़ैसला किसकी मुट्ठी में\n\nनए लोग होटल पहुँचकर सीधे मालिक को खोजते हैं। यह अक्सर उल्टा रास्ता है। सब्ज़ी की ख़रीद का रोज़ का फ़ैसला ज़्यादातर जगह रसोई सँभालने वाले की मुट्ठी में होता है — हेड रसोइया, या रोज़ का सामान लाने वाला आदमी। मालिक महीने का हिसाब देखता है। रसोइया रोज़ की टोकरी देखता है।\n\nइसलिए पहली पहचान रसोई से बनाइए। रसोइए की तारीफ़ सच्ची और सस्ती चाबी है — भैया, आपकी मशरूम-सब्ज़ी की बड़ी तारीफ़ सुनी है। यह वाक्य झूठा नहीं होना चाहिए। जिस होटल की तारीफ़ सुनी ही नहीं, वहाँ सीधा परिचय काफ़ी है। शादी-भोज की दुनिया में यही जगह ठेके वाले रसोइए या हलवाई की है — वह मौसम का बादशाह है और उसकी डायरी में तारीख़ें महीनों पहले लिखी जाती हैं।\n\n### घड़ी और पहला वाक्य\n\nरसोई की भी सुस्त घड़ी होती है। दोपहर का खाना निपटने के बाद और शाम की तैयारी छिड़ने से पहले — मोटे तौर पर तीन से पाँच का पहर — बात के लिए सबसे नरम रहता है। भोर और खाने की भीड़ में रसोई से बात माँगना अपनी बात का अपमान कराना है।\n\nपहला वाक्य वही सीखने वाला रखिए, जो दुकान पर चला था — बेचने नहीं, समझने आया हूँ। संस्था के सामने एक पंक्ति और जोड़िए — आगे चलकर ताज़ा माल की सप्लाई की तैयारी कर रहा हूँ, पहले आपकी ज़रूरत समझना चाहता हूँ। यह पंक्ति आपको ठेलिया वाला नहीं, तैयारी वाला आदमी बनाती है। संस्था तैयारी वालों से बात करती है।\n\n### पाँच सवाल — बड़ी हाँडी की नाप\n\nअब पाँच सवाल, जो संस्था-पन्ने के पाँच खाने भरेंगे।\n\nपहला — मशरूम की खपत कैसी है? हफ़्ते में कितनी बार बनता है, एक बार में मोटा-मोटी कितना लगता है? दूसरा — माल अभी कहाँ से आता है और उस इंतज़ाम में क्या ठीक है, क्या खलता है? यहाँ भी शिकायत ही आपके मौक़े का दरवाज़ा है — देर से आना, माल का झूलता दर्जा, माँग पर न मिलना। तीसरा — माल किस रूप में चाहिए? साफ़, छँटा, किस नाप की टोपी? रसोइए की पसंद पक्की होती है। चौथा — भाव और भुगतान का रिवाज़ क्या है — रोज़, हफ़्ता या महीने का खाता? पिछले पाठ की तीसरी तराज़ू यहीं तौली जाएगी। पाँचवाँ — बड़े मौक़ों की ख़रीद कैसे होती है — शादी-भोज, त्योहारी भीड़ के दिन?\n\nपाँचों जवाब उसी की ज़बान के शब्दों में उतारिए। संस्था-पन्ने का यही माल असली है।\n\n### छोटा वादा, बड़ी इज़्ज़त\n\nविदा की घड़ी दुकान वाली ही है — नाम लेकर धन्यवाद, और दिखाने का वादा: पहली फ़सल आएगी तो नमूना लेकर हाज़िर होऊँगा। पर संस्था के सामने एक लक्ष्मण-रेखा और खिंची है।\n\nरसोइया उत्साह में कह सकता है — ठीक है, अगले महीने से हर हफ़्ते दस किलो देना। जी ललचेगा। रुक जाइए। पाँच बैग वाले पहले चक्र के पास हर हफ़्ते दस किलो नहीं है। जो नाप जेब में नहीं, वह ज़बान पर नहीं। नम्र जवाब तैयार रखिए — अभी मेरी शुरुआत छोटी है। पहले नमूना दिखाऊँगा, फिर जितने का पक्का हो सकूँगा, उतना ही कहूँगा। यह जवाब सौदा नहीं तोड़ता। यह आपको उस भीड़ से अलग करता है, जो बड़ा बोलकर छोटा निकलती है। संस्था की दुनिया में यही अलग पहचान सबसे लंबी चलती है।\n\nना का सलीक़ा यहाँ भी वही है — बहस शून्य, दरवाज़ा खुला, और वही सोने का सवाल: आपकी नज़र में किस रसोई को ताज़े माल की तलाश रहती है?\n\n### भोज-रसोइए की अलग दुनिया\n\nहोटल रोज़ का ग्राहक है। भोज-रसोइया मौसम का ग्राहक है। उसकी दुनिया के तीन नियम अलग से समझिए।\n\nपहला नियम — डायरी राज करती है। लगन के महीनों की तारीख़ें उसकी डायरी में बहुत पहले लिखी जा चुकी होती हैं। यानी उससे बात फ़सल के हफ़्ते नहीं, महीनों पहले की जाती है। आज की भेंट का असली फल अगले लगन-मौसम में मिलेगा — यह लंबी बुआई है, धीरज रखिए।\n\nदूसरा नियम — एकमुश्त का खेल। उसे हर हफ़्ते थोड़ा नहीं, एक दिन बहुत चाहिए — और ठीक उसी सुबह, ताज़ा। यह माँग आगे चलकर आपके लिए सोना है, पर पहले चक्र की तौल से बहुत बड़ी है। इसलिए उससे आज सिर्फ़ जान-पहचान और उसकी ख़रीद का ढंग पूछिए — बाक़ी बात तौल बढ़ने पर।\n\nतीसरा नियम — साथी-जाल। हलवाई अकेला नहीं चलता। उसके साथ बर्तन वाला, टेंट वाला, सब्ज़ी काटने वाली टोली — पूरा जाल चलता है। इस जाल का हर आदमी आपके लिए ख़बर का ज़रिया है — किस गाँव में कब भोज है, किस रसोइए को क्या चाहिए। एक हलवाई से बना रिश्ता दस भोजों की ख़बर लाता है।\n\n### चित्र — रसोई-भेंट की नाप\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">संस्था-भेंट — किससे, कब, क्या</text>\n  <rect x=\"70\" y=\"110\" width=\"320\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"230\" y=\"155\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">किससे बात</text>\n  <text x=\"230\" y=\"190\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">रोज़ की टोकरी = रसोइया</text>\n  <text x=\"230\" y=\"220\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">भोज = ठेके वाला हलवाई</text>\n  <rect x=\"410\" y=\"110\" width=\"320\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"570\" y=\"155\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">किस घड़ी</text>\n  <text x=\"570\" y=\"190\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">दोपहर के बाद का ठहराव</text>\n  <text x=\"570\" y=\"220\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">खाने की भीड़ में कभी नहीं</text>\n  <rect x=\"70\" y=\"280\" width=\"660\" height=\"230\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"320\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">पाँच सवाल — संस्था-पन्ने के पाँच खाने</text>\n  <text x=\"400\" y=\"360\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">1. खपत — कितनी बार, कितना</text>\n  <text x=\"400\" y=\"395\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">2. अभी का स्रोत — और उसकी शिकायत</text>\n  <text x=\"400\" y=\"430\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">3. माल का रूप — सफ़ाई, छँटाई, नाप</text>\n  <text x=\"400\" y=\"465\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">4. भाव-भुगतान का रिवाज़</text>\n  <text x=\"400\" y=\"500\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">5. बड़े मौक़ों की ख़रीद का ढंग</text>\n  <rect x=\"70\" y=\"540\" width=\"660\" height=\"100\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"580\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">लक्ष्मण-रेखा: जो नाप जेब में नहीं, वह ज़बान पर नहीं</text>\n  <text x=\"400\" y=\"615\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">बड़ा बोलकर छोटा निकलना = कटा हुआ नाम</text>\n  <text x=\"400\" y=\"700\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">विदा: नमूना दिखाने का वादा — बेचने का नहीं</text>\n  <text x=\"400\" y=\"745\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">जवाब उसी की ज़बान के शब्दों में दर्ज करो</text>\n</svg>\n\n### 3. आज का काम «असली»\n\nअपने वर्ग-नक़्शे की संस्था-पंक्ति से एक ठिकाना चुनिए — होटल, ढाबा, मेस या भोज-रसोइया। सुस्त घड़ी में जाकर पाँचों सवाल पूछिए और \"संस्था-पन्ना\" भरिए — ठिकाने का नाम, बात किससे हुई, तारीख़ और पाँचों जवाब। कोई बड़ी माँग सामने रखे, तो लक्ष्मण-रेखा वाला नम्र जवाब आज़माकर उसकी प्रतिक्रिया भी दर्ज कीजिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- संस्था-पन्ने के पाँचों खाने भरे हों\n- खपत वाले खाने में बार और मात्रा दोनों दर्ज हों\n\n### 5. सबूत\n\nभरे संस्था-पन्ने की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"होटल-रसोई को छोटे मशरूम-उत्पादक से जुड़ने में आम तौर पर कौन-से डर होते हैं और मैं पहली भेंट में उन्हें कैसे घटा सकता हूँ?\"* — डरों की सूची बनाइए और हरेक के आगे अपनी एक तैयारी लिखिए।\n\n### 7. आम ग़लती\n\nलोग रसोइए के सामने बड़ी हाँ बोल आते हैं — जितना कहेंगे, दे दूँगा। **संस्था हाँ नहीं भूलती।** पहली ही चूक पर वह नाम काटती है और अपने घेरे में बता भी देती है। छोटा बोलकर पूरा करने वाला वहाँ बड़ा बनता है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-24 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, आने-जाने का इंतज़ाम |\n| देखरेख | नाबालिग हों तो घर के बड़े को बताकर निकलें |\n| क्या कर सकते हैं | रसोई से भेंट, पाँच सवाल, पन्ना भरना |\n| क्या कभी नहीं | जेब से बड़ी मात्रा या तारीख़ का वादा कर आना |\n\n### 9. स्रोत\n\n- आपकी अपनी संस्था-भेंट और संस्था-पन्ना — इस पाठ का असली स्रोत यही है\n- भारतीय खाद्य सुरक्षा एवं मानक प्राधिकरण — खान-पान कारोबार के नियमों की झलक ([fssai.gov.in](https://fssai.gov.in/)) · देखा गया 09-08-2026\n\n*होटल-ढाबे ख़ुद खाद्य-नियमों में बँधे हैं — इसीलिए वे साफ़-सुथरे, भरोसेमंद माल वाले को क़दर से देखते हैं। आपकी सफ़ाई वहाँ सीधी पूँजी है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बता सकता हूँ कि रोज़ की ख़रीद का असली फ़ैसला अक्सर किसके पास है\n- [ ] मैं रसोई की सुस्त घड़ी पहचान सकता हूँ\n- [ ] मैं पाँचों सवाल बिना देखे बोल सकता हूँ\n- [ ] मैं लक्ष्मण-रेखा वाला नम्र जवाब कह सकता हूँ\n- [ ] मैंने एक असली रसोई का संस्था-पन्ना भर लिया है\n\n**आगे का पाठ:** पन्नों में बिखरी गिनतियाँ अब जुड़ेंगी — अपने इलाक़े की रोज़ की माँग का पहला जोड़।\n\n---\n---\n", "26": "# पाठ 26 — रोज़ की माँग का अंदाज़ा लगाना\n\n**अध्याय:** अ-3 · **पाठ:** 7 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nअब तक आपने पन्ने भरे — बाज़ार-पत्रक, आदत-पन्ना, दुकान-पन्ना, संस्था-पन्ना। इस पाठ में वे सब जुड़कर एक संख्या बनेंगे — आपके इलाक़े की अंदाज़न माँग। इसके बाद आप कम-बीच-ज़्यादा की तीन-पंक्ति गिनती बनाना सीख जाएँगे और उसे अपनी फ़सल के नाप से मिलाना भी।\n\n### 2. मुख्य बात\n\n> अंदाज़ा अटकल नहीं होता। अंदाज़ा गिनती पर खड़ी सावधान संख्या होता है — और वह हमेशा एक नहीं, तीन आती है: कम से कम, बीच की, ज़्यादा से ज़्यादा।\n\n---\n\n### जोड़ का सीधा सूत्र\n\nमाँग का जोड़ तीन धाराओं से बनता है — वही तीन वर्ग, जिनसे आपने बात की है।\n\nपहली धारा — घर। सूत्र: घरों की गिनती × एक बार की मात्रा × हफ़्ते में बार। मान लो आपकी पहचान के बारह घर हैं। बैठकियों से पता चला कि आम घर एक बार में लगभग आधा किलो लेता है, हफ़्ते में एक बार। जोड़ — बारह × आधा × एक = छह किलो हर हफ़्ता।\n\nदूसरी धारा — दुकान। दुकान-पन्ने से दुकानदार की बताई रोज़ की खपत उठाइए। मान लो दो दुकानें रोज़ दो-दो किलो के आसपास बेचती हैं, हफ़्ते में छह दिन। जोड़ — दो × दो × छह = चौबीस किलो।\n\nतीसरी धारा — संस्था। संस्था-पन्ने की खपत-पंक्ति देखिए। मान लो एक ढाबे में हफ़्ते में दो बार, पाँच-पाँच किलो बनता है। जोड़ — दस किलो।\n\nतीनों धाराएँ मिलाइए — छह और चौबीस और दस, यानी हफ़्ते के लगभग चालीस किलो की झलक। यह आपके छोटे-से घेरे की गिनती है, पूरे इलाक़े की नहीं। असली बाज़ार इससे बड़ा ही होगा।\n\n### एक संख्या नहीं, तीन संख्याएँ\n\nअब इस कोर्स की पुरानी सीख यहाँ लगाइए — नाप हमेशा श्रेणी में। माँग की गिनती भी एक अकेली संख्या नहीं, तीन संख्याएँ माँगती है।\n\nकम से कम वाली संख्या — जब सिर्फ़ पक्की बातें गिनें। सिर्फ़ वे घर, जिन्होंने ख़ुद रुचि दिखाई। सिर्फ़ वह दुकान, जिसने साफ़ कहा — नया माल लूँगा। मान लो यह जोड़ पंद्रह किलो बैठा।\n\nबीच वाली संख्या — ऊपर की पूरी गिनती, यानी चालीस के आसपास।\n\nज़्यादा वाली संख्या — मौक़े के हफ़्तों की। शादी-लगन और त्योहार की भीड़ में यही धाराएँ फूल जाती हैं। मान लो साठ-सत्तर तक।\n\nतीनों संख्याएँ एक साथ लिखने का फल यह है कि कोई एक दिन आपको धोखा नहीं दे पाता। सूने हफ़्ते में आप कम वाली संख्या याद रखते हैं और घबराते नहीं। भीड़ के हफ़्ते में ज़्यादा वाली याद रखते हैं और चूकते नहीं।\n\n### अपनी फ़सल से मिलान — असली आँख खुलती है\n\nअब सबसे मज़ेदार मिलान कीजिए। आपकी पहली फ़सल का नाप क्या है? पाँच बैग। आगे बिछाई वाले अध्याय में गिनकर देखेंगे, पर मोटा अंदाज़ पकड़िए — पाँच घरेलू बैग की एक फ़सल-लहर कुछ ही किलो देती है।\n\nऔर आपके छोटे घेरे की हफ़्ते की बीच वाली माँग? चालीस के आसपास। यानी माँग आपकी पहली फ़सल से कई गुना बड़ी बैठी है।\n\nइस मिलान से तीन सीख निकालिए। पहली — डर उल्टा था। नए आदमी का डर होता है — बिकेगा कहाँ? गिनती कहती है — पहले चक्र का माल तो गिने-चुने घर ही सोख लेंगे। दूसरी — पहला चक्र बेफ़िक्री से सीखने का है; बाज़ार भागा नहीं जा रहा। तीसरी — बढ़ने की सीढ़ी माँग नहीं, आपकी आपूर्ति तय करेगी। यही सीढ़ी आगे बैग-गिनती और हब तक जाएगी।\n\n### अंदाज़ा ताज़ा रहे\n\nआख़िरी नियम — अंदाज़े पर तारीख़ डालिए। आज की गिनती आज का सच है। छह महीने में दुकानें बदलेंगी, मौसम बदलेगा, आपकी पहचान का घेरा बड़ा होगा। इसलिए यह तीन-पंक्ति गिनती पत्थर नहीं, स्लेट है — हर मौसम में एक बार मिटाकर ताज़ा लिखी जाएगी। आगे माँग-योजना वाला अध्याय इसी स्लेट को सालाना तालिका बनाएगा।\n\n### गिनती में हवा किधर से घुसती है\n\nजोड़ सीखने के साथ यह भी सीखिए कि गिनती फूलती कैसे है। तीन छेद आम हैं।\n\nपहला छेद — शिष्टाचार की हाँ। बैठकी में चाची ने कहा — हाँ-हाँ, बनता है कभी-कभी। यह मीठी बात है, पक्की माँग नहीं। गिनती में वही मात्रा जाए, जो उसने ख़ुद बोली — आपके सवाल में घुली उम्मीद नहीं।\n\nदूसरा छेद — भीड़ के दिन का चश्मा। इतवार की हाट देखकर हफ़्ते का जोड़ लगाने वाला दुगना गिन बैठता है। दुकानदार से सीधा पूछिए — सूने दिन कितना जाता है? दोनों दिन की बात से ही सच्ची औसत बनती है।\n\nतीसरा छेद — अपनी बात दूसरे के मुँह में। कितना — दो किलो रोज़ तो बिकता ही होगा न? ऐसा पूछने वाला जवाब नहीं, अपनी गूँज सुनता है। सवाल खुला रखिए — कितना बिकता है? — और जवाब उसी की ज़बान के शब्दों में उतारिए।\n\nगिनती जितनी सूखी, योजना उतनी सच्ची — मीठे अंक सिर्फ़ मन बहलाते हैं।\n\nएक चौथी सावधानी संस्था-धारा की भी। रसोइए की बताई खपत मौसम से झूलती है — लगन के महीने की बात और सूने महीने की बात अलग-अलग पूछिए। एक ही सवाल दो मौसमों के लिए पूछना गिनती को दुगना पक्का कर देता है।\n\nतीनों छेदों की एक ही मरहम है — गिनती में सिर्फ़ वही अंक, जो सामने वाले ने ख़ुद बोला और आपने ठिकाने-समेत दर्ज किया। हवा वाली गिनती से बनी योजना पहली टक्कर में बैठ जाती है।\n\n### चित्र — तीन धाराओं का जोड़\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">हफ़्ते की माँग — मान-लो जोड़</text>\n  <rect x=\"60\" y=\"110\" width=\"200\" height=\"160\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"160\" y=\"150\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">घर</text>\n  <text x=\"160\" y=\"185\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">12 घर × आधा किलो</text>\n  <text x=\"160\" y=\"215\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">× हफ़्ते में 1 बार</text>\n  <text x=\"160\" y=\"250\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">= 6 किलो</text>\n  <rect x=\"300\" y=\"110\" width=\"200\" height=\"160\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"150\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">दुकान</text>\n  <text x=\"400\" y=\"185\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">2 दुकान × 2 किलो</text>\n  <text x=\"400\" y=\"215\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">× 6 दिन</text>\n  <text x=\"400\" y=\"250\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">= 24 किलो</text>\n  <rect x=\"540\" y=\"110\" width=\"200\" height=\"160\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"640\" y=\"150\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">संस्था</text>\n  <text x=\"640\" y=\"185\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">1 ढाबा × 5 किलो</text>\n  <text x=\"640\" y=\"215\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">× 2 बार</text>\n  <text x=\"640\" y=\"250\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">= 10 किलो</text>\n  <line x1=\"160\" y1=\"270\" x2=\"370\" y2=\"380\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"400\" y1=\"270\" x2=\"400\" y2=\"380\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"640\" y1=\"270\" x2=\"430\" y2=\"380\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"250\" y=\"390\" width=\"300\" height=\"80\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"425\" font-size=\"23\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">बीच की संख्या</text>\n  <text x=\"400\" y=\"458\" font-size=\"21\" fill=\"#0B1F3A\" text-anchor=\"middle\">≈ 40 किलो / हफ़्ता</text>\n  <rect x=\"70\" y=\"510\" width=\"320\" height=\"70\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"230\" y=\"540\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">कम से कम ≈ 15</text>\n  <text x=\"230\" y=\"568\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">सिर्फ़ पक्की बातें</text>\n  <rect x=\"410\" y=\"510\" width=\"320\" height=\"70\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"570\" y=\"540\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">ज़्यादा से ज़्यादा ≈ 60-70</text>\n  <text x=\"570\" y=\"568\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">शादी-त्योहार के हफ़्ते</text>\n  <rect x=\"110\" y=\"630\" width=\"580\" height=\"60\" rx=\"30\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"668\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\">पहली फ़सल इससे बहुत छोटी — डर उल्टा था</text>\n  <text x=\"400\" y=\"740\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">हर संख्या मान-लो है — असली संख्या आपके पन्नों से आएगी</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"माँग-गिनती\" पन्ना बनाइए। अपने असली पन्नों से तीनों धाराओं का जोड़ निकालिए — घर, दुकान, संस्था — हर धारा का सूत्र और जोड़ अलग पंक्ति में। फिर नीचे तीन संख्याएँ लिखिए — कम से कम, बीच की, ज़्यादा से ज़्यादा — और हरेक के आगे एक पंक्ति में वजह। आख़िर में आज की तारीख़ डालिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- तीनों धाराओं के सूत्र अंकों समेत दिखें, सिर्फ़ जवाब नहीं\n- तीनों संख्याओं की वजहें अलग-अलग लिखी हों\n\n### 5. सबूत\n\nमाँग-गिनती पन्ने की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरे इलाक़े की माँग-गिनती के ये आँकड़े हैं और मेरी पहली फ़सल छोटी है। बढ़ती आपूर्ति के हिसाब से मुझे किस क्रम में नए ग्राहक जोड़ने चाहिए?\"* — फिर तीनों संख्याएँ और अपने वर्ग-नक़्शे का हाल सुनाइए। मिले क्रम को अगले पाठों की सूची-बनवाई में परखिए।\n\n### 7. आम ग़लती\n\nलोग सबसे ज़्यादा वाली संख्या को ही सच मान बैठते हैं। **ज़्यादा वाली संख्या त्योहार की मेहमान है, रोज़ की नहीं।** उसी के भरोसे बड़ी बुआई करने वाला सूने हफ़्तों में माल लिए बैठा रहता है। योजना बीच वाली से बनती है, हिम्मत कम वाली से।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-25 के पन्ने भरे हों |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | जोड़-गिनती, तीन-संख्या पंक्तियाँ, तारीख़ |\n| क्या कभी नहीं | अंदाज़े की संख्या को किसी के सामने वादे की तरह बोलना |\n\n### 9. स्रोत\n\n- आपके अपने भरे पन्ने (पाठ 14, 23, 24, 25) — गिनती का असली स्रोत यही हैं\n- मंडी-आवक की सरकारी झलक ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n\n*पाठ की सब संख्याएँ मान-लो उदाहरण हैं। आपकी असली संख्याएँ आपके पन्नों से ही निकलेंगी — उन्हीं पर भरोसा कीजिए।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीनों धाराओं के सूत्र बिना देखे बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि संख्या तीन क्यों, एक क्यों नहीं\n- [ ] मैं फ़सल-माँग मिलान की तीनों सीखें गिना सकता हूँ\n- [ ] मैं जानता हूँ कि योजना किस संख्या से बनती है\n- [ ] मेरी माँग-गिनती पर तारीख़ पड़ी है\n\n**आगे का पाठ:** माँग के बाद दाम की बारी — मंडी, दुकान और ऐप की तीन खिड़कियों से भाव की जाँच।\n\n---\n---\n", "27": "# पाठ 27 — दाम की जाँच — मंडी, दुकान और ऐप\n\n**अध्याय:** अ-3 · **पाठ:** 8 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप भाव को तीन खिड़कियों से देखना सीख जाएँगे — मंडी, दुकान और फ़ोन का पर्दा। थोक और फुटकर की सीढ़ी समझेंगे। और अपनी पहली दाम-पट्टी बनाकर उस पर तारीख़ की मुहर लगाएँगे।\n\n### 2. मुख्य बात\n\n> भाव एक नहीं होता — सीढ़ी होता है। मंडी का भाव, दुकान का भाव और ऐप का भाव तीन अलग पायदान हैं। जो तीनों जानता है, वही अपने माल की सही जगह पहचानता है।\n\n---\n\n### भाव की सीढ़ी — पहले ढाँचा\n\nबाज़ार में एक ही दिन, एक ही मशरूम के कई भाव चलते हैं। यह गड़बड़ी नहीं, बनावट है। सीढ़ी ऐसे बनती है।\n\nसबसे नीचे थोक का पायदान — मंडी में या सीधे उत्पादक से बड़ी तौल में ख़रीद। यहाँ भाव सबसे दबा होता है, क्योंकि ख़रीदने वाला आगे बेचकर कमाएगा।\n\nबीच में दुकान का पायदान — दुकानदार थोक से लेकर अपनी मेहनत, दुकान का ख़र्च और सड़ने का जोखिम जोड़कर फुटकर भाव बनाता है।\n\nसबसे ऊपर ऐप और पैकेट का पायदान — शहर की online-किराना सेवाएँ धुला-छँटा माल डिब्बे में सजाकर घर पहुँचाती हैं। सफ़ाई, पैकिंग और पहुँचाने का ख़र्च भाव में चढ़ता है।\n\nआपके लिए इस सीढ़ी का मतलब? आप उत्पादक हैं — आपकी बिक्री ज़्यादातर नीचे-बीच के पायदानों पर होगी। पर ऊपर का पायदान देखना ज़रूरी है, क्योंकि वही बताता है कि आपके माल की आख़िरी थाली तक की क़ीमत क्या है — और बीच में कितनी जगह है।\n\n### तीन खिड़कियाँ — कहाँ-कहाँ झाँकना\n\nअब तीनों खिड़कियों का इस्तेमाल सीखिए।\n\nपहली खिड़की — मंडी। अपने इलाक़े की सब्ज़ी-मंडी में मशरूम की आवक और थोक-भाव पूछिए। साथ में सरकारी झलक भी देखिए — agmarknet पर मंडी-भाव चढ़ते हैं। ध्यान रखिए, हर मंडी का आँकड़ा रोज़ नहीं चढ़ता और मशरूम हर मंडी में दर्ज नहीं होता। सरकारी पन्ना ख़ाली मिले, तो अपनी आँख-पूछ ही असली खिड़की है।\n\nदूसरी खिड़की — दुकान। यह आपके पास पहले से है। बाज़ार-पत्रक और दुकान-पन्ने की दाम-पंक्तियाँ फुटकर भाव की गवाही हैं। आज उन्हें ताज़ा कीजिए — वज़न-समेत, क्योंकि पैकेट का खेल वज़न में छिपा होता है। दो सौ ग्राम के पैकेट का भाव किलो में बदलकर ही तुलना कीजिए।\n\nतीसरी खिड़की — फ़ोन का पर्दा। किसी online-किराना ऐप या site पर अपने या पास के शहर का pin डालकर मशरूम खोजिए। पैकेट का वज़न और दाम नोट कीजिए, किलो में बदलिए। यह खिड़की गाँव में बैठे-बैठे ऊपर के पायदान की झलक देती है।\n\n### पट्टी पढ़ने का हुनर\n\nतीनों खिड़कियों के अंक एक पट्टी पर उतारिए — यही दाम-पट्टी है। अब उसे पढ़िए।\n\nपहली पढ़त — फ़ासला। थोक और फुटकर के बीच की दूरी नापिए। यही दूरी दुकानदार की कमाई की जगह है — और आपकी बातचीत की ज़मीन भी। दूसरी पढ़त — अपनी जगह। घरेलू ग्राहक को सीधी बिक्री में आपका भाव अक्सर फुटकर के आसपास बैठ सकता है, दुकान को बिक्री में थोक के आसपास। तीसरी पढ़त — चढ़ाव-उतार। एक दिन की पट्टी तस्वीर की एक झलक है। मौसम, त्योहार और आवक से भाव साँस लेता है। इसलिए पट्टी पर तारीख़ अनिवार्य है — और हफ़्ते-पखवाड़े में दोहराई गई पट्टियाँ ही असली चाल दिखाती हैं।\n\nएक सावधानी अंक लिखते समय — सुना भाव और छपा भाव अलग-अलग दर्जे के गवाह हैं। हर अंक के आगे उसका ठिकाना लिखिए। बिना ठिकाने का अंक अफ़वाह है — यह नियम आप गिनती वाले पाठ से जानते हैं।\n\n### अपना भाव अभी तय नहीं होगा\n\nएक बात साफ़ कर दूँ, ताकि जल्दबाज़ी न हो। आज की पट्टी आपके अपने भाव का एलान नहीं है। अपना भाव तय करने का गणित अलग अध्याय में आएगा — वहाँ लागत, मेहनत और बाज़ार तीनों जुड़ेंगे। आज का काम सिर्फ़ ज़मीन नापना है।\n\nपर एक फल आज ही मिल गया है। अगली बार कोई दुकानदार या रसोइया भाव की बात छेड़े, तो आप ख़ाली हाथ नहीं होंगे। जेब में तारीख़ लगी पट्टी होगी। बाज़ार जानने वाले से बाज़ार अलग ढंग से बात करता है।\n\n### भाव का मौसम-चक्र\n\nपट्टी दोहराते-दोहराते आपको एक चाल दिखेगी — भाव भी मौसम पहनता है। इसका मोटा ढाँचा अभी से समझ लीजिए।\n\nसर्दी आपकी फ़सल की खिड़की है — पर वही खिड़की इलाक़े के बाक़ी उत्पादकों की भी है। आवक बढ़ती है, तो भाव नरम पड़ता है। यानी सबसे आसान उगाई के हफ़्ते अक्सर सबसे कसे भाव के हफ़्ते होते हैं। घबराइए मत — यही तो हर फ़सल का नियम है।\n\nउल्टी तरफ़, गर्मी में खुले माल की आवक सूखती है और बचा-खुचा माल भाव चढ़ाकर बिकता है — पर वह माल ठंडक-मशीन वालों का है, यानी ऊँचे भाव के पीछे ऊँचा ख़र्च बैठा है।\n\nयह चक्र आपके ख़िलाफ़ नहीं, आपके साथ भी खेलता है — जिसने चाल पहचान ली, वह तुड़ाई और बिक्री की घड़ी उसी हिसाब से बिठाता है।\n\nऔर बीच-बीच में मौक़े की लहरें — लगन और त्योहार के हफ़्तों में फुटकर माँग उछलती है।\n\nआपके लिए सीख दो पंक्तियों की है। पहली — अपनी फ़सल-खिड़की के भाव को पिछले मौसम की पट्टियों से पहचानिए, ऐप के आज के अंक से नहीं। दूसरी — भाव नरम होने का इलाज घबराई बिक्री नहीं, बँधे ग्राहक हैं। जिसकी सूची तैयार है, उसे मंडी की भीड़ से भाव नहीं पूछना पड़ता।\n\n### चित्र — भाव की सीढ़ी और तीन खिड़कियाँ\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">एक मशरूम — भाव की तीन सीढ़ियाँ</text>\n  <rect x=\"90\" y=\"520\" width=\"620\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"558\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">थोक — मंडी / सीधे उत्पादक से</text>\n  <text x=\"400\" y=\"590\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">सबसे दबा भाव · बड़ी तौल</text>\n  <rect x=\"150\" y=\"390\" width=\"500\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"428\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">फुटकर — सब्ज़ी दुकान</text>\n  <text x=\"400\" y=\"460\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">मेहनत + ख़र्च + जोखिम जुड़ा</text>\n  <rect x=\"210\" y=\"260\" width=\"380\" height=\"90\" rx=\"12\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"298\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">ऐप / पैकेट</text>\n  <text x=\"400\" y=\"330\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">सफ़ाई + पैकिंग + पहुँचाना जुड़ा</text>\n  <line x1=\"400\" y1=\"350\" x2=\"400\" y2=\"390\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <line x1=\"400\" y1=\"480\" x2=\"400\" y2=\"520\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <rect x=\"90\" y=\"120\" width=\"620\" height=\"90\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"158\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">तीन खिड़कियाँ: मंडी-पूछ · दुकान-पत्रक · फ़ोन का पर्दा</text>\n  <text x=\"400\" y=\"192\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">हर अंक: वज़न किलो में बदलो + ठिकाना + तारीख़</text>\n  <rect x=\"120\" y=\"650\" width=\"560\" height=\"60\" rx=\"30\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"688\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\">थोक-फुटकर का फ़ासला = बातचीत की ज़मीन</text>\n  <text x=\"400\" y=\"755\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">आज ज़मीन नापो — अपना भाव आगे के अध्याय में बनेगा</text>\n</svg>\n\n### 3. आज का काम «असली»\n\nनोटबुक में \"दाम-पट्टी\" पन्ना बनाइए — चार खंभे: खिड़की, अंक (किलो में), ठिकाना, तारीख़। फिर तीनों खिड़कियाँ सचमुच झाँकिए — मंडी या मंडी-जानकार से थोक-भाव पूछिए, अपनी दुकान-पंक्तियाँ ताज़ा कीजिए, और फ़ोन पर किसी ऐप का पैकेट-भाव किलो में बदलकर उतारिए। आख़िर में थोक-फुटकर का फ़ासला एक पंक्ति में लिखिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- तीनों खिड़कियों के अंक ठिकाने-समेत दर्ज हों\n- हर पैकेट-भाव किलो में बदला गया हो\n\n### 5. सबूत\n\nभरी दाम-पट्टी की साफ़ फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मशरूम के थोक और फुटकर भाव के बीच का फ़ासला किन-किन चीज़ों से बनता है? सूची दो।\"* — सूची को अपनी पट्टी के फ़ासले से मिलाइए। समझ आएगा कि दुकानदार की माँग बेईमानी नहीं, ख़र्चों का जोड़ है।\n\n### 7. आम ग़लती\n\nलोग ऐप का ऊँचा भाव देखकर सपने बुन लेते हैं — मैं भी इसी भाव बेचूँगा। **ऊपर के पायदान का भाव ऊपर के ख़र्चे माँगता है।** सफ़ाई, पैकिंग, पहुँचाना, वापसी का जोखिम — सब उसमें बैठा है। अपनी जगह अपने पायदान से पहचानिए, पड़ोसी के पायदान से नहीं।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-26 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, फ़ोन |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | भाव-पूछ, ऐप-झलक, पट्टी भरना |\n| क्या कभी नहीं | एक दिन की पट्टी को पूरे मौसम का सच मान लेना |\n\n### 9. स्रोत\n\n- मंडी-भाव की सरकारी खिड़की ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n- आपकी अपनी तीन-खिड़की पूछताछ — पट्टी का असली माल वही है\n\n*सरकारी पन्ने पर हर मंडी और हर दिन का मशरूम-भाव नहीं मिलता। ख़ाली खिड़की भी एक जानकारी है — उसे भी दर्ज कीजिए।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं भाव की तीनों सीढ़ियाँ और उनके बनने की वजह बोल सकता हूँ\n- [ ] मैं पैकेट-भाव को किलो में बदलना जानता हूँ\n- [ ] मैं बता सकता हूँ कि थोक-फुटकर फ़ासला किसकी कमाई है\n- [ ] मैं जानता हूँ कि अपना भाव आज क्यों तय नहीं हुआ\n- [ ] मेरी दाम-पट्टी पर तीनों खिड़कियाँ, ठिकाने और तारीख़ दर्ज हैं\n\n**आगे का पाठ:** सारे पन्ने अब एक सूची में सिमटेंगे — आपके अपने दस ग्राहकों की सूची।\n\n---\n---\n", "28": "# पाठ 28 — दस ग्राहकों की अपनी सूची बनाना\n\n**अध्याय:** अ-3 · **पाठ:** 9 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह पाठ इस अध्याय की फ़सल काटने का पाठ है। इसके बाद आपके पास एक तालिका होगी — दस असली नामों की, पाँच खंभों वाली, तारों से सजी। यही तालिका आगे आपके पहले संदेश, पहले वादे और पहली बिक्री की ज़मीन बनेगी।\n\n### 2. मुख्य बात\n\n> धंधे की असली पूँजी खेत में नहीं, नामों में होती है। दस जाने-परखे नाम सौ अनजान चेहरों से भारी हैं — क्योंकि नाम से बात होती है, भीड़ से नहीं।\n\n---\n\n### बिखरे मोती, एक धागा\n\nपिछले आठ पाठों में आपने मोती जमा किए हैं। वर्ग-नक़्शे में छह-सात नाम। आदत-पन्ने में बैठकी वाला घर। दुकान-पन्ने में चार जवाबों वाला दुकानदार। संस्था-पन्ने में रसोइया। और कहीं-कहीं ना कहने वालों के बताए नए नाम भी।\n\nआज इन मोतियों में धागा पिरोना है। धागे का नाम है — दस-ग्राहक सूची। दस ही क्यों? क्योंकि दस नाम एक आदमी की पकड़ में रहते हैं। हर नाम से रिश्ता निभ सकता है। सौ नामों की सूची दिखने में बड़ी, निभाने में शून्य होती है। पहली फ़सल छोटी है — दस दरवाज़े उसके लिए बहुत हैं।\n\n### पाँच खंभों की तालिका\n\nनोटबुक के दो आमने-सामने पन्ने खोलिए। तालिका बनाइए — दस पंक्तियाँ, पाँच खंभे।\n\nपहला खंभा — नाम और वर्ग। आदमी या ठिकाने का नाम, साथ में वर्ग का अक्षर — घ, दु, सं।\n\nदूसरा खंभा — जगह और पहुँच। मोहल्ला या बाज़ार, और वहाँ तक आने-जाने का सहज रास्ता।\n\nतीसरा खंभा — बात की स्थिति। तीन ही शब्द चलेंगे — हो चुकी, अधूरी, बाक़ी। हो चुकी यानी आपने भेंट करके पन्ना भरा है। अधूरी यानी पहचान है पर धंधे की बात नहीं हुई। बाक़ी यानी नाम मिला है, चेहरा नहीं।\n\nचौथा खंभा — अगला क़दम। हर नाम के आगे एक ठोस काम, तारीख़-सोच के साथ। जैसे — इस इतवार बैठकी, या पहली फ़सल पर नमूना।\n\nपाँचवाँ खंभा — तारा। जिस नाम से पहली बिक्री की उम्मीद सबसे पक्की है, उस पर तारा लगाइए। तारे तीन-चार से ज़्यादा मत बाँटिए — हर जगह तारा यानी कहीं तारा नहीं।\n\n### मिश्रण का नुस्ख़ा\n\nदस नाम किस अनुपात में हों? पहली फ़सल के नाप से नुस्ख़ा निकलता है — मोटे तौर पर छह घरेलू, तीन दुकान, एक संस्था।\n\nछह घरेलू क्यों? क्योंकि पहली बिक्री की सबसे सहज ज़मीन वही है — हाथों-हाथ पैसा, ताज़गी की क़दर, और ज़बान का पहिया। तीन दुकान क्यों? क्योंकि दूसरी फ़सल-लहर से बँधी खपत वहीं मिलेगी। एक ही संस्था क्यों? क्योंकि उसकी बड़ी माँग अभी आपकी लक्ष्मण-रेखा के पार है — पर रिश्ता आज से पकना चाहिए, ताकि जब आपकी तौल बढ़े, दरवाज़ा जाना-पहचाना मिले।\n\nयह नुस्ख़ा लोहे का नहीं है। आपके इलाक़े का सच अलग हो, तो अनुपात बदलिए — पर बदलने की वजह एक पंक्ति में लिखिए। बिना वजह बदला नुस्ख़ा अंदाज़ नहीं, आलस होता है।\n\n### सूची ज़िंदा चीज़ है\n\nआख़िरी नियम सूची की देखभाल का। यह तालिका पत्थर पर खुदी लकीर नहीं — आँगन की क्यारी है। इसमें नाम उगेंगे भी, मुरझाएँगे भी।\n\nकोई नाम महीनों तक बाक़ी की स्थिति में पड़ा रहे और कोशिश पर भी बात न बने, तो उसे आदर से काटिए और नया नाम रोपिए। किसी बैठकी में नया उत्साही घर मिले, तो ग्यारहवाँ नाम मत बनाइए — सबसे कमज़ोर नाम की जगह उसे दीजिए। सूची दस की दस रहे, पर हर मौसम थोड़ी ताज़ा होती रहे।\n\nऔर हर बदलाव पर तारीख़ डालिए। महीनों बाद पुरानी कटी-जुड़ी सूची पढ़ेंगे, तो अपने धंधे की पूरी कहानी उसी में लिखी मिलेगी — कौन दरवाज़ा खुला, कौन बंद हुआ, और आपकी परख कितनी पकी।\n\n### तारा किस हिसाब से लगे\n\nतारा मन से नहीं, कसौटी से लगेगा। चार कसौटियाँ मिलाइए।\n\nपहली — बात की ज़मीन। जिससे भेंट हो चुकी और जिसने अपने मुँह से रुचि बोली, वही तारे का दावेदार है। बाक़ी वाली स्थिति में पड़े नाम पर तारा उधार की उम्मीद है।\n\nदूसरी — पहुँच। पहली फ़सल की डिलीवरी आप ख़ुद करेंगे — पैदल या अपनी सवारी से। जो नाम रोज़ के रास्ते पर पड़ता है, वह दूर वाले बराबर नाम से आगे है। ताज़गी घड़ी से बँधी है, और घड़ी रास्ते से।\n\nतीसरी — पैसे की आदत। हाथों-हाथ देने वाला नाम पहली लहर का साथी है — यह तीसरी तराज़ू आप तौल चुके हैं।\n\nचौथी — ज़बान का पहिया। जिस घर की बात मोहल्ले में चलती है, उसकी ख़ुशी दस दरवाज़े खोलेगी। बोलने वाली चाची चुप रहने वाले नाम से क़ीमती है।\n\nकसौटी काग़ज़ पर उतारकर ही परखिए — मन-ही-मन की तौल में पुरानी पसंद जीत जाती है।\n\nचारों कसौटियाँ हर नाम पर एक साथ खरी उतरें, यह ज़रूरी नहीं। तीन पर खरा नाम भी पक्का दावेदार है। असली मक़सद तुलना है — दो नामों में उलझन हो, तो दोनों को चारों कसौटियों पर आमने-सामने रखिए, जवाब ख़ुद दिख जाएगा। और जिस नाम पर एक भी कसौटी न बैठे, उस पर तारा लगाना अपनी पहली फ़सल को अँधेरे में भेजना है।\n\nऔर यह याद रहे — तारा इनाम नहीं, योजना है। तारा हटने का मतलब रिश्ता टूटना नहीं, बस पहली लहर की क़तार बदलना है। कसौटी बदलेगी, तारे घूमेंगे — सूची इसीलिए ज़िंदा कहलाती है।\n\n### चित्र — दस-ग्राहक सूची का खाका\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">दस-ग्राहक सूची — पाँच खंभे</text>\n  <rect x=\"60\" y=\"80\" width=\"680\" height=\"70\" rx=\"12\" fill=\"#0B1F3A\"/>\n  <text x=\"130\" y=\"123\" font-size=\"18\" fill=\"#F9A825\" text-anchor=\"middle\">नाम+वर्ग</text>\n  <text x=\"270\" y=\"123\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">जगह-पहुँच</text>\n  <text x=\"410\" y=\"123\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">बात-स्थिति</text>\n  <text x=\"550\" y=\"123\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">अगला क़दम</text>\n  <text x=\"680\" y=\"123\" font-size=\"18\" fill=\"#F9A825\" text-anchor=\"middle\">तारा</text>\n  <rect x=\"60\" y=\"160\" width=\"680\" height=\"64\" rx=\"8\" fill=\"#1565C0\"/>\n  <text x=\"130\" y=\"200\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">चाची (घ)</text>\n  <text x=\"270\" y=\"200\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">अपना मोहल्ला</text>\n  <text x=\"410\" y=\"200\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">हो चुकी</text>\n  <text x=\"550\" y=\"200\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">फ़सल पर नमूना</text>\n  <text x=\"680\" y=\"202\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">★</text>\n  <rect x=\"60\" y=\"232\" width=\"680\" height=\"64\" rx=\"8\" fill=\"#1565C0\"/>\n  <text x=\"130\" y=\"272\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">सब्ज़ी-दुकान (दु)</text>\n  <text x=\"270\" y=\"272\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">बड़ा बाज़ार</text>\n  <text x=\"410\" y=\"272\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">हो चुकी</text>\n  <text x=\"550\" y=\"272\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">नमूना दिखाना</text>\n  <text x=\"680\" y=\"274\" font-size=\"20\" fill=\"#F9A825\" text-anchor=\"middle\">★</text>\n  <rect x=\"60\" y=\"304\" width=\"680\" height=\"64\" rx=\"8\" fill=\"#1565C0\"/>\n  <text x=\"130\" y=\"344\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">ढाबा (सं)</text>\n  <text x=\"270\" y=\"344\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">सड़क चौक</text>\n  <text x=\"410\" y=\"344\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">अधूरी</text>\n  <text x=\"550\" y=\"344\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">दुबारा भेंट</text>\n  <text x=\"680\" y=\"344\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">—</text>\n  <rect x=\"60\" y=\"376\" width=\"680\" height=\"64\" rx=\"8\" fill=\"#1565C0\"/>\n  <text x=\"130\" y=\"416\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">मास्टर जी (घ)</text>\n  <text x=\"270\" y=\"416\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">स्कूल-टोला</text>\n  <text x=\"410\" y=\"416\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">बाक़ी</text>\n  <text x=\"550\" y=\"416\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">इतवार बैठकी</text>\n  <text x=\"680\" y=\"416\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">—</text>\n  <text x=\"400\" y=\"490\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">... ऐसी कुल दस पंक्तियाँ ...</text>\n  <rect x=\"70\" y=\"530\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"230\" y=\"568\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">मिश्रण-नुस्ख़ा</text>\n  <text x=\"230\" y=\"598\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">6 घर · 3 दुकान · 1 संस्था</text>\n  <rect x=\"410\" y=\"530\" width=\"320\" height=\"90\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"570\" y=\"568\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">तारे 3-4 से ज़्यादा नहीं</text>\n  <text x=\"570\" y=\"598\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">हर जगह तारा = कहीं नहीं</text>\n  <rect x=\"110\" y=\"660\" width=\"580\" height=\"60\" rx=\"30\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"698\" font-size=\"21\" fill=\"#F9A825\" text-anchor=\"middle\">सूची क्यारी है — मुरझाया नाम काटो, नया रोपो</text>\n  <text x=\"400\" y=\"760\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">हर बदलाव पर तारीख़ — यही आपके धंधे की कहानी है</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nअपने सारे पिछले पन्ने सामने फैलाइए। दो खुले पन्नों पर पाँच-खंभा तालिका बनाइए और दस नाम भरिए — मिश्रण-नुस्ख़े के आसपास, अपनी वजह के साथ। हर नाम पर बात-स्थिति और अगला क़दम लिखिए। तीन-चार तारे लगाइए। सबसे ऊपर आज की तारीख़ डालिए।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दसों पंक्तियों के पाँचों खंभे भरे हों, कोई खाना ख़ाली नहीं\n- तारे वाले हर नाम की बात-स्थिति हो चुकी या अधूरी हो, बाक़ी नहीं\n\n### 5. सबूत\n\nपूरी तालिका की साफ़ फ़ोटो, तारीख़ दिखती हुई।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरी दस-ग्राहक सूची यह है। पहली छोटी फ़सल के हिसाब से बताओ — तारे मैंने सही नामों पर लगाए हैं या कहीं बदलाव सोचूँ?\"* — फिर तालिका पढ़कर सुनाइए। AI की राय को अपने इलाक़े की जानकारी से तौलकर ही तारा घटाइए-बढ़ाइए।\n\n### 7. आम ग़लती\n\nलोग सूची में वे नाम भरते हैं, जो भरने में आसान हों — रिश्तेदार, पड़ोसी, दोस्त। **आसान नाम और सच्चा ग्राहक हमेशा एक नहीं होते।** कसौटी रिश्ता नहीं, ख़रीद की उम्मीद है। जिस नाम के आगे अगला क़दम न सूझे, वह नाम सूची का नहीं, दिल का है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-27 के पन्ने भरे हों |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | नाम छाँटना, तालिका भरना, तारे लगाना |\n| क्या कभी नहीं | सूची के नाम-पते किसी और को दिखाना या बाँटना |\n\n### 9. स्रोत\n\n- आपके अपने आठ पाठों के भरे पन्ने — सूची का पूरा माल वहीं से आया है\n- ग्राहक-जानकारी की सँभाल पर सरकारी दिशा की झलक ([meity.gov.in](https://www.meity.gov.in/)) · देखा गया 09-08-2026\n\n*लोगों के नाम-पते आपकी अमानत हैं। नोटबुक सँभालकर रखिए — भरोसा माल से पहले जानकारी की हिफ़ाज़त से बनता है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बता सकता हूँ कि सूची दस की ही क्यों है\n- [ ] मैं पाँचों खंभों के नाम और काम गिना सकता हूँ\n- [ ] मैं मिश्रण-नुस्ख़े की तीनों वजहें समझा सकता हूँ\n- [ ] मैं जानता हूँ कि नाम कब कटता और कब जुड़ता है\n- [ ] मेरी तालिका में दस नाम, तारे और तारीख़ — सब दर्ज हैं\n\n**आगे का पाठ:** सूची तैयार है — अब पहली चिट्ठी की बारी। पहला संदेश कैसे लिखा जाता है और पहला वादा कितना बोला जाता है।\n\n---\n---\n", "29": "# पाठ 29 — पहला संदेश और पहला वादा\n\n**अध्याय:** अ-3 · **पाठ:** 10 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आपके पास पहला संदेश तैयार रखा होगा — तीन हिस्सों वाला, बिना दबाव वाला, भेजने की सही घड़ी के इंतज़ार में। और आप वादे की तौल सीख जाएँगे — कब बोलना वादा है, कब बोलना जाल है।\n\n### 2. मुख्य बात\n\n> पहला संदेश बिक्री की अर्ज़ी नहीं, ख़ुशख़बरी की चिट्ठी है। और वादा तभी वादा है, जब उसमें तीनों बातें हों — तारीख़, तौल और दाम। तीनों में से एक भी अधूरी हो, तो वह वादा नहीं, भ्रम है।\n\n---\n\n### सही घड़ी — फ़सल की तारीख़ दिखने पर\n\nपहला सवाल — संदेश कब जाए? आज नहीं। अभी आपका पहला बैग बिछा नहीं है। बिना फ़सल के भेजा संदेश हवा का वादा है, और हवा के वादे इस कोर्स में निषिद्ध हैं।\n\nसही घड़ी वह है, जब फ़सल की तारीख़ मोटे तौर पर दिखने लगे। आगे पहले-चक्र वाले अध्याय में आप सीखेंगे कि बिछाई के बाद फ़सल की लहर का हफ़्ता लगभग पढ़ा जा सकता है। जब वह हफ़्ता दिखे, उससे कुछ दिन पहले संदेश निकले — इतना पहले कि ग्राहक अपनी रसोई की सोच बना ले, इतना देर से नहीं कि बात हवा में लटके।\n\nतो आज मसौदा क्यों बन रहा है? क्योंकि जल्दबाज़ी में लिखी चिट्ठी हमेशा कमज़ोर होती है। फ़सल के हफ़्ते में आप देखभाल में डूबे होंगे। आज फ़ुर्सत में तौला हुआ मसौदा उस दिन सिर्फ़ तारीख़ भरकर निकल जाएगा।\n\n### तीन हिस्सों की चिट्ठी\n\nअच्छा पहला संदेश तीन हिस्सों में चलता है। WhatsApp पर जाए या ज़बानी बोला जाए — ढाँचा यही रहेगा।\n\nपहला हिस्सा — याद और रिश्ता। आप कौन हैं और बात कहाँ से जुड़ी है। जैसे — नमस्ते चाची, मैं फ़लाँ का बेटा। उस दिन आपसे मशरूम की बात हुई थी।\n\nदूसरा हिस्सा — ख़ुशख़बरी और तारीख़। जैसे — मेरी पहली ताज़ी फ़सल फ़लाँ हफ़्ते आ रही है। सुबह की तोड़ी, बिल्कुल ताज़ी।\n\nतीसरा हिस्सा — छोटा, खुला न्योता। जैसे — आपके लिए थोड़ी रखूँ? पहली बार का स्वाद आप ही परखिए।\n\nग़ौर कीजिए, तीसरे हिस्से में दबाव शून्य है। न मात्रा थोपी, न हाँ माँगी। सिर्फ़ दरवाज़ा खोला। घरेलू वर्ग इसी नरमी पर खिलता है। दुकानदार और रसोइए वाले संदेश में तीसरा हिस्सा बदलेगा — वहाँ न्योते की जगह दिखाने का वादा निभेगा: जैसा कहा था, नमूना लेकर आ रहा हूँ — कौन-सा दिन ठीक रहेगा?\n\n### वादे की तराज़ू — तीन बातें या शून्य\n\nअब इस पाठ की सबसे क़ीमती सीख। संदेश के बाद बातचीत चलेगी, और बातचीत में वादे का पल आएगा। वहीं यह नियम काम आएगा।\n\nवादा तीन बातों से बनता है — तारीख़, तौल, दाम। इतवार सुबह, दो किलो, तय भाव पर — यह वादा है। इसे लिखकर निभाइए।\n\nपर जहाँ तीनों में से कोई एक भी पक्की न हो, वहाँ वादे की भाषा मत बोलिए। देखूँगा, हो जाएगा, अगले हफ़्ते शायद — ये तीनों वाक्य नए धंधे के दीमक हैं। सुनने वाला इन्हें वादा समझ लेता है, बोलने वाला इन्हें बात समझता है। फिर टूटे भरोसे का हिसाब बोलने वाले के नाम लिखा जाता है।\n\nइसलिए साफ़ बोलने की आदत डालिए। जो पक्का है — तीनों बातों समेत बोलिए। जो पक्का नहीं — साफ़ कहिए: अभी तारीख़ पक्की नहीं, पक्की होते ही सबसे पहले आपको बताऊँगा। यह वाक्य ना नहीं है। यह भरोसे की नींव है। पहली फ़सल के वादे छोटे रखिए — तारे वाले तीन-चार नाम ही काफ़ी हैं। बाक़ी सूची दूसरी लहर की मेहमान है।\n\n### भेजने से पहले की जाँच\n\nमसौदा बन जाए, तो भेजने से पहले तीन जाँचें कीजिए। पहली — पढ़कर सुनाइए ख़ुद को: क्या यह चिट्ठी पाकर आपको ख़ुशी होती या बोझ लगता? बोझ लगे, तो दबाव कहीं छिपा है — निकालिए। दूसरी — हर दावा तौलिए: जो लिखा है, क्या फ़सल के दिन सच निकलेगा? तीसरी — नाम-नाम अलग कीजिए: चाची वाला संदेश मास्टर जी को नहीं जाएगा। एक ही लिखावट सबको भेजना बाज़ारू लगता है। ढाँचा एक, चेहरा हर नाम का अपना।\n\n### ज़बानी संदेश और चुप्पी का सलीक़ा\n\nदो बातें और, जो मसौदे को मैदान से जोड़ती हैं।\n\nपहली — हर ग्राहक फ़ोन-संदेश वाला नहीं है। चाची तक चिट्ठी नहीं, चौखट जाएगी। तब भी ढाँचा वही तीन-हिस्सा रहेगा — याद, ख़ुशख़बरी, खुला न्योता — बस लिखा हुआ बोला जाएगा। इसीलिए मसौदे को दो बार ज़ोर से पढ़कर ज़बान पर चढ़ाइए। दुकान-भेंट के अभ्यास वाला नियम यहाँ भी वही है — रटी हुई बात अटकती नहीं।\n\nदूसरी — संदेश के बाद की चुप्पी। संदेश गया और जवाब नहीं आया, तो क्या करें? पीछा नहीं। दो-तीन दिन ठहरकर एक नरम याद भेजिए या मिलने पर हँसकर ज़िक्र कीजिए — बस इतना ही। उसके बाद विराम। बार-बार के संदेश न्योते को उगाही बना देते हैं, और उगाही से घर का ग्राहक सबसे पहले भागता है।\n\nऔर याद एक ही बार — दूसरी चुप्पी का जवाब सिर्फ़ धीरज है।\n\nनरम याद का रूप भी सीख लीजिए — नया संदेश वही पुरानी बात दोहराए नहीं। एक ताज़ा पंक्ति काफ़ी है, जैसे — कल की तुड़ाई की फ़ोटो भेज रहा हूँ, मन हो तो बताइएगा। नई चीज़ दिखाना याद है, पुरानी बात दोहराना उगाही।\n\nचुप्पी का यह धीरज घाटा नहीं है। जिसने आज जवाब नहीं दिया, वह अगली लहर में ख़ुद पूछता आ सकता है — बशर्ते आज का संदेश उसे मीठा लगा हो, चिपकू नहीं। दरवाज़ा खुला छोड़ना ही इस पूरी चिट्ठी-कला का असली सूत्र है।\n\n### चित्र — तीन हिस्से, तीन बातें\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">पहला संदेश — ढाँचा और तराज़ू</text>\n  <rect x=\"80\" y=\"90\" width=\"640\" height=\"100\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"130\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">हिस्सा-1: याद और रिश्ता</text>\n  <text x=\"400\" y=\"165\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">\"उस दिन आपसे मशरूम की बात हुई थी\"</text>\n  <rect x=\"80\" y=\"210\" width=\"640\" height=\"100\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"250\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">हिस्सा-2: ख़ुशख़बरी और तारीख़</text>\n  <text x=\"400\" y=\"285\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">\"पहली ताज़ी फ़सल इस हफ़्ते आ रही है\"</text>\n  <rect x=\"80\" y=\"330\" width=\"640\" height=\"100\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"370\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">हिस्सा-3: छोटा खुला न्योता — दबाव शून्य</text>\n  <text x=\"400\" y=\"405\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">\"आपके लिए थोड़ी रखूँ?\"</text>\n  <rect x=\"80\" y=\"470\" width=\"640\" height=\"130\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"510\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">वादे की तराज़ू — तीनों चाहिए</text>\n  <text x=\"400\" y=\"548\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">तारीख़ ✓ + तौल ✓ + दाम ✓ = वादा</text>\n  <text x=\"400\" y=\"582\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">\"देखूँगा, हो जाएगा\" = भ्रम — कभी नहीं</text>\n  <rect x=\"80\" y=\"630\" width=\"640\" height=\"70\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"660\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">भेजने की घड़ी: फ़सल की तारीख़ दिखने पर, कुछ दिन पहले</text>\n  <text x=\"400\" y=\"690\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">आज सिर्फ़ मसौदा — हवा का वादा निषिद्ध</text>\n  <text x=\"400\" y=\"750\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">ढाँचा एक — पर हर नाम का संदेश उसके अपने चेहरे से</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"पहला संदेश\" पन्ना बनाइए। तीन-हिस्सा ढाँचे पर दो मसौदे लिखिए — एक अपने तारे वाले घरेलू नाम के लिए, एक तारे वाली दुकान के लिए। दोनों में तारीख़ की जगह ख़ाली खाना छोड़िए। नीचे तीन-बात तराज़ू का नियम अपने शब्दों में एक वाक्य में लिखिए। भेजिए अभी कुछ नहीं।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दोनों मसौदों में तीनों हिस्से अलग पहचाने जा सकें\n- किसी मसौदे में मात्रा या हाँ का दबाव न हो\n\n### 5. सबूत\n\nदोनों मसौदों वाले पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"यह मेरा पहला ग्राहक-संदेश है। इसे पढ़कर बताओ — कहीं दबाव, बड़ा दावा या भ्रम वाली भाषा तो नहीं है? नरम सुधार सुझाओ।\"* — सुधारों में से वही अपनाइए, जो आपकी अपनी बोली जैसे लगें। चिट्ठी की आवाज़ आपकी रहनी चाहिए, मशीन की नहीं।\n\n### 7. आम ग़लती\n\nलोग पहले संदेश में पूरी दुकान खोल देते हैं — भाव, मात्रा, गुण-गान, सब एक साथ। **लंबी चिट्ठी पढ़ी नहीं जाती, टाली जाती है।** पहला संदेश छोटा है, काम एक है — दरवाज़ा खोलना। बाक़ी बातें दरवाज़े के भीतर होंगी।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 28 की सूची तैयार हो |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | मसौदा लिखना, तौलना, सुधारना |\n| क्या कभी नहीं | बिना फ़सल-तारीख़ दिखे संदेश भेज देना |\n\n### 9. स्रोत\n\n- आपकी दस-ग्राहक सूची और भेंट-पन्ने — संदेश का माल वहीं से है\n- सुरक्षित digital-व्यवहार की सरकारी झलक ([cybercrime.gov.in](https://cybercrime.gov.in/)) · देखा गया 09-08-2026\n\n*फ़ोन-संदेश भी आपके नाम का दस्तावेज़ है। जो लिखें, वही निभाएँ — लिखा हुआ बोले हुए से लंबा जीता है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं संदेश भेजने की सही घड़ी बता सकता हूँ\n- [ ] मैं तीनों हिस्सों का ढाँचा बिना देखे बोल सकता हूँ\n- [ ] मैं वादे की तीन-बात तराज़ू समझा सकता हूँ\n- [ ] मैं भ्रम वाले तीन वाक्य पहचान सकता हूँ\n- [ ] मेरे दोनों मसौदे तैयार रखे हैं — बिना भेजे\n\n**आगे का पाठ:** अध्याय की आख़िरी परीक्षा — पाँच दुकानों की असली दौड़ और माँग-पत्रक की भराई।\n\n---\n---\n", "30": "# पाठ 30 — आज का काम — पाँच दुकानों से बात करके माँग-पत्रक भरो\n\n**अध्याय:** अ-3 · **पाठ:** 11 में से 11\n**सुरक्षा:** 🟢 सामान्य · **काम:** «असली» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह अध्याय का समापन-पाठ है — और इसकी पूरी जान मैदान में है। इसके बाद आपके पास पाँच दुकानों का भरा माँग-पत्रक होगा, ताज़ा हुई दस-ग्राहक सूची होगी, और इस पूरे अध्याय की कमाई एक जगह सिमटी होगी।\n\n### 2. मुख्य बात\n\n> पढ़ा हुआ अध्याय ज्ञान है। किया हुआ अध्याय पूँजी है। आज के पाँच पत्रक इस अध्याय को ज्ञान से पूँजी बनाएँगे।\n\n---\n\n### आज की दौड़ का नक़्शा\n\nआज का काम साफ़ है — पाँच सब्ज़ी-दुकानों से बात, हर दुकान का एक माँग-पत्रक। पाँच में एक वह दुकान भी हो सकती है, जहाँ पाठ चौबीस की पहली भेंट हुई थी — वहाँ आज की बात दूसरी भेंट बनेगी, यानी रिश्ते की अगली कड़ी। बाक़ी चार नई दुकानें चुनिए — बाज़ार-पत्रक से, या ना-सलीक़े में मिले बताए नामों से।\n\nपाँच ही क्यों? क्योंकि पाँच बातचीतें एक-दो दिन में सचमुच हो जाती हैं — और पाँच पत्रक मिलकर वह चीज़ देते हैं, जो एक पत्रक कभी नहीं देता: तुलना। एक दुकानदार की बात राय होती है। पाँच की मिलती-जुलती बात इलाक़े का सच होती है।\n\n### माँग-पत्रक — पाँच खानों का खाका\n\nहर दुकान के लिए नोटबुक में एक जैसा पत्रक बनाइए — ऊपर दुकान का नाम, जगह और तारीख़, नीचे पाँच खाने।\n\nखाना-1 — अभी का स्रोत। मशरूम रखते हैं तो कहाँ से आता है? नहीं रखते तो क्यों नहीं?\n\nखाना-2 — हफ़्ते की खपत। कितना बिक जाता है, या कितना बिक सकता है? दुकानदार का अपना अंदाज़ा, उसी की ज़बान में।\n\nखाना-3 — शिकायत। मौजूदा इंतज़ाम में क्या खलता है? यह खाना सोने का है — पाँच दुकानों की मिलती-जुलती शिकायत आपके धंधे का दरवाज़ा है।\n\nखाना-4 — परख और पसंद। नया माल किस कसौटी पर लेते हैं? किस रूप में — खुला, थैली, किस नाप की टोपी?\n\nखाना-5 — सीधा सवाल। स्थानीय ताज़ा माल भरोसे से मिले, तो लेंगे? जवाब जैसा मिले वैसा लिखिए — हाँ, ना, या शर्त के साथ हाँ। शर्त मिले तो शर्त शब्दों-समेत उतारिए — वही आपकी असली सीख है।\n\nबात का सलीक़ा वही पुराना — सुस्त घड़ी, सीखने वाला परिचय, मोल-भाव शून्य, धन्यवाद, और लक्ष्मण-रेखा याद: कोई पक्का सौदा आज नहीं, सिर्फ़ दिखाने का वादा।\n\n### पत्रकों से सूची तक\n\nशाम को पाँचों पत्रक बिछाकर तीन काम कीजिए।\n\nपहला — मिलान। पाँचों की खपत जोड़कर अपनी माँग-गिनती की दुकान-धारा से मिलाइए। असली अंक पुराने अंदाज़े से ऊपर-नीचे होंगे — स्लेट ताज़ा कीजिए, तारीख़ बदलिए।\n\nदूसरा — शिकायत-सूची। पाँचों पत्रकों की शिकायतें एक जगह लिखिए। जो शिकायत दो-तीन जगह दोहराई, उस पर घेरा लगाइए — आपके इलाक़े का सबसे खुला दरवाज़ा वही है।\n\nतीसरा — सूची की छँटाई। आज की बातों से दस-ग्राहक सूची ताज़ा कीजिए। जिस दुकान ने शर्त वाली हाँ बोली, वह तारे की दावेदार बन गई। जो नाम ठंडा निकला, उसकी जगह आज मिला गरम नाम रोपिए। बदलाव की तारीख़ डालना मत भूलिए।\n\n### अध्याय की कमाई — एक नज़र\n\nरुककर देखिए, ग्यारह पाठों में क्या-क्या जुड़ा। ग्राहक-पहले की सोच। चार वर्गों का नक़्शा। तीन तराज़ुओं की परख। घरेलू आदत-पन्ना। दुकान और संस्था की भेंटें। माँग की तीन-संख्या गिनती। दाम-पट्टी। दस-ग्राहक सूची। पहले संदेश के मसौदे। और आज के पाँच माँग-पत्रक।\n\nयह सब उस आदमी की तिजोरी है, जिसका पहला बैग अभी बिछा भी नहीं। अगला अध्याय — रास्ते, पूर्व-शर्त और साँचा — अब यही तिजोरी लेकर कोर्स के बड़े नक़्शे में उतरेगा: कौन-से रास्ते खुले हैं और किस क्रम में चलना है।\n\n### दौड़ पूरी करने की तरकीबें\n\nपाँच भेंटों का काम काग़ज़ पर छोटा और पाँव में भारी लगता है। तीन तरकीबें बोझ हल्का कर देंगी।\n\nपहली — दिन नहीं, घड़ियाँ बाँटिए। पाँचों दुकानें एक दुपहरी में निपटाने की ज़िद मत कीजिए। आज दो, कल तीन — हर भेंट सुस्त घड़ी में, बिना हड़बड़ी। हड़बड़ाई भेंट के पत्रक में खाने ख़ाली रह जाते हैं।\n\nदूसरी — पहली दुकान सबसे जानी-पहचानी रखिए। दौड़ की असली दीवार पहला दरवाज़ा है। जान-पहचान की दुकान से खुली दौड़ में हौसला चढ़ता है, और अगली चार भेंटें अपने-आप सरल हो जाती हैं।\n\nतीसरी — हर भेंट के बाद दो मिनट वहीं रुककर पत्रक भरिए। घर लौटकर सब याद से भरने वाला आधा माल गिरा देता है — ख़ासकर शिकायत के वे शब्द, जो सोने के हैं। ताज़ा बात ताज़ा स्याही माँगती है।\n\nहर शाम की समेटाई में एक पंक्ति अपने हौसले की भी लिखिए — आज कौन-सी बात पिछली भेंट से बेहतर हुई। दौड़ सिर्फ़ पत्रक नहीं भरती, बोलने वाला भी गढ़ती है।\n\nऔर एक बात हौसले की। पाँच में से दो दुकानें रूखी भी मिल सकती हैं। पत्रक फिर भी भरिए — रूखा जवाब भी जवाब है, और ना-सलीक़े वाला सोने का सवाल वहाँ भी चलेगा। दौड़ का नाप पाँच पत्रक है, पाँच मीठी बातें नहीं।\n\n### चित्र — माँग-पत्रक का खाका\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">माँग-पत्रक — एक दुकान का खाका</text>\n  <rect x=\"80\" y=\"80\" width=\"640\" height=\"620\" rx=\"14\" fill=\"#F5F7FA\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <rect x=\"80\" y=\"80\" width=\"640\" height=\"64\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"122\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\">दुकान का नाम · जगह · तारीख़</text>\n  <text x=\"110\" y=\"185\" font-size=\"20\" fill=\"#0B1F3A\">1. अभी का स्रोत — कहाँ से आता है / क्यों नहीं रखते</text>\n  <line x1=\"110\" y1=\"205\" x2=\"690\" y2=\"205\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"110\" y=\"255\" font-size=\"20\" fill=\"#0B1F3A\">2. हफ़्ते की खपत — उसी का अंदाज़ा, उसी की ज़बान</text>\n  <line x1=\"110\" y1=\"275\" x2=\"690\" y2=\"275\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"110\" y=\"325\" font-size=\"20\" fill=\"#0B1F3A\">3. शिकायत — मौजूदा इंतज़ाम में क्या खलता है ★</text>\n  <line x1=\"110\" y1=\"345\" x2=\"690\" y2=\"345\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"110\" y=\"395\" font-size=\"20\" fill=\"#0B1F3A\">4. परख और पसंद — कसौटी, रूप, नाप</text>\n  <line x1=\"110\" y1=\"415\" x2=\"690\" y2=\"415\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <text x=\"110\" y=\"465\" font-size=\"20\" fill=\"#0B1F3A\">5. सीधा सवाल — स्थानीय ताज़ा माल लेंगे?</text>\n  <text x=\"110\" y=\"500\" font-size=\"19\" fill=\"#2E7D32\">जवाब: हाँ / ना / शर्त के साथ हाँ — शर्त शब्दों-समेत</text>\n  <line x1=\"110\" y1=\"520\" x2=\"690\" y2=\"520\" stroke=\"#1565C0\" stroke-width=\"3\"/>\n  <rect x=\"110\" y=\"550\" width=\"580\" height=\"60\" rx=\"12\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"588\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">ऐसे पाँच पत्रक = तुलना = इलाक़े का सच</text>\n  <rect x=\"110\" y=\"625\" width=\"580\" height=\"55\" rx=\"12\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"660\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">दोहराई गई शिकायत पर घेरा — वही खुला दरवाज़ा</text>\n  <text x=\"400\" y=\"740\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">शाम को: माँग-स्लेट ताज़ा + दस-ग्राहक सूची की छँटाई</text>\n</svg>\n\n### 3. आज का काम «असली»\n\nनोटबुक में पाँच माँग-पत्रक बनाइए। फिर एक-दो दिन की दौड़ में पाँच सब्ज़ी-दुकानों से बात कीजिए — एक पुरानी जान-पहचान की, चार नई। हर दुकान के पाँचों खाने भरिए, शर्तें और शिकायतें शब्दों-समेत। शाम को तीनों समेटू काम कीजिए — माँग-स्लेट ताज़ा, शिकायत-सूची पर घेरा, दस-ग्राहक सूची की छँटाई तारीख़ के साथ।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- पाँचों पत्रकों के पच्चीसों खाने भरे हों, हर पत्रक पर तारीख़ हो\n- शिकायत-सूची में कम से कम एक घेरे वाली दोहराई शिकायत निकली हो\n\n### 5. सबूत\n\nपाँचों पत्रकों की फ़ोटो और ताज़ा की गई दस-ग्राहक सूची की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"पाँच दुकानों के मेरे माँग-पत्रकों का सार यह है — खपत, शिकायतें और शर्तें। इस सबसे मेरे इलाक़े के बारे में सबसे बड़ी तीन सीख क्या निकलती हैं?\"* — AI की तीन सीखों को अपनी घेरे वाली शिकायत से मिलाइए। मेल खाए, तो समझ पक्की; न खाए, तो पत्रक दोबारा पढ़िए — जवाब वहीं है।\n\n### 7. आम ग़लती\n\nलोग पाँच की जगह दो दुकानों पर रुक जाते हैं — बाक़ी फिर कभी। **अधूरी तुलना पूरी तुलना से ख़तरनाक है।** दो दुकानों की मिलती बात को लोग इलाक़े का सच मान लेते हैं, जबकि वह संयोग भी हो सकता है। पाँच का नाप इसीलिए है — दौड़ पूरी कीजिए।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 20-29 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम, आने-जाने का इंतज़ाम |\n| देखरेख | नाबालिग हों तो घर के बड़े को बताकर निकलें |\n| क्या कर सकते हैं | पाँच भेंटें, पत्रक-भराई, शाम की समेटाई |\n| क्या कभी नहीं | पत्रक भरवाने के जोश में कोई पक्का सौदा या भाव बोल आना |\n\n### 9. स्रोत\n\n- आपके पाँच माँग-पत्रक — इस पाठ का पूरा माल यही हैं\n- मंडी-भाव की सरकारी खिड़की — भेंट-पूर्व तैयारी ([agmarknet.gov.in](https://agmarknet.gov.in/)) · देखा गया 09-08-2026\n\n*पाँच दुकानों का सच भी पूरा इलाक़ा नहीं है — पर शुरुआत की तुलना के लिए भरा-पूरा है। घेरा बढ़ेगा, सच गहराएगा।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं बता सकता हूँ कि पत्रक पाँच दुकानों से ही क्यों भरवाए जाते हैं\n- [ ] मैं पाँचों खानों के नाम बिना देखे गिना सकता हूँ\n- [ ] मैं समझा सकता हूँ कि दोहराई शिकायत सोने की क्यों है\n- [ ] मैंने शाम के तीनों समेटू काम पूरे किए हैं\n- [ ] मैं अध्याय की कमाई की सूची अपने शब्दों में बोल सकता हूँ\n\n**आगे का पाठ:** अध्याय अ-3 पूरा — बधाई। अगला अध्याय कोर्स का बड़ा नक़्शा खोलेगा — रास्ते, पूर्व-शर्त और साँचा।\n\n---\n---\n", "31": "# पाठ 31 — यह कोर्स किसके लिए है — चार वर्ग\n\n**अध्याय:** अ-4 · **पाठ:** 1 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «देखो» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह अध्याय कोर्स का नक़्शा-घर है। बाहर निकलने से पहले नक़्शा पढ़ने वाला रास्ता कम भटकता है। इस पहले पाठ के बाद आप जान जाएँगे कि यह कोर्स किन चार वर्गों के लिए बुना गया है — और उनमें अपनी कुर्सी पहचान लेंगे।\n\n### 2. मुख्य बात\n\n> छह सौ सत्ताईस पाठ किसी एक आदमी के लिए नहीं हैं। यह चार अलग-अलग वर्गों का साझा घर है — और हर वर्ग को पूरा घर नहीं, अपना हिस्सा पढ़ना है।\n\n---\n\n### पहले उलझन साफ़ — यह ख़रीदार वाले वर्ग नहीं हैं\n\nएक भ्रम पहले ही झाड़ लीजिए। पिछले अध्याय में आपने ग्राहक के चार वर्ग पढ़े — घर, दुकान, संस्था, प्रसंस्करण। वे ख़रीदने वालों के खाने थे।\n\nआज के चार वर्ग सीखने वालों के खाने हैं — यानी इस कोर्स को पढ़ने बैठे लोगों के। दोनों की गिनती चार-चार होना संयोग है, रिश्ता नहीं। वहाँ सवाल था — मेरा माल कौन लेगा? यहाँ सवाल है — इस किताब को खोलने वाला कौन है, और उसे इसमें से क्या चाहिए?\n\n### वर्ग-1 — उगाने वाला\n\nपहला और सबसे बड़ा वर्ग — शुरुआती उत्पादक और किसान। जिसे अपने आँगन या कोठरी में बटन उगाकर बेचना है। पिछले तीन अध्याय आपने इसी कुर्सी पर बैठकर पढ़े हैं — तैयारी-पत्र, ग्राहक-सूची, माँग-पत्रक सब इसी वर्ग के औज़ार थे।\n\nइस वर्ग की रीढ़ है — पाँच बैग का पहला चक्र, फिर सीढ़ी-दर-सीढ़ी चढ़ाई। कोर्स का सबसे लंबा और सबसे सजा रास्ता इसी के लिए बिछा है — उत्पादन, देखभाल, तुड़ाई, बिक्री।\n\n### वर्ग-2 — घर से उठती उद्यमी\n\nदूसरा वर्ग — युवा उद्यमी और घर से काम करने वाली महिलाएँ। इस वर्ग की ताक़त वही है, जो तीसरी टाँग वाले पाठ में दिखी थी — आँगन के पास रहने वाला ही रोज़ की नज़र रख पाता है। मशरूम की देखभाल घर के काम-चक्र में बैठ जाती है।\n\nइस वर्ग के लिए कोर्स में दो चीज़ें ख़ास हैं। पहली — हर काम की सीढ़ी छोटे से शुरू होती है, ताकि घर की ज़िम्मेदारियों के साथ चल सके। दूसरी — आगे के खंडों में डिजिटल बिक्री और घर-बैठे धंधे के पूरे अध्याय हैं। और सरकारी योजनाओं की महिला-प्राथमिकता वाली बात आप तीन-पूँजी पाठ से जानते ही हैं।\n\n### वर्ग-3 — जुड़कर चलने वाले समूह\n\nतीसरा वर्ग — छोटे उत्पादन-समूह और स्वयं-सहायता समूह। छोटी तिपाई वाले पाठ की याद कीजिए — अकेले की जेब छोटी हो, तो समूह की जेब बड़ी होती है। यह वर्ग उसी रास्ते का है।\n\nसमूह के लिए कोर्स का पढ़ने का ढंग थोड़ा अलग है। पाठ सब वही हैं, पर काम बँट जाते हैं — कोई उत्पादन की सीढ़ी चढ़ता है, कोई बिक्री की, कोई हिसाब की। आगे हब वाला पूरा खंड — जैसे बीस घरों का जुड़ा हुआ ढाँचा — इसी वर्ग की मंज़िल है।\n\n### वर्ग-4 — सेवा और धंधे वाले\n\nचौथा वर्ग सबसे कम पहचाना जाता है, पर धंधे की दुनिया में सबसे चतुर गिना जाता है — वे लोग, जो मशरूम उगाना नहीं, मशरूम-उगाने वालों की सेवा करना चाहते हैं।\n\nकम्पोस्ट बनाकर बेचने वाला। Spawn (मशरूम बीज) की लैब चलाने वाला। सुखाने-पैक करने वाला। बेचने और online-दुकान चलाने वाला। याद कीजिए — कम्पोस्ट वाले पाठ में लिखा था: कल आप ख़रीदार हैं, परसों विक्रेता भी बन सकते हैं। यह वर्ग सीधे परसों से शुरू करता है। कोर्स में बेड, बीज, प्रसंस्करण और विपणन के अलग-अलग पूरे खंड इसी वर्ग के घर हैं।\n\n### एक आदमी, कई कुर्सियाँ\n\nआख़िरी बात — ये खाने दीवारें नहीं हैं। एक ही आदमी वक़्त के साथ कुर्सी बदलता है। आज की उगाने वाली कल समूह की अगुआ बन सकती है। आज का उत्पादक परसों कम्पोस्ट बेच सकता है। ग्राहक-नक़्शे में आपने पढ़ा था — चेहरे खानों से बड़े होते हैं। सीखने वालों पर भी यही सच है।\n\nइसलिए आज का काम अपनी आज की कुर्सी पहचानना है — जन्म-भर की नहीं। अगला पाठ बताएगा कि हर कुर्सी से कौन-सा रास्ता खुलता है।\n\n### और यह कोर्स किनके लिए नहीं है\n\nईमानदारी का एक खाना यह भी। तीन तरह के लोगों को यह कोर्स निराश करेगा — पहले ही बता देना भला है।\n\nपहला — रातों-रात कमाई खोजने वाला। यहाँ हर पाठ में मेहनत, गिनती और धीरज है; जादू का कोई अध्याय नहीं। दूसरा — सिर्फ़ काग़ज़ चाहने वाला। जो काम किए बिना आगे बढ़ना चाहे, उसके लिए हर पाठ का सबूत-खाना दीवार बनेगा — और यही इस कोर्स की इज़्ज़त है। तीसरा — आज ही फ़सल चाहने वाला बेमौसम पाठक। बटन की खिड़की का इंतज़ार जिसे मंज़ूर नहीं, वह पहले मौसम-पाठ से सुलह करे, फिर लौटे।\n\nग़ौर कीजिए — तीनों \"नहीं\" किसी आदमी को छाँटते नहीं, आदत को छाँटते हैं। रातों-रात वाली सोच बदल जाए, तो वही आदमी कल का सबसे पक्का पाठक है। दरवाज़ा किसी पर बंद नहीं — बस भीतर आने की चाल यही तीन बातें माँगती हैं: मेहनत का मन, काम का सबूत, मौसम का धीरज।\n\nअगर आप इन तीनों में नहीं हैं, तो यह घर आपका है — किसी भी वर्ग की कुर्सी से।\n\n### चित्र — चार वर्ग, एक कोर्स\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"55\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">यह कोर्स किसके लिए — सीखने वालों के चार वर्ग</text>\n  <rect x=\"270\" y=\"330\" width=\"260\" height=\"120\" rx=\"16\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <text x=\"400\" y=\"380\" font-size=\"24\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">एक कोर्स</text>\n  <text x=\"400\" y=\"415\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">627 पाठ · अपना हिस्सा चुनो</text>\n  <rect x=\"60\" y=\"110\" width=\"310\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"215\" y=\"150\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">1. उगाने वाला</text>\n  <text x=\"215\" y=\"185\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">किसान · शुरुआती उत्पादक</text>\n  <text x=\"215\" y=\"215\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">पाँच बैग से सीढ़ी-चढ़ाई</text>\n  <rect x=\"430\" y=\"110\" width=\"310\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"585\" y=\"150\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">2. घर की उद्यमी</text>\n  <text x=\"585\" y=\"185\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">महिलाएँ · युवा उद्यमी</text>\n  <text x=\"585\" y=\"215\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">घर के चक्र में बैठा काम</text>\n  <rect x=\"60\" y=\"530\" width=\"310\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"215\" y=\"570\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">3. समूह</text>\n  <text x=\"215\" y=\"605\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">स्वयं-सहायता · उत्पादन-समूह</text>\n  <text x=\"215\" y=\"635\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">काम बँटे — मंज़िल हब</text>\n  <rect x=\"430\" y=\"530\" width=\"310\" height=\"140\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"585\" y=\"570\" font-size=\"22\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">4. सेवा-धंधे वाले</text>\n  <text x=\"585\" y=\"605\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">कम्पोस्ट · बीज · प्रसंस्करण · बिक्री</text>\n  <text x=\"585\" y=\"635\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">उगाने वालों की सेवा = धंधा</text>\n  <line x1=\"215\" y1=\"250\" x2=\"330\" y2=\"345\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"585\" y1=\"250\" x2=\"470\" y2=\"345\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"215\" y1=\"530\" x2=\"330\" y2=\"440\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <line x1=\"585\" y1=\"530\" x2=\"470\" y2=\"440\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"740\" font-size=\"20\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">खाने दीवारें नहीं — कुर्सियाँ वक़्त के साथ बदलती हैं</text>\n</svg>\n\n### 3. आज का काम «देखो»\n\nकोर्स की पाठ-सूची (मास्टर-सूची) खोलिए और उसका शुरुआती हिस्सा ध्यान से देखिए — \"यह कोर्स किनके लिए है\" और \"भीतर का नक़्शा\" वाली तालिका। फिर नोटबुक में दो पंक्तियाँ लिखिए — पहली: मेरी आज की कुर्सी कौन-से वर्ग की है और क्यों। दूसरी: पाँच साल बाद मैं अपने-आप को किस कुर्सी पर देखता हूँ।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- दोनों पंक्तियों में वर्ग का नाम और वजह दोनों हों\n- आज वाली वजह आपके तैयारी-पत्र से मेल खाती हो\n\n### 5. सबूत\n\nदोनों पंक्तियों वाले पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरी हालत यह है — जेब, जगह, समय और रुचि। सीखने वालों के चार वर्गों में से मेरी आज की कुर्सी कौन-सी दिखती है?\"* — फिर तैयारी-पत्र की पंक्तियाँ सुनाइए। AI का जवाब अपनी लिखी वजह से मिलाइए — फ़ैसला आपकी क़लम का है।\n\n### 7. आम ग़लती\n\nलोग सोचते हैं — पूरा कोर्स है, तो पूरा पढ़ना होगा, और छह सौ पाठ देखकर हिम्मत छोड़ देते हैं। **यह किताब नहीं, बाज़ार है।** बाज़ार में कोई हर दुकान नहीं जाता — अपनी ज़रूरत की दुकानें जाता है। अगले पाठ में दुकानों की गली-गली का नक़्शा मिलेगा।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | खंड-1 के पिछले अध्याय पढ़े हों तो बेहतर |\n| ज़रूरी सामान | पाठ-सूची, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | सूची देखना, अपनी कुर्सी पहचानना, लिखना |\n| क्या कभी नहीं | दूसरे की कुर्सी देखकर अपनी राह चुनना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — चारों वर्ग वहीं दर्ज हैं\n- बिहार सरकार — बाग़वानी विभाग, योजनाओं में प्राथमिकता की झलक ([horticulture.bihar.gov.in](https://horticulture.bihar.gov.in/)) · देखा गया 09-08-2026\n\n*वर्ग-पहचान आज की तस्वीर है, जन्म-पत्री नहीं। हर बड़े मौसम पर इसे दोबारा देखना समझदारी है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं ग्राहक-वर्ग और सीखने वाले वर्ग का फ़र्क़ बता सकता हूँ\n- [ ] मैं चारों सीखने वाले वर्ग एक-एक पहचान के साथ गिना सकता हूँ\n- [ ] मैं बता सकता हूँ कि समूह-वर्ग का पढ़ने का ढंग अलग कैसे है\n- [ ] मैं सेवा-वर्ग के चार धंधे गिना सकता हूँ\n- [ ] मैंने अपनी आज की कुर्सी वजह-समेत लिख ली है\n\n**आगे का पाठ:** कुर्सी पहचानी — अब उससे खुलने वाले सात रास्तों का नक़्शा।\n\n---\n---\n", "32": "# पाठ 32 — सात रास्ते — कौन-सी क्या सिखाती है\n\n**अध्याय:** अ-4 · **पाठ:** 2 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद कोर्स के सात रास्ते आपकी हथेली पर होंगे — अ से ग तक। आप जानेंगे कि हर रास्ता किसके लिए बना है, कौन-से खंड जोड़ता है, और चार साझा खंड सबके लिए क्यों हैं। और अपनी कुर्सी से मिलते दो रास्तों पर निशान लगा लेंगे।\n\n### 2. मुख्य बात\n\n> रेल के जंक्शन पर हर गाड़ी हर पटरी नहीं पकड़ती — अपनी मंज़िल की पटरी पकड़ती है। यह कोर्स सात रास्तों का जंक्शन है। रास्ता चुनना पढ़ाई घटाना नहीं है — पढ़ाई को मंज़िल से जोड़ना है।\n\n---\n\n### चार साझा खंड — हर रास्ते की ज़मीन\n\nनक़्शे से पहले ज़मीन। सात रास्ते जो भी चुनें, चार खंड सबके पाँव तले रहेंगे — खंड एक, दो, तीन और सात।\n\nखंड-1 यानी नींव और फ़ैसला — जो आप अभी पूरा कर रहे हैं। खंड-2 यानी AI आपका साथी — अगला ही खंड, जो हर धंधे का औज़ार-घर है। खंड-3 यानी पहला चक्र — पाँच बैग का असली अनुभव। और खंड-7 यानी सुरक्षा, गुणवत्ता और समस्या-समाधान।\n\nखंड-7 सबके लिए क्यों, जबकि हर कोई उगाएगा नहीं? क्योंकि मशरूम खाने की चीज़ है। बेचने वाला हो, सुखाने वाला हो या बीज बनाने वाला — खाद्य-सुरक्षा और गुणवत्ता की समझ के बिना कोई इस धंधे की किसी कुर्सी पर नहीं बैठ सकता। और पहला चक्र सबके लिए क्यों? क्योंकि जिसने पाँच बैग ख़ुद नहीं सँभाले, वह उगाने वाले की दुनिया कभी नहीं समझेगा — चाहे उसे बेचना हो या बीज बनाना।\n\n### सात रास्तों की गली-गली\n\nअब सातों रास्ते, एक-एक पहचान के साथ।\n\nरास्ता-अ — उत्पादन। उगाने वाले का सीधा रास्ता। साझा खंडों के ऊपर खंड-6 (उत्पादन की गहराई) और खंड-8 (तुड़ाई के बाद) जुड़ते हैं। वर्ग-1 और वर्ग-2 का घर-रास्ता यही है।\n\nरास्ता-ब — बेड। सब्सट्रेट यानी तैयार बेड-कम्पोस्ट बनाकर बेचने वाले का रास्ता — खंड-4 इसकी दुकान है। याद कीजिए, कम्पोस्ट-पाठ में जिन बड़ी इकाइयों से आपने ख़रीदना सीखा था — यह रास्ता उन्हीं की कुर्सी तक जाता है।\n\nरास्ता-स — बीज। Spawn बनाने वाले की लैब — खंड-5। ताज़गी की तीन निशानियाँ परखने वाला ख़रीदार यहाँ बनाने वाला बन जाता है।\n\nरास्ता-द — प्रसंस्करण। सुखाने, पीसने, पैक करने वाले का रास्ता — तुड़ाई-बाद वाले खंड-8 की गहराई। दूसरे दर्जे के माल का ठिकाना वाली बात यहीं धंधा बनती है।\n\nरास्ता-इ — विपणन। बेचने के हुनर का रास्ता — खंड-11। जो आदमी माल नहीं, बाज़ार सँभालना चाहता है।\n\nरास्ता-फ़ — डिजिटल। online-दुकान, फ़ोन से धंधा — खंड-11 का ही दूसरा दरवाज़ा, पर्दे वाली दुनिया के लिए।\n\nरास्ता-ग — उद्यम और हब। मालिक बनने वालों का रास्ता — खंड-9 (उद्यम-संचालन), खंड-10 (हब) और खंड-12 (पैसा, क़ानून, योजना)। समूह-वर्ग और बड़े सपने वालों की मंज़िल।\n\n### रास्ते जुड़ते भी हैं\n\nनक़्शा पढ़कर एक सवाल उठेगा — क्या एक ही रास्ता चुनना पड़ेगा? नहीं। रास्ते गलियाँ हैं, जेल नहीं।\n\nआम जोड़ देखिए। उगाने वाला (अ) आगे चलकर सुखाना भी सीखे (द) — फ़सल का दाना-दाना बिकाने के लिए। बेचने वाली (इ) डिजिटल दुकान भी खोले (फ़) — दोनों एक ही खंड में पड़ोसी हैं। और हर रास्ता आख़िर में ग की ओर देखता है — क्योंकि हर धंधे का पका रूप उद्यम ही है।\n\nनियम बस एक है — एक बार में एक रास्ता। दो गलियों में एक साथ दौड़ने वाला दोनों में हाँफता है। पहला रास्ता पककर दूसरा जुड़े, तो दोनों फलते हैं।\n\n### रास्ता चुनने की तीन कसौटियाँ\n\nनक़्शा हाथ में है — पर चुनाव किस तराज़ू से? तीन कसौटियाँ मिलाइए।\n\nपहली — कुर्सी का मेल। पिछले पाठ की अपनी कुर्सी देखिए। उगाने वाले की सहज गली अ है, सेवा-धंधे वाले की ब-स-द में से कोई, समूह की नज़र ग पर।\n\nदूसरी — इलाक़े का मौक़ा। अपने माँग-पत्रकों की घेरे वाली शिकायत निकालिए। मान लो पाँचों दुकानों की दोहराई शिकायत ताज़े माल की अनियमित सप्लाई थी — यह उत्पादन (अ) और विपणन (इ) दोनों का न्योता है। और अगर आपके इलाक़े में उगाने वाले तो कई हैं पर कम्पोस्ट दूर से आता है — यह ब-रास्ते का खुला दरवाज़ा है। इलाक़े का होल ही आपके धंधे की जगह है।\n\nतीसरी — मन का खिंचाव। दो रास्ते बराबर तुलें, तो वह चुनिए जिसका काम करते हुए घड़ी भूल जाते हैं। धंधा लंबी दौड़ है — बेमन की गली में लंबा नहीं चला जाता।\n\nऔर तौल के दिन जल्दबाज़ी मत कीजिए — एक रात की नींद भी चुनाव की कसौटी है। सुबह जो रास्ता वैसा ही खिंचे, वही आपका है।\n\nकसौटियों को काग़ज़ पर तौलिए, मन-ही-मन नहीं। हर रास्ते के आगे तीन निशान लगाइए — कुर्सी-मेल पर, मौक़े पर, मन पर — और गिनकर देखिए किसके तीन में से कितने भरे। लिखी हुई तौल में पुरानी सुनी-सुनाई बातें हार जाती हैं और अपने पत्रकों का सच जीत जाता है — यही तो पूरे खंड-1 की कमाई थी।\n\nतीनों कसौटियाँ एक तरफ़ झुकें, तो चुनाव पक्का। बँटी हुई हों, तो कुर्सी-मेल को पहला वोट दीजिए — मन और मौक़ा वक़्त के साथ रास्ते में जुड़ते भी हैं।\n\n### चित्र — सात रास्तों का जंक्शन\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">सात रास्ते — साझा ज़मीन से मंज़िल तक</text>\n  <rect x=\"150\" y=\"90\" width=\"500\" height=\"80\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"125\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">साझा ज़मीन — सबके लिए</text>\n  <text x=\"400\" y=\"155\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">खंड 1 नींव · 2 AI · 3 पहला चक्र · 7 सुरक्षा</text>\n  <line x1=\"400\" y1=\"170\" x2=\"400\" y2=\"220\" stroke=\"#0B1F3A\" stroke-width=\"6\"/>\n  <rect x=\"60\" y=\"230\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"165\" y=\"260\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">अ — उत्पादन</text>\n  <text x=\"165\" y=\"288\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 6, 8</text>\n  <rect x=\"295\" y=\"230\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"260\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">ब — बेड</text>\n  <text x=\"400\" y=\"288\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 4</text>\n  <rect x=\"530\" y=\"230\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"635\" y=\"260\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">स — बीज</text>\n  <text x=\"635\" y=\"288\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 5</text>\n  <rect x=\"60\" y=\"320\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"165\" y=\"350\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">द — प्रसंस्करण</text>\n  <text x=\"165\" y=\"378\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 8</text>\n  <rect x=\"295\" y=\"320\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"350\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">इ — विपणन</text>\n  <text x=\"400\" y=\"378\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 11</text>\n  <rect x=\"530\" y=\"320\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"635\" y=\"350\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">फ़ — डिजिटल</text>\n  <text x=\"635\" y=\"378\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">+ खंड 11</text>\n  <rect x=\"295\" y=\"410\" width=\"210\" height=\"70\" rx=\"10\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"440\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">ग — उद्यम व हब</text>\n  <text x=\"400\" y=\"468\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">+ खंड 9, 10, 12</text>\n  <rect x=\"80\" y=\"530\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"568\" font-size=\"21\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">नियम: एक बार में एक रास्ता</text>\n  <text x=\"400\" y=\"600\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">पहला पके, तब दूसरा जुड़े — जैसे अ के बाद द</text>\n  <text x=\"400\" y=\"680\" font-size=\"20\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">हर रास्ता आख़िर में ग की ओर देखता है</text>\n  <text x=\"400\" y=\"740\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">रास्ता चुनना = पढ़ाई को मंज़िल से जोड़ना</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरा रास्ता-पन्ना\" बनाइए। सातों रास्तों के नाम लिखिए। हर नाम के आगे एक शब्द — मेरा / शायद / नहीं। \"मेरा\" सिर्फ़ एक रास्ते पर, \"शायद\" ज़्यादा से ज़्यादा दो पर। फिर नीचे तीन पंक्तियों में लिखिए — मैंने यह रास्ता क्यों चुना, यह मेरी कुर्सी (पाठ 31) से कैसे मिलता है, और साझा चार खंडों के बाद मैं किस खंड में घुसूँगा।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- \"मेरा\" एक ही रास्ते पर लगा हो\n- तीनों पंक्तियों में वजह, कुर्सी-मेल और अगला खंड तीनों साफ़ हों\n\n### 5. सबूत\n\nरास्ता-पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरी कुर्सी, तैयारी-पत्र और रुचि यह है। सात रास्तों में से मेरे लिए पहला रास्ता कौन-सा दिखता है और उसके बाद का स्वाभाविक जोड़ कौन-सा?\"* — जवाब को अपने रास्ता-पन्ने से मिलाइए। \"मेरा\" का निशान अपनी क़लम से ही लगे।\n\n### 7. आम ग़लती\n\nलोग जोश में तीन-चार रास्तों पर \"मेरा\" लगा देते हैं — सब सीख लूँगा। **सात गलियों में एक साथ दौड़ने वाला किसी के छोर तक नहीं पहुँचता।** पहले एक रास्ते का छोर छूइए। जुड़ने वाले रास्ते भागे नहीं जा रहे — वे जंक्शन पर ही खड़े हैं।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 31 पूरा |\n| ज़रूरी सामान | पाठ-सूची, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | नक़्शा पढ़ना, निशान लगाना, वजह लिखना |\n| क्या कभी नहीं | बिना साझा खंड पढ़े सीधे अपने खंड में कूदना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — सात रास्तों की तालिका वहीं दर्ज है\n- राष्ट्रीय बाग़वानी बोर्ड — बाग़वानी-धंधों की क़िस्मों की झलक ([nhb.gov.in](https://www.nhb.gov.in/)) · देखा गया 09-08-2026\n\n*रास्ते का चुनाव आज की समझ से है। पहला चक्र पूरा करके कई लोग रास्ता बदलते हैं — यह हार नहीं, नक़्शे का सही इस्तेमाल है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं चारों साझा खंड और उनकी वजह बोल सकता हूँ\n- [ ] मैं सातों रास्ते एक-एक पहचान के साथ गिना सकता हूँ\n- [ ] मैं दो रास्तों के आम जोड़ का एक उदाहरण दे सकता हूँ\n- [ ] मैं \"एक बार में एक रास्ता\" की वजह समझा सकता हूँ\n- [ ] मेरे रास्ता-पन्ने पर \"मेरा\" का एक निशान लग चुका है\n\n**आगे का पाठ:** रास्ता चुना — अब सूची में लिखी \"पूर्व-शर्त\" की भाषा पढ़ना सीखिए, ताकि कोई दरवाज़ा ग़लत क्रम में न खुले।\n\n---\n---\n", "33": "# पाठ 33 — पूर्व-शर्त नक़्शा कैसे पढ़ें\n\n**अध्याय:** अ-4 · **पाठ:** 3 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद पाठ-सूची की छोटी-सी पंक्ति — पूर्व-शर्त: अ.1 — आपके लिए संकेत-भाषा नहीं रहेगी। आप अध्याय-कोड पढ़ना, शर्तों की जंज़ीर समझना और छोड़ने का नक़्शा इस्तेमाल करना सीख जाएँगे — और अपने चुने रास्ते की शर्त-सीढ़ी काग़ज़ पर उतार लेंगे।\n\n### 2. मुख्य बात\n\n> पूर्व-शर्त रोक नहीं, सीढ़ी का डंडा है। वह यह नहीं कहती — तुम नहीं पढ़ सकते। वह कहती है — यह मंज़िल उस डंडे के बाद ज़्यादा आसान है। डंडा छोड़कर चढ़ने वाला गिरता ज़्यादा है।\n\n---\n\n### कोड की वर्णमाला\n\nसूची में हर अध्याय के नीचे कभी-कभी एक पंक्ति दिखती है — पूर्व-शर्त: अ.1। इसे खोलिए।\n\n\"अ\" का मतलब अध्याय। \"अ.1\" यानी अध्याय एक — मशरूम का जीवन-चक्र। तो पूरी पंक्ति का अर्थ — इस अध्याय में घुसने से पहले अध्याय-1 पढ़ा होना चाहिए। जैसे आपने देखा, अध्याय-2 और अध्याय-3 दोनों की शर्त अ.1 थी — क्योंकि जीवन-चक्र समझे बिना न बटन का चुनाव समझ आता, न फ़सल की जल्दी-ख़राबी वाली घड़ी।\n\nखंडों की भी शर्तें हैं। खंड-2 की शर्त अ.4 — यानी यही अध्याय, जो आप पढ़ रहे हैं। जहाँ पंक्ति लिखी ही नहीं, वहाँ शर्त साझा-नियम से चलती है — साझा चार खंड सबसे पहले।\n\n### शर्त क्यों — तीन वजहें\n\nशर्तों का मक़सद रौब नहीं, तीन सीधी वजहें हैं।\n\nपहली वजह — भाषा। आगे के पाठ पीछे के शब्दों पर खड़े हैं। केसिंग वाला पाठ जाल-फैलाव मान कर चलता है। जिसने जाल नहीं पढ़ा, उसके लिए केसिंग हवा में लटकी रहेगी।\n\nदूसरी वजह — सुरक्षा। गर्म भाप वाले काम से पहले सुरक्षा-खंड की समझ चाहिए। यह शर्त हड्डी बचाती है, समय नहीं खाती।\n\nतीसरी वजह — पैसा। ख़रीद-फ़रोख़्त वाले पाठ बिना गिनती वाले पाठों के पढ़े जाएँ, तो जेब से सीख होती है — और जेब की सीख सबसे महँगी है।\n\n### छोड़ने का नक़्शा — शर्त का दूसरा चेहरा\n\nअब शर्त का उलटा औज़ार — छोड़ने का नक़्शा। सूची कहती है कि हर आदमी को हर गहराई नहीं चाहिए।\n\nबीज-रास्ते का दर्ज उदाहरण लीजिए। Spawn वाले खंड में गहराई की सीढ़ियाँ हैं। सूची साफ़ बताती है — उगाने वाले को शुरुआती अध्याय काफ़ी हैं; बीज बनाने वाला एक क़दम और उतरे; कल्चर तक जाने वाला और गहरा; व्यावसायिक लैब वाला पूरी गहराई तक। एक ही खंड, चार गहराइयाँ — हर पाठक अपनी ज़रूरत के तल पर रुक जाए।\n\nयही इस कोर्स के \"छह सौ सत्ताईस\" का राज़ है। गिनती डराने के लिए नहीं, हर गहराई के पाठक के लिए है। आपका अपना रास्ता इसमें से कहीं छोटा है — और छोड़ने का नक़्शा ही उसे काटकर देता है।\n\n### अपनी शर्त-सीढ़ी बनाइए\n\nअब यह सब अपने रास्ते पर लगाइए। तरीक़ा तीन क़दम का है।\n\nपहला क़दम — अपने रास्ते के खंड लिखिए। साझा चार पहले, फिर रास्ते के जोड़ वाले।\n\nदूसरा क़दम — हर खंड की पूर्व-शर्त पंक्ति सूची से देखकर आगे लिखिए। जहाँ नहीं लिखी, वहाँ साझा-नियम।\n\nतीसरा क़दम — क्रम जमाइए। शर्तें ख़ुद बता देंगी कि कौन पहले, कौन बाद। यही आपकी शर्त-सीढ़ी है — ऊपर से नीचे पढ़ने का पक्का क्रम।\n\nएक राहत भी दर्ज कीजिए — पढ़ना हमेशा खुला है। शर्त काम की है, जिज्ञासा की नहीं। आगे का कोई पाठ झाँकने का मन हो, तो झाँकिए। बस काम वाला हिस्सा तभी कीजिए, जब सीढ़ी के डंडे पार हों — यह बात सुरक्षा-वर्ग वाले पाठ में और पक्की होगी।\n\n### एक चलता उदाहरण — रास्ता-अ की सीढ़ी\n\nविधि को एक बार पूरा चलाकर देखिए — उत्पादन-रास्ते (अ) के पाठक की सीढ़ी।\n\nपहला क़दम — खंड लिखे: साझा चार (एक, दो, तीन, सात) और रास्ते के जोड़ (छह, आठ)। दूसरा क़दम — शर्तें देखीं: खंड-दो के नीचे लिखा मिला — पूर्व-शर्त अ.4, यानी यही अध्याय; बाक़ी पर साझा-नियम। तीसरा क़दम — क्रम जमा: पहले खंड-एक (जो पूरा होने चला), फिर खंड-दो, फिर खंड-तीन का पहला चक्र, साथ-साथ खंड-सात की सुरक्षा, और तब खंड-छह की गहराई व खंड-आठ की तुड़ाई-बाद दुनिया।\n\nदेखिए — छह सौ सत्ताईस में से इस पाठक की अपनी पगडंडी कोई दो सौ के आसपास पाठों की बनी, और उसका क्रम ख़ुद शर्तों ने जमा दिया। यही अभ्यास आज आप अपने रास्ते पर करेंगे।\n\nसीढ़ी बनते ही उसे पाठ-सूची के पहले पन्ने पर चिपकाइए — रोज़ आँख के सामने रहे।\n\nहर रास्ते की सीढ़ी इसी विधि से बनेगी — सिर्फ़ जोड़ वाले खंड बदलेंगे, चाल वही रहेगी।\n\nऔर इस उदाहरण से एक हौसला भी उठाइए। दो सौ पाठ सुनकर भी साँस मत रोकिए — यह गिनती महीनों में बँटी है, और आप उन्नीस-बीस पाठ पहले ही पार कर चुके हैं। सीढ़ी का काम डराना नहीं, दूरी को डंडों में तोड़ना है। एक बार में एक डंडा — बस यही चाल पूरी दूरी खा जाती है।\n\nएक बारीक़ी और — पूर्व-शर्त और सुरक्षा-शर्त अलग चीज़ें हैं। पूर्व-शर्त पढ़ाई का क्रम है; सुरक्षा-शर्त (उम्र, निगरानी, सामान) काम की चौकी है। दोनों की भाषा सूची में अलग-अलग लिखी मिलती है, और दोनों की गहराई अगले पाठों में खुलेगी।\n\n### चित्र — शर्त-सीढ़ी का पढ़ना\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">पूर्व-शर्त — संकेत से सीढ़ी तक</text>\n  <rect x=\"80\" y=\"90\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"128\" font-size=\"22\" fill=\"#F9A825\" text-anchor=\"middle\">सूची की पंक्ति: \"पूर्व-शर्त: अ.1\"</text>\n  <text x=\"400\" y=\"160\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\">अ = अध्याय · अ.1 = अध्याय-1 पहले पढ़ो</text>\n  <rect x=\"80\" y=\"210\" width=\"640\" height=\"120\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"248\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">शर्त की तीन वजहें</text>\n  <text x=\"400\" y=\"282\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">भाषा — आगे के शब्द पीछे बनते हैं</text>\n  <text x=\"400\" y=\"312\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">सुरक्षा — हड्डी बचती है · पैसा — जेब बचती है</text>\n  <rect x=\"80\" y=\"360\" width=\"640\" height=\"180\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"398\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">छोड़ने का नक़्शा — बीज-रास्ते का उदाहरण</text>\n  <text x=\"400\" y=\"432\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">उगाने वाला — शुरुआती अध्याय काफ़ी</text>\n  <text x=\"400\" y=\"462\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बीज बनाने वाला — एक क़दम गहरा</text>\n  <text x=\"400\" y=\"492\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">कल्चर वाला — और गहरा · लैब वाला — पूरी गहराई</text>\n  <text x=\"400\" y=\"522\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">एक खंड — चार गहराइयाँ — अपने तल पर रुको</text>\n  <rect x=\"80\" y=\"570\" width=\"640\" height=\"90\" rx=\"14\" fill=\"#F9A825\" stroke=\"#0B1F3A\" stroke-width=\"4\"/>\n  <text x=\"400\" y=\"608\" font-size=\"21\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">पढ़ना हमेशा खुला — काम सीढ़ी के क्रम से</text>\n  <text x=\"400\" y=\"640\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">शर्त जिज्ञासा की नहीं, काम की चौकी है</text>\n  <text x=\"400\" y=\"720\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">तीन क़दम: खंड लिखो → शर्तें देखो → क्रम जमाओ</text>\n  <text x=\"400\" y=\"760\" font-size=\"19\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">यही आपकी शर्त-सीढ़ी है</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nअपने चुने रास्ते (पाठ 32) की शर्त-सीढ़ी बनाइए। नोटबुक में तीन-क़दम विधि चलाइए — रास्ते के सब खंड, हर खंड की सूची में लिखी पूर्व-शर्त, और ऊपर-से-नीचे जमा हुआ पढ़ने का क्रम। आख़िर में अपनी सीढ़ी का अगला डंडा घेर दीजिए — यानी आज के अध्याय के बाद कौन-सा खंड।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- सीढ़ी में साझा चार खंड सबसे ऊपर हों\n- हर खंड के आगे उसकी शर्त-पंक्ति या \"साझा-नियम\" लिखा हो\n\n### 5. सबूत\n\nशर्त-सीढ़ी वाले पन्ने की फ़ोटो, घेरा दिखता हुआ।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरा रास्ता और उसकी शर्त-सीढ़ी यह है। बताओ — क्रम में कोई डंडा उलटा तो नहीं जमा? और किस डंडे पर सबसे ज़्यादा समय लगना चाहिए?\"* — जवाब को सूची की छपी शर्तों से मिलाइए। सूची और AI में फ़र्क़ दिखे, तो छपी सूची जीतेगी।\n\n### 7. आम ग़लती\n\nलोग शर्त को दीवार समझकर या तो रुक जाते हैं या फाँदकर सीधे गहरे पाठ में कूद पड़ते हैं। **दोनों ग़लत हैं।** शर्त पढ़ने से नहीं रोकती और काम में छूट नहीं देती। पढ़िए खुलकर, कीजिए क्रम से — यही एक पंक्ति पूरा नियम है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 31-32 पूरे |\n| ज़रूरी सामान | पाठ-सूची, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | कोड पढ़ना, सीढ़ी बनाना, क्रम जमाना |\n| क्या कभी नहीं | शर्त फाँदकर काम वाला अभ्यास कर बैठना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — शर्त-पंक्तियाँ और छोड़ने का नक़्शा वहीं छपे हैं\n- मशरूम अनुसंधान निदेशालय, सोलन — प्रशिक्षण-सामग्री की सीढ़ीदार बनावट की झलक ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n\n*शर्त-सीढ़ी पढ़ाई का क्रम है, कैलेंडर नहीं। हर डंडे पर कितने दिन लगेंगे — यह आपकी रफ़्तार तय करेगी, सूची नहीं।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं \"पूर्व-शर्त: अ.1\" जैसी पंक्ति का पूरा अर्थ खोल सकता हूँ\n- [ ] मैं शर्त की तीनों वजहें गिना सकता हूँ\n- [ ] मैं छोड़ने के नक़्शे का बीज-उदाहरण समझा सकता हूँ\n- [ ] मैं \"पढ़ना खुला, काम क्रम से\" का नियम बोल सकता हूँ\n- [ ] मेरी शर्त-सीढ़ी बनी है और अगला डंडा घिरा है\n\n**आगे का पाठ:** सीढ़ी पढ़ाई की बनी — अब ज़िंदगी की सीढ़ी: काम की छह सीढ़ियाँ, प्रशिक्षु से मालिक तक।\n\n---\n---\n", "34": "# पाठ 34 — काम की छह सीढ़ियाँ — प्रशिक्षु से मालिक तक\n\n**अध्याय:** अ-4 · **पाठ:** 4 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आपके पास हुनर की लंबी सीढ़ी का नक़्शा होगा — छह डंडे, प्रशिक्षु से मालिक तक। आप जानेंगे कि हर डंडे पर आदमी क्या करता है, अगला डंडा किस बात से मिलता है, और आज आप कौन-से डंडे पर खड़े हैं।\n\n### 2. मुख्य बात\n\n> कोई मालिक पैदा नहीं होता। हर मालिक कभी प्रशिक्षु था। छह सीढ़ियाँ यही रास्ता हैं — और हर सीढ़ी का किराया एक ही सिक्के में लगता है: सीखा हुआ काम, निभाई हुई ज़िम्मेदारी।\n\n---\n\n### दो सीढ़ियाँ — गड्ड-मड्ड मत कीजिए\n\nपहले एक उलझन साफ़। इस कोर्स में \"सीढ़ी\" शब्द दो जगह आता है।\n\nएक — काम की तीन सीढ़ियाँ: देखो, अभ्यास, करो। यह रोज़ के पाठ-काम का रूप है — आज का काम किस ढंग से होगा।\n\nदो — काम की छह सीढ़ियाँ: यह ज़िंदगी और धंधे में आपकी कुर्सी की चढ़ाई है। आज का पाठ इसी दूसरी सीढ़ी का है। तीन वाली रोज़ बदलती है, छह वाली सालों में चढ़ती है।\n\n### छह डंडे — एक-एक कर\n\nपहला डंडा — प्रशिक्षु। जो सीख रहा है। काम निगरानी में करता है, ग़लती की छूट पाता है, सवाल पूछना उसका असली काम है। इस कोर्स का पाठक आज ज़्यादातर यहीं खड़ा है — और यह गर्व की जगह है, शर्म की नहीं।\n\nदूसरा डंडा — सहायक। जो जाने हुए काम अकेले निभा लेता है, पर फ़ैसले ऊपर से लेता है। पाँच बैग का पहला चक्र पूरा करने वाला मोटे तौर पर यहाँ पहुँचता है — हाथ चलने लगे, समझ पकने लगी।\n\nतीसरा डंडा — कुशल कर्मी। जिसके हाथ का काम बोलता है। फ़सल की देखभाल, तुड़ाई की सफ़ाई, गड़बड़ की पहचान — बिना पूछे सही होती है। बाज़ार में इसी डंडे से इज़्ज़त की कमाई शुरू होती है।\n\nचौथा डंडा — प्रधान कर्मी। जो अपने काम के साथ दो-चार और हाथों को सँभालता है। नए को सिखाना, काम बाँटना, दिन का हिसाब रखना — कंधे पर पहली टीम यहीं आती है।\n\nपाँचवाँ डंडा — प्रबंधक। जिसके ज़िम्मे पूरा चक्र है — माल की ख़रीद से बिक्री की वसूली तक। हाथ कम, दिमाग़ ज़्यादा। रजिस्टर, योजना, ग्राहक और टीम — चारों उसकी मेज़ पर हैं।\n\nछठा डंडा — मालिक। जो जोखिम अपने नाम लेता है। पूँजी उसकी, फ़ैसला उसका, नुक़सान भी उसका और बढ़त भी। मालिक होना ठाट का नाम नहीं — आख़िरी ज़िम्मेदारी का नाम है।\n\n### डंडे और रास्ते — जोड़ समझिए\n\nछह सीढ़ियाँ सातों रास्तों पर एक-सी चलती हैं। उगाने वाला भी प्रशिक्षु से मालिक तक चढ़ता है और बीज-लैब वाला भी। रास्ता बताता है — किस गली में; सीढ़ी बताती है — गली में कितना ऊपर।\n\nऔर पिछले पाठ की L-वाली बात यहीं जुड़ेगी — अगला पाठ पैमाने के उदाहरण खोलेगा। मोटा रिश्ता यह है: सीढ़ी हुनर की चढ़ाई है, पैमाना ढाँचे के आकार की। पाँच बैग वाला सहायक भी हो सकता है और बीस घर के हब का मालिक भी कभी प्रशिक्षु था। दोनों नाप अलग-अलग चीज़ें तौलते हैं — गड्ड-मड्ड यहाँ भी नहीं।\n\n### चढ़ने का सिक्का — और उतरने की इज़्ज़त\n\nअगला डंडा किस बात से मिलता है? तीन चीज़ों के जोड़ से — काम की गिनती (कितने चक्र, कितनी फ़सलें), काम का सबूत (रजिस्टर, फ़ोटो, गवाह), और ज़िम्मेदारी निभाने का इतिहास (वादे पूरे किए या नहीं)। ग़ौर कीजिए — तीनों चीज़ें यह कोर्स आपसे हर पाठ में जमा करवा ही रहा है। सबूत वाला खाना और योग्यता-जाँच इसी चढ़ाई की ईंटें हैं।\n\nऔर एक बड़प्पन की बात। ऊपर का डंडा नीचे वाले से ऊँचा है, बड़ा नहीं। मालिक की थाली कुशल कर्मी के हाथ से ही भरती है। जो मालिक अपने प्रशिक्षु की इज़्ज़त नहीं करता, उसकी सीढ़ी नीचे से सड़ने लगती है। इस कोर्स की नज़र में हर डंडे का आदमी बराबर इज़्ज़त का हक़दार है।\n\n### डंडा और कमाई — सीधा हिसाब नहीं\n\nएक ग़लतफ़हमी यहीं झाड़ दें। ऊँचा डंडा कमाई की गारंटी नहीं है। यह कोर्स कमाई का कोई वादा नहीं करता — डंडे का रिश्ता कमाई से नहीं, मौक़े और ज़िम्मेदारी से है। ऊपर का डंडा बड़े फ़ैसले का हक़ देता है — और बड़े फ़ैसले में बड़ी बढ़त भी बैठी है, बड़ा नुक़सान भी। मालिक की कुर्सी की यही क़ीमत है।\n\nगिनती-सबूत की बही ही डंडे की सच्ची गवाह रहेगी।\n\nसीढ़ी का असली फल भरोसा है — अपने हाथ पर, अपनी परख पर। और भरोसे की गिनती कमाई से पहले चलती है।\n\nइसीलिए घर-बाहर की बातचीत में डंडे का नाम कमाई के दावे की तरह कभी मत बोलिए। \"अब मैं प्रबंधक हूँ, तो इतना तो कमाऊँगा ही\" — यह वाक्य उसी सपना-बेचने वाली भाषा का रिश्तेदार है, जिसकी कसौटी अगला पाठ देगा। डंडा बताइए, हिसाब अपने पत्रकों से कीजिए।\n\nऔर सीढ़ी पर आना-जाना दोनों चलता है। भीड़ की फ़सल-घड़ी में समझदार मालिक ख़ुद तुड़ाई में हाथ लगाता है — उस घंटे वह कुशल कर्मी की कुर्सी पर बैठा है, और यह उतरना उसकी शान घटाता नहीं, बढ़ाता है। डंडा पहचान है, पिंजरा नहीं।\n\n### चित्र — छह डंडों की सीढ़ी\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">काम की छह सीढ़ियाँ — हुनर की चढ़ाई</text>\n  <rect x=\"90\" y=\"640\" width=\"620\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"250\" y=\"683\" font-size=\"21\" fill=\"#F5F7FA\">1. प्रशिक्षु — सीखता है, पूछता है</text>\n  <rect x=\"130\" y=\"550\" width=\"580\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"290\" y=\"593\" font-size=\"21\" fill=\"#F5F7FA\">2. सहायक — जाना काम अकेले</text>\n  <rect x=\"170\" y=\"460\" width=\"540\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"330\" y=\"503\" font-size=\"21\" fill=\"#F5F7FA\">3. कुशल कर्मी — हाथ बोलता है</text>\n  <rect x=\"210\" y=\"370\" width=\"500\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"370\" y=\"413\" font-size=\"21\" fill=\"#F5F7FA\">4. प्रधान कर्मी — पहली टीम</text>\n  <rect x=\"250\" y=\"280\" width=\"460\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"410\" y=\"323\" font-size=\"21\" fill=\"#F5F7FA\">5. प्रबंधक — पूरा चक्र मेज़ पर</text>\n  <rect x=\"290\" y=\"190\" width=\"420\" height=\"70\" rx=\"10\" fill=\"#0B1F3A\"/>\n  <text x=\"450\" y=\"233\" font-size=\"21\" fill=\"#F9A825\">6. मालिक — जोखिम अपने नाम</text>\n  <line x1=\"120\" y1=\"640\" x2=\"320\" y2=\"200\" stroke=\"#2E7D32\" stroke-width=\"6\"/>\n  <text x=\"150\" y=\"240\" font-size=\"20\" fill=\"#2E7D32\" font-weight=\"bold\">चढ़ने का सिक्का:</text>\n  <text x=\"150\" y=\"275\" font-size=\"19\" fill=\"#0B1F3A\">काम की गिनती</text>\n  <text x=\"150\" y=\"305\" font-size=\"19\" fill=\"#0B1F3A\">काम का सबूत</text>\n  <text x=\"150\" y=\"335\" font-size=\"19\" fill=\"#0B1F3A\">निभाई ज़िम्मेदारी</text>\n  <rect x=\"90\" y=\"730\" width=\"620\" height=\"50\" rx=\"25\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"762\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">हर डंडे का आदमी बराबर इज़्ज़त का हक़दार है</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरी सीढ़ी\" पन्ना बनाइए। छह डंडे लिखिए। जिस डंडे पर आज खड़े हैं, उस पर घेरा लगाइए और एक पंक्ति में वजह लिखिए। फिर अगले डंडे के आगे लिखिए — वहाँ पहुँचने के लिए मुझे कौन-से तीन काम गिनती-सबूत-ज़िम्मेदारी के सिक्के में जमा करने हैं।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- घेरे वाले डंडे की वजह में कोई ठोस काम या अनुभव लिखा हो, सिर्फ़ मन की बात नहीं\n- अगले डंडे के तीनों काम अलग-अलग और करने लायक़ हों\n\n### 5. सबूत\n\nमेरी-सीढ़ी पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरा आज का डंडा और अनुभव यह है। अगले डंडे के लिए मेरे तीन जमा-काम कौन-से होने चाहिए — छोटे और नापने लायक़?\"* — मिले कामों को अपने पन्ने के तीन कामों से मिलाइए और सबसे ठोस तीन रखिए।\n\n### 7. आम ग़लती\n\nलोग पहले दिन से मालिक वाला डंडा घेर लेते हैं — मैं तो अपना धंधा शुरू कर रहा हूँ, मालिक ही हुआ न? **काग़ज़ का मालिक और सीढ़ी का मालिक अलग हैं।** पाँच बैग का मालिक होना अच्छी शुरुआत है, पर हुनर की सीढ़ी पर वह प्रशिक्षु की जगह है — और वही सच्ची जगह तेज़ चढ़ाती है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 31-33 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | अपनी जगह पहचानना, जमा-काम लिखना |\n| क्या कभी नहीं | ऊँचे डंडे का दावा बिना गिनती-सबूत के करना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — छह सीढ़ियों की पंक्ति वहीं दर्ज है\n- मशरूम अनुसंधान निदेशालय — प्रशिक्षण से हुनर-चढ़ाई की झलक ([dmrsolan.res.in](https://dmrsolan.res.in/)) · देखा गया 09-08-2026\n\n*डंडे की पहचान आज की है। हर चक्र के बाद इस पन्ने पर लौटिए — घेरा खिसकता देखना इस कोर्स का सबसे मीठा फल है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीन-सीढ़ी और छह-सीढ़ी का फ़र्क़ बता सकता हूँ\n- [ ] मैं छहों डंडे एक-एक पहचान के साथ गिना सकता हूँ\n- [ ] मैं चढ़ने के सिक्के की तीनों चीज़ें बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि काग़ज़ का मालिक सीढ़ी का मालिक क्यों नहीं\n- [ ] मैंने अपना डंडा घेरकर अगले के तीन जमा-काम लिख लिए हैं\n\n**आगे का पाठ:** हुनर की सीढ़ी के बाद ढाँचे का पैमाना — पाँच बैग से बड़े उद्यम तक के उदाहरण, और उन पर लिखी सबसे ज़रूरी चेतावनी: यह वादा नहीं है।\n\n---\n---\n", "35": "# पाठ 35 — पैमाने के उदाहरण — यह वादा नहीं है\n\n**अध्याय:** अ-4 · **पाठ:** 5 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद आप कोर्स की पैमाना-तालिका पढ़ना सीख जाएँगे — शुरुआती कोठरी से बड़े उद्यम तक। और उससे भी ज़रूरी — आप समझ जाएँगे कि यह तालिका नमूना क्यों है, वादा क्यों नहीं, और सपने-देखने और सपना-बेचने में क्या फ़र्क़ है।\n\n### 2. मुख्य बात\n\n> पैमाने के उदाहरण रास्ते के मील-पत्थर हैं — यह बताने के लिए कि आगे क्या-क्या आता है। मील-पत्थर यह वादा नहीं करता कि हर गाड़ी वहाँ पहुँचेगी ही, या इतने में पहुँचेगी। जो तालिका को वादा बना दे, वह पढ़ाने वाला नहीं, बेचने वाला है।\n\n---\n\n### पाँच पड़ाव — एक नज़र\n\nकोर्स की तालिका पाँच पड़ाव दिखाती है। इन्हें कहानी की तरह पढ़िए।\n\nपहला पड़ाव — शुरुआती। पाँच बैग, घर की कोठरी। यही आपका पहला चक्र है — सीखने का, कमाने का नहीं। तीन-पूँजी वाले पाठ की छोटी तिपाई यहीं खड़ी होती है।\n\nदूसरा पड़ाव — छोटी इकाई। पचास से पाँच सौ बैग, छप्पर या झोपड़ी। पहला चक्र पकने के बाद की स्वाभाविक चढ़ाई — जब ग्राहक-सूची माँगने लगे और हाथ सधने लगे।\n\nतीसरा पड़ाव — व्यावसायिक इकाई। अपना कम्पोस्ट, नियमित बिक्री। यहाँ \"बनाओ मत, ख़रीदो\" वाला नियम पलट जाता है — क्योंकि अब हाथ पके हैं और तौल बड़ी है।\n\nचौथा पड़ाव — उद्यम। Spawn-लैब, या हब — जैसे बीस घरों का जुड़ा ढाँचा। यहाँ आदमी अकेला उगाने वाला नहीं रहता — ढाँचा चलाने वाला बन जाता है। समूह-वर्ग की मंज़िल यही थी।\n\nपाँचवाँ पड़ाव — बड़ा उद्यम। प्रसंस्करण, अपना नाम-छाप, बाहर भेजना। कोर्स का आख़िरी खंड इसी दुनिया के दरवाज़े खोलता है।\n\n### \"जैसे\" शब्द का वज़न\n\nतालिका की भाषा ग़ौर से देखिए — हब के आगे लिखा है: जैसे बीस घर। यह \"जैसे\" पूरी तालिका की आत्मा है।\n\nबीस कोई पवित्र गिनती नहीं। किसी हब में बारह घर होंगे, किसी में तीस। पचास-पाँच-सौ बैग वाली श्रेणी भी यही कहती है — छोटी इकाई एक फैलाव है, एक अंक नहीं। नाप-नियम वाली पुरानी सीख याद कीजिए — जहाँ मान बदल सकते हैं, वहाँ अकेला नंबर नहीं, श्रेणी। पैमाना-तालिका उसी नियम की बड़ी बहन है।\n\nइसलिए तालिका से सवाल यह मत पूछिए — मैं कब बीस घर वाला बनूँगा? सवाल यह पूछिए — मेरे अगले पड़ाव की शक्ल क्या है और उसकी तैयारी में क्या-क्या लगेगा?\n\n### ₹ यहाँ क्यों नहीं — और कहाँ मिलेंगे\n\nअब वह सवाल, जो हर पाठक के मन में है — पैसा कितना लगेगा? तालिका में ₹ के अंक जान-बूझकर नहीं हैं। वजह तीन हैं।\n\nपहली — लागत जगह से बदलती है। जिसके घर भूसा है, उसकी गिनती और है। दूसरी — लागत समय से बदलती है। आज छपा अंक अगले मौसम झूठ हो जाता है। तीसरी — छपा अंक वादा बन जाता है। पढ़ने वाला उसे पत्थर मान लेता है, और असली दुनिया में ऊपर-नीचे होते ही ठगा महसूस करता है।\n\nतो ₹ की गिनती कहाँ होगी? इकाई-हिसाब और Project Report वाले पाठों में — जहाँ हर अंक स्रोत के साथ चलेगा, \"यह अनुमान है\" की पंक्ति के साथ, और सबसे ऊपर आपके अपने भरे पत्रकों से। दाम-पट्टी और कम्पोस्ट-सवालों की आपकी नोटबुक ही वहाँ की असली किताब बनेगी। कोर्स आपको दूसरों के अंक रटाएगा नहीं — अपने अंक निकालना सिखाएगा।\n\n### सपना देखना बनाम सपना बेचना\n\nआख़िर में इस पाठ के शीर्षक की जड़। बाज़ार में मशरूम के नाम पर बड़े-बड़े वादे बिकते हैं — इतने दिन में इतना कमाओ, इतने महीने में मालामाल। ऐसे हर वादे के आगे यह कोर्स आपको एक कसौटी देता है।\n\nकसौटी सीधी है — जो कमाई, उपज या समय का पक्का अंक बोले और साथ में शर्तें, स्रोत और \"बदल सकता है\" न बोले, वह पढ़ा नहीं रहा, बेच रहा है। यह कोर्स ख़ुद भी इसी कसौटी पर परखिए — यहाँ हर बड़ी संख्या के साथ या तो स्रोत मिलेगा या \"मान लो\" का साफ़ ठप्पा।\n\nसपना देखना छोड़िए मत। पाँचवाँ पड़ाव सचमुच है और लोग वहाँ पहुँचे हैं। पर रास्ता मील-पत्थर गिनकर तय होता है, नारे सुनकर नहीं।\n\n### तालिका बातचीत में कैसे काम आती है\n\nऔर यही भाषा आपको ठगों से भी बचाती है — जो पड़ाव नहीं, सीधा पाँचवाँ आसमान बेचते हैं।\n\nपड़ाव-भाषा की एक ताक़त और है — वह बातचीत को अंकों से उतारकर शक्ल पर ले आती है। \"कितना लगेगा\" पर बहस अटकती है; \"अगले पड़ाव की शक्ल क्या है\" पर बात चलती है। शक्ल समझ में आ जाए, तो अंक अपने पत्रकों से निकालने का धीरज ख़ुद आ जाता है।\n\nइस तालिका का एक चौथा इस्तेमाल भी है — घर की बातचीत। नया धंधा शुरू करने वाले से घर के लोग अक्सर दो छोर के सवाल पूछते हैं — या तो \"इसमें रखा क्या है?\" या \"कब बड़ा आदमी बनेगा?\"\n\nदोनों का सधा जवाब यही तालिका है। पन्ना दिखाकर कहिए — यह रास्ते के पाँच पड़ाव हैं; मैं पहले पर हूँ, और पहला पड़ाव सीखने का है, कमाने का नहीं। न बढ़ा-चढ़ाकर, न दबकर। घर वालों की उम्मीद सही पड़ाव पर बँध जाए, तो सूने हफ़्तों में ताने नहीं, चाय मिलती है — और यह सहारा किसी पूँजी से कम नहीं।\n\n### चित्र — पाँच पड़ाव, एक चेतावनी\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">पैमाने के उदाहरण — मील-पत्थर, वादा नहीं</text>\n  <line x1=\"100\" y1=\"620\" x2=\"700\" y2=\"140\" stroke=\"#0B1F3A\" stroke-width=\"5\"/>\n  <rect x=\"70\" y=\"630\" width=\"230\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"185\" y=\"660\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">1. शुरुआती</text>\n  <text x=\"185\" y=\"688\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">पाँच बैग · घर की कोठरी</text>\n  <rect x=\"180\" y=\"510\" width=\"230\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"295\" y=\"540\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">2. छोटी इकाई</text>\n  <text x=\"295\" y=\"568\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">50-500 बैग · छप्पर</text>\n  <rect x=\"290\" y=\"390\" width=\"230\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"405\" y=\"420\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">3. व्यावसायिक इकाई</text>\n  <text x=\"405\" y=\"448\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">अपना कम्पोस्ट · नियमित बिक्री</text>\n  <rect x=\"400\" y=\"270\" width=\"230\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"515\" y=\"300\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">4. उद्यम</text>\n  <text x=\"515\" y=\"328\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">Spawn-लैब · हब — जैसे 20 घर</text>\n  <rect x=\"510\" y=\"150\" width=\"230\" height=\"70\" rx=\"10\" fill=\"#0B1F3A\"/>\n  <text x=\"625\" y=\"180\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">5. बड़ा उद्यम</text>\n  <text x=\"625\" y=\"208\" font-size=\"17\" fill=\"#F5F7FA\" text-anchor=\"middle\">प्रसंस्करण · नाम-छाप · निर्यात</text>\n  <rect x=\"80\" y=\"730\" width=\"640\" height=\"55\" rx=\"27\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"765\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">\"जैसे\" = नमूना · ₹-गिनती अपने पत्रकों से, स्रोत-सहित</text>\n  <text x=\"180\" y=\"200\" font-size=\"20\" fill=\"#2E7D32\" font-weight=\"bold\">कसौटी:</text>\n  <text x=\"180\" y=\"235\" font-size=\"18\" fill=\"#0B1F3A\">पक्का अंक + बिना शर्त</text>\n  <text x=\"180\" y=\"265\" font-size=\"18\" fill=\"#0B1F3A\">= बेचने वाला, पढ़ाने वाला नहीं</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक में \"मेरे मील-पत्थर\" पन्ना बनाइए। पाँचों पड़ाव लिखिए। अपने आज के पड़ाव पर घेरा लगाइए। अगले पड़ाव के आगे तीन पंक्तियाँ लिखिए — उसकी शक्ल मेरे इलाक़े में कैसी दिखेगी, उसके लिए कौन-सी नई चीज़ें जुड़ेंगी, और कौन-से सवालों के ₹-जवाब मुझे अपने पत्रकों से निकालने होंगे।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- घेरा आज की सच्चाई पर हो, चाहत पर नहीं\n- ₹ वाली पंक्ति में अंक नहीं, सवाल लिखे हों\n\n### 5. सबूत\n\nमील-पत्थर पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मशरूम-धंधे के बड़े वादों वाले प्रचार में कौन-सी पाँच निशानियाँ बताती हैं कि सामने वाला सिखा नहीं, बेच रहा है?\"* — पाँचों निशानियाँ नोटबुक में उतारिए। आगे कोई भी वीडियो या प्रचार दिखे, तो यही सूची उसकी छन्नी बनेगी।\n\n### 7. आम ग़लती\n\nलोग तालिका देखकर उलटा सफ़र बाँध लेते हैं — सीधे चौथे पड़ाव का किराया-भाड़ा जोड़ने बैठ जाते हैं। **पड़ाव फाँदने की सवारी इस रास्ते पर नहीं चलती।** हर पड़ाव पिछले की कमाई हुई समझ पर खड़ा है। पाँच बैग की कोठरी ही बीस घर के हब की पहली ईंट है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 31-34 पूरे |\n| ज़रूरी सामान | नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | पड़ाव पहचानना, अगले की तैयारी-सूची लिखना |\n| क्या कभी नहीं | तालिका के पड़ावों को कमाई या समय का वादा बताकर किसी को सुनाना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — पैमाना-तालिका और \"यह वादा नहीं\" की पंक्ति वहीं छपी है\n- बटन के वैश्विक बाज़ार की झलक — बड़े पड़ाव सचमुच हैं ([imarcgroup.com](https://www.imarcgroup.com/mushroom-market)) · देखा गया 09-08-2026\n\n*तालिका रास्ते की तस्वीर है, गारंटी नहीं। हर पड़ाव की असली गिनती अपने पत्रकों और स्रोत-सहित पाठों से ही निकलेगी।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं पाँचों पड़ाव क्रम से पहचान-समेत गिना सकता हूँ\n- [ ] मैं \"जैसे\" शब्द का वज़न समझा सकता हूँ\n- [ ] मैं बता सकता हूँ कि तालिका में ₹ क्यों नहीं और कहाँ मिलेंगे\n- [ ] मैं सपना-बेचने वाले की कसौटी बोल सकता हूँ\n- [ ] मैंने अपना पड़ाव घेरकर अगले की तैयारी-पंक्तियाँ लिख ली हैं\n\n**आगे का पाठ:** नक़्शा पूरा होने चला — अब उस साँचे की बारी, जिसमें हर पाठ ढला है: दस खाने, और उन्हें निचोड़ने का हुनर।\n\n---\n---\n", "36": "# पाठ 36 — हर पाठ के दस खाने\n\n**अध्याय:** अ-4 · **पाठ:** 6 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nअब तक आपने चौबीस पाठ पढ़े — पर शायद ग़ौर नहीं किया कि हर पाठ एक ही साँचे में ढला है। इस पाठ के बाद वह साँचा आपके सामने खुला होगा — दसों खाने, हर खाने का काम, और हर खाने को निचोड़ने का तरीक़ा। साँचा जानने वाला पाठक दुगना पाता है।\n\n### 2. मुख्य बात\n\n> यह कोर्स कहानी की किताब नहीं, काम की किताब है। इसीलिए हर पाठ थाली की तरह परोसा गया है — दस कटोरियाँ, हर कटोरी का अपना स्वाद और अपना काम। कटोरी छोड़ने वाला भूखा ही उठता है।\n\n---\n\n### दस खाने — एक-एक कर पहचान\n\nचलिए, थाली खोलते हैं।\n\nखाना-1 — उद्देश्य। पाठ का वादा: इसके बाद आप क्या कर पाएँगे। पढ़ने से पहले इसे पढ़िए, पढ़ने के बाद इससे मिलाइए।\n\nखाना-2 — मुख्य बात। पूरा पाठ एक-दो वाक्यों में निचोड़ा हुआ। महीनों बाद दोहराई इसी डिब्बे से होगी।\n\nबीच का हिस्सा — नामी खंड और चित्र। यही पाठ का शरीर है — कहानियाँ, तरीक़े, नक़्शे। चित्र सजावट नहीं है; वह पाठ की बात को आँख की भाषा में दोहराता है। चित्र को ढँककर उसकी बात ख़ुद बोलने की कोशिश कीजिए — यह दोहराई का सबसे तेज़ खेल है।\n\nखाना-3 — आज का काम। पाठ की जान। देखो, अभ्यास या करो — तीन में से एक रूप में। जो पाठक सिर्फ़ पढ़ता है और काम छोड़ता है, वह इस कोर्स से किताब निकाल लेता है और कोर्स फेंक देता है।\n\nखाना-4 — नाप। काम सही होने की कसौटी — ताकि \"हो गया\" कहने से पहले आप ख़ुद जाँच सकें।\n\nखाना-5 — सबूत। काम का निशान — ज़्यादातर एक फ़ोटो। अगला ही नहीं, आने वाले पाठ इस पर पूरे उतरेंगे — सबूत का पूरा शास्त्र दो पाठ आगे है।\n\nखाना-6 — AI-सहायक। तैयार सवाल, जो आप AI से पूछ सकते हैं। यह खाना कभी ख़ाली भी रह सकता है — AI ज़बरदस्ती नहीं। और इसका जवाब हमेशा आपकी अपनी जाँच से मिलकर ही पक्का होता है।\n\nखाना-7 — आम ग़लती। जहाँ लोग अक्सर गिरते हैं, वहाँ पहले से लगा बोर्ड।\n\nखाना-8 — सुरक्षा-पत्रक। छह पंक्तियों की तालिका — जोखिम-स्तर से लेकर \"क्या कभी नहीं\" तक। अगला पाठ इसी की गहराई है।\n\nखाना-9 — स्रोत। पाठ की बातें कहाँ से आईं — तारीख़-समेत। भरोसा दावे से नहीं, स्रोत से बनता है।\n\nखाना-10 — योग्यता-जाँच। पाँच ख़ाने वाली अपनी परीक्षा — जिसमें झूठ बोलने पर सज़ा नहीं मिलती, सिर्फ़ नुक़सान अपना होता है।\n\n### थाली खाने का क्रम\n\nदस खाने हैं, पर खाने का एक सधा क्रम दुगना स्वाद देता है।\n\nपहली बार पढ़ते समय — उद्देश्य से योग्यता-जाँच तक सीधा चलिए, काम समेत। दोहराते समय — सिर्फ़ मुख्य बात, चित्र और अपनी भरी योग्यता-जाँच देखिए; तीन मिनट में पाठ लौट आता है। काम करते समय — आज का काम, नाप और सुरक्षा-पत्रक तीनों साथ खोलिए; नाप देखे बिना किया काम आधा होता है। और उलझन के समय — आम ग़लती और AI-खाना; ज़्यादातर उलझनें वहीं पहले से लिखी मिलेंगी।\n\n### साँचा एक क्यों है\n\nआख़िरी सवाल — छह सौ पाठ, साँचा एक ही क्यों? तीन वजहें।\n\nपहली — रफ़्तार। जाना-पहचाना साँचा दिमाग़ का रास्ता साफ़ रखता है; पाठक ढूँढने में नहीं, समझने में समय लगाता है। दूसरी — भरोसा। हर पाठ में नाप, स्रोत और सुरक्षा उसी जगह मिलेंगे — कोई पाठ इन तीनों से बच नहीं सकता। तीसरी — आदत। दस खानों की थाली रोज़ खाने वाला ख़ुद वैसा ही सोचने लगता है — काम से पहले नाप, दावे से पहले स्रोत, जोश से पहले सुरक्षा। साँचा असल में कोर्स का सबसे चुपचाप पढ़ाया गया पाठ है।\n\n### साथ पढ़ने वालों की थाली — बाँटकर दुगनी\n\n(यह बैठक-विधि आगे हब वाले खंड में और पकेगी — वहाँ यही आदत ढाँचा बनेगी।)\n\nथाली की एक कटोरी पर अलग से दो पंक्तियाँ — योग्यता-जाँच और सबूत की जोड़ी। दोनों मिलकर वही जमा-पूँजी बनाते हैं, जिसका पूरा शास्त्र दो पाठ आगे खुलेगा। यहाँ बस इतना पकड़िए — इन दो खानों में की गई ईमानदारी ही आगे हर दरवाज़े की चाबी है, और बेईमानी सिर्फ़ अपनी ही सीढ़ी काटती है।\n\nऔर एक भरोसे की बात — साँचा आपका पुराना परिचित है। चौबीस पाठों से आप इसी थाली से खा रहे हैं, बिना नाम जाने। आज सिर्फ़ नाम पड़े हैं। नाम पड़ते ही आदत औज़ार बन जाती है — अब आप हर नए पाठ को पहली नज़र में ही तौल सकेंगे कि उसकी कौन-सी कटोरी आपके लिए सबसे भारी है।\n\nसमूह-वर्ग के पाठकों के लिए साँचे का एक और फल है — थाली बाँटी जा सकती है।\n\nतरीक़ा आज़माया हुआ है। हफ़्ते की एक बैठक तय कीजिए। हर सदस्य वही पाठ पढ़कर आए, पर बैठक में भूमिकाएँ बँटें — एक मुख्य बात और चित्र सुनाए, दूसरा अपना किया हुआ काम दिखाए, तीसरा आम ग़लती पर अपनी आपबीती जोड़े, चौथा योग्यता-जाँच की पाँचों पंक्तियाँ सबसे बुलवाए। आधे घंटे की ऐसी बैठक अकेली पढ़ाई के तीन घंटों पर भारी है।\n\nऔर एक चेतावनी साथ — काम और सबूत हरेक का अपना रहेगा। समूह में पढ़ाई बँटती है, अभ्यास नहीं। जिसका पत्रक दूसरे ने भरा, उसकी सीढ़ी दूसरे की चढ़ी — अपनी नहीं।\n\n### चित्र — दस खानों की थाली\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">हर पाठ की थाली — दस खाने</text>\n  <rect x=\"80\" y=\"90\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"235\" y=\"120\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">1. उद्देश्य — पाठ का वादा</text>\n  <text x=\"235\" y=\"148\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">पहले और बाद — दो बार पढ़ो</text>\n  <rect x=\"410\" y=\"90\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"565\" y=\"120\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">2. मुख्य बात — निचोड़</text>\n  <text x=\"565\" y=\"148\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">दोहराई का दरवाज़ा</text>\n  <rect x=\"80\" y=\"180\" width=\"640\" height=\"70\" rx=\"10\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"210\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">बीच का शरीर — नामी खंड + चित्र</text>\n  <text x=\"400\" y=\"238\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">चित्र ढँककर उसकी बात बोलो — तेज़ दोहराई</text>\n  <rect x=\"80\" y=\"270\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"235\" y=\"300\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">3. आज का काम — पाठ की जान</text>\n  <text x=\"235\" y=\"328\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">देखो / अभ्यास / करो</text>\n  <rect x=\"410\" y=\"270\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"565\" y=\"300\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">4. नाप — सही की कसौटी</text>\n  <text x=\"565\" y=\"328\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">काम के साथ खुली रहे</text>\n  <rect x=\"80\" y=\"360\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"235\" y=\"390\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">5. सबूत — काम का निशान</text>\n  <text x=\"235\" y=\"418\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">पूरा शास्त्र दो पाठ आगे</text>\n  <rect x=\"410\" y=\"360\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"565\" y=\"390\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">6. AI-सहायक — तैयार सवाल</text>\n  <text x=\"565\" y=\"418\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">ज़बरदस्ती नहीं · जाँच अपनी</text>\n  <rect x=\"80\" y=\"450\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"235\" y=\"480\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">7. आम ग़लती — गिरने का बोर्ड</text>\n  <text x=\"235\" y=\"508\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">उलझन में पहले यहीं</text>\n  <rect x=\"410\" y=\"450\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"565\" y=\"480\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">8. सुरक्षा-पत्रक — छह पंक्तियाँ</text>\n  <text x=\"565\" y=\"508\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">अगला पाठ इसी की गहराई</text>\n  <rect x=\"80\" y=\"540\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"235\" y=\"570\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">9. स्रोत — तारीख़-समेत</text>\n  <text x=\"235\" y=\"598\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">भरोसा स्रोत से बनता है</text>\n  <rect x=\"410\" y=\"540\" width=\"310\" height=\"70\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"565\" y=\"570\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">10. योग्यता-जाँच — अपनी परीक्षा</text>\n  <text x=\"565\" y=\"598\" font-size=\"17\" fill=\"#F9A825\" text-anchor=\"middle\">झूठ का नुक़सान अपना</text>\n  <rect x=\"80\" y=\"650\" width=\"640\" height=\"60\" rx=\"30\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"688\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">साँचा = चुपचाप पढ़ाया गया पाठ: नाप, स्रोत, सुरक्षा — हर बार</text>\n  <text x=\"400\" y=\"750\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">दोहराई: मुख्य बात + चित्र + भरी योग्यता-जाँच = तीन मिनट</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nअपना कोई पिछला पसंदीदा पाठ खोलिए। उसके दसों खानों पर उँगली रखकर नाम बोलिए। फिर नोटबुक में \"मेरी थाली-आदत\" की तीन पंक्तियाँ लिखिए — कौन-सा खाना मैं अब तक सबसे ग़ौर से खाता रहा, कौन-सा अनजाने में छोड़ता रहा, और अगले पाठ से छूटे खाने के लिए मेरा क्या इरादा है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- छूटे खाने की पहचान ईमानदार हो — ज़्यादातर पाठकों का कोई न कोई खाना छूटता ही है\n- इरादे की पंक्ति में ठोस तरीक़ा हो, सिर्फ़ \"ध्यान रखूँगा\" नहीं\n\n### 5. सबूत\n\nतीन पंक्तियों वाले पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैं दस-खाने वाले साँचे के कोर्स में फ़लाँ खाना अक्सर छोड़ देता हूँ। इसे आदत में लाने की दो छोटी तरकीबें बताओ।\"* — मिली तरकीबों में से एक चुनकर अगले तीन पाठों में आज़माइए।\n\n### 7. आम ग़लती\n\nलोग बीच का शरीर पढ़कर पाठ को पूरा मान लेते हैं और नीचे के खाने \"बाद में\" पर टाल देते हैं। **नीचे के खाने ही पाठ को काम में बदलते हैं।** ऊपर पढ़ा हुआ ज्ञान है — नीचे किया हुआ पूँजी। ज्ञान और पूँजी का यह फ़र्क़ आप अध्याय-3 के समापन से जानते हैं।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | कोई भी पिछला पाठ पढ़ा हो |\n| ज़रूरी सामान | कोई पुराना पाठ, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | साँचा पहचानना, अपनी आदत परखना |\n| क्या कभी नहीं | नाप और सुरक्षा-पत्रक पढ़े बिना कोई \"करो\" वाला काम |\n\n### 9. स्रोत\n\n- यह कोर्स स्वयं — कोई भी पिछला पाठ खोलकर दसों खाने गिने जा सकते हैं\n- Applied Computer School — कोर्स-मंच ([acslearn.com](https://acslearn.com/)) · देखा गया 09-08-2026\n\n*साँचा पाठकों की सुविधा के लिए है, पूजा के लिए नहीं। किसी पाठ में कोई खाना छोटा या ख़ाली मिले — जैसे AI-खाना — तो वह चूक नहीं, सोचा हुआ फ़ैसला है।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं दसों खाने बिना देखे क्रम से गिना सकता हूँ\n- [ ] मैं दोहराई वाला तीन-मिनट का तरीक़ा बता सकता हूँ\n- [ ] मैं समझा सकता हूँ कि काम-नाप-सुरक्षा साथ क्यों खुलते हैं\n- [ ] मैं साँचा एक रखने की तीनों वजहें बोल सकता हूँ\n- [ ] मैंने अपना छूटता खाना पहचानकर इरादा लिख लिया है\n\n**आगे का पाठ:** थाली का आठवाँ खाना अब पूरा खुलेगा — सुरक्षा-वर्ग: हरा, पीला, लाल।\n\n---\n---\n", "37": "# पाठ 37 — सुरक्षा-वर्ग — हरा, पीला, लाल\n\n**अध्याय:** अ-4 · **पाठ:** 7 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nइस पाठ के बाद कोर्स की तीन-रंग सुरक्षा-भाषा आपकी अपनी भाषा बन जाएगी। आप जानेंगे कि हरा, पीला और लाल हर रंग किस शर्त का नाम है, लाल सूची में कौन-कौन बैठा है, और \"पढ़ना खुला, करना शर्तों पर\" का नियम रोज़ कैसे चलता है।\n\n### 2. मुख्य बात\n\n> सड़क की बत्ती गाड़ी रोकने के लिए नहीं, सफ़र पूरा कराने के लिए लगती है। कोर्स के तीन रंग भी यही हैं। हरा कहता है — चलो, होश से। पीला कहता है — साथ लेकर चलो। लाल कहता है — यह मोड़ शर्तों वाला है।\n\n---\n\n### हरा — छूट नहीं, होश\n\nहरा यानी सामान्य — कोई विशेष रोक नहीं। पर सूची की छपी चेतावनी याद रखिए: हरे का मतलब बेरोक नहीं।\n\nहरे पाठ का काम भी अपने सुरक्षा-पत्रक से बँधा है। बाज़ार-दौड़ हरा काम थी — फिर भी पत्रक में लिखा था: नाबालिग घर के बड़े को बताकर निकलें, और सौदे का जोश निषिद्ध। यही हरे की असलियत है — ख़तरा छोटा है, नियम फिर भी है। जिस दिन हरे को \"कुछ भी चलेगा\" पढ़ा, उस दिन पीले-लाल की इज़्ज़त भी गई।\n\n### पीला — अकेले नहीं, साथ से\n\nपीला यानी सावधानी — प्रशिक्षित वयस्क की निगरानी में, सुरक्षा-सामान के साथ।\n\nइस पंक्ति के दोनों हिस्से तौलिए। निगरानी का मतलब पास खड़ा कोई भी आदमी नहीं — वह आदमी, जो उस काम को जानता हो और ग़लती होते देखकर रोक सके। और सुरक्षा-सामान का मतलब जो उस पाठ का पत्रक कहे — दस्ताने हों, चश्मा हो, या कुछ और। दोनों में से एक भी ग़ैरहाज़िर, तो पीला काम उस दिन नहीं होगा — टलेगा, मरेगा नहीं। सीखने की सीढ़ी याद कीजिए — जो काम आज \"करो\" नहीं हो सकता, वह आज \"देखो\" बनकर भी सिखा जाता है।\n\n### लाल — दरवाज़ा बंद नहीं, चौकीदार वाला\n\nलाल यानी ऊँचा जोखिम — असली अभ्यास केवल तय उम्र, प्रशिक्षण और प्रत्यक्ष प्रशिक्षित निगरानी की शर्तों पर।\n\nकोर्स की लाल सूची खोलकर देखिए — दबाव वाले यंत्र, गर्म भाप, रसायन, यूवी, बिजली के औज़ार, काटने की मशीन। और सूची का सबसे चौंकाने वाला नाम — बैंक-क़र्ज़ के फ़ैसले। हाँ, पैसा भी लाल है। जली उँगली हफ़्तों में भर जाती है; ग़लत क़र्ज़ बरसों नहीं भरता। इसीलिए क़र्ज़ वाले पाठ भी उसी चौकीदारी से चलेंगे — पूरी जानकारी, बड़ों की सलाह, और कोई जल्दबाज़ी नहीं।\n\nलाल की सबसे ज़रूरी पंक्ति फिर भी यह है — पढ़ना सबके लिए खुला है। भाप वाला पाठ चौदह साल का बच्चा भी पढ़ सकता है, समझ सकता है, सवाल पूछ सकता है। ताला ज्ञान पर नहीं, सिर्फ़ असली अभ्यास पर है। यही \"पढ़ना खुला, करना शर्तों पर\" का पूरा अर्थ है — जो पूर्व-शर्त वाले पाठ में बोया था, वह यहाँ फल बना।\n\n### रंग कौन तय करता है — और आप क्या तय करते हैं\n\nहर पाठ का रंग कोर्स ने पहले से तय कर रखा है — वह पाठ के माथे पर छपा मिलेगा, और सूची में सिर्फ़ पीले-लाल के निशान लिखे हैं। आपके ज़िम्मे तय करना नहीं, निभाना है।\n\nपर एक अधिकार आपके पास हमेशा है — रंग को ऊपर की ओर बदलने का। कोई हरा काम आपकी अपनी हालत में जोखिम भरा लगे — तबीयत ढीली है, जगह ठीक नहीं, मन कहीं और है — तो उसे उस दिन पीले की इज़्ज़त दीजिए: टालिए या साथ लेकर कीजिए। नीचे की ओर बदलना — पीले को हरा मान लेना — किसी के पास नहीं है, आपके पास भी नहीं। सुरक्षा में उधार ऊपर का चलता है, नीचे का नहीं।\n\n### घर वालों को रंग-भाषा सिखाइए\n\nऔर यह भाषा घर की उम्र-सीमाओं से टकराती नहीं, उन्हें पक्का ही करती है — जो शर्त क़ानून या पाठ माँगे, वह हर हाल ऊपर रहेगी।\n\nरंगों की जड़ में एक सीधा गणित है — जोखिम और तैयारी का मेल। जोखिम जितना ऊँचा, तैयारी की माँग उतनी सख़्त। हरे में तैयारी का नाम होश है, पीले में साथ और सामान, लाल में उम्र-प्रशिक्षण-निगरानी तीनों। यह वही सोच है, जो अच्छी रसोई से लेकर बड़े कारख़ाने तक हर जगह चलती है — नया आदमी पहले दिन आग के पास नहीं, सब्ज़ी धोने पर लगता है।\n\nरंग-भाषा तभी पूरा काम करती है, जब अकेले आप नहीं, आपका आँगन भी उसे बोले।\n\nतीन काम कीजिए। पहला — घर के बड़ों को तीनों रंग एक बैठक में समझाइए, ख़ासकर उसे, जो आपका निगरानी-साथी बनेगा। जो आदमी नहीं जानता कि पीले में उसकी मौजूदगी शर्त है, वह ऐन मौक़े पर टहलने निकल जाएगा। दूसरा — घर के बच्चों को साफ़ बताइए कि कौन-सी चीज़ें छूने की नहीं हैं और क्यों — डर से नहीं, समझ से। तीसरा — ना कहने की हिम्मत घर में पहले से बो दीजिए: जिस दिन साथ या सामान पूरा न हो, उस दिन काम टलेगा — और टालने वाले को कोई ताना नहीं मिलेगा। जिस आँगन में सुरक्षा पर ताना चलता है, वहाँ लोग चोट छिपाने लगते हैं — और छिपी चोट सबसे महँगी है।\n\n### चित्र — तीन रंग, तीन शर्तें\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">सुरक्षा-वर्ग — कोर्स की बत्ती</text>\n  <rect x=\"80\" y=\"90\" width=\"640\" height=\"130\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"130\" font-size=\"23\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">🟢 हरा — सामान्य</text>\n  <text x=\"400\" y=\"165\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">कोई विशेष रोक नहीं — पर बेरोक नहीं</text>\n  <text x=\"400\" y=\"197\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">हर काम अपने सुरक्षा-पत्रक से बँधा है</text>\n  <rect x=\"80\" y=\"240\" width=\"640\" height=\"130\" rx=\"14\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"280\" font-size=\"23\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">🟡 पीला — सावधानी</text>\n  <text x=\"400\" y=\"315\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">प्रशिक्षित वयस्क की निगरानी + सुरक्षा-सामान</text>\n  <text x=\"400\" y=\"347\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">एक भी ग़ैरहाज़िर = काम आज टलेगा</text>\n  <rect x=\"80\" y=\"390\" width=\"640\" height=\"170\" rx=\"14\" fill=\"#0B1F3A\"/>\n  <text x=\"400\" y=\"430\" font-size=\"23\" fill=\"#F9A825\" text-anchor=\"middle\" font-weight=\"bold\">🔴 लाल — ऊँचा जोखिम</text>\n  <text x=\"400\" y=\"465\" font-size=\"19\" fill=\"#F5F7FA\" text-anchor=\"middle\">तय उम्र + प्रशिक्षण + प्रत्यक्ष प्रशिक्षित निगरानी</text>\n  <text x=\"400\" y=\"497\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">सूची: दबाव-यंत्र · गर्म भाप · रसायन · यूवी</text>\n  <text x=\"400\" y=\"527\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">बिजली के औज़ार · काटने की मशीन · बैंक-क़र्ज़ के फ़ैसले</text>\n  <rect x=\"80\" y=\"590\" width=\"640\" height=\"70\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"620\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">पढ़ना सबके लिए खुला — ताला सिर्फ़ असली अभ्यास पर</text>\n  <text x=\"400\" y=\"648\" font-size=\"18\" fill=\"#F9A825\" text-anchor=\"middle\">ज्ञान पर ताला नहीं, जोखिम पर चौकीदार है</text>\n  <text x=\"400\" y=\"710\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\">रंग ऊपर बदल सकते हो — नीचे कभी नहीं</text>\n  <text x=\"400\" y=\"755\" font-size=\"19\" fill=\"#2E7D32\" text-anchor=\"middle\" font-weight=\"bold\">बत्ती रोकती नहीं — सफ़र पूरा कराती है</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nपाठ-सूची खोलिए और अपने चुने रास्ते के खंडों पर नज़र दौड़ाइए। नोटबुक में \"मेरी रंग-सूची\" बनाइए — अपने रास्ते के पीले और लाल निशान वाले पाठों में से पाँच-सात लिखिए। हर एक के आगे लिखिए — इसकी शर्त पूरी करने के लिए मुझे क्या चाहिए होगा: कौन-सा साथ, कौन-सा सामान, कौन-सी उम्र या तैयारी।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- सूची में पीले और लाल दोनों रंग के पाठ आए हों\n- हर पंक्ति में शर्त-पूर्ति का ठोस इंतज़ाम लिखा हो, सिर्फ़ \"देख लूँगा\" नहीं\n\n### 5. सबूत\n\nरंग-सूची पन्ने की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरे इलाक़े और घर की हालत यह है। पीले कामों के लिए प्रशिक्षित निगरानी वाला साथ मुझे कहाँ-कहाँ मिल सकता है?\"* — मिले रास्तों को नोटबुक में लिखिए। पर निगरानी लायक़ आदमी की अंतिम पहचान आमने-सामने परख से ही कीजिए।\n\n### 7. आम ग़लती\n\nलोग रंग को पाठ की \"कठिनाई\" समझ लेते हैं — लाल यानी मुश्किल, हरा यानी आसान। **रंग कठिनाई नहीं, जोखिम बोलता है।** कोई हरा पाठ दिमाग़ के लिए कठिन हो सकता है और कोई लाल काम हाथ के लिए सरल — पर जोखिम भरा। पढ़ाई की मेहनत और चोट का ख़तरा — दो अलग तराज़ू हैं।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 33 (पूर्व-शर्त नक़्शा) पढ़ा हो |\n| ज़रूरी सामान | पाठ-सूची, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | रंग पहचानना, शर्त-इंतज़ाम की सूची बनाना |\n| क्या कभी नहीं | किसी पीले-लाल काम को हरा मानकर अकेले या बिना सामान करना |\n\n### 9. स्रोत\n\n- कोर्स की मास्टर पाठ-सूची (v2.3) — तीन-रंग तालिका और लाल-सूची वहीं छपी है\n- भारतीय खाद्य सुरक्षा एवं मानक प्राधिकरण — खाने के धंधे में सुरक्षा-संस्कृति की झलक ([fssai.gov.in](https://fssai.gov.in/)) · देखा गया 09-08-2026\n\n*रंग-भाषा पूरे ACS मंच की साझा भाषा है — यहाँ सीखी बत्ती हर कोर्स में यही बोलेगी।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं तीनों रंगों की शर्तें बिना देखे बोल सकता हूँ\n- [ ] मैं लाल सूची के कम से कम पाँच नाम गिना सकता हूँ\n- [ ] मैं समझा सकता हूँ कि बैंक-क़र्ज़ लाल क्यों है\n- [ ] मैं \"रंग ऊपर बदलो, नीचे कभी नहीं\" का नियम समझा सकता हूँ\n- [ ] मैंने अपने रास्ते की रंग-सूची इंतज़ाम-समेत बना ली है\n\n**आगे का पाठ:** नियम निभाने का हिसाब किस चीज़ से होता है? सबूत से। अगला पाठ सबूत के दस रूप और योग्यता-जाँच का पूरा शास्त्र खोलेगा।\n\n---\n---\n", "38": "# पाठ 38 — सबूत के दस रूप और योग्यता-जाँच\n\n**अध्याय:** अ-4 · **पाठ:** 8 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nहर पाठ में आपने \"सबूत\" का खाना भरा है — ज़्यादातर एक फ़ोटो से। इस पाठ के बाद आपके तरकश में सबूत के दस रूप होंगे, उन्हें सँभालने का एक पक्का ढंग होगा, और योग्यता-जाँच के पाँच ख़ानों को ईमानदारी से भरने की पूरी समझ होगी।\n\n### 2. मुख्य बात\n\n> बोला हुआ उड़ जाता है, दर्ज किया हुआ काम आता है। सबूत अपने-आप को दिया गया वचन है — और आगे चलकर यही वचन आपकी सीढ़ी-चढ़ाई का सिक्का बनता है।\n\n---\n\n### सबूत किसके लिए — पहले आईना, फिर दुनिया\n\nसबूत का पहला ग्राहक कोई और नहीं — छह महीने बाद के आप हैं। तब का आदमी आज की बारीक़ियाँ भूल चुका होगा। उसकी मदद आज का दर्ज पन्ना ही करेगा।\n\nदूसरा ग्राहक — आपकी सीढ़ी। काम की छह सीढ़ियों वाले पाठ में चढ़ने का सिक्का पढ़ा था: गिनती, सबूत, ज़िम्मेदारी। और आगे कोर्स-अंत की परीक्षा से वर्कशॉप और उस्ताद के आमने-सामने प्रमाणीकरण तक — हर दरवाज़े पर यही जमा-पूँजी बोलेगी। जो आज से जमा करता चला, उसे किसी दरवाज़े पर ख़ाली हाथ खड़ा नहीं होना पड़ेगा।\n\n### दस रूप — तरकश खोलिए\n\nअब दसों रूप, काम की मिसाल के साथ।\n\nरूप-1 — फ़ोटो। सबसे आम — भरा पन्ना, चुना कोना, सजी टोकरी।\n\nरूप-2 — पहले-बाद की जोड़ी। एक ही जगह की दो फ़ोटो — सफ़ाई से पहले, सफ़ाई के बाद। बदलाव का सबसे बोलता सबूत।\n\nरूप-3 — भरी तालिका या पत्रक। माँग-पत्रक, दाम-पट्टी, दस-ग्राहक सूची — काग़ज़ ख़ुद गवाह।\n\nरूप-4 — रजिस्टर की पंक्ति। तारीख़ वाली बही में उस दिन की दर्ज लिखाई। आगे रोज़-रजिस्टर वाले पाठों की रीढ़ यही है।\n\nरूप-5 — नाप का अंक। थर्मामीटर की पढ़त, तौल का काँटा — इकाई और घड़ी-समेत लिखा अंक।\n\nरूप-6 — छोटा वीडियो। जहाँ हरकत ही सबूत है — हाथ धोने का ढंग, तुड़ाई की पकड़।\n\nरूप-7 — आवाज़-टिप्पणी। लिखने का समय न हो, तो अपनी आवाज़ में दो पंक्तियाँ — बाद में नोटबुक में उतारने के वादे के साथ।\n\nरूप-8 — गवाह की पुष्टि। जिस बड़े या साथ वाले की निगरानी में काम हुआ, उसके दस्तख़त या नाम-तारीख़ की पंक्ति — पीले कामों में यही असली मुहर।\n\nरूप-9 — पर्ची और रसीद। ख़रीद की पर्ची, बुकिंग की लिखा-पढ़ी — पैसे से जुड़े हर काम का काग़ज़ी पहरा।\n\nरूप-10 — संदेश की प्रति। ग्राहक से हुई फ़ोन-लिखाई का screenshot — पहला संदेश और वादे वाले पाठ की सीख यहीं दर्ज होती है: लिखा हुआ बोले हुए से लंबा जीता है।\n\n### सँभाल का ढंग — तीन आदतें\n\nसबूत बनाना आधा काम है, सँभालना बाक़ी आधा। तीन आदतें काफ़ी हैं।\n\nपहली — एक घर। फ़ोन में एक अलग album या folder — नाम रखिए अपने कोर्स का। हर सबूत उसी घर में, उसी दिन। बिखरा सबूत खोया सबूत है।\n\nदूसरी — नाम में तारीख़। फ़ोटो के साथ नोटबुक में एक पंक्ति — कौन-सा पाठ, कौन-सा दिन। महीनों बाद ढूँढना मिनट का काम रहेगा।\n\nतीसरी — निजता का पहरा। सबूत आपकी अमानत है — पर उसमें दूसरों के नाम-नंबर भी हैं। ग्राहक-सूची और संदेश-प्रति जैसी चीज़ें दिखावे के लिए नहीं बाँटी जातीं। यह नियम आप दस-ग्राहक सूची वाले पाठ से जानते हैं — यहाँ वह हर सबूत पर फैल गया।\n\n### योग्यता-जाँच — पाँच ख़ानों का सच\n\nअब थाली का दसवाँ खाना। हर पाठ के अंत में पाँच ख़ाली ख़ाने — और उन्हें भरने वाले अकेले आप।\n\nइसकी बनावट समझिए। पाँचों पंक्तियाँ उसी पाठ की रीढ़ से बनी हैं — कोई बाहर से नहीं आई। यानी जो पाँचों पर सच्चा ✔ लगा सकता है, उसने पाठ सचमुच निचोड़ लिया।\n\nभरने का नियम एक ही है — ✔ तभी, जब वह बात अभी, बिना देखे, कर या बोल सकें। शक हो, तो ख़ाना ख़ाली छोड़िए और पाठ के उस हिस्से पर लौटिए। ख़ाली ख़ाना हार नहीं — वह तीर का निशान है: यहाँ दोबारा आओ। और झूठा ✔? उसकी कोई सज़ा नहीं है — यही उसकी सबसे बड़ी सज़ा है। झूठ किसी और से नहीं, अपनी ही नींव से होता है, और नींव का झूठ दीवार गिरने पर पकड़ में आता है।\n\n### सबूत में मिलावट निषिद्ध\n\nसबूत का बोझ मत बढ़ाइए — हर काम पर मिनट-भर का एक निशान काफ़ी है; बही सजाने में दिन नहीं जाना चाहिए।\n\nदस रूपों में से किस काम पर कौन-सा चुनें? अँगूठे का नियम — जो रूप उस काम को सबसे कम मेहनत में सबसे साफ़ पकड़े। लिखे काम की फ़ोटो, हरकत का वीडियो, गिनती का अंक, बात की संदेश-प्रति। एक काम पर दो रूप जुड़ जाएँ — जैसे पत्रक की फ़ोटो और गवाह की पंक्ति — तो सबूत दुगना गहरा।\n\nएक लक्ष्मण-रेखा सबूत की भी। सबूत सजाया नहीं जाता — जैसा काम, वैसा निशान।\n\nपुरानी फ़ोटो नई तारीख़ के आगे नहीं लगेगी। बिना किए काम का \"कर लिया\" नहीं लिखेगा। और आधे-अधूरे काम की फ़ोटो पूरे की तरह पेश नहीं होगी — अधूरे की फ़ोटो अधूरा लिखकर लगाइए, वह भी सच्चा सबूत है। वजह वही पुरानी है — इस बही का पहला पाठक आप ख़ुद हैं। मिलावटी सबूत से आपने किसी और को नहीं, अपनी छह महीने बाद की योजना को ठगा।\n\n### चित्र — सबूत का तरकश\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">सबूत के दस रूप — काम का तरकश</text>\n  <rect x=\"70\" y=\"90\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"175\" y=\"128\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">1. फ़ोटो</text>\n  <text x=\"175\" y=\"158\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">भरा पन्ना, सजी टोकरी</text>\n  <rect x=\"295\" y=\"90\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"128\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">2. पहले-बाद जोड़ी</text>\n  <text x=\"400\" y=\"158\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">बदलाव का गवाह</text>\n  <rect x=\"520\" y=\"90\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"625\" y=\"128\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">3. भरा पत्रक</text>\n  <text x=\"625\" y=\"158\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">काग़ज़ ख़ुद गवाह</text>\n  <rect x=\"70\" y=\"200\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"175\" y=\"238\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">4. रजिस्टर-पंक्ति</text>\n  <text x=\"175\" y=\"268\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">तारीख़ वाली बही</text>\n  <rect x=\"295\" y=\"200\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"238\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">5. नाप का अंक</text>\n  <text x=\"400\" y=\"268\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">इकाई + घड़ी समेत</text>\n  <rect x=\"520\" y=\"200\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"625\" y=\"238\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">6. छोटा वीडियो</text>\n  <text x=\"625\" y=\"268\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">जहाँ हरकत ही सबूत</text>\n  <rect x=\"70\" y=\"310\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"175\" y=\"348\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">7. आवाज़-टिप्पणी</text>\n  <text x=\"175\" y=\"378\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">बाद में लिखाई पक्की</text>\n  <rect x=\"295\" y=\"310\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"348\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">8. गवाह-पुष्टि</text>\n  <text x=\"400\" y=\"378\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">पीले काम की मुहर</text>\n  <rect x=\"520\" y=\"310\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"625\" y=\"348\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">9. पर्ची-रसीद</text>\n  <text x=\"625\" y=\"378\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">पैसे का काग़ज़ी पहरा</text>\n  <rect x=\"295\" y=\"420\" width=\"210\" height=\"90\" rx=\"10\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"458\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">10. संदेश-प्रति</text>\n  <text x=\"400\" y=\"488\" font-size=\"16\" fill=\"#F9A825\" text-anchor=\"middle\">लिखा हुआ लंबा जीता है</text>\n  <rect x=\"70\" y=\"540\" width=\"660\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"578\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">सँभाल: एक घर (album) · नाम में तारीख़ · निजता का पहरा</text>\n  <text x=\"400\" y=\"610\" font-size=\"18\" fill=\"#F9A825\" text-anchor=\"middle\">बिखरा सबूत = खोया सबूत</text>\n  <rect x=\"70\" y=\"650\" width=\"660\" height=\"80\" rx=\"14\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"685\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">योग्यता-जाँच: ✔ तभी, जब अभी बिना देखे कर सको</text>\n  <text x=\"400\" y=\"715\" font-size=\"18\" fill=\"#0B1F3A\" text-anchor=\"middle\">ख़ाली ख़ाना = तीर का निशान: यहाँ दोबारा आओ</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nआज दो काम। पहला — फ़ोन में अपने कोर्स के नाम का album या folder बनाइए और अब तक के सारे सबूत-फ़ोटो उसमें डालिए। दूसरा — नोटबुक में \"सबूत-रूप तालिका\" बनाइए: दसों रूपों के नाम, और हर रूप के आगे अपने पिछले पाठों में से एक-एक जगह, जहाँ वह रूप काम आया था या आ सकता था।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- album में पिछले पाठों के सबूत सचमुच एक जगह आ गए हों\n- तालिका के कम से कम सात रूपों के आगे असली मिसाल लिखी हो\n\n### 5. सबूत\n\nalbum के पहले पन्ने का screenshot और भरी तालिका की फ़ोटो।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मैं फ़ोन में अपने कोर्स के सबूत-फ़ोटो सँभालना चाहता हूँ। album को महीनों तक साफ़-सुथरा रखने की तीन आसान आदतें बताओ।\"* — तीनों आदतों में से जो आपके फ़ोन-इस्तेमाल से मेल खाए, उसे अपनी सँभाल-विधि में जोड़िए।\n\n### 7. आम ग़लती\n\nलोग सबूत को \"किसी को दिखाने की चीज़\" समझकर टाल देते हैं — अभी कौन देख रहा है? **पहला देखने वाला छह महीने बाद का आप ख़ुद है।** और जिस दिन कोई दरवाज़ा — परीक्षा, वर्कशॉप, ग्राहक का भरोसा — सबूत माँगेगा, उस दिन जमा-पूँजी रातों-रात नहीं बनती।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 36 (दस खाने) पढ़ा हो |\n| ज़रूरी सामान | फ़ोन, नोटबुक, क़लम |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | album बनाना, तालिका भरना, पुराने सबूत समेटना |\n| क्या कभी नहीं | ग्राहकों के नाम-नंबर वाले सबूत किसी को भेजना या सार्वजनिक करना |\n\n### 9. स्रोत\n\n- आपके अपने पिछले पाठों के सबूत — इस पाठ की सामग्री वही है\n- निजी जानकारी की हिफ़ाज़त पर सरकारी दिशा की झलक ([meity.gov.in](https://www.meity.gov.in/)) · देखा गया 09-08-2026\n\n*सबूत-आदत इसी कोर्स तक सीमित नहीं — यही आदत आगे रजिस्टर, हिसाब और Project Report की नींव बनेगी।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं सबूत के दोनों ग्राहक बता सकता हूँ\n- [ ] मैं दसों रूप बिना देखे गिना सकता हूँ\n- [ ] मैं सँभाल की तीनों आदतें बोल सकता हूँ\n- [ ] मैं समझा सकता हूँ कि झूठे ✔ की सज़ा क्या है\n- [ ] मेरा सबूत-album बन चुका है और पुराने सबूत उसमें हैं\n\n**आगे का पाठ:** अध्याय और खंड की आख़िरी कड़ी — अपना रास्ता चुनकर नब्बे दिन की योजना।\n\n---\n---\n", "39": "# पाठ 39 — आज का काम — अपनी रास्ता चुनकर 90 दिन की योजना लिखो\n\n**अध्याय:** अ-4 · **पाठ:** 9 में से 9\n**सुरक्षा:** 🟢 सामान्य · **काम:** «अभ्यास» · **पढ़ने का समय:** लगभग 14 मिनट\n\n---\n\n### 1. उद्देश्य\n\nयह खंड-1 का आख़िरी पाठ है — और इसका फल एक पन्ना है: आपकी नब्बे दिन की योजना। इसके बाद आपके हाथ में सिर्फ़ नक़्शा नहीं, चलने का कार्यक्रम होगा — हफ़्तों में बँटा, मौसम से मिला, और स्लेट की तरह ताज़ा होने वाला।\n\n### 2. मुख्य बात\n\n> नक़्शा बताता है — रास्ते कौन-से हैं। योजना बताती है — इस हफ़्ते पाँव कहाँ पड़ेगा। नब्बे दिन इतने लंबे हैं कि कुछ ठोस बन जाए, और इतने छोटे कि आँख से ओझल न हों।\n\n---\n\n### नब्बे ही क्यों\n\nपहले गिनती की वजह। साल की योजना सपना बन जाती है — बारहवें महीने तक पहला भी धुँधला जाता है। हफ़्ते की योजना साँस नहीं लेने देती। नब्बे दिन — यानी लगभग एक मौसम — बीच का सधा नाप है।\n\nऔर आपके लिए तो यह नाप क़ुदरत ने ख़ुद काटा है। मौसम-पाठ की सीख याद कीजिए — बटन की फ़सल-खिड़की और तैयारी का उल्टा-हिसाब मिलकर मोटे तौर पर एक मौसम की ही चौड़ाई बनाते हैं। नब्बे दिन की योजना यानी अपने अगले मौसम की योजना।\n\n### योजना का ढाँचा — तीन तीस\n\nपन्ने को तीन हिस्सों में बाँटिए — तीन महीने, हर महीने का एक ख़ाना।\n\nपहला तीस — नींव पक्की। मोटा ढाँचा ऐसा बन सकता है: खंड-2 की पढ़ाई (AI का औज़ार-घर — अगला ही खंड), अधूरे पन्नों की भराई — तैयारी-पत्र के \"पता-नहीं\", रंग-सूची के इंतज़ाम — और अपने रास्ते की शर्त-सीढ़ी का अगला डंडा।\n\nदूसरा तीस — तैयारी ज़मीन पर। कम्पोस्ट-ठिकाने और Spawn-स्रोत से बात पक्की, कोने की सफ़ाई-जमावट, ख़रीद की सूची, और खंड-3 (पहला चक्र) की पढ़ाई शुरू।\n\nतीसरा तीस — पहला चक्र की ओर। मौसम-खिड़की से मिलाकर पहले चक्र का आग़ाज़ — या, खिड़की दूर हो, तो उसकी पक्की उल्टी-गिनती और तब तक के पाठ।\n\nयह ढाँचा नमूना है, वर्दी नहीं। आपकी खिड़की, आपका रास्ता और आपकी रफ़्तार इसे अपने नाप से काटेगी — बस तीन-तीस की चाल और हफ़्ता-पंक्तियाँ बनी रहें।\n\n### हफ़्ता-पंक्ति कैसे लिखें\n\nहर महीने के ख़ाने में चार हफ़्ता-पंक्तियाँ बनाइए। हर पंक्ति में तीन चीज़ें — इस हफ़्ते के पाठ (कौन-से नंबर), इस हफ़्ते का काम (कौन-सा ठोस क़दम), और उसका सबूत-रूप (दस में से कौन-सा)।\n\nपंक्ति लिखने की दो कसौटियाँ। पहली — हर पंक्ति नापने लायक़ हो। \"AI सीखूँगा\" नहीं — \"खंड-2 के पहले सात पाठ, हर पाठ का काम, सबूत album में\"। दूसरी — हर हफ़्ते में कम से कम एक ज़मीनी क़दम हो। सिर्फ़ पढ़ाई वाले हफ़्ते नक़्शे को किताब बना देते हैं — और यह कोर्स किताब नहीं है, यह आप छब्बीस पाठ पहले से जानते हैं।\n\nऔर एक ख़बरदारी, जो अब आपकी अपनी भाषा है — यह योजना ख़ुद से किया वादा है, बाहर बोला वादा नहीं। तारीख़-तौल-दाम वाली तराज़ू यहाँ भी लागू है: ग्राहक या घर वालों के सामने वही तारीख़ बोलिए, जो पक्की हो।\n\n### स्लेट-नियम — योजना ज़िंदा रहे\n\nआख़िरी नियम पुराना दोस्त है — स्लेट। माँग-गिनती की तरह योजना भी पत्थर नहीं। हर तीसें के अंत में पन्ने पर लौटिए — क्या हुआ, क्या खिसका, क्यों। खिसके काम को अगले ख़ाने में नई तारीख़ दीजिए, और वजह की एक पंक्ति साथ लिखिए। बिना वजह खिसकाना आदत बनती है; वजह-समेत खिसकाना सीख।\n\nऔर नब्बेवें दिन? पूरा पन्ना पढ़िए, अपनी सीढ़ी-पन्ने और मील-पत्थर पन्ने से मिलाइए — और अगली नब्बे दिन की स्लेट लिखिए। यही चक्र आपको छह सौ सत्ताईस पाठों के जंगल से अपनी पगडंडी पर रखेगा।\n\n### पहली पंक्ति आज ही की शाम से\n\nयह योजना खंड-1 की आख़िरी परीक्षा भी है — इसकी हर पंक्ति में पिछले पाठों की कमाई झलकनी चाहिए। रास्ता पाठ बत्तीस से, क्रम शर्त-सीढ़ी से, खिड़की मौसम-पत्रक से, ज़मीनी क़दम ग्राहक-पन्नों से, और सबूत-रूप पिछले ही पाठ के तरकश से। जो पंक्ति किसी पिछले पन्ने से नहीं जुड़ती, वह हवा से आई है — उसे दोबारा तौलिए।\n\nयोजना की सबसे ख़तरनाक घड़ी उसके बनने के ठीक बाद की है — भरा पन्ना देखकर मन को लगता है, काम हो गया। यह संतोष का धोखा है।\n\nतोड़ इसका एक ही है — घेरे वाली पहली पंक्ति का पहला क़दम आज ही उठ जाए। छोटा-सा ही सही: खंड-2 का पहला पाठ खोल लिया, या अधूरे तैयारी-पत्र का एक \"पता-नहीं\" फ़ोन से \"पक्का\" हो गया। पन्ने की स्याही सूखने से पहले पड़ा पहला क़दम पूरी योजना की चाल तय कर देता है।\n\nऔर दूसरा सहारा — एक जोड़ी-साथी। घर का कोई, समूह का कोई, या साथ पढ़ता कोई — जिसे हर हफ़्ते के अंत में आप अपनी हफ़्ता-पंक्ति का हाल दो मिनट में सुनाएँगे। किसी को सुनाने भर की जवाबदेही निभाई को दुगना कर देती है — और यह वादा-भाषा नहीं, सीखने की जुगत है।\n\n### चित्र — नब्बे दिन की स्लेट\n\n<svg viewBox=\"0 0 800 800\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"800\" fill=\"#F5F7FA\"/>\n  <text x=\"400\" y=\"50\" font-size=\"28\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">नब्बे दिन की योजना — तीन तीस</text>\n  <rect x=\"70\" y=\"90\" width=\"660\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"128\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">पहला तीस — नींव पक्की</text>\n  <text x=\"400\" y=\"162\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">खंड-2 (AI) · अधूरे पन्ने · शर्त-सीढ़ी का अगला डंडा</text>\n  <text x=\"400\" y=\"192\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">चार हफ़्ता-पंक्तियाँ: पाठ + काम + सबूत-रूप</text>\n  <rect x=\"70\" y=\"240\" width=\"660\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"278\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">दूसरा तीस — तैयारी ज़मीन पर</text>\n  <text x=\"400\" y=\"312\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">ठिकाने पक्के · कोना तैयार · खंड-3 शुरू</text>\n  <text x=\"400\" y=\"342\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">हर हफ़्ते कम से कम एक ज़मीनी क़दम</text>\n  <rect x=\"70\" y=\"390\" width=\"660\" height=\"130\" rx=\"14\" fill=\"#1565C0\"/>\n  <text x=\"400\" y=\"428\" font-size=\"21\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">तीसरा तीस — पहला चक्र की ओर</text>\n  <text x=\"400\" y=\"462\" font-size=\"19\" fill=\"#F9A825\" text-anchor=\"middle\">मौसम-खिड़की से मिलान — या पक्की उल्टी-गिनती</text>\n  <text x=\"400\" y=\"492\" font-size=\"18\" fill=\"#F5F7FA\" text-anchor=\"middle\">ढाँचा नमूना है — अपनी खिड़की से काटो</text>\n  <rect x=\"70\" y=\"550\" width=\"660\" height=\"90\" rx=\"14\" fill=\"#2E7D32\"/>\n  <text x=\"400\" y=\"588\" font-size=\"20\" fill=\"#F5F7FA\" text-anchor=\"middle\" font-weight=\"bold\">स्लेट-नियम: हर तीसें के अंत में लौटो</text>\n  <text x=\"400\" y=\"620\" font-size=\"18\" fill=\"#F9A825\" text-anchor=\"middle\">खिसका काम = नई तारीख़ + वजह की पंक्ति</text>\n  <rect x=\"70\" y=\"660\" width=\"660\" height=\"60\" rx=\"30\" fill=\"#F9A825\"/>\n  <text x=\"400\" y=\"698\" font-size=\"20\" fill=\"#0B1F3A\" text-anchor=\"middle\" font-weight=\"bold\">ख़ुद से किया वादा — बाहर वही बोलो जो पक्का हो</text>\n  <text x=\"400\" y=\"760\" font-size=\"19\" fill=\"#0B1F3A\" text-anchor=\"middle\">नब्बेवें दिन: मिलान करो, अगली स्लेट लिखो</text>\n</svg>\n\n### 3. आज का काम «अभ्यास»\n\nनोटबुक के दो खुले पन्नों पर अपनी नब्बे दिन की योजना बनाइए — तीन महीने-ख़ाने, हर ख़ाने में चार हफ़्ता-पंक्तियाँ, हर पंक्ति में पाठ-काम-सबूत तीनों। ऊपर अपना चुना रास्ता और आज की तारीख़ लिखिए। मौसम-पत्रक सामने रखकर तीसरे तीस को अपनी खिड़की से मिलाइए। आख़िर में पहली हफ़्ता-पंक्ति पर घेरा लगाइए — चलना वहीं से है।\n\n### 4. नाप\n\nआपका काम सही है, अगर —\n- बारहों हफ़्ता-पंक्तियों में पाठ, काम और सबूत-रूप तीनों भरे हों\n- हर महीने-ख़ाने में कम से कम दो ज़मीनी क़दम हों\n\n### 5. सबूत\n\nपूरी योजना के दोनों पन्नों की फ़ोटो — यह फ़ोटो आपके album की सबसे क़ीमती प्रति है।\n\n### 6. AI-सहायक\n\nAI से पूछिए —\n*\"मेरा रास्ता, मौसम-खिड़की और नब्बे दिन की योजना यह है। बताओ — कौन-सा हफ़्ता सबसे ज़्यादा लदा है और कौन-सी पंक्ति नापने लायक़ नहीं बनी?\"* — फिर बारहों पंक्तियाँ पढ़कर सुनाइए। लदे हफ़्ते का बोझ अगले हफ़्तों में बाँटिए।\n\n### 7. आम ग़लती\n\nलोग योजना को इतना भर देते हैं कि पहला ही हफ़्ता टूट जाता है — और टूटे पहले हफ़्ते के साथ पूरी स्लेट कूड़े में जाती है। **योजना की ताक़त भराई नहीं, निभाई है।** पहले हफ़्ते को जान-बूझकर हल्का रखिए — पहली जीत ही आगे की बारह जीतों की माँ है।\n\n### 8. सुरक्षा-पत्रक\n\n| खाना | ब्योरा |\n|---|---|\n| जोखिम-स्तर | 🟢 सामान्य |\n| ज़रूरी हुनर | पाठ 31-38 के पन्ने तैयार हों |\n| ज़रूरी सामान | नोटबुक, क़लम, मौसम-पत्रक, पाठ-सूची |\n| देखरेख | कोई नहीं |\n| क्या कर सकते हैं | योजना लिखना, मिलान, पहली पंक्ति पर घेरा |\n| क्या कभी नहीं | योजना की तारीख़ें ग्राहकों के सामने वादे की तरह बोलना |\n\n### 9. स्रोत\n\n- आपके खंड-1 के सारे पन्ने — योजना की हर पंक्ति वहीं से निकली है\n- मौसम की सरकारी जानकारी — खिड़की-मिलान के लिए ([mausam.imd.gov.in](https://mausam.imd.gov.in/)) · देखा गया 09-08-2026\n\n*नब्बे दिन की योजना कोर्स की नहीं, आपकी है। कोर्स रास्ता देता है — रफ़्तार, ठहराव और मोड़ आपकी स्लेट तय करेगी।*\n\n### 10. योग्यता-जाँच\n\n- [ ] मैं नब्बे दिन के नाप की वजह बता सकता हूँ\n- [ ] मैं तीन-तीस का ढाँचा और हफ़्ता-पंक्ति के तीन हिस्से बोल सकता हूँ\n- [ ] मैं स्लेट-नियम और वजह-समेत खिसकाने का फ़र्क़ समझा सकता हूँ\n- [ ] मेरी बारह पंक्तियाँ भरी हैं और पहली पर घेरा है\n- [ ] मैं जानता हूँ कि पहला हफ़्ता हल्का क्यों रखा जाता है\n\n**आगे का पाठ:** 🎉 खंड-1 पूरा — नींव पड़ चुकी, फ़ैसला हो चुका। अगला खंड आपके औज़ार-घर का दरवाज़ा खोलता है — AI आपका साथी।\n\n---\n---\n"};
